export type RunAction = "resume" | "cancel" | "approve" | "reject";
const STATUS: Record<AgentToolCall["status"], string> = {
    pending: "准备执行", awaiting_approval: "等待批准", approved: "已批准，等待执行",
    running: "执行中", completed: "已完成", failed: "失败", rejected: "已拒绝", unknown: "结果待核实",
};
const EFFECT: Record<AgentToolCall["effect"], string> = {
    read: "读取本地数据", write: "编辑数据", network: "使用互联网", bookkeeping: "维护任务与计划",
};

function StepIcon({status}: { status: AgentToolCall["status"] }) {
    if (status === "completed") return <Check size={15} className="text-green-500"/>;
    if (status === "running") return <LoaderCircle size={15} className="animate-spin motion-reduce:animate-none"/>;
    if (status === "awaiting_approval") return <ShieldQuestion size={15} className="text-amber-500"/>;
    if (status === "failed" || status === "unknown") return <CircleAlert size={15} className="text-amber-500"/>;
    return <Circle size={15}/>;
}

/** Only this tiny label ticks; historical markdown never rerenders for the clock. */
function RunElapsed({run}: { run: AgentRun }) {
    const [now, setNow] = useState(Date.now);
    useEffect(() => {
        if (run.status !== "running") return;
        setNow(Date.now());
        const timer = window.setInterval(() => setNow(Date.now()), 1000);
        return () => window.clearInterval(timer);
    }, [run.status]);
    return <span title="本轮经过时间，包含等待确认的时间">用时 {formatRunElapsed(getRunElapsedMs(run, now))}</span>;
}

function validationFailure(call: AgentToolCall): ToolValidationFailure | undefined {
    if (call.status !== "failed") return undefined;
    return readToolValidationFailure(call.result);
}

function ValidationFailureNotice({failure, legacy}: { failure: ToolValidationFailure; legacy?: boolean }) {
    return <div className="agent-tool-validation-error" role="alert">
        <strong>参数校验失败，操作未执行</strong>
        {legacy &&
            <p className="agent-tool-validation-legacy">历史记录补充：按当前工具规则复核，以下诊断不代表当时返回内容。</p>}
        <ul>{failure.issues.map((issue, index) => <li key={`${issue.path}-${index}`}>
            <code>{issue.path}</code>：{issue.constraint}{issue.received !== undefined &&
            <span>（收到 {String(issue.received)}）</span>}</li>)}</ul>
        <p className="agent-tool-validation-recovery">
            此次操作未执行，也未产生结果。助手应修正上述参数后重新调用；若依据其他资料回答，需要说明缺失信息对结论的影响。
            {failure.issues.some((issue) => /limit|offset/i.test(issue.path)) && " 如需读取较长内容，请按 nextOffset 分页读取，每次请求保持在单次上限内。"}
        </p>
    </div>;
}

function ToolCallRow({run, call, busy, readOnly, unknown, executing, onAction}: {
    run: AgentRun; call: AgentToolCall; busy: boolean; readOnly?: boolean;
    unknown: boolean; executing: boolean;
    onAction: (runId: string, action: RunAction, callId?: string) => void;
}) {
    const {request} = useAgentActivityNavigation();
    const [open, setOpen] = useState(call.status === "awaiting_approval" || call.status === "unknown");
    const panelId = useId();
    useEffect(() => {
        if (request?.runId === run.id && request.callId === call.id) setOpen(true);
    }, [request, run.id, call.id]);
    const recoverable = canResumeAgentRun(run);
    const reviewGeneration = !readOnly && call.name === "submit_generation" && call.status === "awaiting_approval" && recoverable && !unknown && !executing;
    const musicReview = call.name === "music_generate";
    const activeMusicReview = musicReview && !readOnly && call.status === "awaiting_approval" && recoverable && !unknown && !executing;
    const preview = call.generationOverride?.preview ?? call.preview;
    const [legacyValidation, setLegacyValidation] = useState<ToolValidationFailure | undefined>();
    const structuredValidation = useMemo(() => validationFailure(call), [call.status, call.result]);
    useEffect(() => {
        let cancelled = false;
        if (!structuredValidation && call.status === "failed" && call.error?.includes("参数无效")) {
            void import("@/lib/agent/tools").then(({getLegacyToolValidationFailure}) => {
                if (!cancelled) setLegacyValidation(getLegacyToolValidationFailure(call));
            });
        } else setLegacyValidation(undefined);
        return () => {
            cancelled = true;
        };
    }, [call, structuredValidation]);
    const validation = structuredValidation ?? legacyValidation;
    const isLegacyValidation = !structuredValidation && Boolean(legacyValidation);
    return <div className="agent-run-step" data-activity-call={call.id}>
        <button type="button" className="agent-tool-call-toggle" aria-expanded={open} aria-controls={panelId}
                onClick={() => setOpen((value) => !value)}>
            <StepIcon status={call.status}/><span>{call.title}</span><small>{STATUS[call.status]}</small><ChevronDown
            size={12} className={open ? "rotate-180" : ""} aria-hidden/>
        </button>
        <div id={panelId} hidden={!open}>
            <div className="agent-step-payload">
                <p>{EFFECT[call.effect]}{validation ? " · 未执行" : call.highRisk ? " · 高风险操作" : ""}</p>
                {validation && <ValidationFailureNotice failure={validation} legacy={isLegacyValidation}/>}
                {musicReview ? <MusicGenerationReview key={call.id} call={call} busy={busy} active={activeMusicReview}
                                                      onAction={onAction}/> : reviewGeneration ?
                    <GenerationReview call={call} busy={busy} onAction={onAction}/> : preview &&
                    <div className="agent-change-preview">
                        <strong>{preview.summary}</strong>
                        {preview.changes.length > 0 &&
                            <ul>{preview.changes.map((change, index) => <li key={index}>{change}</li>)}</ul>}
                        {preview.target && /^\/(?!\/)/.test(preview.target.href) && <Link to={preview.target.href}
                                                                                          className="agent-change-link">查看{preview.target.label} ↗</Link>}
                    </div>}
                <WebResearchSources call={call}/>
                <ProjectImageSources call={call}/>
                <details className="agent-step-technical">
                    <summary>参数与返回结果</summary>
                    <div className="agent-step-payload-label">AI 原始参数</div>
                    <pre>{call.arguments}</pre>
                    {call.generationOverride && <>
                        <div className="agent-step-payload-label">用户确认的参数</div>
                        <pre>{call.generationOverride.arguments}</pre>
                    </>}
                    {call.result && <>
                        <div className="agent-step-payload-label">返回结果</div>
                        <pre>{call.result}</pre>
                    </>}
                </details>
                {call.error && !validation && <p className="text-destructive">{call.error}</p>}
            </div>
            {call.name !== "project_create" && <CreatedEntityLinks call={call}/>}
            {!readOnly && !reviewGeneration && !musicReview && call.status === "awaiting_approval" && recoverable && !unknown && !executing &&
                <div className="agent-step-actions">
                    <Button size="sm" disabled={busy}
                            onClick={() => onAction(run.id, "approve", call.id)}>批准此次操作</Button>
                    <Button size="sm" variant="outline" disabled={busy}
                            onClick={() => onAction(run.id, "reject", call.id)}>拒绝</Button>
                </div>}
        </div>
        {call.name === "project_create" && <CreatedEntityLinks call={call} allowProjectConversation={!readOnly}/>}
    </div>;
}

function ToolGroup({calls, ...props}: Omit<Parameters<typeof ToolCallRow>[0], "call"> & { calls: AgentToolCall[] }) {
    const {request} = useAgentActivityNavigation();
    const [open, setOpen] = useState(false);
    const panelId = useId();
    const handledRequest = useRef<number | undefined>(undefined);
    useEffect(() => {
        if (request?.runId === props.run.id && request.callId && calls.some((call) => call.id === request.callId) && handledRequest.current !== request.key) {
            handledRequest.current = request.key;
            setOpen(true);
        }
    }, [request, props.run.id, calls]);
    const running = calls.some((call) => call.status === "running");
    const attention = calls.some((call) => call.status === "awaiting_approval" || call.status === "unknown");
    const failed = calls.filter((call) => call.status === "failed").length;
    const titles = [...new Set(calls.map((call) => call.title))];
    const label = titles.slice(0, 2).join("、") + (titles.length > 2 ? "等" : "");
    return <div className="agent-tool-group">
        <button type="button" className="agent-tool-group-toggle" aria-expanded={open} aria-controls={panelId}
                onClick={() => setOpen((value) => !value)}>
            {running ? <LoaderCircle size={14} className="animate-spin motion-reduce:animate-none" aria-hidden/> :
                <Wrench size={14} aria-hidden/>}
            <span>{label}</span><small>{calls.length} 项{attention ? " · 待处理" : failed ? ` · 含 ${failed} 项失败` : running ? " · 执行中" : ""}</small><ChevronDown
            size={12} className={open ? "rotate-180" : ""} aria-hidden/>
        </button>
        <div id={panelId} className="agent-tool-group-calls" hidden={!open}>
            {calls.map((call) => <ToolCallRow key={call.id} {...props} call={call}/>)}
        </div>
    </div>;
}

export function AgentRunDetails({run, message, calls, busy, readOnly, onAction}: {
    run: AgentRun; message: ChatMessage; calls: AgentToolCall[];
    busy: boolean; readOnly?: boolean;
    onAction: (runId: string, action: RunAction, callId?: string) => void;
}) {
    const {request} = useAgentActivityNavigation();
    const [expanded, setExpanded] = useState(run.status === "running");
    const [hasExpanded, setHasExpanded] = useState(run.status === "running");
    const previousStatus = useRef(run.status);
    const sectionRef = useRef<HTMLElement>(null);
    const positionedRequest = useRef<number | undefined>(undefined);
    const panelId = useId();
    const ownedCalls = useMemo(() => calls.filter((call) => call.runId === run.id && call.threadId === run.threadId), [run.id, run.threadId, calls]);
    const activity = useMemo(() => buildRunActivity(run, ownedCalls), [run, ownedCalls]);
    const unknown = ownedCalls.some((call) => call.status === "unknown");
    const executing = ownedCalls.some((call) => call.status === "running");
    const pendingApproval = ownedCalls.some((call) => call.status === "awaiting_approval");
    const recoverable = canResumeAgentRun(run);
    const persisted = isPersistedToolRound(run, message, ownedCalls);
    const currentReasoning = persisted ? "" : message.reasoning?.trim();
    const currentContent = run.status === "running" && !persisted ? message.content : "";
    const reasoningActive = run.status === "running" && !!currentReasoning && !currentContent;
    const budgetPaused = run.status === "interrupted" && run.pauseReason === "model_step_limit";
    const failedCount = ownedCalls.filter((call) => call.status === "failed").length;
    const execution = useMemo(() => describeRunExecution(run, ownedCalls), [run, ownedCalls]);
    const missingLedger = Boolean(run.hasToolCalls && !ownedCalls.length);

    useEffect(() => {
        if (expanded) setHasExpanded(true);
    }, [expanded]);

    useEffect(() => {
        if (previousStatus.current !== run.status) {
            // Transition only: database updates must never undo a manual toggle.
            if (run.status === "running") setExpanded(true);
            else if (["completed", "cancelled", "failed", "interrupted"].includes(run.status)) setExpanded(false);
            previousStatus.current = run.status;
        }
    }, [run.status]);

    useEffect(() => {
        if (request?.runId !== run.id || positionedRequest.current === request.key) return;
        setExpanded(true);
        if (request.callId && !calls.some((call) => call.id === request.callId)) return;
        const frame = requestAnimationFrame(() => {
            const section = sectionRef.current;
            if (!section) return;
            positionedRequest.current = request.key;
            const target = request.callId
                ? [...section.querySelectorAll<HTMLElement>("[data-activity-call]")].find((element) => element.dataset.activityCall === request.callId) ?? section
                : section;
            const list = section.closest<HTMLElement>(".agent-message-list");
            if (list) list.scrollTop += target.getBoundingClientRect().top - list.getBoundingClientRect().top - 64;
            // Batch dialog manages its own focus. Approval/recovery navigation focuses the visible control.
            if (!request.batchId) target.querySelector<HTMLElement>("button:not([disabled])")?.focus({preventScroll: true});
        });
        return () => cancelAnimationFrame(frame);
    }, [request, run.id, calls]);

    return <section ref={sectionRef} className="agent-run-activity agent-execution-activity" aria-label="执行过程"
                    data-activity-run={run.id}>
        <Button variant="ghost" className="agent-run-summary agent-execution-summary h-auto justify-start rounded-none"
                aria-expanded={expanded} aria-controls={panelId} onClick={() => setExpanded((value) => !value)}>
            <RunElapsed run={run}/><ChevronDown size={14} className={expanded ? "rotate-180" : ""} aria-hidden/>
            <small>{execution.label}</small>
            {failedCount > 0 && <small className="agent-execution-failure-summary">含 {failedCount} 项失败</small>}
        </Button>
        <AgentWriteOutcomes run={run} calls={ownedCalls}/>
        <div id={panelId} className="agent-execution-timeline" hidden={!expanded}>
            {(expanded || hasExpanded) && <>
                <div className="agent-execution-explanation">
                    <p>{execution.detail}</p>
                    <Popover><PopoverTrigger asChild><Button variant="ghost" size="sm"
                                                             className="h-auto px-0 py-1 text-xs text-muted-foreground">执行记录</Button></PopoverTrigger>
                        <PopoverContent align="start" className="w-72 text-xs">
                            <p className="mb-3 text-muted-foreground">以下为本次执行记录，不代表作品已制作完成。</p>
                            <dl className="grid grid-cols-2 gap-x-3 gap-y-2">
                                <dt>模型请求</dt>
                                <dd>{execution.modelSteps ?? "未记录"}</dd>
                                <dt>工具调用</dt>
                                <dd>{missingLedger ? "记录不完整" : `${execution.counts.total} 项`}</dd>
                                <dt>调用已返回</dt>
                                <dd>{missingLedger ? "未记录" : `${execution.counts.completed} 项`}</dd>
                                <dt>失败 / 拒绝</dt>
                                <dd>{missingLedger ? "未记录" : `${execution.counts.failed} / ${execution.counts.rejected}`}</dd>
                                <dt>等待批准 / 待核实</dt>
                                <dd>{missingLedger ? "未记录" : `${execution.counts.waiting} / ${execution.counts.unknown}`}</dd>
                                <dt>最后请求提供的工具</dt>
                                <dd>{execution.offeredTools ?? "未记录"}</dd>
                                <dt>请求协议</dt>
                                <dd>{execution.protocol ?? "未记录"}</dd>
                            </dl>
                        </PopoverContent>
                    </Popover>
                </div>
                {activity.map((item) => item.kind === "text"
                    ? <Markdown key={item.id} {...MARKDOWN_PROPS}
                                className="agent-activity-narrative">{item.content}</Markdown>
                    : item.kind === "reasoning"
                        ? <ThinkingPanel key={item.id} reasoning={item.content} active={false}
                                         durationMs={item.durationMs}/>
                        : <ToolGroup key={item.id} calls={item.calls} run={run} busy={busy} readOnly={readOnly}
                                     unknown={unknown} executing={executing} onAction={onAction}/>)}
                {currentReasoning && <ThinkingPanel reasoning={currentReasoning} active={reasoningActive}
                                                    durationMs={message.reasoningDurationMs}/>}
                {currentContent &&
                    <Markdown {...MARKDOWN_PROPS} className="agent-activity-narrative">{currentContent}</Markdown>}
                {run.status === "running" &&
                    <div className="agent-activity-working" role="status"><LoaderCircle size={12}
                                                                                        className="animate-spin motion-reduce:animate-none"
                                                                                        aria-hidden/><span>{executing ? "正在执行工具" : currentContent ? "正在撰写" : "正在思考"}</span>
                    </div>}
                {run.plan && run.plan.length > 0 && <details className="agent-activity-plan">
                    <summary>执行计划
                        · {run.plan.filter((step) => step.status === "completed").length}/{run.plan.length}<ChevronDown
                            size={12} aria-hidden/></summary>
                    <ol className="agent-run-plan" aria-label="本次执行计划">{run.plan.map((step) => <li key={step.id}>
                        <StepIcon
                            status={step.status === "completed" ? "completed" : step.status === "in_progress" ? "running" : "pending"}/>
                        <span>{step.title}<small>{step.status === "completed" ? "已完成" : step.status === "in_progress" ? "进行中" : "待办"}</small></span>
                    </li>)}</ol>
                </details>}
            </>}
            {/* Keep mounted: review dialogs own unsaved drafts and navigation guards. */}
            <AgentGenerationResults runId={run.id}/>
            {unknown && <p role="status"
                           className="text-xs text-amber-500">上次操作的结果尚未确认，为避免重复执行，已暂停自动接续。请先核实已有结果，再结束本次执行。</p>}
            {!readOnly && recoverable && <div className="agent-step-actions">
                {!unknown && !pendingApproval && <Button size="sm" variant="outline" disabled={busy}
                                                         onClick={() => onAction(run.id, "resume")}>{budgetPaused ? `继续执行 · 最多 ${MODEL_STEPS_PER_SEGMENT} 轮` : "从已保存的步骤继续"}</Button>}
                <Button size="sm" variant="ghost" disabled={busy}
                        onClick={() => onAction(run.id, "cancel")}>结束本次执行</Button>
            </div>}
        </div>
    </section>;
}

import type {RunAction} from "./AgentRunDetails";
import {useAgentActivityNavigation} from "./AgentActivityNavigation";
import type {AgentRun} from "@/domain/agent";
import {ActionIcon, Flexbox} from "@lobehub/ui";
import {ChatHeader, ChatHeaderTitle} from "@lobehub/ui/chat";
import {Dropdown} from "antd";
import {ListTodo, MoreHorizontal, PanelLeft, PanelRight, Pencil, Trash2,} from "lucide-react";
import {type CSSProperties, lazy, Suspense, useCallback, useLayoutEffect, useRef, useState} from "react";
import {TopicListBody, TopicSidebar} from "@/components/agent/TopicSidebar";
import type {ComposerProps} from "@/components/agent/composerTypes";
import {FloatingComposer} from "@/components/agent/FloatingComposer";
import {
    CHAT_COMPOSER_SAFE,
    CHAT_CONTENT_MAX,
    CHAT_HEADER_HEIGHT,
    CHAT_SAFE_X,
    SIDEBAR_COLLAPSED_KEY,
} from "@/components/agent/agentTheme";
import {Sheet, SheetContent, SheetHeader, SheetTitle,} from "@/components/ui/sheet";
import type {ChatMessage, ChatThread, Id} from "@/domain/types";
// Rich transcript rendering (markdown, diagrams, syntax highlighting) is needed only
// once a thread contains messages. Keep the Agent runtime and composer mounted.
const MessageList = lazy(() => import("./MessageList").then((module) => ({default: module.MessageList})));

function readCollapsed(): boolean {
    try {
        return sessionStorage.getItem(SIDEBAR_COLLAPSED_KEY) === "1";
    } catch {
        return false;
    }
}

function writeCollapsed(collapsed: boolean) {
    try {
        sessionStorage.setItem(SIDEBAR_COLLAPSED_KEY, collapsed ? "1" : "0");
    } catch {
        /* ignore quota / private mode */
    }
}

function popupRoot(): HTMLElement {
    return document.querySelector<HTMLElement>(".agent-chat-root") ?? document.body;
}

/**
 * Chat workspace — lobehub Conversation layout:
 * collapsible TopicSidebar (md+) | ChatHeader + message stream +
 * floating composer. Below md, topics open in a left Sheet.
 */
export function ChatWorkspace({
                                  threads,
                                  activeThreadId,
                                  activeThread,
                                  messages,
                                  runs,
                                  retryableRunId,
                                  onRetryRun,
                                  onRunAction,
                                  composer,
                                  onSelectThread,
                                  onNewTopic,
                                  onRenameThread,
                                  onDeleteThread,
                                  onOpenTasks,
                                  onOpenTask,
                                  taskTitle,
                                  taskGoal,
                              }: {
    onOpenTasks: () => void;
    onOpenTask: () => void;
    taskTitle?: string;
    taskGoal?: string;
    threads: ChatThread[];
    activeThreadId?: Id;
    activeThread?: ChatThread;
    messages: ChatMessage[] | undefined;
    runs?: AgentRun[];
    retryableRunId?: string;
    onRetryRun: (id: string) => void;
    onRunAction: (runId: string, action: RunAction, callId?: string) => void;
    composer: ComposerProps;
    onSelectThread: (id: Id) => void;
    onNewTopic: () => void;
    onRenameThread: (thread: ChatThread) => void;
    onDeleteThread: (thread: ChatThread) => void;
}) {
    const [expanded, setExpanded] = useState(false);
    const {request: activityRequest} = useAgentActivityNavigation();
    useLayoutEffect(() => {
        if (activityRequest) setExpanded(false);
    }, [activityRequest]);
    const dockRef = useRef<HTMLDivElement>(null);
    useLayoutEffect(() => {
        const dock = dockRef.current;
        const column = dock?.parentElement;
        if (!dock || !column) return;
        const resize = new ResizeObserver(() => {
            if (dock.classList.contains("is-expanded")) return;
            column.style.setProperty("--agent-chat-composer-safe", `${dock.getBoundingClientRect().height + 16}px`);
        });
        resize.observe(dock);
        return () => resize.disconnect();
    }, []);
    const [collapsed, setCollapsed] = useState(readCollapsed);
    const [topicsOpen, setTopicsOpen] = useState(false);

    const toggleCollapsed = useCallback(() => {
        setCollapsed((prev) => {
            const next = !prev;
            writeCollapsed(next);
            return next;
        });
    }, []);

    const selectAndClose = useCallback(
        (id: Id) => {
            onSelectThread(id);
            setTopicsOpen(false);
        },
        [onSelectThread],
    );

    const newTopicAndClose = useCallback(() => {
        onNewTopic();
        setTopicsOpen(false);
    }, [onNewTopic]);

    return (
        <Flexbox
            horizontal
            height="100%"
            className="agent-conversation"
            style={
                {
                    minHeight: "100%",
                    maxHeight: "100%",
                    background: "transparent",
                    overflow: "hidden",
                    "--agent-chat-header-height": `${CHAT_HEADER_HEIGHT}px`,
                    "--agent-chat-safe-x": `${CHAT_SAFE_X}px`,
                    "--agent-chat-composer-safe": `${CHAT_COMPOSER_SAFE}px`,
                    "--agent-content-max": `${CHAT_CONTENT_MAX}px`,
                } as CSSProperties
            }
        >
            <div className="hidden h-full min-h-0 shrink-0 md:flex">
                <TopicSidebar
                    threads={threads}
                    activeThreadId={activeThreadId}
                    collapsed={collapsed}
                    onToggleCollapsed={toggleCollapsed}
                    onSelect={onSelectThread}
                    onNewTopic={onNewTopic}
                    onRename={onRenameThread}
                    onDelete={onDeleteThread}
                    onOpenTasks={onOpenTasks}
                />
            </div>

            <Sheet open={topicsOpen} onOpenChange={setTopicsOpen}>
                <SheetContent
                    side="right"
                    showCloseButton={false}
                    className="agent-chat-root agent-topic-sheet flex h-full w-[min(280px,85vw)] flex-col gap-0 border-[#202020] bg-[#0d0d0d] p-0 text-white sm:max-w-[280px]"
                >
                    <SheetHeader className="sr-only">
                        <SheetTitle>话题</SheetTitle>
                    </SheetHeader>
                    <Flexbox
                        direction="vertical"
                        height="100%"
                        width="100%"
                        className="agent-topic-sidebar"
                        style={{minHeight: 0, borderInlineEnd: "none"}}
                    >
                        <TopicListBody
                            threads={threads}
                            activeThreadId={activeThreadId}
                            onSelect={selectAndClose}
                            onNewTopic={newTopicAndClose}
                            onRename={onRenameThread}
                            onDelete={onDeleteThread}
                            onOpenTasks={onOpenTasks}
                        />
                    </Flexbox>
                </SheetContent>
            </Sheet>

            <Flexbox flex={1} height="100%" className="agent-chat-column min-w-0">
                <ChatHeader
                    className="agent-chat-header" style={expanded ? {visibility: "hidden"} : undefined}
                    left={
                        <ChatHeaderTitle
                            title={activeThread?.title ?? "对话"}
                            tag={
                                activeThread ? (
                                    <Dropdown
                                        trigger={["click"]}
                                        getPopupContainer={popupRoot}
                                        menu={{
                                            items: [
                                                {
                                                    key: "rename",
                                                    label: "重命名",
                                                    icon: <Pencil size={14}/>,
                                                    onClick: () => onRenameThread(activeThread),
                                                },
                                                {
                                                    key: "delete",
                                                    label: "删除",
                                                    icon: <Trash2 size={14}/>,
                                                    danger: true,
                                                    onClick: () => onDeleteThread(activeThread),
                                                },
                                            ],
                                        }}
                                    >
                    <span>
                      <ActionIcon icon={MoreHorizontal} title="更多" size="small"/>
                    </span>
                                    </Dropdown>
                                ) : undefined
                            }
                        />
                    }
                    right={
                        <Flexbox horizontal gap={4}>
                            {(taskTitle || (composer.projectId && !composer.blocked)) &&
                                <ActionIcon icon={ListTodo} title={taskTitle ? "任务详情" : "创建关联任务"}
                                            onClick={onOpenTask}/>}
                            <span className="md:hidden">
                <ActionIcon
                    icon={PanelLeft}
                    title="话题列表"
                    onClick={() => setTopicsOpen(true)}
                />
              </span>
                            <span className="hidden md:inline-flex">
                <ActionIcon
                    icon={collapsed ? PanelRight : PanelLeft}
                    title="侧栏"
                    onClick={toggleCollapsed}
                />
              </span>
                        </Flexbox>
                    }
                />
                <div className="agent-transcript-container" inert={expanded}
                     style={expanded ? {visibility: "hidden"} : undefined}>
                    {taskTitle && messages?.length === 0 ?
                        <div className="agent-task-conversation-empty"><ListTodo size={28}
                                                                                 strokeWidth={1.5}/><span>准备开始</span>
                            <h2>{taskTitle}</h2><p>{taskGoal}</p>
                            <div>
                                <button type="button" onClick={onOpenTask}>整理目标与清单</button>
                                {!composer.blocked && <button type="button"
                                                              onClick={() => composer.onChange("请根据当前任务目标和执行清单开始推进；如需补充关键信息，请先说明。")}>与助手一起开始</button>}
                            </div>
                            <small>也可以独立完成清单，随时回来确认成果。</small></div> : messages?.length ? <Suspense
                                fallback={<div className="agent-message-list" role="status">
                                    <div className="agent-content">正在加载对话…</div>
                                </div>}><MessageList messages={messages} runs={runs} retryableRunId={retryableRunId}
                                                     onRetryRun={onRetryRun} busy={composer.sending}
                                                     readOnly={composer.readOnly} onRunAction={onRunAction}/></Suspense> :
                            <div className="agent-message-list"
                                 aria-busy={messages === undefined}>{messages === undefined &&
                                <div className="agent-content" role="status">加载中…</div>}</div>}</div>
                <div ref={dockRef} className={`agent-composer-dock${expanded ? " is-expanded" : ""}`}>
                    <div className="agent-content">
                        <FloatingComposer {...composer} surface="detail" expanded={expanded}
                                          onExpandedChange={setExpanded}/>
                    </div>
                </div>
            </Flexbox>
        </Flexbox>
    );
}

import {Check, ChevronDown, LoaderCircle, TriangleAlert} from "lucide-react";
import type {ContextCompaction} from "@/domain/context";
import {formatTokenCount} from "@/lib/agent/contextUsage";

export function ContextCompactionDetails({record}: { record: ContextCompaction }) {
    const running = record.status === "running", done = record.status === "completed";
    const Icon = running ? LoaderCircle : done ? Check : TriangleAlert;
    return <details className="agent-compaction">
        <summary><Icon size={14}
                       className={running ? "animate-spin" : undefined}/>{running ? "正在整理较早的对话" : done ? "历史已整理" : record.status === "interrupted" ? "整理已中断" : "整理未完成"}<span>{record.coverage.length} 条</span><ChevronDown
            size={12}/></summary>
        <div className="agent-compaction-body">
            <p>{done ? `摘要已保存，约 ${formatTokenCount(record.beforeTokens)} → ${formatTokenCount(record.afterTokens ?? 0)} tokens；原始消息仍可在对话中查看。` : running ? "完成后自动接续回复。可通过输入框的停止按钮中断，未完成的摘要不会生效。" : `${record.error ?? "原始对话已保留。"} 使用回复上的重新生成或执行步骤中的继续操作重试。`}</p>
            {record.usage?.totalTokens !== undefined &&
                <p>整理用量：{formatTokenCount(record.usage.totalTokens)} tokens · 与回复用量分开统计</p>}
            {done && <pre>{record.content}</pre>}
            <details className="agent-compaction-source">
                <summary>查看摘要覆盖的原始消息</summary>
                {record.coverage.map((message) => <div key={message.id}>
                    <p>{message.role === "user" ? "你" : message.role === "assistant" ? "助手" : "系统"}</p>
                    <pre>{message.content}</pre>
                </div>)}</details>
        </div>
    </details>;
}

import {
    createToolLoading,
    DISCOVERY_TOOL_NAME,
    getOfferedToolNames,
    toolLoadingInstructions
} from "@/lib/agent/toolLoading";
import type {ReferenceAttachment} from "@/domain/references";
import {referenceSelectionCharacterBudget, selectReferenceContext} from "@/lib/agent/referenceContext";
import {requireVision, resolveVisionCapability} from "@/lib/ai/visionCapability";
import {getMemorySelection} from "@/db/memoryRetrieval";
import {withMemoryContext} from "@/lib/memory/retrieval";
import {filterProjectMemoryTools} from "@/lib/agent/memoryToolNames";
import {MemoryContextDetails} from "./MemoryContextDetails";
import {getTaskContext} from "@/lib/agent/taskContext";
import type {AgentTask} from "@/domain/agent";
import {type AgentInteractionMode, type AgentRun, GENERAL_AGENT_ID,} from "@/domain/agent";
import {ContextCompactionDetails} from "./ContextCompactionDetails";
import {normalizeContextPolicy, resolveContextCapacity,} from "@/lib/agent/contextPolicy";
import {
    budgetContext,
    buildContextMessages,
    findApplicableSummary,
    selectContextHistory,
} from "@/lib/agent/contextPlanner";
import {continuationExtraTokens} from "@/lib/agent/contextCompaction";
import type {ChatModelMetadata} from "@/lib/ai/modelMetadata";
import type {ChatMessage, ConnectorConfig} from "@/domain/types";
import {useDeferredValue, useMemo, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import * as Popover from "@radix-ui/react-popover";
import {X} from "lucide-react";
import {db} from "@/db/database";
import {assembleSkills, DEFAULT_SKILL_IDS} from "@/lib/agent/skills";
import {toolSchemas} from "@/lib/agent/tools";
import {estimateContextUsage, formatTokenCount,} from "@/lib/agent/contextUsage";

type ContextProps = {
    attachments?: ReferenceAttachment[];
    threadId?: string;
    projectId?: string;
    task?: AgentTask;
    interactionMode?: AgentInteractionMode;
    draft: string;
    messages: ChatMessage[];
    runs: AgentRun[];
    model: string;
    connector?: ConnectorConfig;
    modelMetadata?: Record<string, ChatModelMetadata>;
};

function useContextUsage({
                             attachments = [],
                             draft,
                             messages,
                             runs,
                             model,
                             connector,
                             modelMetadata,
                             interactionMode,
                             task,
                             threadId,
                             projectId,
                         }: ContextProps) {
    const config = useLiveQuery(() => db.agents.get(GENERAL_AGENT_ID), []);
    const loadedThread = useLiveQuery(
        () => (threadId ? db.chatThreads.get(threadId) : undefined),
        [threadId],
    );
    const thread = loadedThread?.id === threadId ? loadedThread : undefined;
    const records = useLiveQuery(
        () =>
            threadId
                ? db.contextCompactions
                    .where("threadId")
                    .equals(threadId)
                    .sortBy("createdAt")
                : [],
        [threadId],
    );
    const contextKey = JSON.stringify([
        threadId,
        config?.instructions,
        thread?.taskMode,
        interactionMode,
        task?.id,
        projectId,
    ]);
    const loadedContext = useLiveQuery(async () => {
        try {
            return {
                key: contextKey,
                context: await getTaskContext(
                    threadId,
                    config?.instructions ?? "",
                    thread?.taskMode,
                    interactionMode,
                    projectId,
                ),
                error: undefined,
            };
        } catch (error) {
            return {
                key: contextKey,
                context: undefined,
                error: error instanceof Error ? error.message : "项目上下文不可用",
            };
        }
    }, [contextKey]);
    const contextState =
        loadedContext?.key === contextKey ? loadedContext : undefined;
    const taskContext = contextState?.context;
    const deferredDraft = useDeferredValue(draft);
    const requestDraft = deferredDraft.trim() || (attachments.length ? "请结合附加的参考资料协助我。" : "");
    const previewPolicy = normalizeContextPolicy(
        threadId ? thread?.contextPolicy : config?.contextPolicy,
    );
    const memoryOptions = taskContext?.projectContext
        ? {
            projectId: taskContext.projectContext.projectId,
            threadId,
            draft: requestDraft,
            recentUserTurns: selectContextHistory(
                messages.filter((message) => message.threadId === threadId),
                previewPolicy,
            )
                .filter((message) => message.role === "user")
                .map((message) => message.content),
            taskTitle: taskContext.task?.title,
            taskGoal: taskContext.task?.goal,
            capacity: resolveContextCapacity(
                model,
                modelMetadata?.[model],
                connector?.definitionId,
                previewPolicy,
            ).capacity,
        }
        : undefined;
    // Dexie retains the previous value while a changed query resolves. Never label
    // an earlier project/draft's selection as the current request preview.
    const memoryKey = JSON.stringify(memoryOptions ?? null);
    const loadedMemory = useLiveQuery(async () => {
        try {
            return {
                key: memoryKey,
                selection: memoryOptions
                    ? await getMemorySelection(memoryOptions)
                    : undefined,
                error: undefined,
            };
        } catch (error) {
            return {
                key: memoryKey,
                selection: undefined,
                error: error instanceof Error ? error.message : "项目记忆暂时无法读取",
            };
        }
    }, [memoryKey]);
    const memoryState =
        loadedMemory?.key === memoryKey ? loadedMemory : undefined;
    const referenceOptions = {
        projectId: thread?.projectId ?? projectId,
        attachments,
        capacity: resolveContextCapacity(model, modelMetadata?.[model], connector?.definitionId, previewPolicy).capacity,
    };
    const referenceKey = JSON.stringify([threadId, contextKey, referenceOptions, model, connector?.definitionId, modelMetadata?.[model]]);
    const loadedReferences = useLiveQuery(async () => {
        try {
            const selection = await selectReferenceContext(referenceOptions.projectId, referenceOptions.attachments, referenceSelectionCharacterBudget(referenceOptions.capacity));
            if (selection?.images?.length) requireVision(await resolveVisionCapability(model, connector?.definitionId, modelMetadata?.[model]));
            return {key: referenceKey, selection, error: undefined};
        } catch (error) {
            return {
                key: referenceKey,
                selection: undefined,
                error: error instanceof Error ? error.message : "参考资料暂时无法读取"
            };
        }
    }, [referenceKey]);
    const referenceState = loadedReferences?.key === referenceKey ? loadedReferences : undefined;
    const latest = runs.at(-1);
    const activeRun =
        latest &&
        latest.threadId === threadId &&
        (latest.status === "running" ||
            latest.status === "waiting_approval" ||
            (latest.hasToolCalls &&
                (latest.status === "failed" || latest.status === "interrupted")))
            ? latest
            : undefined;
    return useMemo(() => {
        const policy =
            activeRun?.context?.policy ??
            normalizeContextPolicy(
                threadId ? thread?.contextPolicy : config?.contextPolicy,
            );
        const selected = selectContextHistory(
            messages.filter((message) => message.threadId === threadId),
            policy,
        );
        const summary = policy.autoCompress
            ? findApplicableSummary(
                selected,
                (records ?? []).filter((record) => record.threadId === threadId),
            )
            : undefined;
        const resolved =
            activeRun?.context ??
            resolveContextCapacity(
                model,
                modelMetadata?.[model],
                connector?.definitionId,
                policy,
            );
        const {capacity, capacitySource: source} = resolved;
        const skills = assembleSkills(
            interactionMode === "conversation"
                ? []
                : (config?.enabledSkillIds ?? DEFAULT_SKILL_IDS),
        );
        const instructions =
            activeRun?.agentSnapshot.instructions ??
            taskContext?.instructions ??
            config?.instructions ??
            "";
        const allowedNames = activeRun?.enabledToolNames ?? filterProjectMemoryTools([...new Set([...skills.enabledToolNames, ...(taskContext?.taskToolNames ?? [])])], taskContext?.projectContext?.projectId, interactionMode);
        const loading = activeRun ? activeRun.toolLoading : createToolLoading(interactionMode === "conversation" ? [] : config?.enabledSkillIds ?? DEFAULT_SKILL_IDS, allowedNames, taskContext?.projectKind);
        const offeredNames = activeRun ? getOfferedToolNames(activeRun) : getOfferedToolNames({
            enabledToolNames: loading ? [...allowedNames, DISCOVERY_TOOL_NAME] : allowedNames,
            toolLoading: loading,
            interactionMode
        });
        const skillInstructions = activeRun
            ? (activeRun.skillInstructions ?? "")
            : loading ? toolLoadingInstructions(loading) : skills.skillInstructions;
        const memorySelection =
            activeRun?.memorySelection ?? memoryState?.selection;
        const selectedReferences = activeRun ? activeRun.context?.selectedReferences : referenceState?.selection;
        const request = activeRun
            ? (activeRun.continuationMessages ?? activeRun.requestMessages)
            : withMemoryContext(
                buildContextMessages(
                    instructions,
                    skillInstructions,
                    selected,
                    requestDraft,
                    summary,
                    undefined,
                    selectedReferences,
                ),
                memorySelection,
            );
        const tools = toolSchemas(offeredNames);
        const budget = budgetContext(
            request,
            tools,
            capacity,
            !!(activeRun?.context?.summaryId ?? summary),
            activeRun ? continuationExtraTokens(activeRun) : 0,
        );
        const usage = estimateContextUsage({
            instructions,
            skillInstructions,
            messages: request,
            tools,
        });
        const projectContext =
            activeRun?.projectContext ?? taskContext?.projectContext;
        if (projectContext) usage.categories[0].label = "助手指令与项目事实";
        const overhead = Math.max(0, budget.estimatedTokens - usage.total);
        usage.categories.push({
            id: "envelope",
            label: "请求结构与续接状态",
            tokens: overhead,
            color: "#888888",
        });
        usage.total += overhead;
        const percent = capacity
            ? Math.min(100, (usage.total / capacity) * 100)
            : undefined;
        return {
            toolCount: offeredNames.length,
            capabilityCount: loading?.groups.length ?? 0,
            loadedCapabilities: loading?.groups.filter(group => loading.loadedGroupIds.includes(group.id)).map(group => group.name) ?? [],
            projectContext,
            memorySelection,
            selectedReferences,
            referencesLoading: !activeRun && attachments.length > 0 && !referenceState,
            error: activeRun ? undefined : contextState?.error ?? memoryState?.error ?? referenceState?.error,
            usage:
                (config &&
                    taskContext &&
                    (!taskContext.projectContext || memoryState) &&
                    (!attachments.length || (referenceState?.selection && !referenceState.error))) ||
                activeRun
                    ? usage
                    : undefined,
            capacity,
            percent: activeRun || !attachments.length || referenceState?.selection ? percent : undefined,
            activeRun,
            source,
            policy,
            budget,
            selectedCount: activeRun?.context?.history.length ?? selected.length,
            lastRecord: records?.filter((record) => record.threadId === threadId).at(-1),
        };
    }, [
        activeRun,
        config,
        thread,
        threadId,
        records,
        messages,
        requestDraft,
        attachments.length,
        referenceState,
        interactionMode,
        taskContext,
        memoryState,
        contextState?.error,
        model,
        modelMetadata,
        connector,
    ]);
}

export function ContextUsagePanel({
                                      onClose,
                                      onMemoryOpen,
