/**
 * Floating composer — left Agent/任务, right model (with connector inside) + send.
 */
export function FloatingComposer({
                                     threadId,
                                     attachments = [],
                                     referenceImports = [],
                                     onAttachReference,
                                     onRemoveReference,
                                     onImportReferences,
                                     onCancelReferenceImport,
                                     onRetryReferenceImport,
                                     value,
                                     sending,
                                     blocked,
                                     blockedReason,
                                     connectors,
                                     selectedConnectorId,
                                     model,
                                     reasoningEffort,
                                     onReasoningEffortChange,
                                     modelOptions,
                                     modelMetadata,
                                     probingModels,
                                     modelPolicy,
                                     modelWarning,
                                     chatMode,
                                     projects,
                                     projectId,
                                     projectRequired,
                                     projectLocked,
                                     onProjectChange,
                                     interactionMode,
                                     onChange,
                                     onSend,
                                     onStop,
                                     onConnectorChange,
                                     onModelChange,
                                     onChatModeChange,
                                     onInteractionModeChange,
                                     large,
                                     contextUsage,
                                     status,
                                     surface = "home",
                                     expanded = false,
                                     onExpandedChange,
                                 }: ComposerProps & {
    surface?: "home" | "detail";
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void
}) {
    const canSend = (Boolean(value.trim()) || attachments.length > 0) && referenceImports.length === 0 && !blocked && !sending && !projectRequired && !modelPolicy.incompatibleModels.includes(model.trim());
    const [libraryOpen, setLibraryOpen] = useState(false);
    const [projectAction, setProjectAction] = useState<"import" | "library" | File[]>();
    const fileInput = useRef<HTMLInputElement>(null);
    const [dragging, setDragging] = useState(false);
    const scope = `${threadId ?? "home"}/${projectId ?? ""}`;
    useEffect(() => {
        setLibraryOpen(false);
        setProjectAction(undefined);
        setDragging(false);
    }, [threadId]);

    function filesSelected(files: File[]) {
        if (!files.length || blocked || sending) return;
        if (!projectId) {
            setProjectAction(files);
            return;
        }
        onImportReferences?.(files);
    }

    function openReferenceAction(action: "import" | "library") {
        if (sending || blocked) return;
        if (!projectId) {
            setProjectAction(action);
            return;
        }
        if (action === "library") setLibraryOpen(true); else fileInput.current?.click();
    }

    useEffect(() => {
        if (!projectId || !projectAction) return;
        const action = projectAction;
        setProjectAction(undefined);
        if (action === "library") setLibraryOpen(true);
        else if (action === "import") fileInput.current?.click();
        else onImportReferences?.(action);
    }, [projectId, projectAction, onImportReferences]);
    const composing = useRef(false);
    const inputRef = useRef<ComponentRef<typeof Input.TextArea>>(null);
    useEffect(() => {
        inputRef.current?.focus({preventScroll: true});
    }, [expanded]);
    const [modelOpen, setModelOpen] = useState(false);

    const [sendShortcut, setSendShortcut] = useState<"enter" | "mod-enter">(() => {
        try {
            return localStorage.getItem("cuepoint.agent.sendShortcut") === "mod-enter" ? "mod-enter" : "enter";
        } catch {
            return "enter";
        }
    });
    const [listening, setListening] = useState(false);
    const speechRef = useRef<SpeechRecognitionLike | null>(null);
    const speechBaseRef = useRef("");
    const detail = surface === "detail";

    useEffect(() => {
        if (!expanded) return;
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key === "Escape" && !event.defaultPrevented && event.target instanceof Element && event.target.closest(".agent-composer-stack")) onExpandedChange?.(false);
        };
        window.addEventListener("keydown", onKeyDown);
        return () => window.removeEventListener("keydown", onKeyDown);
    }, [expanded, onExpandedChange]);

    useEffect(() => () => {
        const speech = speechRef.current;
        if (speech) {
            speech.onresult = null;
            speech.onend = null;
            speech.onerror = null;
            speech.stop();
        }
    }, []);

    const toggleVoiceInput = () => {
        if (listening) {
            speechRef.current?.stop();
            return;
        }
        const Recognition = speechRecognitionConstructor();
        if (!Recognition) {
            toast.info("当前浏览器不支持语音输入");
            return;
        }
        const recognition = new Recognition();
        speechBaseRef.current = value.trimEnd();
        recognition.continuous = true;
        recognition.interimResults = false;
        recognition.lang = "zh-CN";
        recognition.onresult = (event) => {
            const transcript = Array.from({length: event.results.length}, (_, index) => event.results[index]?.[0]?.transcript ?? "").join("").trim();
            onChange([speechBaseRef.current, transcript].filter(Boolean).join(" "));
        };
        recognition.onend = () => {
            setListening(false);
            speechRef.current = null;
        };
        recognition.onerror = () => {
            setListening(false);
            speechRef.current = null;
            toast.error("语音输入失败，请重试");
        };
        speechRef.current = recognition;
        setListening(true);
        try {
            recognition.start();
        } catch {
            speechRef.current = null;
            setListening(false);
            toast.error("无法启动语音输入，请检查浏览器的麦克风权限");
        }
    };

    const trySend = () => {
        if (canSend && !listening) onSend();
    };

    return (
        <div className={`agent-composer-stack${expanded ? " is-expanded" : ""}`}>
            {status ? <div className="agent-composer-status">{status}</div> : null}
            <div className={`agent-composer agent-composer-refined${dragging ? " reference-dragging" : ""}`}
                 onDragOver={(event) => {
                     if (event.dataTransfer.types.includes("Files")) {
                         event.preventDefault();
                         setDragging(true);
                     }
                 }}
                 onDragLeave={(event) => {
                     if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setDragging(false);
                 }}
                 onDrop={(event) => {
                     if (!event.dataTransfer.types.includes("Files")) return;
                     event.preventDefault();
                     setDragging(false);
                     filesSelected(Array.from(event.dataTransfer.files));
                 }}
                 onPaste={(event) => {
                     const images = Array.from(event.clipboardData.items).filter((item) => item.kind === "file" && item.type.startsWith("image/")).map((item) => item.getAsFile()).filter((file): file is File => !!file);
                     if (images.length) {
                         if (!event.clipboardData.getData("text/plain")) event.preventDefault();
                         filesSelected(images);
                     }
                 }}>
                <input ref={fileInput} type="file" accept={REFERENCE_ACCEPT} multiple hidden onChange={(event) => {
                    filesSelected(Array.from(event.target.files ?? []));
                    event.target.value = "";
                }}/>
                <ReferenceAttachments projectId={projectId} attachments={attachments} onRemove={onRemoveReference}/>
                {referenceImports.length > 0 &&
                    <div className="reference-imports" aria-live="polite">{referenceImports.map((job) => <div
                        key={job.id}>{job.status === "importing" ?
                        <LoaderCircle size={14} className="reference-spinner"/> : <span
                            aria-hidden>!</span>}<span><strong>{job.filename}</strong><small>{job.error ?? "正在本地导入与解析…"}</small></span>{job.status === "failed" &&
                        <button type="button" aria-label={`重试导入 ${job.filename}`}
                                onClick={() => onRetryReferenceImport?.(job)}><RotateCcw size={14}/></button>}
                        <button type="button" aria-label={`取消附件 ${job.filename}`}
                                onClick={() => onCancelReferenceImport?.(job.id)}><X size={14}/></button>
                    </div>)}</div>}
                {attachments.length > 0 &&
                    <p className="reference-send-note">发送后，所选图片及文档提取文字将分享给当前模型；超长内容按上下文预算读取。</p>}
                {dragging && <div className="reference-drop-hint">松开以导入参考资料</div>}
                <Input.TextArea
                    ref={inputRef}
                    readOnly={listening}
                    value={value}
                    variant="borderless"
                    placeholder={blocked ? blockedReason ?? "重新打开任务后可继续对话" : projectRequired ? "先选择项目，再描述你想完成的事…" : surface === "home" && chatMode === "task" ? "描述你想完成的事，与助手一起明确需求…" : "提问、创建内容或启动任务"}
                    autoSize={expanded ? false : {minRows: large ? 3 : 2, maxRows: 10}}
                    className="agent-composer-input"
                    onChange={(event) => onChange(event.target.value)}
                    onCompositionStart={() => {
                        composing.current = true;
                    }}
                    onCompositionEnd={() => {
                        composing.current = false;
                    }}
                    onPressEnter={(event) => {
                        if (composing.current || event.nativeEvent.isComposing || event.shiftKey || event.altKey) return;
                        if (expanded) {
                            if (event.metaKey || event.ctrlKey) {
                                event.preventDefault();
                                trySend();
                            }
                            return;
                        }
                        if (detail && sendShortcut === "mod-enter" && !(event.metaKey || event.ctrlKey)) return;
                        if (detail && !expanded && sendShortcut === "enter" && (event.metaKey || event.ctrlKey)) return;
                        event.preventDefault();
                        trySend();
                    }}
                />
                {modelWarning ? <div role="status" style={{
                    padding: "0 16px 8px",
                    fontSize: 12,
                    color: "#e0b878"
                }}>{modelWarning}</div> : null}
                <div className="agent-composer-footer">
                    <div className="agent-composer-cluster">
                        <div className="agent-composer-scope"><ProjectPicker projects={projects} projectId={projectId}
                                                                             required={projectRequired}
                                                                             locked={projectLocked}
                                                                             onChange={onProjectChange}/>
                            {!detail && <ModeSwitch mode={chatMode} onChange={onChatModeChange}/>}</div>
                        <ComposerPlusMenu threadId={threadId} projectId={projectId}
                                          onImport={() => openReferenceAction("import")}
                                          onLibrary={() => openReferenceAction("library")}/>
                        {detail ? <button type="button" className="agent-chip agent-control agent-control-icon"
                                          aria-label={expanded ? "退出全屏编辑" : "展开编辑器"}
                                          onClick={() => onExpandedChange?.(!expanded)}>
                            {expanded ? <Minimize2 size={17} aria-hidden/> : <Expand size={17} aria-hidden/>}
                        </button> : null}
                    </div>

                    <div className="agent-composer-cluster agent-composer-cluster-right">
                        <ModelSelectTrigger
                            trigger={model ?
                                <ModelSettingsMenu connector={connectors.find((c) => c.id === selectedConnectorId)}
                                                   model={model} effort={reasoningEffort}
                                                   onChange={onReasoningEffortChange}
                                                   onChooseModel={() => setModelOpen(true)}/> : undefined}
                            open={modelOpen}
                            onOpenChange={setModelOpen}
                            model={model}
                            modelOptions={modelOptions}
                            modelMetadata={modelMetadata}
                            probingModels={probingModels}
                            modelPolicy={modelPolicy}
                            connectors={connectors}
                            selectedConnectorId={selectedConnectorId}
                            onConnectorChange={onConnectorChange}
                            onModelChange={onModelChange}
                        />
                        {detail ? <button type="button"
                                          className={`agent-chip agent-control agent-control-icon agent-voice-button${listening ? " is-active" : ""}`}
                                          aria-label={listening ? "停止语音输入" : "语音输入"}
                                          onClick={toggleVoiceInput} disabled={sending}
                                          title={listening ? "停止语音输入" : "语音输入"}><Mic size={17} aria-hidden/>
                        </button> : null}
                        <div className="agent-composer-send-group">
                            <SendCircleButton sending={sending} canSend={canSend && !listening} onSend={trySend}
                                              onStop={onStop}/>
                            {detail && !sending ? <Dropdown
                                trigger={["click"]}
                                placement="topRight"
                                getPopupContainer={popupRoot}
                                menu={{
                                    className: "agent-composer-menu",
                                    selectedKeys: [expanded ? "mod-enter" : sendShortcut],
                                    items: [
                                        {
                                            key: "enter",
                                            disabled: expanded,
                                            label: <span
                                                className="agent-control-option"><span>按 Enter 发送 {!expanded && sendShortcut === "enter" &&
                                                <Check size={14}/>}</span><small>Shift + Enter 换行</small></span>
                                        },
                                        {
                                            key: "mod-enter",
                                            label: <span
                                                className="agent-control-option"><span>按 ⌘ / Ctrl + Enter 发送 {(expanded || sendShortcut === "mod-enter") &&
                                                <Check size={14}/>}</span><small>Enter 换行</small></span>
                                        },
                                    ],
                                    onClick: ({key}) => {
                                        setSendShortcut(key as "enter" | "mod-enter");
                                        try {
                                            localStorage.setItem("cuepoint.agent.sendShortcut", key);
                                        } catch { /* Current page still uses the selection. */
                                        }
                                    },
                                }}
                            >
                                <button type="button" className="agent-send-menu-trigger" aria-label="发送方式">
                                    <ChevronDown size={13} aria-hidden/></button>
                            </Dropdown> : null}
                        </div>
                    </div>
                </div>
            </div>
            {detail ? <div className="agent-composer-controlbar">
                <div className="agent-composer-cluster">
                    <InteractionModeSwitch mode={interactionMode} onChange={onInteractionModeChange}/>
                </div>
                <div className="agent-composer-cluster agent-composer-permissions"><AgentControls/>{contextUsage}</div>
            </div> : null}
            {projectId &&
                <ReferenceLibrary key={scope} projectId={projectId} open={libraryOpen} onOpenChange={setLibraryOpen}
                                  selected={attachments} onSelect={(attachment) => onAttachReference?.(attachment)}
                                  onImport={() => fileInput.current?.click()}/>}
            <Dialog open={!!projectAction && !projectId} onOpenChange={(open) => {
                if (!open) setProjectAction(undefined);
            }}><DialogContent
                className="reference-dialog reference-project-dialog"><DialogHeader><DialogTitle>先为资料选择项目</DialogTitle><DialogDescription>{projectLocked ? "当前对话未绑定项目且已开始，请新开一个项目对话导入资料。" : "资料保存在所选项目中；你的消息草稿会保留。"}</DialogDescription></DialogHeader><ProjectPicker
                projects={projects} projectId={projectId} locked={projectLocked} allowClear={false}
                onChange={onProjectChange}/><p className="reference-note">支持 JPEG / PNG / WebP（10 MB）、TXT / MD（5
                MB）、PDF / DOCX（20 MB），每次最多 10 个文件。导入仅在本地解析。</p></DialogContent></Dialog>
        </div>
    );
}

import {useId, useRef, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {Input, Select} from "antd";
import {Link} from "@tanstack/react-router";
import {ArrowUpRight, Image, LoaderCircle, RotateCcw, Video} from "lucide-react";
import {toast} from "sonner";
import {db} from "@/db/database";
import {getGenerationPreferenceState, saveGenerationPreference} from "@/db/generationPreferences";
import type {AgentToolCall} from "@/domain/agent";
import {IMAGE_RATIOS, VIDEO_RATIOS} from "@/domain/output";
import {Button} from "@/components/ui/button";
import {Checkbox} from "@/components/ui/checkbox";
import {
    GENERATION_PROFILES,
    type GenerationSubmitArgs,
    generationSubmitSchema,
    profileRequest
} from "@/lib/agent/generationProfiles";
import {reviewAndApproveGeneration} from "@/lib/agent/generationReview";
import {recommendGenerationSelection} from "@/lib/agent/generationSelection";
import {applyGenerationSelection} from "@/lib/agent/generationReviewDraft";
import type {RunAction} from "./AgentRunDetails";

const PROVIDER_LABELS = {apimart: "APIMart", aihubmix: "AIHubMix"};

function popupRoot() {
    return document.querySelector<HTMLElement>(".agent-chat-root") ?? document.body;
}

function Choice({label, value, options, onChange, disabled}: {
    label: string; value?: string; options: Array<{ value: string; label: string; disabled?: boolean }>;
    onChange: (value: string) => void; disabled?: boolean;
}) {
    const id = useId();
    return <div className="agent-generation-field"><label htmlFor={id}>{label}</label>
        <Select id={id} value={value} options={options} onChange={onChange} disabled={disabled} variant="borderless"
                getPopupContainer={(trigger: HTMLElement) => trigger.closest<HTMLElement>('[role=dialog]') ?? popupRoot()}
                popupMatchSelectWidth virtual={false} className="agent-generation-choice"/>
    </div>;
}

const options = (values: readonly (string | number)[]) => values.map((value) => ({
    value: String(value),
    label: String(value)
}));

/** The model's proposal remains immutable; only confirmed overrides become executable. */
export function GenerationReview({call, busy, onAction}: {
    call: AgentToolCall; busy: boolean; onAction: (runId: string, action: RunAction, callId?: string) => void;
}) {
    let raw: unknown;
    try {
        raw = JSON.parse(call.arguments);
    } catch {
        raw = undefined;
    }
    const parsed = generationSubmitSchema.safeParse(raw);
    if (!parsed.success || !call.preview?.revision) return <div><p
        role="alert">生成提案不完整，请取消后让助手重新准备。</p><Button variant="ghost" size="sm" disabled={busy}
                                                                       onClick={() => onAction(call.runId, "reject", call.id)}>取消本次生成</Button>
    </div>;
    return <GenerationReviewForm key={call.id} call={call} initial={parsed.data} busy={busy} onAction={onAction}/>;
}

function GenerationReviewForm({call, initial, busy, onAction}: {
    call: AgentToolCall;
    initial: GenerationSubmitArgs;
    busy: boolean;
    onAction: (runId: string, action: RunAction, callId?: string) => void;
}) {
    const [draft, setDraft] = useState(initial);
    const [saving, setSaving] = useState(false);
    const [remember, setRemember] = useState(false);
    const [error, setError] = useState<string>();
    const [notice, setNotice] = useState<string>();
    const savingRef = useRef(false);
    const connectors = useLiveQuery(() => db.connectors.toArray(), []);
    const preferenceState = useLiveQuery(getGenerationPreferenceState, []);
    const project = useLiveQuery(async () => (await db.projects.get(initial.target.projectId)) ?? null, [initial.target.projectId]);
    const kind = initial.target.kind === "shot" && initial.target.slot === "clip" ? "video" : "image";
    const title = kind === "image" ? "图片" : "视频";
    const Icon = kind === "image" ? Image : Video;
    const selected = connectors?.find((item) => item.id === draft.connectorId);
    const provider = selected?.definitionId;
    const validProvider = provider === "apimart" || provider === "aihubmix" ? provider : undefined;
    const recommendation = connectors && preferenceState && project !== undefined ? recommendGenerationSelection({
        kind,
        connectors,
        projectDefaults: project?.generationDefaults,
        preferences: preferenceState.preferences,
        preferenceIssues: preferenceState.issues,
    }) : undefined;
    const hasDefault = Boolean(preferenceState?.preferences[kind] || preferenceState?.issues[kind]);
    let validation: string | undefined;
    try {
        if (!connectors) throw new Error("正在读取生成连接…");
        if (!selected?.apiKey.trim() || !validProvider) throw new Error("请选择已配置密钥的生成连接。");
        if (!draft.prompt.trim()) throw new Error("请填写画面描述。");
        profileRequest(generationSubmitSchema.parse(draft), validProvider);
    } catch (cause) {
        validation = cause instanceof Error && cause.name !== "ZodError" ? cause.message : "请检查画面描述与生成参数。";
    }
    const disabled = busy || saving;

    async function confirm() {
        if (savingRef.current || busy || validation) return;
        savingRef.current = true;
        setSaving(true);
        setError(undefined);
        try {
            await reviewAndApproveGeneration(call.runId, call.id, draft, {
                arguments: call.arguments,
                revision: call.preview!.revision!
            });
            if (remember) {
                const parameters = {...draft.parameters};
                delete parameters.mode;
                if (parameters.aspectRatio === "adaptive") delete parameters.aspectRatio;
                await saveGenerationPreference(kind, {connectorId: draft.connectorId, model: draft.model, parameters})
                    .catch(() => toast.error("本次生成已确认，但默认配置保存失败，请稍后重试。"));
            }
            onAction(call.runId, "resume");
        } catch (cause) {
            setError(cause instanceof Error ? cause.message : "确认失败，请重试。");
        } finally {
            savingRef.current = false;
            setSaving(false);
        }
    }

    return <div className="agent-generation-review" aria-label={`确认${title}生成`}>
        <div className="agent-generation-review-heading"><Icon size={18}
                                                               aria-hidden/><strong>确认{title}生成</strong><span>AI 已准备</span>
        </div>
        <p className="agent-generation-review-intro">可以直接确认，也可以调整下面的配置。</p>
        {call.preview?.target && /^\/(?!\/)/.test(call.preview.target.href) && <Link className="agent-generation-target"
                                                                                     to={call.preview.target.href}>{call.preview.target.label}<ArrowUpRight
            size={13} aria-hidden/></Link>}
        {recommendation && ["project", "global"].includes(recommendation.source) &&
            <div className="agent-generation-default">
                <span>{recommendation.status === "ready" ? `${recommendation.source === "project" ? "项目" : "我的"}默认 · ${recommendation.recommendation?.model}` : recommendation.issues.join("；")}</span>
                {recommendation.recommendation && <button type="button" disabled={disabled} onClick={() => {
                    const selection = recommendation.recommendation!;
                    const selectedProvider = connectors?.find((item) => item.id === selection.connectorId)?.definitionId;
                    if (selectedProvider === "apimart" || selectedProvider === "aihubmix") {
                        setDraft(applyGenerationSelection(draft, selection, selectedProvider));
                        setError(undefined);
                        setNotice("已应用默认配置，生成方式沿用本次参考素材。");
                    }
                }}>应用默认</button>}
            </div>}
        <GenerationConfigurationFields draft={draft} onChange={setDraft} disabled={disabled}/>
        {notice && <p className="agent-generation-form-note" role="status">{notice}</p>}
        <div className="agent-generation-remember"><label><Checkbox checked={remember} disabled={disabled}
                                                                    onCheckedChange={(value) => setRemember(value === true)}/>设为默认{title}生成配置</label>
            {hasDefault && <button type="button" className="agent-generation-reset" disabled={disabled} onClick={() => {
                if (savingRef.current) return;
                savingRef.current = true;
                setSaving(true);
                void saveGenerationPreference(kind, null).then(() => toast.success(`已清除默认${title}配置`)).catch(() => toast.error("清除默认配置失败，请重试。"))
                    .finally(() => {
                        savingRef.current = false;
                        setSaving(false);
                    });
            }}>清除已保存的默认</button>}
        </div>
        {remember &&
            <p className="agent-generation-form-note">用于未设置项目默认值的后续生成，仅记住连接、模型和通用参数。</p>}
        {(error || validation) && <p role="alert" className="agent-generation-form-error">{error ?? validation}</p>}
        <div className="agent-generation-confirm-actions">
            <Button size="sm" disabled={disabled || Boolean(validation)} onClick={() => void confirm()}>{saving &&
                <LoaderCircle size={14} className="animate-spin motion-reduce:animate-none"/>}确认并生成{title}</Button>
            <Button size="sm" variant="ghost" disabled={disabled}
                    onClick={() => onAction(call.runId, "reject", call.id)}>取消本次生成</Button>
            <button type="button" className="agent-generation-reset" disabled={disabled} onClick={() => {
                setDraft(initial);
                setError(undefined);
                setNotice(undefined);
            }}><RotateCcw size={13} aria-hidden/>恢复 AI 建议
            </button>
        </div>
        <p className="agent-generation-cost-note">确认后向所选供应商提交，可能产生费用。生成结果会先保存到本地。</p>
    </div>;
}

/** Shared configuration controls for single requests and durable batch drafts. */
export function GenerationConfigurationFields({draft, onChange, disabled}: {
    draft: GenerationSubmitArgs;
    onChange: (draft: GenerationSubmitArgs) => void;
    disabled: boolean
}) {
    const promptId = useId();
    const connectors = useLiveQuery(() => db.connectors.toArray(), []);
    const kind = draft.target.kind === 'shot' && draft.target.slot === 'clip' ? 'video' : 'image';
    const selected = connectors?.find(item => item.id === draft.connectorId);
    const provider = selected?.definitionId;
    const validProvider = provider === 'apimart' || provider === 'aihubmix' ? provider : undefined;
    const choices = (connectors ?? []).filter(item => item.definitionId === 'apimart' || item.definitionId === 'aihubmix');
    const models = GENERATION_PROFILES.filter(item => item.provider === provider && item.kind === kind);
    const profile = models.find(item => item.model === draft.model);
    const p = draft.parameters;
    const frames = draft.inputs.some(input => ['first-frame', 'last-frame'].includes(input.role));
    const references = draft.inputs.length > 0 && !frames;
    const referenceVideos = draft.inputs.filter(input => input.role === 'reference-video').length;
    const patch = (parameters: GenerationSubmitArgs['parameters']) => onChange({
        ...draft,
        parameters: {...draft.parameters, ...parameters}
    });

    function changeConnection(connectorId: string) {
        const connection = choices.find(item => item.id === connectorId);
        const supported = GENERATION_PROFILES.filter(profile => profile.provider === connection?.definitionId && profile.kind === kind);
        const model = supported.find(profile => profile.model === draft.model)?.model ?? supported[0]?.model;
        if (model && connection && (connection.definitionId === 'apimart' || connection.definitionId === 'aihubmix')) onChange(applyGenerationSelection(draft, {
            connectorId,
            model,
            parameters: {}
        }, connection.definitionId));
    }

    return <>
        <div className="agent-generation-fields">
            <Choice label="供应商连接" value={draft.connectorId} disabled={disabled} options={[
                ...choices.map((item) => ({
                    value: item.id,
                    label: `${PROVIDER_LABELS[item.definitionId as keyof typeof PROVIDER_LABELS]}${item.label ? ` · ${item.label}` : ""}${!item.apiKey.trim() ? "（未配置密钥）" : ""}`,
                    disabled: !item.apiKey.trim()
                })),
                ...(!selected ? [{
                    value: draft.connectorId,
                    label: connectors ? "原连接已不可用" : "读取连接…",
                    disabled: true
                }] : []),
            ]} onChange={changeConnection}/>
            <Choice label="生成模型" value={draft.model} disabled={disabled || !models.length}
                    options={models.map((model) => ({value: model.model, label: model.label}))} onChange={(model) => {
                if (validProvider) onChange(applyGenerationSelection(draft, {
                    connectorId: draft.connectorId,
                    model,
                    parameters: {}
                }, validProvider));
            }}/>
        </div>
        <div className="agent-generation-field"><label htmlFor={promptId}>画面描述</label><Input.TextArea id={promptId}
                                                                                                          value={draft.prompt}
                                                                                                          onChange={(event) => {
                                                                                                              onChange({
                                                                                                                  ...draft,
                                                                                                                  prompt: event.target.value
                                                                                                              });
                                                                                                          }}
                                                                                                          disabled={disabled}
                                                                                                          autoSize={{
                                                                                                              minRows: 3,
                                                                                                              maxRows: 9
                                                                                                          }}
                                                                                                          maxLength={32000}
                                                                                                          variant="borderless"/>
        </div>
        <div className="agent-generation-fields agent-generation-parameters">
            {kind === "image" ? <>
                <Choice label={provider === "aihubmix" ? "图片尺寸" : "图片比例"} value={p.size ?? "auto"}
                        disabled={disabled}
                        options={provider === "aihubmix" ? options(["auto", "1024x1024", "1536x1024", "1024x1536"]) : options(profile && "sizes" in profile ? profile.sizes : ["auto", ...IMAGE_RATIOS])}
                        onChange={(size) => patch({size})}/>
                {provider === "aihubmix" ? <Choice label="画质" value={p.quality ?? "default"} disabled={disabled}
                                                   options={[{value: "default", label: "模型默认"}, {
                                                       value: "low",
                                                       label: "低"
                                                   }, {value: "medium", label: "中"}, {value: "high", label: "高"}]}
                                                   onChange={(quality) => patch({quality: quality === "default" ? undefined : quality as "low" | "medium" | "high"})}/>
                    : <Choice label="分辨率" value={p.resolution ?? "1k"} disabled={disabled}
                              options={options(["1k", "2k", "4k"])} onChange={(resolution) => patch({resolution})}/>}
                {profile && "qualities" in profile &&
                    <Choice label="画质" value={p.quality ?? "auto"} disabled={disabled}
                            options={options(profile.qualities)}
                            onChange={(quality) => patch({quality: quality as NonNullable<GenerationSubmitArgs["parameters"]["quality"]>})}/>}
                {profile && "versions" in profile &&
                    <Choice label="版本" value={p.version ?? "flare"} disabled={disabled}
                            options={[{value: "flare", label: "flare"}, {value: "sunburst", label: "sunburst"}]}
                            onChange={(version) => patch({version: version as "flare" | "sunburst"})}/>}
            </> : <>
                <Choice label="分辨率" value={p.resolution ?? (provider === "aihubmix" ? "720p" : "2K")}
                        disabled={disabled}
                        options={options(provider === "aihubmix" ? referenceVideos ? ["720p"] : ["720p", "1080p", "4K"] : ["768P", "2K"])}
                        onChange={(resolution) => patch({resolution, ...(provider === "aihubmix" && resolution !== "720p" ? {duration: 8} : {})})}/>
                <Choice label="时长（秒）" value={String(p.duration ?? (provider === "aihubmix" ? 8 : 5))}
                        disabled={disabled}
                        options={options(provider === "aihubmix" ? (p.resolution && p.resolution !== "720p" || references) ? [8] : [4, 6, 8] : Array.from({length: 12}, (_, i) => i + 4))}
                        onChange={(duration) => patch({duration: Number(duration)})}/>
                {!(frames && provider === "apimart") && <Choice label="视频比例"
                                                                value={p.aspectRatio ?? (references && provider === "apimart" ? "adaptive" : "16:9")}
                                                                disabled={disabled}
                                                                options={options(provider === "aihubmix" ? ["16:9", "9:16"] : [...VIDEO_RATIOS, ...(references ? ["adaptive"] : [])])}
                                                                onChange={(aspectRatio) => patch({aspectRatio})}/>}
            </>}
        </div>
        {profile && "qualities" in profile &&
            <p className="agent-generation-form-note">auto 会按最高档预扣，完成后再按实际用量结算。</p>}
