import * as Popover from "@radix-ui/react-popover";
import {ArrowLeft, Check, ChevronDown, Folder, Plus, Search, X} from "lucide-react";
import {useId, useMemo, useRef, useState} from "react";
import {toast} from "sonner";
import type {Id, Project, ProjectKind} from "@/domain/types";
import {createAudioMusicProject, createProject} from "@/db/repo";

import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {Tabs, TabsList, TabsTrigger} from "@/components/ui/tabs";

export function ProjectPicker({projects, projectId, required, locked, onChange, allowClear = true, allLabel}: {
    projects: Project[]; projectId?: Id; required?: boolean; locked?: boolean;
    onChange: (projectId: Id | undefined) => void | Promise<void>;
    allowClear?: boolean; allLabel?: string;
}) {
    const [open, setOpen] = useState(false);
    const [query, setQuery] = useState("");
    const [creating, setCreating] = useState(false);
    const [name, setName] = useState("");
    const [kind, setKind] = useState<ProjectKind>("video");
    const [pending, setPending] = useState(false);
    const saveLock = useRef(false);
    const trigger = useRef<HTMLButtonElement>(null);
    const listId = useId();
    const selected = projects.find((project) => project.id === projectId);
    const filtered = useMemo(() => {
        const needle = query.trim().toLocaleLowerCase();
        return projects.filter((project) => !needle || `${project.name} ${project.brief ?? ""}`.toLocaleLowerCase().includes(needle));
    }, [projects, query]);

    async function choose(next?: Id) {
        if (locked || saveLock.current) return;
        saveLock.current = true;
        setPending(true);
        try {
            await onChange(next);
            setOpen(false);
            setQuery("");
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "项目选择失败");
        } finally {
            saveLock.current = false;
            setPending(false);
        }
    }

    async function create() {
        if (locked || saveLock.current || !name.trim()) return;
        saveLock.current = true;
        setPending(true);
        try {
            const project = kind === "video" ? await createProject(name.trim()) : await createAudioMusicProject(name.trim(), kind);
            await onChange(project.id);
            setCreating(false);
            setOpen(false);
            setName("");
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "创建项目失败");
        } finally {
            saveLock.current = false;
            setPending(false);
        }
    }

    return <Popover.Root open={open && !locked} onOpenChange={(next) => {
        if (!locked && !pending) setOpen(next);
        if (!next) {
            setQuery("");
            setCreating(false);
        }
    }}>
        <Popover.Trigger asChild>
            <button ref={trigger} type="button"
                    className={`agent-chip agent-project-trigger${required && !selected ? " is-required" : ""}`}
                    aria-label={projectId ? `项目：${selected?.name ?? "项目不可用"}` : "选择项目"} disabled={locked}
                    title={locked ? projectId ? "此对话的项目已固定；处理其他项目请新开对话" : "此对话已开始；在项目中工作请新开对话" : undefined}>
                <Folder size={15}
                        aria-hidden/><span>{selected?.name ?? (projectId ? "项目不可用" : locked ? "未绑定项目" : allLabel ?? (required ? "先选择项目" : "选择项目"))}</span>{!locked &&
                <ChevronDown size={12} aria-hidden/>}
            </button>
        </Popover.Trigger>
        <Popover.Portal
            container={trigger.current?.closest<HTMLElement>('[role="dialog"]') ?? document.querySelector<HTMLElement>(".agent-chat-root") ?? undefined}>
            <Popover.Content side="top" align="start" sideOffset={8} collisionPadding={12}
                             className="agent-project-picker" aria-label={creating ? "新建项目" : "选择项目"}
                             onKeyDown={(event) => {
                                 if (event.key === "Escape") return;
                                 if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                                     const options = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="option"]')];
                                     const index = options.indexOf(document.activeElement as HTMLButtonElement);
                                     const next = event.key === "ArrowDown" ? (index + 1) % options.length : (index <= 0 ? options.length - 1 : index - 1);
                                     if (options[next]) {
                                         event.preventDefault();
                                         options[next].focus();
                                     }
                                 }
                             }}>
                {creating ? <div className="agent-project-create-form">
                    <Button type="button" variant="ghost" size="sm" onClick={() => setCreating(false)}
                            disabled={pending}><ArrowLeft size={14}/>返回项目</Button>
                    <h3>给创作一个空间</h3><p>先起一个名字，创作设定可以稍后补充。</p>
                    <Tabs value={kind} onValueChange={(value) => {
                        if (value === "video" || value === "audio" || value === "music") setKind(value);
                    }}><TabsList className="mb-3 w-full" aria-label="项目类型"><TabsTrigger value="video"
                                                                                            disabled={pending}>视频</TabsTrigger><TabsTrigger
                        value="audio" disabled={pending}>音频</TabsTrigger><TabsTrigger value="music"
                                                                                        disabled={pending}>音乐</TabsTrigger></TabsList></Tabs>
                    <Input autoFocus value={name} onChange={(event) => setName(event.target.value)} maxLength={120}
                           placeholder="项目名称" aria-label="项目名称" disabled={pending} onKeyDown={(event) => {
                        if (event.key === "Enter" && !event.nativeEvent.isComposing) {
                            event.preventDefault();
                            event.stopPropagation();
                            void create();
                        }
                    }}/>
                    <Button type="button" className="mt-4 w-full" disabled={pending || !name.trim()}
                            onClick={() => void create()}>{pending ? "创建中…" : "创建并选择"}</Button>
                </div> : <>
                    <div className="agent-project-picker-search"><Search size={15} aria-hidden/><input autoFocus
                                                                                                       value={query}
                                                                                                       onChange={(event) => setQuery(event.target.value)}
                                                                                                       placeholder="搜索项目"
                                                                                                       aria-label="搜索项目"
                                                                                                       aria-controls={listId}
                                                                                                       onKeyDown={(event) => {
                                                                                                           if (event.key === "Enter" && !event.nativeEvent.isComposing && filtered.length) {
                                                                                                               event.preventDefault();
                                                                                                               event.stopPropagation();
                                                                                                               void choose(filtered[0].id);
                                                                                                           }
                                                                                                       }}/></div>
                    <div id={listId} className="agent-project-picker-list" role="listbox" aria-label="项目列表">
                        {filtered.map((project) => <button type="button" role="option"
                                                           aria-selected={project.id === projectId} key={project.id}
                                                           disabled={pending} onClick={() => void choose(project.id)}>
                            <Folder size={16}
                                    aria-hidden/><span><strong>{project.name}</strong>{project.brief?.trim() &&
                            <small>{project.brief}</small>}</span>{project.id === projectId &&
                            <Check size={15} aria-hidden/>}</button>)}
                        {!filtered.length &&
                            <p className="agent-project-picker-empty">{projects.length ? "没有找到匹配的项目" : "还没有项目，先为这次创作起个名字。"}</p>}
                    </div>
                    <div className="agent-project-picker-actions">{allowClear &&
                        <button type="button" onClick={() => void choose(undefined)} disabled={!projectId || pending}><X
                            size={15} aria-hidden/>{allLabel ?? "不在项目中工作"}</button>}
                        <button type="button" disabled={pending} onClick={() => setCreating(true)}><Plus size={15}
                                                                                                         aria-hidden/>新建项目
                        </button>
                    </div>
                </>}
            </Popover.Content>
        </Popover.Portal>
    </Popover.Root>;
}

import type {AgentRun} from "@/domain/agent";
import type {AgentImageReference, AgentSelectedReferences} from "@/domain/referenceInput";
import {useEffect, useRef, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {FileText, ImageIcon, Paperclip, X} from "lucide-react";
import {db} from "@/db/database";
import {getReferenceSource} from "@/db/references";
import {type ProjectReference, type ReferenceAttachment, referenceLocatorLabel} from "@/domain/references";
import {Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle} from "@/components/ui/dialog";
import "./references.css";

export const REFERENCE_STATUS_LABELS: Record<ProjectReference["status"], string> = {
    parsing: "解析中",
    ready: "可使用",
    partial: "部分解析",
    failed: "解析失败",
    unavailable: "已移除"
};

export function ReferenceIcon({kind}: { kind?: string }) {
    return kind === "image" ? <ImageIcon size={16} aria-hidden/> : <FileText size={16} aria-hidden/>;
}

function SourcePreview({projectId, attachment, chunkIndex}: {
    projectId: string;
    attachment: ReferenceAttachment;
    chunkIndex?: number
}) {
    const [attempt, setAttempt] = useState(0);
    const key = `${projectId}/${attachment.referenceId}/${attachment.revision}`;
    const loaded = useLiveQuery(async () => {
        try {
            return {key, data: await getReferenceSource(projectId, attachment), error: undefined};
        } catch (error) {
            return {key, data: undefined, error: error instanceof Error ? error.message : "读取资料失败"};
        }
    }, [key, attempt]);
    const result = loaded?.key === key ? loaded : undefined;
    const source = result?.data;
    const [image, setImage] = useState<{ blob: Blob; url: string }>();
    useEffect(() => {
        if (!source || source.reference.kind !== "image") return;
        const url = URL.createObjectURL(source.media.blob);
        setImage({blob: source.media.blob, url});
        return () => URL.revokeObjectURL(url);
    }, [source?.media.blob, source?.reference.kind]);
    const [visible, setVisible] = useState(Math.max(20, (chunkIndex ?? 0) + 1));
    const targetRef = useRef<HTMLElement>(null);
    useEffect(() => {
        if (source && chunkIndex !== undefined) targetRef.current?.scrollIntoView({block: "center"});
    }, [source, chunkIndex]);
    if (!result) return <p role="status">正在读取资料…</p>;
    if (!source) return <div className="reference-error" role="alert"><p>{result.error}</p>
        <button type="button" onClick={() => setAttempt((n) => n + 1)}>重新读取</button>
        <p>历史消息中的引用会保留；不可用的资料无法参与新的请求。</p></div>;
    const {reference, chunks} = source;
    return <>
        <div className="reference-source-meta"><ReferenceIcon
            kind={reference.kind}/><strong>{reference.filename}</strong><span>v{reference.revision} · {REFERENCE_STATUS_LABELS[reference.status]}</span>
        </div>
        <p className="reference-note">{reference.kind === "image" ? "原始图片 · 发送后由所选模型读取" : `已提取 ${reference.coverage.characters.toLocaleString()} 字符 · 处理 ${reference.coverage.processedUnits}/${reference.coverage.totalUnits} 个来源单元。这里是提取预览，不代表模型已完整阅读。`}</p>
        {reference.warnings.map((warning, i) => <p className="reference-warning" key={i}>{warning}</p>)}
        {reference.coverage.emptyUnits.length > 0 &&
            <p className="reference-warning">没有可提取文字的单元：{reference.coverage.emptyUnits.join("、")}</p>}
        <div className="reference-preview">
            {reference.kind === "image" ? image?.blob === source.media.blob && <img src={image.url}
                                                                                    alt={reference.filename}/> : chunks.length ? <>{chunks.slice(0, visible).map((chunk) =>
                    <section key={chunk.id} ref={chunk.index === chunkIndex ? targetRef : undefined}
                             className={chunk.index === chunkIndex ? "reference-cited-chunk" : undefined}><span
                        className="reference-locator">{referenceLocatorLabel(chunk.locator)} · 片段 {chunk.index + 1}</span>
                        <pre>{chunk.text}</pre>
                    </section>)}{visible < chunks.length && <button type="button"
                                                                    onClick={() => setVisible((n) => n + 20)}>继续查看（还有 {chunks.length - visible} 段）</button>}</> :
                <p>文件中没有提取到文字。</p>}
        </div>
    </>;
}

export function ReferenceSourceLink({projectId, attachment, label, chunkIndex}: {
    projectId: string;
    attachment: ReferenceAttachment;
    label?: string;
    chunkIndex?: number
}) {
    const [open, setOpen] = useState(false);
    const loaded = useLiveQuery(async () => {
        try {
            return {
                projectId,
                id: attachment.referenceId,
                row: await db.projectReferences.get(attachment.referenceId) ?? null
            };
        } catch {
            return {projectId, id: attachment.referenceId, row: null};
        }
    }, [projectId, attachment.referenceId]);
    const row = loaded?.projectId === projectId && loaded.id === attachment.referenceId && loaded.row?.projectId === projectId ? loaded.row : undefined;
    return <>
        <button type="button" className="reference-source-link" onClick={() => setOpen(true)}
                title={row?.filename ?? label}><ReferenceIcon
            kind={row?.kind}/><span>{label ?? row?.filename ?? "参考资料"}</span>{row?.status === "unavailable" &&
            <small>已移除</small>}</button>
        <Dialog open={open} onOpenChange={setOpen}><DialogContent
            className="reference-dialog"><DialogHeader><DialogTitle>来源资料</DialogTitle><DialogDescription>原始内容与提取结果
            · 只在发送或工具读取时分享给模型</DialogDescription></DialogHeader>{open &&
            <SourcePreview key={`${projectId}/${attachment.referenceId}/${attachment.revision}`} projectId={projectId}
                           attachment={attachment} chunkIndex={chunkIndex}/>}</DialogContent></Dialog></>;
}

export function ReferenceAttachments({projectId, attachments, onRemove}: {
    projectId?: string;
    attachments: ReferenceAttachment[];
    onRemove?: (attachment: ReferenceAttachment) => void
}) {
    if (!attachments.length) return null;
    return <div className="reference-chips" aria-label="已附加的资料">{attachments.map((attachment) => <span
        className="reference-chip" key={`${attachment.referenceId}/${attachment.revision}`}>{projectId ?
        <ReferenceSourceLink projectId={projectId} attachment={attachment}/> : <><Paperclip
            size={14}/>参考资料</>}{onRemove &&
        <button type="button" aria-label="从消息中移除附件" title="仅从草稿中移除，项目资料仍保留"
                onClick={() => onRemove(attachment)}><X size={14}/></button>}</span>)}</div>;
}

export function ReferenceMessageSources({context, run, content}: {
    context?: AgentSelectedReferences;
    run?: AgentRun;
    content: string
}) {
    const audits = run?.referenceAudit ?? [];
    const inputs = [...(context ? [context] : []), ...audits.flatMap((audit) => audit.inputs)];
    const citations = [...content.matchAll(/(ref_[a-zA-Z0-9-]+)@(\d+)#(\d+)/g)].flatMap((match) => {
        const referenceId = match[1];
        const revision = Number(match[2]);
        const chunkIndex = Number(match[3]);
        const input = inputs.find((input) => input.references.some((item) => item.referenceId === referenceId && item.revision === revision));
        return input ? [{projectId: input.projectId, referenceId, revision, chunkIndex}] : [];
    }).filter((item, i, all) => all.findIndex((other) => other.projectId === item.projectId && other.referenceId === item.referenceId && other.revision === item.revision && other.chunkIndex === item.chunkIndex) === i);
    if (!inputs.length) return null;
    return <div className="reference-message-sources">{context &&
        <ReferenceAttachments projectId={context.projectId} attachments={context.references}/>}{citations.length > 0 &&
        <div className="reference-chips">{citations.map((citation) => <ReferenceSourceLink
            key={`${citation.referenceId}/${citation.revision}/${citation.chunkIndex}`} projectId={citation.projectId}
            attachment={citation} chunkIndex={citation.chunkIndex}
            label={`引用 · 片段 ${citation.chunkIndex + 1}`}/>)}</div>}{audits.length > 0 && <details>
        <summary>请求资料记录 · {audits.length} 次请求</summary>
        {audits.map((audit) => <section key={audit.step}>
            <strong>第 {audit.step} 次请求</strong>{audit.inputs.map((input, index) => <div key={index}>
            <ReferenceAttachments projectId={input.projectId}
                                  attachments={input.references}/>{input.images?.filter((image) => !image.reference).map((image) =>
            <ProjectImageSource key={image.mediaId} image={image}/>)}{input.coverage?.map((coverage) => <p
            className="reference-note"
            key={`${coverage.referenceId}/${coverage.revision}`}>{coverage.filename} · {coverage.kind === "image" ? input.images?.some((image) => image.reference?.referenceId === coverage.referenceId && image.reference.revision === coverage.revision) ? "本轮图片输入（图像 token 为估算）" : "图片来源记录（本轮不含图片像素）" : `包含 ${coverage.includedChunkIndices.length}/${coverage.totalChunks} 段，${coverage.includedCharacters.toLocaleString()} 字符${coverage.partial ? " · 部分内容" : ""}`}{coverage.warnings.length > 0 ? ` · ${coverage.warnings.join("；")}` : ""}</p>)}
        </div>)}</section>)}</details>}</div>;
}

function ProjectImageSource({image}: { image: AgentImageReference }) {
    const [open, setOpen] = useState(false);
    const key = `${image.projectId}/${image.mediaId}`;
    const loaded = useLiveQuery(async () => {
        try {
            const media = open && await db.projects.get(image.projectId) ? await db.media.get(image.mediaId) : undefined;
            return {
                key,
                media: media?.projectId === image.projectId && ["image/png", "image/jpeg", "image/webp"].includes(media.mimeType) ? media : null
            };
        } catch {
            return {key, media: null};
        }
    }, [key, open]);
    const media = loaded?.key === key ? loaded.media : undefined;
    const [preview, setPreview] = useState<{ blob: Blob; url: string }>();
    useEffect(() => {
        if (!media) return;
        const url = URL.createObjectURL(media.blob);
        setPreview({blob: media.blob, url});
        return () => URL.revokeObjectURL(url);
    }, [media?.blob]);
    return <>
        <button className="reference-source-link" type="button" onClick={() => setOpen(true)}><ImageIcon
            size={14}/><span>{image.filename} · 本轮图片输入</span></button>
        <Dialog open={open} onOpenChange={setOpen}><DialogContent
            className="reference-dialog"><DialogHeader><DialogTitle>{image.filename}</DialogTitle><DialogDescription>为本次请求准备的项目图片；不代表请求已经发出。图像
            token 用量为估算。</DialogDescription></DialogHeader>
            <div className="reference-preview">{media === undefined ? <p>加载中…</p> : !media ?
                <p>原始图片已不可用，历史引用记录仍保留。</p> : preview?.blob === media.blob &&
                <img src={preview.url} alt={image.filename}/>}</div>
        </DialogContent></Dialog></>;
}

import {db} from "@/db/database";
import type {MediaRecord} from "@/domain/types";
import {useEffect, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {Check, Plus, RotateCcw, Search, Trash2, Upload} from "lucide-react";
import {toast} from "sonner";
import {listProjectReferences, removeProjectReference} from "@/db/references";
import {registerProjectImage, retryReferenceImport} from "@/lib/references/import";
import {type ProjectReference, type ReferenceAttachment, referenceAttachment} from "@/domain/references";
import {Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle} from "@/components/ui/dialog";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle
} from "@/components/ui/alert-dialog";
import {REFERENCE_STATUS_LABELS, ReferenceSourceLink} from "./ReferenceAttachments";

export function ReferenceLibrary({projectId, open, onOpenChange, selected, onSelect, onImport}: {
    projectId: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    selected: ReferenceAttachment[];
    onSelect: (attachment: ReferenceAttachment) => void;
    onImport: () => void
}) {
    const [view, setView] = useState<"references" | "images">("references");
    const [query, setQuery] = useState("");
    const [attempt, setAttempt] = useState(0);
    const [busy, setBusy] = useState<string>();
    const [remove, setRemove] = useState<ProjectReference>();
    const loaded = useLiveQuery(async () => {
        try {
            return {projectId, rows: open ? await listProjectReferences(projectId) : [], error: undefined};
        } catch (error) {
            return {projectId, rows: [], error: error instanceof Error ? error.message : "读取资料库失败"};
        }
    }, [projectId, open, attempt]);
    const loadedImages = useLiveQuery(async () => {
        try {
            return {
                projectId,
                rows: open && view === "images" ? await db.media.where("projectId").equals(projectId).filter((row) => ["image/png", "image/jpeg", "image/webp"].includes(row.mimeType)).toArray() : [],
                error: undefined
            };
        } catch {
            return {projectId, rows: [], error: "读取项目图片失败，请重新打开资料库"};
        }
    }, [projectId, open, view]);
    const images = loadedImages?.projectId === projectId ? loadedImages : undefined;

    async function chooseImage(media: MediaRecord) {
        if (busy) return;
        setBusy(media.id);
        try {
            const reference = await registerProjectImage(projectId, media.id);
            if (reference.status !== "ready") throw new Error(reference.error ?? "图片不可用");
            onSelect(referenceAttachment(reference));
            toast.success("已附加到消息");
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "附加图片失败");
        } finally {
            setBusy(undefined);
        }
    }

    const result = loaded?.projectId === projectId ? loaded : undefined;
    const rows = result?.rows.filter((row) => row.filename.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())) ?? [];

    async function retry(row: ProjectReference) {
        setBusy(row.id);
        try {
            await retryReferenceImport(projectId, row.id);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "重新解析失败");
        } finally {
            setBusy(undefined);
        }
    }

    async function removeSource() {
        if (!remove || busy) return;
        setBusy(remove.id);
        try {
            await removeProjectReference(projectId, remove.id);
            setRemove(undefined);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "移除失败");
        } finally {
            setBusy(undefined);
        }
    }

    return <><Dialog open={open} onOpenChange={onOpenChange}><DialogContent
        className="reference-dialog"><DialogHeader><DialogTitle>项目资料</DialogTitle><DialogDescription>此项目的对话共享资料库。只将你选择的资料附加到当前消息。</DialogDescription></DialogHeader>
        <div className="reference-library-tabs" aria-label="资料类型">
            <button type="button" aria-pressed={view === "references"} onClick={() => setView("references")}>参考资料
            </button>
            <button type="button" aria-pressed={view === "images"} onClick={() => setView("images")}>项目图片</button>
        </div>
        <div className="reference-library-toolbar"><label><Search size={16}/><input autoFocus aria-label="搜索项目资料"
                                                                                    placeholder="搜索文件名…"
                                                                                    value={query}
                                                                                    onChange={(e) => setQuery(e.target.value)}/></label>
            <button type="button" onClick={onImport}><Upload size={16}/>导入</button>
        </div>
        <p className="reference-note">图片 ≤10 MB · TXT / MD ≤5 MB · PDF / DOCX ≤20 MB · 每次最多 10 个</p>
        <div className="reference-library-list">
            {view === "images" ? !images ? <p role="status">加载图片…</p> : images.error ?
                <p role="alert">{images.error}</p> : <><p
                    className="reference-note">包括上传和生成的图片。点击附加可让当前模型查看原始图片。</p>
                    <div
                        className="reference-image-grid">{images.rows.filter((row) => row.filename.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())).map((media) =>
                        <ProjectImage key={media.id} media={media} disabled={!!busy}
                                      onSelect={() => void chooseImage(media)}/>)}</div>
                    {!images.rows.length && <p className="reference-empty">项目中还没有图片</p>}</> : !result ?
                <p role="status">加载中…</p> : result.error ? <div role="alert"><p>{result.error}</p>
                    <button type="button" onClick={() => setAttempt((n) => n + 1)}>重试</button>
                </div> : !rows.length ? <div className="reference-empty"><Upload
                    size={28}/><strong>{query ? "没有匹配的资料" : "把创作参考放在这里"}</strong>
                    <p>导入剧本、文档或图片，之后可以在项目的其他对话中复用。</p></div> : rows.map((row) => {
                    const attached = selected.some((item) => item.referenceId === row.id && item.revision === row.revision);
                    const usable = row.status === "ready" || row.status === "partial";
                    return <div className="reference-library-row" key={row.id}>
                        <div><ReferenceSourceLink projectId={projectId}
                                                  attachment={referenceAttachment(row)}/><small>{row.kind.toUpperCase()} · {(row.size / 1024).toFixed(0)} KB
                            · {REFERENCE_STATUS_LABELS[row.status]}{row.kind !== "image" && usable ? ` · ${row.coverage.characters.toLocaleString()} 字符` : ""}</small>{row.error &&
                            <p className="reference-error">{row.error}</p>}{row.warnings.map((warning, i) => <p
                            className="reference-warning" key={i}>{warning}</p>)}</div>
                        <div className="reference-row-actions">{(row.status === "failed" || row.status === "parsing") &&
                            <button type="button" disabled={!!busy} aria-label={`重新解析 ${row.filename}`}
                                    onClick={() => void retry(row)}><RotateCcw size={16}/></button>}
                            <button type="button" disabled={!usable || attached}
                                    onClick={() => onSelect(referenceAttachment(row))}
                                    aria-label={`${attached ? "已附加" : "附加"} ${row.filename}`}>{attached ?
                                <Check size={16}/> : <Plus size={16}/>}</button>
                            <button type="button" disabled={!!busy} onClick={() => setRemove(row)}
                                    aria-label={`移除资料 ${row.filename}`}><Trash2 size={15}/></button>
                        </div>
                    </div>;
                })}</div>
    </DialogContent></Dialog><AlertDialog open={!!remove} onOpenChange={(next) => {
        if (!next && !busy) setRemove(undefined);
    }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>从项目移除这份资料？</AlertDialogTitle><AlertDialogDescription>“{remove?.filename}”将无法用于新的消息和工具读取。历史消息及引用记录仍会保留。</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel
        disabled={!!busy}>取消</AlertDialogCancel><AlertDialogAction disabled={!!busy} onClick={(event) => {
        event.preventDefault();
        void removeSource();
    }}>移除资料</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

function ProjectImage({media, disabled, onSelect}: { media: MediaRecord; disabled: boolean; onSelect: () => void }) {
    const [image, setImage] = useState<{ blob: Blob; url: string }>();
    useEffect(() => {
        const url = URL.createObjectURL(media.blob);
        setImage({blob: media.blob, url});
        return () => URL.revokeObjectURL(url);
    }, [media.blob]);
    return <button type="button" className="reference-project-image" disabled={disabled} onClick={onSelect}
                   title={`附加 ${media.filename}`}>{image?.blob === media.blob &&
        <img src={image.url} alt={media.filename} loading="lazy"/>}<span>{media.filename}</span><small>附加图片</small>
    </button>;
}

import {useMemo, useRef, useState} from "react";
import {ArrowLeft, ArrowUpRight, Check, ListTodo, Plus, Search, Sparkles} from "lucide-react";
import {toast} from "sonner";
import type {AgentRun, AgentTask} from "@/domain/agent";
import type {Id, Project} from "@/domain/types";
import {createAgentTask} from "@/db/agentTasks";
import {getTaskDisplayState, TASK_STATE_LABELS} from "@/lib/agent/taskState";
import {Button} from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle
} from "@/components/ui/dialog";
import {Input} from "@/components/ui/input";
import {Textarea} from "@/components/ui/textarea";
import {ProjectPicker} from "./ProjectPicker";
import "./taskWorkspace.css";
import "./composerControls.css";

type BoardFilter = "active" | "all" | "archived";
const COLUMNS = [
    {id: "pending", label: "待开始", hint: "把想法变成清晰的目标", states: ["pending"]},
    {id: "running", label: "进行中", hint: "围绕目标，逐步推进", states: ["running"]},
    {
        id: "attention",
        label: "待处理",
        hint: "检查结果，或接续执行",
        states: ["approval", "interrupted", "failed", "cancelled", "review"]
    },
    {id: "done", label: "已完成", hint: "经过你确认的成果", states: ["completed", "archived"]},
];

export function TaskBoard({tasks, runs, projects, onOpenTask, onBack}: {
    tasks: AgentTask[] | undefined; runs: AgentRun[] | undefined; projects: Project[];
    onOpenTask: (task: AgentTask) => void; onBack: () => void;
}) {
    const [query, setQuery] = useState("");
    const [filter, setFilter] = useState<BoardFilter>("active");
    const [creating, setCreating] = useState(false);
    const [title, setTitle] = useState("");
    const [goal, setGoal] = useState("");
    const [saving, setSaving] = useState(false);
    const [projectId, setProjectId] = useState<Id>();
    const [filterProjectId, setFilterProjectId] = useState<Id>();
    const saveLock = useRef(false);
    const ready = tasks !== undefined && runs !== undefined;
    const entries = useMemo(() => {
        const grouped = new Map<string, AgentRun[]>();
        for (const run of runs ?? []) grouped.set(run.threadId, [...(grouped.get(run.threadId) ?? []), run]);
        return (tasks ?? []).map((task) => ({task, state: getTaskDisplayState(task, grouped.get(task.threadId) ?? [])}))
            .sort((a, b) => b.task.updatedAt.localeCompare(a.task.updatedAt));
    }, [tasks, runs]);
    const scoped = entries.filter(({task}) => !filterProjectId || task.projectId === filterProjectId);
    const visible = scoped.filter(({task}) =>
        (filter === "all" || (filter === "archived" ? task.lifecycle === "archived" : task.lifecycle !== "archived")) &&
        `${task.title} ${task.goal}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
    const completeCount = scoped.filter(({state}) => state === "completed").length;

    async function create() {
        if (saveLock.current || !title.trim() || !goal.trim() || !projectId) {
            if (!projectId) toast.error("请先选择项目");
            return;
        }
        saveLock.current = true;
        setSaving(true);
        try {
            const task = await createAgentTask({projectId, title: title.trim(), goal: goal.trim()});
            setCreating(false);
            setTitle("");
            setGoal("");
            onOpenTask(task);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "创建任务失败，请重试");
        } finally {
            saveLock.current = false;
            setSaving(false);
        }
    }

    return <section className="agent-task-board" aria-label="任务工作区">
        <header className="agent-task-board-heading">
            <div><Button variant="ghost" size="sm" className="agent-task-back"
                         onClick={onBack}><ArrowLeft/>返回助手</Button>
                <div className="agent-task-eyebrow">创作工作区 <span>/</span> TASKS</div>
                <h1>让每一个想法，走向完成<span>。</span></h1>
                <p>与小光点一起拆解目标、推进步骤，留下经过确认的成果。</p>
            </div>
            <Button onClick={() => {
                setProjectId(filterProjectId);
                setCreating(true);
            }} className="agent-task-create"><Plus/>新建任务</Button>
        </header>
        <div className="agent-task-board-toolbar">
            <ProjectPicker projects={projects} projectId={filterProjectId} onChange={setFilterProjectId}
                           allLabel="全部项目"/>
            <div className="agent-task-filters" role="group" aria-label="筛选任务">
                {([{value: "active", label: "工作台"}, {value: "all", label: "全部"}, {
                    value: "archived",
                    label: "已归档"
                }] as const).map(({value, label}) =>
                    <button key={value} type="button" aria-pressed={filter === value}
                            onClick={() => setFilter(value)}>{label}</button>)}
            </div>
            <span
                className="agent-task-board-count">{ready ? `${scoped.length} 个任务 · ${completeCount} 个已完成` : "读取工作区…"}</span>
            <label className="agent-task-search"><Search size={16} aria-hidden/><input aria-label="搜索任务"
                                                                                       placeholder="搜索任务与目标…"
                                                                                       value={query}
                                                                                       onChange={(event) => setQuery(event.target.value)}/></label>
        </div>
        {!ready ?
            <div className="agent-task-loading" role="status">正在读取任务与执行进度…</div> : entries.length === 0 ?
                <div className="agent-task-empty"><ListTodo size={32} strokeWidth={1.25} aria-hidden/>
                    <h2>先定一个小目标</h2><p>整理角色设定、打磨故事，或准备下一次创作。<br/>你可以先写下任务，随时再与助手一起推进。
                    </p><Button onClick={() => {
                        setProjectId(filterProjectId);
                        setCreating(true);
                    }}><Plus/>创建第一个任务</Button><span>无需配置模型，也可以手动管理任务</span></div> :
                <div className="agent-task-columns">
                    {COLUMNS.map((column) => {
                        const cards = visible.filter(({state}) => column.states.includes(state));
                        return <section className="agent-task-column" key={column.id} aria-label={column.label}>
                            <header><span className={`agent-task-state-dot is-${column.id}`}/><h2>{column.label}</h2>
                                <span>{cards.length}</span></header>
                            <p className="agent-task-column-hint">{column.hint}</p>
                            {cards.length === 0 ? <div
                                className="agent-task-column-empty">{query || filter === "archived" ? "没有匹配的任务" : "暂无任务"}</div> : cards.map(({
                                                                                                                                                            task,
                                                                                                                                                            state
                                                                                                                                                        }) => {
                                const done = task.plan.filter((step) => step.status === "completed").length;
                                return <button className="agent-task-card" key={task.id} type="button"
                                               onClick={() => onOpenTask(task)}>
                                    <div className="agent-task-card-top"><span
                                        className={`agent-task-status is-${state}`}>{TASK_STATE_LABELS[state]}</span><ArrowUpRight
                                        size={16} aria-hidden/></div>
                                    <h3>{task.title}</h3><p>{task.goal}</p><small
                                    className="agent-task-card-project">{projects.find((project) => project.id === task.projectId)?.name ?? "项目不可用"}</small>
                                    {task.plan.length > 0 && <div className="agent-task-mini-progress"><span
                                        style={{width: `${done / task.plan.length * 100}%`}}/></div>}
                                    <footer><span><Sparkles size={12}
                                                            aria-hidden/>小光点</span><span>{task.plan.length ? <><Check
                                        size={12} aria-hidden/>{done}/{task.plan.length}</> : "待拆解步骤"}</span>
                                    </footer>
                                </button>;
                            })}
                        </section>;
                    })}
                </div>}
        <Dialog open={creating} onOpenChange={(next) => {
            if (!saveLock.current) setCreating(next);
        }}>
            <DialogContent className="agent-task-dialog" showCloseButton={!saving}>
                <DialogHeader><DialogTitle>新建任务</DialogTitle><DialogDescription>写下想完成的事情，步骤可以稍后补充。</DialogDescription></DialogHeader>
                <form onSubmit={(event) => {
                    event.preventDefault();
                    void create();
                }}>
                    <div className="agent-task-field">所属项目<ProjectPicker projects={projects} projectId={projectId}
                                                                             required allowClear={false} locked={saving}
                                                                             onChange={setProjectId}/></div>
                    <label className="agent-task-field">任务名称<Input autoFocus value={title} maxLength={120}
                                                                       onChange={(event) => setTitle(event.target.value)}
                                                                       placeholder="例如：完善主角的人物设定"
                                                                       disabled={saving} required/></label>
                    <label className="agent-task-field">目标与完成标准<Textarea value={goal} maxLength={20_000}
                                                                                onChange={(event) => setGoal(event.target.value)}
                                                                                placeholder="希望得到什么结果？有哪些需要注意的要求？"
                                                                                rows={5} disabled={saving}
                                                                                required/></label>
                    <DialogFooter><Button type="button" variant="ghost" disabled={saving}
                                          onClick={() => setCreating(false)}>取消</Button><Button type="submit"
                                                                                                  disabled={saving || !projectId || !title.trim() || !goal.trim()}>{saving ? "创建中…" : "创建任务"}</Button></DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    </section>;
}

import {useRef, useState} from "react";
import {
    Archive,
    ArrowLeft,
    Check,
    ChevronDown,
    Circle,
    ClipboardCheck,
    ListTodo,
    Pencil,
    Pin,
    Plus,
    RotateCcw,
    Sparkles,
    X
} from "lucide-react";
import {toast} from "sonner";
import type {AgentPlanItem, AgentRun, AgentTask} from "@/domain/agent";
import type {ChatMessage} from "@/domain/types";
import {pinAgentTaskResult, setAgentTaskLifecycle, unpinAgentTaskResult, updateAgentTask} from "@/db/agentTasks";
import {getTaskDisplayState, isTaskBusy, TASK_STATE_LABELS} from "@/lib/agent/taskState";
import {Button} from "@/components/ui/button";
import {Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle} from "@/components/ui/sheet";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle
} from "@/components/ui/dialog";
import {Input} from "@/components/ui/input";
import {Textarea} from "@/components/ui/textarea";
import {TaskRecords} from "./TaskRecords";
import {TaskWrapup, type WrapupModelSelection} from "./TaskWrapup";
import "./taskWorkspace.css";

type InspectorProps = {
    projectName?: string;
    projectUnavailable?: boolean;
    summaryModel?: WrapupModelSelection;
    task: AgentTask;
    runs: AgentRun[];
    messages: ChatMessage[];
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onOpenBoard: () => void
};
const RUN_LABELS: Record<AgentRun["status"], string> = {
    running: "执行中",
    waiting_approval: "等待批准",
    completed: "已回复",
    failed: "执行失败",
    cancelled: "已停止",
    interrupted: "执行中断"
};
const dateLabel = (value: string) => new Date(value).toLocaleString("zh-CN", {
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit"
});

export function TaskInspector(props: InspectorProps) {
    return <TaskInspectorContent key={props.task.id} {...props} />;
}

function TaskInspectorContent({
                                  task,
                                  runs,
                                  messages,
                                  open,
                                  onOpenChange,
                                  onOpenBoard,
                                  summaryModel,
                                  projectName,
                                  projectUnavailable
                              }: InspectorProps) {
    const [editor, setEditor] = useState<"goal" | "plan" | null>(null);
    const [tab, setTab] = useState<"overview" | "records" | "wrapup">("overview");
    const [reviewEditing, setReviewEditing] = useState(false);
    const [reviewPending, setReviewPending] = useState(false);
    const [criteria, setCriteria] = useState("");
    const [editRevision, setEditRevision] = useState(1);
    const [title, setTitle] = useState("");
    const [goal, setGoal] = useState("");
    const [planText, setPlanText] = useState("");
    const [pending, setPending] = useState(false);
    const lock = useRef(false);
    const threadRuns = runs.filter((run) => run.threadId === task.threadId);
    const taskRuns = threadRuns.filter((run) => run.taskId === task.id);
    const state = getTaskDisplayState(task, taskRuns);
    const busy = isTaskBusy(threadRuns);
    const editable = !projectUnavailable && !busy && !reviewPending && task.lifecycle === "open" && !pending;
    const completed = task.plan.filter((step) => step.status === "completed").length;
    const orderedRuns = [...taskRuns].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    const outputs = orderedRuns.flatMap((run) => {
        const message = messages.find((item) => item.id === run.assistantMessageId && item.threadId === task.threadId && item.role === "assistant" && item.runId === run.id && item.status === "complete" && item.content.trim());
        return run.taskId === task.id && run.status === "completed" && message ? [{run, message}] : [];
    });

    async function mutate(action: () => Promise<unknown>, success?: string, after?: () => void) {
        if (lock.current) return;
        lock.current = true;
        setPending(true);
        try {
            await action();
            after?.();
            if (success) toast.success(success);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "保存失败，请重试");
        } finally {
            lock.current = false;
            setPending(false);
        }
    }

    function editGoal() {
        setTitle(task.title);
        setGoal(task.goal);
        setCriteria((task.acceptanceCriteria ?? []).join("\n"));
        setEditRevision(task.revision ?? 1);
        setEditor("goal");
    }

    function editPlan() {
        setEditRevision(task.revision ?? 1);
        setPlanText(task.plan.map((item) => item.title).join("\n"));
        setEditor("plan");
    }

    function savePlan() {
        // Consume matches once: duplicate titles retain their own IDs when reordered.
        const remaining = [...task.plan];
        const plan: AgentPlanItem[] = planText.split("\n").map((line) => line.trim()).filter(Boolean).map((title) => {
            const index = remaining.findIndex((item) => item.title === title);
            return index >= 0 ? remaining.splice(index, 1)[0] : {id: crypto.randomUUID(), title, status: "pending"};
        });
        void mutate(() => updateAgentTask(task.id, {plan}, editRevision), "执行清单已保存", () => setEditor(null));
    }

    return <Sheet open={open} onOpenChange={(next) => {
        if (!lock.current && !editor && !reviewEditing && !reviewPending) onOpenChange(next);
    }}>
        <SheetContent className="agent-task-inspector" showCloseButton={false}>
            <div className="agent-task-inspector-nav"><Button variant="ghost" size="sm"
                                                              disabled={pending || reviewEditing || reviewPending}
                                                              onClick={() => {
                                                                  onOpenChange(false);
                                                                  onOpenBoard();
                                                              }}><ArrowLeft/>任务工作台</Button><Button variant="ghost"
                                                                                                        size="icon"
                                                                                                        aria-label="关闭任务详情"
                                                                                                        disabled={pending || reviewEditing || reviewPending}
                                                                                                        onClick={() => onOpenChange(false)}><X/></Button>
            </div>
            <div className="agent-task-inspector-scroll">
                <SheetHeader className="agent-task-inspector-heading"><span
                    className={`agent-task-status is-${state}`}>{TASK_STATE_LABELS[state]}</span><SheetTitle>{task.title}</SheetTitle><SheetDescription><Sparkles
                    size={14} aria-hidden/>{projectName ?? "项目不可用"} ·
                    小光点<span>更新于 {dateLabel(task.updatedAt)}</span></SheetDescription></SheetHeader>
                {projectUnavailable && <div className="agent-task-notice">所属项目已不可用，历史记录仍可查看。</div>}
                {busy &&
                    <div className="agent-task-notice">执行尚未结束。请在对话中处理批准、停止或恢复操作，再编辑任务。</div>}
                {state === "review" && <div className="agent-task-notice">请检查成果与清单，由你确认任务完成。</div>}
                <div className="agent-task-inspector-tabs" aria-label="任务详情视图">
                    <button type="button" disabled={reviewEditing || reviewPending} aria-pressed={tab === "overview"}
                            onClick={() => setTab("overview")}>概览
                    </button>
                    <button type="button" disabled={reviewEditing || reviewPending} aria-pressed={tab === "records"}
                            onClick={() => setTab("records")}>工作记录
                    </button>
                    <button type="button" aria-pressed={tab === "wrapup"} onClick={() => setTab("wrapup")}>验收总结
                    </button>
                </div>
                <div hidden={tab !== "wrapup"}><TaskWrapup task={task} modelSelection={summaryModel}
                                                           busy={Boolean(projectUnavailable) || busy || pending}
                                                           onEditingChange={setReviewEditing}
                                                           onPendingChange={setReviewPending}/></div>
                <div hidden={tab !== "records"}><TaskRecords task={task} messages={messages} editable={editable}/></div>
                <div hidden={tab !== "overview"}>
                    <section className="agent-task-section">
                        <div className="agent-task-section-heading"><h3>任务目标</h3><Button variant="ghost"
                                                                                             size="icon-sm"
                                                                                             aria-label="编辑任务目标"
                                                                                             disabled={!editable}
                                                                                             onClick={editGoal}><Pencil/></Button>
                        </div>
                        <p className="agent-task-goal">{task.goal}</p>{!!task.acceptanceCriteria?.length &&
                        <div className="agent-task-acceptance"><h4>完成标准</h4>
                            <ul>{task.acceptanceCriteria.map((criterion, index) => <li
                                key={index}>{criterion}</li>)}</ul>
                        </div>}</section>
                    <section className="agent-task-section">
                        <div className="agent-task-section-heading">
                            <h3>执行清单 <span>{completed} / {task.plan.length}</span></h3><Button variant="ghost"
                                                                                                   size="sm"
                                                                                                   disabled={!editable}
                                                                                                   onClick={editPlan}>{task.plan.length ?
                            <Pencil/> : <Plus/>}{task.plan.length ? "编辑" : "添加步骤"}</Button></div>
                        {task.plan.length ? <>
                                <div className="agent-task-progress" role="progressbar" aria-label="任务步骤完成进度"
                                     aria-valuemin={0} aria-valuemax={task.plan.length} aria-valuenow={completed}><span
                                    style={{width: `${completed / task.plan.length * 100}%`}}/></div>
                                <ol className="agent-task-checklist">{task.plan.map((step) => <li key={step.id}
                                                                                                  className={step.status === "completed" ? "is-completed" : ""}>
                                    <button type="button" role="checkbox" aria-checked={step.status === "completed"}
                                            aria-label={step.title} disabled={!editable}
                                            onClick={() => void mutate(() => updateAgentTask(task.id, {
                                                plan: task.plan.map((item) => item.id === step.id ? {
                                                    ...item,
                                                    status: item.status === "completed" ? "pending" : "completed"
                                                } : item)
                                            }, task.revision ?? 1))}>{step.status === "completed" ?
                                        <Check size={14}/> : step.status === "in_progress" ?
                                            <span className="agent-task-step-active"/> : null}</button>
                                    <span>{step.title}{step.status === "in_progress" && <small>进行中</small>}</span>
                                </li>)}</ol>
                            </> :
                            <p className="agent-task-muted">把目标拆成几个可执行的步骤，也可以在对话中请助手帮你规划。</p>}
                    </section>
                    <section className="agent-task-section">
                        <div className="agent-task-section-heading"><h3>任务成果 <span>{task.artifacts.length}</span>
                        </h3><Pin size={16} className="agent-task-muted" aria-hidden/></div>
                        {task.artifacts.length === 0 &&
                            <p className="agent-task-muted">将有价值的完整回复保留在这里，方便随时回看。</p>}
                        {task.artifacts.map((artifact, index) => {
                            const message = messages.find((item) => item.id === artifact.messageId);
                            return <div key={artifact.id} className="agent-task-result">
                                <details>
                                    <summary><Pin size={14}
                                                  aria-hidden/><span>成果 {index + 1}<small>{dateLabel(artifact.createdAt)}</small></span><ChevronDown
                                        size={14}/></summary>
                                    <p>{message?.content ?? "这条回复已不可用"}</p></details>
                                <Button variant="ghost" size="icon-sm" aria-label={`移除成果 ${index + 1}`}
                                        disabled={!editable}
                                        onClick={() => void mutate(() => unpinAgentTaskResult(task.id, artifact.id), "已从成果中移除")}><X/></Button>
                            </div>;
                        })}
                        {outputs.some(({message}) => !task.artifacts.some((artifact) => artifact.messageId === message.id)) &&
                            <details className="agent-task-output-picker">
                                <summary><Plus size={14}/>从完整回复中添加</summary>
                                {outputs.filter(({message}) => !task.artifacts.some((artifact) => artifact.messageId === message.id)).map(({
                                                                                                                                               run,
                                                                                                                                               message
                                                                                                                                           }) =>
                                    <div key={run.id}>
                                        <span><small>{dateLabel(run.createdAt)}</small><p>{message.content.slice(0, 160)}</p></span><Button
                                        variant="ghost" size="icon-sm"
                                        aria-label={`保留 ${dateLabel(run.createdAt)} 的回复为成果`}
                                        disabled={!editable}
                                        onClick={() => void mutate(() => pinAgentTaskResult(task.id, run.id), "已保留为任务成果")}><Pin/></Button>
                                    </div>)}</details>}
                    </section>
                    <section className="agent-task-section">
                        <div className="agent-task-section-heading"><h3>执行记录 <span>{taskRuns.length}</span></h3>
                            <ListTodo size={16} className="agent-task-muted" aria-hidden/></div>
                        {orderedRuns.length ?
                            <ol className="agent-task-history">{orderedRuns.map((run) => <li key={run.id}><Circle
                                size={8} aria-hidden/>
                                <div>
                                    <span>{RUN_LABELS[run.status]}</span><small>{run.model} · {dateLabel(run.createdAt)}</small>{run.retryOfRunId &&
                                    <small>继续尝试</small>}</div>
                            </li>)}</ol> :
                            <p className="agent-task-muted">还没有执行记录。在对话中发送目标，即可开始。</p>}</section>
                </div>
            </div>
            <footer className="agent-task-inspector-footer">
                {task.lifecycle === "open" ? <><Button variant="ghost"
                                                       disabled={projectUnavailable || busy || pending || reviewPending || reviewEditing}
                                                       onClick={() => void mutate(() => setAgentTaskLifecycle(task.id, "archived"), "任务已归档", () => onOpenChange(false))}><Archive/>归档</Button>{tab !== "wrapup" ?
                    <Button disabled={projectUnavailable || busy || pending || reviewPending}
                            onClick={() => setTab("wrapup")}><ClipboardCheck/>检查并收尾</Button> :
                    <span className="agent-task-muted">由你检查并确认完成</span>}</> : <><span
                    className="agent-task-muted">{task.lifecycle === "completed" ? <Button variant="ghost"
                                                                                           disabled={projectUnavailable || busy || pending || reviewPending || reviewEditing}
                                                                                           onClick={() => void mutate(() => setAgentTaskLifecycle(task.id, "archived"), "任务已归档", () => onOpenChange(false))}><Archive/>归档</Button> : "已归档"}</span><Button
                    disabled={projectUnavailable || busy || pending || reviewPending || reviewEditing}
                    onClick={() => void mutate(() => setAgentTaskLifecycle(task.id, "open"), "任务已重新打开")}><RotateCcw/>重新打开</Button></>}
            </footer>
            <Dialog open={editor !== null} onOpenChange={(next) => {
                if (!next && !lock.current) setEditor(null);
            }}><DialogContent className="agent-task-dialog"
                              showCloseButton={!pending}><DialogHeader><DialogTitle>{editor === "goal" ? "编辑任务目标" : "编辑执行清单"}</DialogTitle><DialogDescription>{editor === "goal" ? "清晰的目标和完成标准，帮助每一次执行保持方向。" : "每行一个步骤，调整行的顺序即可排序。修改名称会将该步骤重置为待完成。"}</DialogDescription></DialogHeader>
                <form onSubmit={(event) => {
                    event.preventDefault();
                    if (editor === "goal") void mutate(() => updateAgentTask(task.id, {
                        title: title.trim(),
                        goal: goal.trim(),
                        acceptanceCriteria: criteria.split("\n").map((line) => line.trim()).filter(Boolean)
                    }, editRevision), "任务目标已保存", () => setEditor(null)); else savePlan();
                }}>
                    {editor === "goal" ? <><label className="agent-task-field">任务名称<Input autoFocus value={title}
                                                                                              maxLength={120} required
                                                                                              disabled={pending}
                                                                                              onChange={(event) => setTitle(event.target.value)}/></label><label
                            className="agent-task-field">任务目标<Textarea value={goal} maxLength={20_000} required rows={6}
                                                                           disabled={pending}
                                                                           onChange={(event) => setGoal(event.target.value)}/></label><label
                            className="agent-task-field">完成标准<Textarea value={criteria} rows={4} disabled={pending}
                                                                           onChange={(event) => setCriteria(event.target.value)}
                                                                           placeholder="每行一项，写下如何判断任务已经完成"/></label></> :
                        <label className="agent-task-field">步骤<Textarea autoFocus value={planText} rows={9}
                                                                          disabled={pending}
                                                                          onChange={(event) => setPlanText(event.target.value)}
                                                                          placeholder={"明确故事主题\n完善人物关系\n确认最终设定"}/></label>}
                    <DialogFooter><Button type="button" variant="ghost" disabled={pending}
                                          onClick={() => setEditor(null)}>取消</Button><Button type="submit"
                                                                                               disabled={!editable || (editor === "goal" && (!title.trim() || !goal.trim()))}>{pending ? "保存中…" : "保存"}</Button></DialogFooter>
                </form>
            </DialogContent></Dialog>
        </SheetContent>
    </Sheet>;
}

import {
    listTaskGenerationSources,
    listTaskRecords,
    listTaskRecordVersions,
    saveTaskRecord
} from "@/db/agentTaskRecords";
import {ReferenceSourceLink} from "./ReferenceAttachments";
import {toolReferenceAttachments} from "@/lib/agent/referenceEvidence";
import {useRef, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {BookOpen, ChevronDown, History, Pencil, Plus, Search} from "lucide-react";
import {toast} from "sonner";
import type {AgentTask} from "@/domain/agent";
import type {ChatMessage} from "@/domain/types";
import {
    type AgentTaskRecord,
    TASK_RECORD_CLAIMS,
    TASK_RECORD_KINDS,
    type TaskRecordInput
} from "@/domain/agentTaskRecords";
import {db} from "@/db/database";
import {CreatedEntityLinks} from "./CreatedEntityLinks";
import {Button} from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle
} from "@/components/ui/dialog";
import {Input} from "@/components/ui/input";
import {Textarea} from "@/components/ui/textarea";

const KINDS = {research: "调研", approach: "方案", progress: "进展", verification: "验证", question: "待解决"};
const CLAIMS = {observation: "观察", proposal: "建议", decision: "已确认决策", result: "完成结果"};
const dateLabel = (value: string) => new Date(value).toLocaleString("zh-CN", {
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit"
});
const emptyRecord = (): TaskRecordInput => ({kind: "research", claim: "proposal", title: "", body: "", sources: []});

type Props = { task: AgentTask; messages: ChatMessage[]; editable: boolean };

export function TaskRecords({task, messages, editable}: Props) {
    const records = useLiveQuery(() => listTaskRecords(task.id), [task.id]);
    const calls = useLiveQuery(async () => {
        const runs = await db.agentRuns.where("taskId").equals(task.id).toArray();
        const owned = new Set(runs.filter((run) => run.threadId === task.threadId).map((run) => run.id));
        return (await db.agentToolCalls.where("threadId").equals(task.threadId).toArray()).filter((call) => owned.has(call.runId));
    }, [task.id, task.threadId]);
    const generationEvidence = useLiveQuery(() => listTaskGenerationSources(task), [task.id, task.threadId, task.projectId]);
    const [filter, setFilter] = useState<TaskRecordInput["kind"] | "all">("all");
    const [query, setQuery] = useState("");
    const [editing, setEditing] = useState<{ record?: AgentTaskRecord; input: TaskRecordInput }>();
    const [historyId, setHistoryId] = useState<string>();
    const [pending, setPending] = useState(false);
    const [error, setError] = useState("");
    const saving = useRef(false);
    const history = useLiveQuery(() => historyId ? listTaskRecordVersions(task.id, historyId) : [], [task.id, historyId]);
    const evidence = [
        ...(generationEvidence ?? []).map(item => ({
            type: "generation" as const,
            id: item.id,
            label: item.label,
            body: item.body
        })),
        ...messages.filter((message) => message.threadId === task.threadId && message.role === "user" && (message.content.trim() || message.attachments?.length)).map((message) => ({
            type: "message" as const,
            id: message.id,
            label: `用户 · ${message.content.slice(0, 70) || "参考资料"}`,
            body: message.content
        })),
        ...(calls ?? []).filter((call) => call.status === "completed" && call.effect !== "bookkeeping" && call.result).map((call) => ({
            type: "tool" as const,
            id: call.id,
            label: call.title,
            body: call.result!
        })),
    ];
    const visible = [...(records ?? [])].reverse().filter((record) => (filter === "all" || record.kind === filter) && `${record.title} ${record.body}`.toLowerCase().includes(query.trim().toLowerCase()));

    function edit(record?: AgentTaskRecord) {
        setError("");
        setEditing({
            record,
            input: record ? {
                kind: record.kind,
                claim: record.claim,
                title: record.title,
                body: record.body,
                sources: [...record.sources],
                todoId: record.todoId
            } : emptyRecord()
        });
    }

    function change(patch: Partial<TaskRecordInput>) {
        setEditing((current) => current ? {...current, input: {...current.input, ...patch}} : current);
    }

    async function save() {
        if (!editing || saving.current || !editable) return;
        saving.current = true;
        setPending(true);
        setError("");
        try {
            await saveTaskRecord(task.id, editing.input, editing.record ? {
                id: editing.record.id,
                expectedRevision: editing.record.revision
            } : {});
            setEditing(undefined);
            toast.success("工作记录已保存");
        } catch (failure) {
            setError(failure instanceof Error ? failure.message : "保存失败，请重试");
        } finally {
            saving.current = false;
            setPending(false);
        }
    }

    return <div className="agent-task-records">
        <div className="agent-task-section-heading">
            <div><h3>工作记录 <span>{records?.length ?? 0}</span></h3><p
                className="agent-task-muted">保留依据与决策，让下一次执行接得上。</p></div>
            <Button variant="ghost" size="sm" disabled={!editable} onClick={() => edit()}><Plus/>新记录</Button></div>
        <label className="agent-task-record-search"><Search size={16}/><input aria-label="搜索工作记录"
                                                                              placeholder="搜索标题或内容…"
                                                                              value={query}
                                                                              onChange={(event) => setQuery(event.target.value)}/></label>
        <div className="agent-task-record-filters" aria-label="记录类型">
            <button type="button" aria-pressed={filter === "all"} onClick={() => setFilter("all")}>全部</button>
            {TASK_RECORD_KINDS.map((kind) => <button key={kind} type="button" aria-pressed={filter === kind}
                                                     onClick={() => setFilter(kind)}>{KINDS[kind]}</button>)}</div>
        {!records ? <p className="agent-task-muted" role="status">正在读取记录…</p> : !visible.length ?
            <div className="agent-task-record-empty"><BookOpen size={28} strokeWidth={1.3}/>
                <h3>{records.length ? "没有匹配的记录" : "每一步，都有迹可循"}</h3>
                <p>{records.length ? "试试其他关键词或分类。" : "助手会在推进任务时记录调研、方案和验证结果。你也可以补充重要信息。"}</p>
            </div> : visible.map((record) => <details className="agent-task-record" key={record.id}>
                <summary><span className={`agent-task-record-kind is-${record.kind}`}>{KINDS[record.kind]}</span><span
                    className="agent-task-record-title">{record.title}<small>{CLAIMS[record.claim]} · {record.author === "ai" ? "助手" : "你"} · {dateLabel(record.updatedAt)}</small></span><ChevronDown
                    size={16}/></summary>
                <div className="agent-task-record-content">
                    <div className="agent-task-record-actions">
                        <span>版本 {record.revision}{record.todoId ? ` · ${task.plan.find((step) => step.id === record.todoId)?.title ?? "原步骤已调整"}` : ""}</span><Button
                        variant="ghost" size="icon-sm" aria-label={`查看${record.title}的历史版本`}
                        onClick={() => setHistoryId(record.id)}><History/></Button><Button variant="ghost"
                                                                                           size="icon-sm"
                                                                                           aria-label={`编辑${record.title}`}
                                                                                           disabled={!editable || record.body.length > 12_000}
                                                                                           title={record.body.length > 12_000 ? "这是完整变更快照，请在概览中调整任务要求" : undefined}
                                                                                           onClick={() => edit(record)}><Pencil/></Button>
                    </div>
                    <p className="agent-task-record-body">{record.body}</p>
                    {record.sources.length > 0 &&
                        <div className="agent-task-record-sources"><h4>记录依据</h4>{record.sources.map((source) => {
                            const item = evidence.find((entry) => entry.id === source.id && entry.type === source.type);
                            return <details key={`${source.type}:${source.id}`}>
                                <summary>{item?.label ?? "来源已不可用"}</summary>
                                {source.type === "tool" ? <>{calls?.filter((call) => call.id === source.id).map((call) =>
                                    <div key={call.id}><CreatedEntityLinks call={call}
                                                                           includePreview/>{toolReferenceAttachments(call.result, task.projectId).map(attachment =>
                                        <ReferenceSourceLink key={`${attachment.referenceId}:${attachment.revision}`}
                                                             projectId={task.projectId} attachment={attachment}/>)}
                                    </div>)}
                                    <details className="agent-task-record-raw">
                                        <summary>查看原始工具结果</summary>
                                        <pre>{item?.body ?? "原始记录不存在，无法重新核实。"}</pre>
                                    </details>
                                </> : <>
                                    <pre>{item?.body ?? "原始记录不存在，无法重新核实。"}</pre>
                                    {messages.find(message => message.id === source.id)?.attachments?.map(attachment =>
                                        <ReferenceSourceLink key={`${attachment.referenceId}:${attachment.revision}`}
                                                             projectId={task.projectId} attachment={attachment}/>)}</>}
                            </details>;
                        })}</div>}
                </div>
            </details>)}
        <Dialog open={!!editing} onOpenChange={(open) => {
            if (!open && !saving.current) setEditing(undefined);
        }}><DialogContent className="agent-task-dialog agent-task-record-editor"
                          showCloseButton={!pending}><DialogHeader><DialogTitle>{editing?.record ? "编辑工作记录" : "新建工作记录"}</DialogTitle><DialogDescription>保存后保留历史版本。编辑记录仅影响本文；目标与清单请在概览中调整。</DialogDescription></DialogHeader>{editing &&
            <form onSubmit={(event) => {
                event.preventDefault();
                void save();
            }}>
                <div className="agent-task-record-selects"><label className="agent-task-field">分类<select
                    value={editing.input.kind} disabled={pending}
                    onChange={(event) => change({kind: event.target.value as TaskRecordInput["kind"]})}>{TASK_RECORD_KINDS.map((kind) =>
                    <option key={kind} value={kind}>{KINDS[kind]}</option>)}</select></label><label
                    className="agent-task-field">内容性质<select value={editing.input.claim} disabled={pending}
                                                                 onChange={(event) => change({claim: event.target.value as TaskRecordInput["claim"]})}>{TASK_RECORD_CLAIMS.map((claim) =>
                    <option key={claim} value={claim}>{CLAIMS[claim]}</option>)}</select></label></div>
                <label className="agent-task-field">标题<Input autoFocus maxLength={120} required disabled={pending}
                                                               value={editing.input.title}
                                                               onChange={(event) => change({title: event.target.value})}/></label>
                <label className="agent-task-field">内容<Textarea rows={9} maxLength={12_000} required
                                                                  disabled={pending} value={editing.input.body}
                                                                  onChange={(event) => change({body: event.target.value})}
                                                                  placeholder="记录发现、决策依据，或接下来需要解决的问题…"/></label>
                <label className="agent-task-field">关联步骤<select value={editing.input.todoId ?? ""}
                                                                    disabled={pending}
                                                                    onChange={(event) => change({todoId: event.target.value || undefined})}>
                    <option value="">整个任务</option>
                    {editing.input.todoId && !task.plan.some((step) => step.id === editing.input.todoId) &&
                        <option value={editing.input.todoId}>原步骤已调整，请重新选择</option>}{task.plan.map((step) =>
                    <option key={step.id} value={step.id}>{step.title}</option>)}</select></label>
                {evidence.length > 0 && <details className="agent-task-evidence-picker">
                    <summary>关联依据 <span>{editing.input.sources.length} / 12</span></summary>
                    <div>{evidence.map((item) => {
                        const selected = editing.input.sources.some((source) => source.id === item.id && source.type === item.type);
                        return <label key={`${item.type}:${item.id}`}><input type="checkbox" checked={selected}
                                                                             disabled={pending || (!selected && editing.input.sources.length >= 12)}
                                                                             onChange={() => change({
                                                                                 sources: selected ? editing.input.sources.filter((source) => source.id !== item.id || source.type !== item.type) : [...editing.input.sources, {
                                                                                     type: item.type,
                                                                                     id: item.id
                                                                                 }]
                                                                             })}/><span>{item.label}</span></label>;
                    })}</div>
                </details>}
                {error && <p className="agent-task-record-error"
                             role="alert">{error}。草稿仍在，可以复制内容后重新打开最新版本。</p>}
                <DialogFooter><Button type="button" variant="ghost" disabled={pending}
                                      onClick={() => setEditing(undefined)}>取消</Button><Button type="submit"
                                                                                                 disabled={pending || !editable || !editing.input.title.trim() || !editing.input.body.trim()}>{pending ? "保存中…" : "保存记录"}</Button></DialogFooter>
            </form>}</DialogContent></Dialog>
        <Dialog open={!!historyId} onOpenChange={(open) => {
            if (!open) setHistoryId(undefined);
        }}><DialogContent
            className="agent-task-dialog agent-task-record-editor"><DialogHeader><DialogTitle>历史版本</DialogTitle><DialogDescription>按保存时间留存，可展开查看当时的内容。</DialogDescription></DialogHeader>{history ? [...history].reverse().map((version) =>
            <details className="agent-task-record-version" key={version.versionId}>
                <summary>
                    <span>版本 {version.revision} · {version.author === "ai" ? "助手" : "你"}</span><small>{dateLabel(version.updatedAt)}</small>
                </summary>
                <h3>{version.title}</h3><p
                className="agent-task-muted">{KINDS[version.kind]} · {CLAIMS[version.claim]}</p><p
                className="agent-task-record-body">{version.body}</p></details>) : <p role="status">正在读取历史…</p>}
        </DialogContent></Dialog>
    </div>;
}

import {ReferenceSourceLink} from "./ReferenceAttachments";
import {MemoryEditor} from "@/components/memory/MemoryEditor";
import type {MemoryCandidate, ProjectMemory} from "@/domain/projectMemory";
import {MemoryPromotion} from "@/components/memory/MemoryPromotion";
import {useEffect, useRef, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {Link} from "@tanstack/react-router";
import {
    ArrowUpRight,
    CheckCheck,
    ClipboardCheck,
    History,
    LoaderCircle,
    Pencil,
    Plus,
    RefreshCw,
    Sparkles,
    X
} from "lucide-react";
import {toast} from "sonner";
import type {AgentReasoningEffort, AgentTask} from "@/domain/agent";
import type {ConnectorConfig} from "@/domain/types";
import type {ChatModelMetadata} from "@/lib/ai/modelMetadata";
import type {AgentTaskWrapup, TaskWrapupState, WrapupContent, WrapupEvidence} from "@/domain/agentTaskWrapup";
import {confirmWrapup, createManualWrapup, getTaskWrapupState, saveWrapup} from "@/db/agentTaskWrapups";
import {setAgentTaskLifecycle} from "@/db/agentTasks";
import {cancelTaskWrapup, prepareTaskWrapup, recoverTaskWrapups} from "@/lib/agent/taskWrapup";
import {Button} from "@/components/ui/button";
import {Textarea} from "@/components/ui/textarea";
