/** Shared nav + searchable topic list for desktop sidebar and mobile drawer. */
export function TopicListBody({
                                  threads,
                                  activeThreadId,
                                  onSelect,
                                  onNewTopic,
                                  onOpenTasks,
                                  onRename,
                                  onDelete,
                                  footer,
                              }: {
    threads: ChatThread[];
    activeThreadId?: Id;
    onSelect: (id: Id) => void;
    onNewTopic: () => void;
    onOpenTasks: () => void;
    onRename: (thread: ChatThread) => void;
    onDelete: (thread: ChatThread) => void;
    footer?: ReactNode;
}) {
    const [topicsOpen, setTopicsOpen] = useState(true);
    const [folded, setFolded] = useState<Record<string, boolean>>({});
    const [searchOpen, setSearchOpen] = useState(false);
    const [query, setQuery] = useState("");
    const searchRef = useRef<HTMLInputElement>(null);

    const filtered = useMemo(
        () => filterThreadsByTitle(threads, query),
        [threads, query],
    );
    const groups = useMemo(() => groupThreadsByTime(filtered), [filtered]);

    useEffect(() => {
        if (searchOpen) {
            searchRef.current?.focus();
        }
    }, [searchOpen]);

    const openSearch = () => {
        setSearchOpen(true);
        setTopicsOpen(true);
    };

    const clearSearch = () => {
        setQuery("");
        setSearchOpen(false);
    };

    return (
        <>
            <Flexbox paddingInline={8} gap={2} style={{flex: "none"}}>
                <SidebarNavItem icon={MessageSquarePlus} label="开启新话题" onClick={onNewTopic}/>
                <SidebarNavItem icon={Search} label="搜索" onClick={openSearch}/>
                <SidebarNavItem
                    icon={MessageSquare}
                    label="话题"
                    active={!searchOpen}
                    onClick={() => {
                        clearSearch();
                        setTopicsOpen(true);
                    }}
                />
                <SidebarNavItem icon={ListTodo} label="任务" onClick={onOpenTasks}/>
            </Flexbox>

            {searchOpen ? (
                <Flexbox paddingInline={8} paddingBlock={4} style={{flex: "none"}}>
                    <div className="agent-topic-search">
                        <Search size={14} aria-hidden className="agent-topic-search-icon"/>
                        <input
                            ref={searchRef}
                            type="search"
                            className="agent-topic-search-input"
                            placeholder="搜索话题标题"
                            value={query}
                            aria-label="搜索话题标题"
                            onChange={(event) => setQuery(event.target.value)}
                        />
                        <button
                            type="button"
                            className="agent-topic-search-clear"
                            aria-label="关闭搜索"
                            onClick={clearSearch}
                        >
                            <X size={14}/>
                        </button>
                    </div>
                </Flexbox>
            ) : null}

            <Flexbox flex={1} gap={4} style={{overflowY: "auto", minHeight: 0, padding: "8px 8px 12px"}}>
                <button
                    type="button"
                    className="agent-sidebar-section"
                    onClick={() => setTopicsOpen((open) => !open)}
                >
          <span>
            话题 {searchOpen && query.trim() ? `${filtered.length}/${threads.length}` : threads.length}
          </span>
                    <ChevronDown
                        size={14}
                        className={topicsOpen ? "agent-sidebar-chevron" : "agent-sidebar-chevron is-closed"}
                        aria-hidden
                    />
                </button>

                {filtered.length === 0 ? (
                    <Text type="secondary" style={{fontSize: 12, padding: 8}}>
                        {threads.length === 0
                            ? "还没有话题，发一条消息开始。"
                            : "没有匹配的话题标题。"}
                    </Text>
                ) : topicsOpen ? (
                    groups.map((group) => {
                        const closed = folded[group.label];
                        return (
                            <Flexbox key={group.label} gap={1}>
                                <button
                                    type="button"
                                    className="agent-sidebar-group"
                                    onClick={() =>
                                        setFolded((prev) => ({...prev, [group.label]: !prev[group.label]}))
                                    }
                                >
                                    {group.label}
                                    <ChevronDown
                                        size={12}
                                        className={closed ? "agent-sidebar-chevron is-closed" : "agent-sidebar-chevron"}
                                        aria-hidden
                                    />
                                </button>
                                {closed
                                    ? null
                                    : group.threads.map((thread) => (
                                        <TopicRow
                                            key={thread.id}
                                            thread={thread}
                                            active={thread.id === activeThreadId}
                                            onSelect={() => onSelect(thread.id)}
                                            onRename={() => onRename(thread)}
                                            onDelete={() => onDelete(thread)}
                                        />
                                    ))}
                            </Flexbox>
                        );
                    })
                ) : null}
            </Flexbox>

            {footer}
        </>
    );
}

function SidebarNavItem({
                            icon: Icon,
                            label,
                            onClick,
                            active,
                        }: {
    icon: ComponentType<{ size?: number; strokeWidth?: number }>;
    label: string;
    onClick: () => void;
    active?: boolean;
}) {
    return (
        <button
            type="button"
            className={active ? "agent-sidebar-nav is-active" : "agent-sidebar-nav"}
            onClick={onClick}
        >
            <Icon size={16} strokeWidth={1.75}/>
            <span>{label}</span>
        </button>
    );
}

function TopicRow({
                      thread,
                      active,
                      onSelect,
                      onRename,
                      onDelete,
                  }: {
    thread: ChatThread;
    active: boolean;
    onSelect: () => void;
    onRename: () => void;
    onDelete: () => void;
}) {
    const [hovered, setHovered] = useState(false);

    return (
        <div
            className={active ? "agent-topic-row is-active" : "agent-topic-row"}
            role="button"
            tabIndex={0}
            onClick={onSelect}
            onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    onSelect();
                }
            }}
            onMouseEnter={() => setHovered(true)}
            onMouseLeave={() => setHovered(false)}
        >
            <span className="agent-topic-row-title">{thread.title}</span>
            {hovered || active ? (
                <span className="agent-topic-row-actions" onClick={(event) => event.stopPropagation()}>
          <ActionIcon icon={Pencil} size="small" title="重命名" onClick={onRename}/>
          <ActionIcon icon={Trash2} size="small" title="删除" onClick={onDelete}/>
        </span>
            ) : null}
        </div>
    );
}

import {useEffect, useRef, useState} from "react";
import {toast} from "sonner";
import {REFERENCE_LIMITS, referenceAttachment, type ReferenceAttachment} from "@/domain/references";
import {importReferenceFile, retryReferenceImport} from "@/lib/references/import";

export type ReferenceImportDraft = {
    id: string;
    filename: string;
    status: "importing" | "failed";
    error?: string;
    file: File;
    referenceId?: string
};
type DraftState = { attachments: ReferenceAttachment[]; imports: ReferenceImportDraft[] };
const EMPTY: DraftState = {attachments: [], imports: []};

export function useReferenceDraft(scope: string, projectId?: string) {
    const [drafts, setDrafts] = useState<Record<string, DraftState>>({});
    const controllers = useRef(new Map<string, AbortController>());
    const mounted = useRef(true);
    useEffect(() => {
        mounted.current = true;
        return () => {
            mounted.current = false;
            for (const controller of controllers.current.values()) controller.abort();
        };
    }, []);
    const draft = drafts[scope] ?? EMPTY;

    function update(fn: (previous: DraftState) => DraftState, key = scope) {
        if (mounted.current) setDrafts((previous) => ({...previous, [key]: fn(previous[key] ?? EMPTY)}));
    }

    function attach(attachment: ReferenceAttachment) {
        update((previous) => ({
            ...previous,
            attachments: [...previous.attachments.filter((item) => item.referenceId !== attachment.referenceId), attachment]
        }));
    }

    async function importFiles(files: File[], retryId?: string) {
        if (!projectId) return;
        if (files.length > REFERENCE_LIMITS.selection) {
            toast.error(`每次最多导入 ${REFERENCE_LIMITS.selection} 个文件`);
            return;
        }
        const jobs = files.map((file) => ({
            id: crypto.randomUUID(),
            filename: file.name,
            status: "importing" as const,
            file
        }));
        update((previous) => ({...previous, imports: [...previous.imports, ...jobs]}));
        for (const job of jobs) controllers.current.set(job.id, new AbortController());
        for (const job of jobs) {
            const controller = controllers.current.get(job.id);
            if (!controller || controller.signal.aborted || !mounted.current) continue;
            try {
                const options = {
                    signal: controller.signal,
                    onProgress: (reference: { id: string }) => update((previous) => ({
                        ...previous,
                        imports: previous.imports.map((item) => item.id === job.id ? {
                            ...item,
                            referenceId: reference.id
                        } : item)
                    }))
                };
                const reference = retryId ? await retryReferenceImport(projectId, retryId, options) : await importReferenceFile(projectId, job.file, options);
                if (controller.signal.aborted) continue;
                update((previous) => ({
                    ...previous,
                    imports: previous.imports.map((item) => item.id === job.id ? {
                        ...item,
                        referenceId: reference.id
                    } : item)
                }));
                if (reference.status !== "ready" && reference.status !== "partial") throw new Error(reference.error ?? "解析未完成，请重试");
                update((previous) => ({
                    attachments: [...previous.attachments.filter((item) => item.referenceId !== reference.id), referenceAttachment(reference)],
                    imports: previous.imports.filter((item) => item.id !== job.id)
                }));
            } catch (error) {
                if (!controller.signal.aborted) update((previous) => ({
                    ...previous,
                    imports: previous.imports.map((item) => item.id === job.id ? {
                        ...item,
                        status: "failed",
                        error: error instanceof Error ? error.message : "导入失败"
                    } : item)
                }));
            } finally {
                controllers.current.delete(job.id);
            }
        }
    }

    function cancel(id: string) {
        controllers.current.get(id)?.abort();
        controllers.current.delete(id);
        update((previous) => ({...previous, imports: previous.imports.filter((item) => item.id !== id)}));
    }

    function clearSent(attachments: ReferenceAttachment[], key = scope) {
        update((previous) => ({
            ...previous,
            attachments: previous.attachments.filter((item) => !attachments.some((sent) => sent.referenceId === item.referenceId && sent.revision === item.revision))
        }), key);
    }

    function moveTo(key: string) {
        if (key === scope) return;
        setDrafts((previous) => ({...previous, [key]: previous[scope] ?? EMPTY, [scope]: EMPTY}));
    }

    return {
        ...draft,
        moveTo,
        attach,
        importFiles,
        cancel,
        clearSent,
        remove: (attachment: ReferenceAttachment) => clearSent([attachment]),
        retry: (job: ReferenceImportDraft) => {
            cancel(job.id);
            void importFiles([job.file], job.referenceId);
        }
    };
}

