type AssetTab = Exclude<WorldTab, "setting">;
type WorldAsset = Character | Scene | Prop | VisualStyle;

const TAB_COPY: Record<AssetTab, { singular: string; create: string }> = {
    characters: {singular: "角色", create: "新建角色"},
    scenes: {singular: "场景", create: "新建场景"},
    props: {singular: "道具", create: "新建道具"},
    styles: {singular: "风格", create: "新建风格"},
};

function sourceAssetId(asset: WorldAsset): string | undefined {
    const value = asset.extra?.sourceAssetId;
    return typeof value === "string" ? value : undefined;
}

function coverOf(asset: WorldAsset, tab: AssetTab): Id | undefined {
    if (tab === "characters") {
        const character = asset as Character;
        return firstResultId(CHARACTER_SLOTS.map((slot) => character.slots?.[slot.id]));
    }
    if (tab === "scenes") {
        const scene = asset as Scene;
        return firstResultId(SCENE_SLOTS.map((slot) => scene.slots?.[slot.id]));
    }
    if (tab === "props") {
        const prop = asset as Prop;
        return firstResultId(PROP_SLOTS.map((slot) => prop.slots?.[slot.id]));
    }
    const style = asset as VisualStyle;
    return firstResultId(STYLE_SLOTS.map((slot) => style.slots?.[slot.id]));
}

function assetDetail(asset: WorldAsset, tab: AssetTab): string {
    if (tab === "characters") return (asset as Character).appearance || "未填写外观";
    if (tab === "scenes") {
        const scene = asset as Scene;
        return [scene.location, scene.timeOfDay].filter(Boolean).join(" · ") || "未填写地点";
    }
    if (tab === "props") return (asset as Prop).kind || "未填写类型";
    return asset.notes || "未填写风格说明";
}

export function AssetLibraryPage({projectId, tab, onTabChange}: {
    projectId: string;
    tab: WorldTab;
    onTabChange: (tab: WorldTab) => void;
}) {
    const navigate = useNavigate();
    const [query, setQuery] = useState("");
    const [pickerOpen, setPickerOpen] = useState(false);
    const characters =
        useLiveQuery(
            () => db.characters.where("projectId").equals(projectId).reverse().sortBy("updatedAt"),
            [projectId],
        ) ?? [];
    const scenes =
        useLiveQuery(
            () => db.scenes.where("projectId").equals(projectId).reverse().sortBy("updatedAt"),
            [projectId],
        ) ?? [];
    const props =
        useLiveQuery(
            () => db.props.where("projectId").equals(projectId).reverse().sortBy("updatedAt"),
            [projectId],
        ) ?? [];
    const styles =
        useLiveQuery(
            () => db.styles.where("projectId").equals(projectId).reverse().sortBy("updatedAt"),
            [projectId],
        ) ?? [];
    const [pendingDelete, setPendingDelete] = useState<
        { tab: AssetTab; id: string; name: string } | undefined
    >();

    const assets: Record<AssetTab, WorldAsset[]> = {characters, scenes, props, styles};
    const activeAssets = tab === "setting" ? [] : assets[tab].filter((asset) => matchesAssetSearch(asset, query));

    async function createLocal(activeTab: AssetTab) {
        if (activeTab === "characters") {
            const asset = await addCharacter(projectId);
            await navigate({
                to: "/p/$projectId/assets/characters/$characterId",
                params: {projectId, characterId: asset.id},
            });
        } else if (activeTab === "scenes") {
            const asset = await addScene(projectId);
            await navigate({
                to: "/p/$projectId/assets/scenes/$sceneId",
                params: {projectId, sceneId: asset.id},
            });
        } else if (activeTab === "props") {
            const asset = await addProp(projectId);
            await navigate({
                to: "/p/$projectId/assets/props/$propId",
                params: {projectId, propId: asset.id},
            });
        } else {
            const asset = await addStyle(projectId);
            await navigate({
                to: "/p/$projectId/assets/styles/$styleId",
                params: {projectId, styleId: asset.id},
            });
        }
    }

    return (
        <div className="h-full overflow-auto">
            <div className="mx-auto max-w-6xl px-4 py-6 sm:px-8">
                <div className="flex flex-wrap items-center justify-between gap-4">
                    <div>
                        <h1 className="text-lg font-semibold">世界</h1>
                        <p className="text-muted-foreground mt-1 text-xs">
                            设定是这部戏一直为真的东西。角色、场景、道具、风格是能被点名的名册。
                        </p>
                    </div>
                    {tab !== "setting" ? (
                        <div className="flex gap-2">
                            <Button size="sm" variant="outline" onClick={() => setPickerOpen(true)}>
                                <Library/> 从工作室添加
                            </Button>
                            <Button size="sm" variant="brand" onClick={() => void createLocal(tab)}>
                                <Plus/> {TAB_COPY[tab].create}
                            </Button>
                        </div>
                    ) : null}
                </div>

                <Tabs
                    value={tab}
                    onValueChange={(value) => {
                        setQuery("");
                        onTabChange(value as WorldTab);
                    }}
                    className="mt-5"
                >
                    <TabsList className="h-auto flex-wrap">
                        <TabsTrigger value="setting">设定</TabsTrigger>
                        <TabsTrigger value="characters">角色 {characters.length}</TabsTrigger>
                        <TabsTrigger value="scenes">场景 {scenes.length}</TabsTrigger>
                        <TabsTrigger value="props">道具 {props.length}</TabsTrigger>
                        <TabsTrigger value="styles">风格 {styles.length}</TabsTrigger>
                    </TabsList>
                </Tabs>

                {tab !== "setting" ? <Input className="mt-5 max-w-sm" aria-label={`搜索项目${TAB_COPY[tab].singular}`}
                                            placeholder={`搜索${TAB_COPY[tab].singular}名称与设定…`} value={query}
                                            onChange={(event) => setQuery(event.target.value)}/> : null}
                {tab === "setting" ? (
                    <WorldSettingPanel projectId={projectId}/>
                ) : activeAssets.length === 0 ? (
                    query.trim() ?
                        <p className="text-muted-foreground py-8 text-sm">没有匹配的{TAB_COPY[tab].singular}，试试其他关键词。</p> :
                        <EmptyWorldTab singular={TAB_COPY[tab].singular}/>
                ) : (
                    <ul className="mt-6 grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-4">
                        {activeAssets.map((asset) => (
                            <AssetCard
                                key={asset.id}
                                projectId={projectId}
                                tab={tab}
                                asset={asset}
                                onDelete={() => setPendingDelete({tab, id: asset.id, name: asset.name})}
                            />
                        ))}
                    </ul>
                )}
            </div>

            {tab !== "setting" ? (
                <StudioAssetPicker
                    key={tab}
                    open={pickerOpen}
                    onOpenChange={setPickerOpen}
                    projectId={projectId}
                    tab={tab}
                    copiedAssets={assets[tab]}
                />
            ) : null}

            <AlertDialog
                open={Boolean(pendingDelete)}
                onOpenChange={(open) => !open && setPendingDelete(undefined)}
            >
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>
                            删除{pendingDelete ? TAB_COPY[pendingDelete.tab].singular : "资产"}
                        </AlertDialogTitle>
                        <AlertDialogDescription>
                            确定删除「{pendingDelete?.name}」？已有引用会被清除。
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>取消</AlertDialogCancel>
                        <AlertDialogAction
                            className="bg-destructive hover:bg-destructive/90"
                            onClick={() => {
                                if (!pendingDelete) return;
                                if (pendingDelete.tab === "characters") void deleteCharacter(pendingDelete.id);
                                else if (pendingDelete.tab === "scenes") void deleteScene(pendingDelete.id);
                                else if (pendingDelete.tab === "props") void deleteProp(pendingDelete.id);
                                else void deleteStyle(pendingDelete.id);
                            }}
                        >
                            删除
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

function AssetCard({
                       projectId,
                       tab,
                       asset,
                       onDelete,
                   }: {
    projectId: string;
    tab: AssetTab;
    asset: WorldAsset;
    onDelete: () => void;
}) {
    const card = (
        <>
            <MediaPreview
                mediaId={coverOf(asset, tab)}
                className="h-40 w-full"
                empty={TAB_COPY[tab].singular}
            />
            <div className="px-3 py-3">
                <p className="truncate font-medium">{asset.name}</p>
                <p className="text-muted-foreground truncate text-xs">{assetDetail(asset, tab)}</p>
            </div>
        </>
    );
    return (
        <li className="group relative">
            {tab === "characters" ? (
                <Link
                    to="/p/$projectId/assets/characters/$characterId"
                    params={{projectId, characterId: asset.id}}
                    className="bg-card block overflow-hidden rounded-2xl border"
                >
                    {card}
                </Link>
            ) : tab === "scenes" ? (
                <Link
                    to="/p/$projectId/assets/scenes/$sceneId"
                    params={{projectId, sceneId: asset.id}}
                    className="bg-card block overflow-hidden rounded-2xl border"
                >
                    {card}
                </Link>
            ) : tab === "props" ? (
                <Link
                    to="/p/$projectId/assets/props/$propId"
                    params={{projectId, propId: asset.id}}
                    className="bg-card block overflow-hidden rounded-2xl border"
                >
                    {card}
                </Link>
            ) : (
                <Link
                    to="/p/$projectId/assets/styles/$styleId"
                    params={{projectId, styleId: asset.id}}
                    className="bg-card block overflow-hidden rounded-2xl border"
                >
                    {card}
                </Link>
            )}
            <Button
                type="button"
                size="icon-sm"
                variant="secondary"
                className="absolute top-2 right-2 flex rounded-full md:opacity-0 md:group-hover:opacity-100 md:group-focus-within:opacity-100 focus-visible:opacity-100"
                onClick={onDelete}
                aria-label={`删除${TAB_COPY[tab].singular}`}
            >
                <Trash2/>
            </Button>
        </li>
    );
}

function StudioAssetPicker({
                               open,
                               onOpenChange,
                               projectId,
                               tab,
                               copiedAssets,
                           }: {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    projectId: string;
    tab: AssetTab;
    copiedAssets: WorldAsset[];
}) {
    const [selected, setSelected] = useState<Set<string>>(new Set());
    const [copying, setCopying] = useState(false);
    const [query, setQuery] = useState("");
    const studioAssets =
        useLiveQuery(async () => {
            const table =
                tab === "characters"
                    ? db.characters
                    : tab === "scenes"
                        ? db.scenes
                        : tab === "props"
                            ? db.props
                            : db.styles;
            return table.where("projectId").equals(STUDIO_LIBRARY_ID).reverse().sortBy("updatedAt");
        }, [tab]) ?? [];
    const copiedSourceIds = new Set(
        copiedAssets.map(sourceAssetId).filter((id): id is string => Boolean(id)),
    );
    const available = studioAssets.filter((asset) => !copiedSourceIds.has(asset.id) && matchesAssetSearch(asset, query));

    function closePicker() {
        setSelected(new Set());
        onOpenChange(false);
    }

    async function copySelected() {
        setCopying(true);
        try {
            const copied = await copySelection(selected, copiedSourceIds, async (sourceId) => {
                if (tab === "characters") await copyStudioCharacter(projectId, sourceId);
                else if (tab === "scenes") await copyStudioScene(projectId, sourceId);
                else if (tab === "props") await copyStudioProp(projectId, sourceId);
                else await copyStudioStyle(projectId, sourceId);
            }, (sourceId) => setSelected((current) => new Set([...current].filter((id) => id !== sourceId))));
            toast.success(`已添加 ${copied} 个${TAB_COPY[tab].singular}`);
            closePicker();
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "添加失败");
        } finally {
            setCopying(false);
        }
    }

    return (
        <Dialog
            open={open}
            onOpenChange={(nextOpen) => {
                if (copying) return;
                if (!nextOpen) setSelected(new Set());
                onOpenChange(nextOpen);
            }}
        >
            <DialogContent>
                <DialogHeader>
                    <DialogTitle>从工作室添加{TAB_COPY[tab].singular}</DialogTitle>
                    <DialogDescription>添加后成为项目快照，可以独立修改。</DialogDescription>
                </DialogHeader>
                <Input aria-label="搜索工作室资产" placeholder="搜索名称与设定…" value={query}
                       disabled={copying} onChange={(event) => setQuery(event.target.value)}/>
                <div className="max-h-80 space-y-2 overflow-auto">
                    {available.length === 0 ? (
                        <p className="text-muted-foreground py-8 text-center text-sm">
                            {query.trim() ? "没有匹配的" : "没有可添加的"}工作室{TAB_COPY[tab].singular}
                        </p>
                    ) : (
                        available.map((asset) => (
                            <label
                                key={asset.id}
                                className="hover:bg-muted/50 flex cursor-pointer items-center gap-3 rounded-xl border p-3"
                            >
                                <Checkbox
                                    disabled={copying}
                                    checked={selected.has(asset.id)}
                                    onCheckedChange={(checked) =>
                                        setSelected((current) => {
                                            const next = new Set(current);
                                            if (checked) next.add(asset.id);
                                            else next.delete(asset.id);
                                            return next;
                                        })
                                    }
                                />
                                <MediaPreview
                                    mediaId={coverOf(asset, tab)}
                                    className="size-12 shrink-0 rounded-lg"
                                    empty={TAB_COPY[tab].singular}
                                />
                                <span className="min-w-0">
                  <span className="block truncate text-sm font-medium">{asset.name}</span>
                  <span className="text-muted-foreground block truncate text-xs">
                    {assetDetail(asset, tab)}
                  </span>
                </span>
                            </label>
                        ))
                    )}
                </div>
                <DialogFooter>
                    <Button variant="outline" disabled={copying} onClick={closePicker}>
                        取消
                    </Button>
                    <Button
                        variant="brand"
                        disabled={selected.size === 0 || copying}
                        onClick={() => void copySelected()}
                    >
                        {copying ? "添加中…" : `添加 ${selected.size || ""}`}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

function EmptyWorldTab({singular}: { singular: string }) {
    return (
        <div className="bg-card mt-6 max-w-xl rounded-2xl border border-dashed px-5 py-8">
            <p className="text-sm font-medium">还没有{singular}</p>
            <p className="text-muted-foreground mt-2 text-xs leading-5">
                可以新建，或从工作室添加一份可独立修改的快照。
            </p>
        </div>
    );
}

import {useState} from "react";
import {Check, Library, Plus, Trash2, Volume2} from "lucide-react";
import {db} from "@/db/database";
import {addAudioClip, deleteAudioTake, patchAudioSegment} from "@/db/audio";
import {promoteLegacyMaterial} from "@/db/materials";
import type {AudioProjectSnapshot, AudioSegment, AudioTake} from "@/domain/audio";
import {DraftConflictError} from "@/lib/draftConflict";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {AudioPlayer, Field, GenerationJobs, SavedText, timeLabel} from "@/components/audioMusic/shared";
import {Disclosure, DisclosureTitle, SelectOption, WorkspaceSelect} from "@/components/audioMusic/controls";
import {SpeechControls} from "./SpeechControls";
import {AudioExports} from "./AudioExports";

export type AudioAction = (fn: () => Promise<unknown>) => Promise<void>;

export function AudioInspector({
                                   projectId,
                                   chapterId,
                                   snapshot,
                                   segment,
                                   takeId,
                                   tab,
                                   onTabChange,
                                   onTake,
                                   onClip,
                                   onAddSources,
                                   action,
                                   busy,
                                   onVoices
                               }: {
    projectId: string;
    chapterId: string;
    snapshot: AudioProjectSnapshot;
    segment?: AudioSegment;
    takeId: string;
    onVoices: () => void;
    tab: "voice" | "sources" | "exports";
    onTabChange: (tab: "voice" | "sources" | "exports") => void;
    onTake: (id: string) => void;
    onClip: (id: string) => void;
    onAddSources: (segmentId?: string) => void;
    action: AudioAction;
    busy: boolean;
}) {
    const [trackId, setTrackId] = useState("");
    const [pauseSec, setPauseSec] = useState("0");
    const tracks = snapshot.tracks.filter((row) => row.chapterId === chapterId);
    const track = tracks.find((row) => row.id === trackId) ?? tracks[0];
    const take = snapshot.takes.find((row) => row.id === takeId);
    const takes = tab === "voice" && segment ? snapshot.takes.filter((row) => row.segmentId === segment.id) : snapshot.takes;
    const speaker = snapshot.speakers.find((row) => row.id === segment?.speakerId);
    return <div className="as-inspector-content">
        <nav className="as-inspector-tabs" aria-label="声音面板"><Button size="sm"
                                                                         variant={tab === "voice" ? "secondary" : "ghost"}
                                                                         onClick={() => onTabChange("voice")}>段落声音</Button><Button
            size="sm" variant={tab === "sources" ? "secondary" : "ghost"}
            onClick={() => onTabChange("sources")}>素材</Button><Button size="sm"
                                                                        variant={tab === "exports" ? "secondary" : "ghost"}
                                                                        onClick={() => onTabChange("exports")}>成品</Button>
        </nav>
        {tab === "exports" ? <><AudioExports snapshot={snapshot}/>{!snapshot.exports.length &&
            <div className="as-inspector-empty"><p>还没有导出成品</p><small>将声音放入时间线后，从底部导出 WAV。</small>
            </div>}</> : <>
            <div className="as-inspector-heading"><span className="as-voice-avatar">{speaker?.name.slice(0, 1) ??
                <Volume2 size={15}/>}</span>
                <div>
                    <strong>{tab === "voice" && segment ? speaker?.name ?? "当前段落" : "项目声音"}</strong><small>{tab === "voice" && segment ? `${snapshot.segments.filter((row) => row.chapterId === chapterId).indexOf(segment) + 1} · ${segment.text.slice(0, 48) || "尚未填写脚本"}` : `${snapshot.takes.length} 个声音版本，原始文件均保留`}</small>
                </div>
            </div>
            <Button variant="outline" size="sm" onClick={() => onAddSources(tab === "voice" ? segment?.id : undefined)}><Plus/>添加声音</Button>
            {tab === "voice" && segment &&
                <SpeechControls key={`${segment.id}:${speaker?.id ?? ""}`} segment={segment} speaker={speaker}
                                speakers={snapshot.speakers} onVoices={onVoices}/>}
            <div className="as-subheading"><h3>{tab === "voice" && segment ? "配音版本" : "全部声音"}</h3>
                <span>{takes.length}</span></div>
            {!takes.length && <p className="as-help">录音、上传已有声音，或使用文字生成配音。完成后会保留在这里。</p>}
            <div className="as-version-list">{takes.map((row, index) => <Button
                variant={takeId === row.id ? "secondary" : "ghost"} className="as-version-row" key={row.id}
                onClick={() => onTake(row.id)}><Volume2
                size={14}/><span><strong>{row.name || `版本 ${index + 1}`}</strong><small>{sourceLabel(row.source)} · {timeLabel(row.durationSec)}{row.source === "tts" && row.textSnapshot !== undefined && snapshot.segments.find((item) => item.id === row.segmentId)?.text !== row.textSnapshot ? " · 播报文本与稿件不同" : ""}</small></span>{segment?.selectedTakeId === row.id &&
                <Check size={14}/>}</Button>)}</div>
            {take && <div className="as-take-detail"><AudioPlayer mediaId={take.mediaId} title={take.name}
                                                                  compact/>{take.textSnapshot !== undefined &&
                <Disclosure><DisclosureTitle>实际播报文本</DisclosureTitle><p
                    className="whitespace-pre-wrap text-sm">{take.textSnapshot}</p></Disclosure>}
                <div className="as-detail-actions">{segment && take.segmentId === segment.id &&
                    <Button size="sm" variant={segment.selectedTakeId === take.id ? "secondary" : "outline"}
                            disabled={busy || segment.selectedTakeId === take.id}
                            onClick={() => void action(() => patchAudioSegment(projectId, segment.id, segment.revision, {selectedTakeId: take.id}))}><Check/>{segment.selectedTakeId === take.id ? "已采用" : "采用此版本"}
                    </Button>}<Button size="icon-sm" variant="ghost" title="保存到素材库" aria-label="保存到素材库"
                                      disabled={busy}
                                      onClick={() => void action(() => promoteLegacyMaterial("media", take.mediaId, {kind: "global"}))}><Library/></Button><Button
                    size="icon-sm" variant="ghost" title="删除未采用版本" aria-label="删除未采用版本"
                    disabled={busy || snapshot.clips.some((clip) => clip.takeId === take.id) || snapshot.segments.some((row) => row.selectedTakeId === take.id)}
                    onClick={() => void action(async () => {
                        await deleteAudioTake(projectId, take.id, take.revision);
                        onTake("");
                    })}><Trash2/></Button></div>
                <Field label="放入音轨"><WorkspaceSelect value={track?.id ?? ""}
                                                         onValueChange={setTrackId}>{tracks.map((row) => <SelectOption
                    key={row.id} value={row.id}>{row.name}</SelectOption>)}</WorkspaceSelect></Field><Field
                    label="前置停顿（秒）"><Input type="number" min={0} max={300} step={0.1} value={pauseSec}
                                                onChange={(event) => setPauseSec(event.target.value)}/></Field><Button
                    className="w-full" disabled={busy || !track} onClick={() => void action(async () => {
                    if (!track) return;
                    const pause = Number(pauseSec);
                    if (!Number.isFinite(pause) || pause < 0 || pause > 300) throw new Error("前置停顿应为 0–300 秒");
                    const end = Math.max(0, ...snapshot.clips.filter((row) => row.trackId === track.id).map((row) => row.startSec + row.trimEndSec - row.trimStartSec));
                    const clip = await addAudioClip(projectId, {
                        chapterId,
                        trackId: track.id,
                        takeId: take.id,
                        startSec: end + pause,
                        trimStartSec: 0,
                        trimEndSec: take.durationSec,
                        gain: 1,
                        fadeInSec: 0,
                        fadeOutSec: 0
                    });
                    onClip(clip.id);
                })}><Plus/>加入时间线</Button><p className="as-help">追加到音轨末尾，已有剪辑保持原样。</p></div>}
            {segment && tab === "voice" &&
                <Disclosure className="as-note"><DisclosureTitle>配音备注</DisclosureTitle><SavedText
                    key={`${segment.id}:notes`} projectId={projectId} rowId={segment.id} field="notes"
                    value={segment.notes} label="配音备注" multiline save={async (notes, baseline) => {
                    const current = await db.audioSegments.get(segment.id);
                    if (!current || current.notes !== baseline) throw new DraftConflictError();
                    await patchAudioSegment(projectId, current.id, current.revision, {notes});
                }}/></Disclosure>}
        </>}
        <GenerationJobs projectId={projectId}/>
    </div>;
}

function sourceLabel(source: AudioTake["source"]) {
    return {upload: "导入", recording: "录音", library: "素材库", tts: "AI 配音", music: "音乐作品"}[source];
}

