const cache = new AudioBufferCache();

async function loadBuffers(schedule: AudioSchedule) {
    preflightAudioRender(schedule.durationSec, schedule.sources);
    const buffers = new Map<string, AudioBuffer>();
    for (const source of schedule.sources) {
        let buffer = cache.get(source.mediaId);
        if (!buffer) {
            const record = await db.media.get(source.mediaId);
            if (!record) throw new Error("音频原文件已不存在，无法完整播放或导出");
            buffer = await decodeAudioBlob(record.blob);
            cache.set(source.mediaId, buffer);
        }
        buffers.set(source.mediaId, buffer);
    }
    return buffers;
}

type DragState = {
    clip: AudioClip;
    kind: "move" | "start" | "end";
    initialX: number;
    startSec: number;
    trimStartSec: number;
    trimEndSec: number
};

export interface AudioTimelineProps {
    projectId: string;
    projectName: string;
    chapterId: string;
    snapshot: AudioProjectSnapshot;
    selectedId: string;
    onSelect: (id: string) => void;
    mobileMode?: "script" | "timeline";
    seekRequest?: { id: string; position: number };
    onPositionChange?: (seconds: number) => void;
    onOpenSources?: () => void;
}

export function AudioTimeline({
                                  projectId,
                                  projectName,
                                  chapterId,
                                  snapshot,
                                  selectedId,
                                  onSelect,
                                  mobileMode = "script",
                                  seekRequest,
                                  onPositionChange,
                                  onOpenSources
                              }: AudioTimelineProps) {
    const player = useRef<AudioPreviewPlayer | null>(null);
    const scroll = useRef<HTMLDivElement>(null);
    const root = useRef<HTMLElement>(null);
    const onPosition = useRef(onPositionChange);
    onPosition.current = onPositionChange;
    const history = useMemo(() => new AudioClipHistory(projectId, chapterId), [projectId, chapterId]);
    const [, redraw] = useState(0);
    const [position, setPosition] = useState(0);
    const positionRef = useRef(0);
    const [playing, setPlaying] = useState(false);
    const [zoom, setZoom] = useState(1);
    const [viewportWidth, setViewportWidth] = useState(900);
    const [expanded, setExpanded] = useState(true);
    const [snapping, setSnapping] = useState(true);
    const [error, setError] = useState("");
    const [notice, setNotice] = useState("");
    const [busy, setBusy] = useState(false);
    const busyRef = useRef(false);
    const mounted = useRef(true);
    const [exportScope, setExportScope] = useState("chapter");
    const [inspector, setInspector] = useState(false);
    const [menu, setMenu] = useState<{ x: number; y: number; clip?: AudioClip; track?: AudioTrack }>();
    const [drag, setDrag] = useState<DragState>();
    const dragRef = useRef<DragState | undefined>(undefined);
    const scrubRef = useRef<{ resume: boolean } | undefined>(undefined);
    const playEpoch = useRef(0);
    const tracks = snapshot.tracks.filter((row) => row.chapterId === chapterId).sort((a, b) => a.order - b.order);
    const clips = snapshot.clips.filter((row) => row.chapterId === chapterId);
    const selected = clips.find((row) => row.id === selectedId);
    const contentDuration = Math.max(0, ...clips.map((clip) => clip.startSec + clip.trimEndSec - clip.trimStartSec));
    const geometry = timelineGeometry(contentDuration, viewportWidth, zoom);
    const compositionKey = JSON.stringify([clips, tracks]);
    const canSplit = (clip: AudioClip) => position > clip.startSec && position < clip.startSec + clip.trimEndSec - clip.trimStartSec && position - clip.startSec >= clip.fadeInSec && position - clip.startSec <= clip.trimEndSec - clip.trimStartSec - clip.fadeOutSec;
    const splitAvailable = Boolean(selected && canSplit(selected));

    function updatePosition(seconds: number) {
        positionRef.current = seconds;
        setPosition(seconds);
        onPosition.current?.(seconds);
    }

    useEffect(() => {
        mounted.current = true;
        const instance = new AudioPreviewPlayer();
        player.current = instance;
        const timer = window.setInterval(() => {
            if (instance.playing) updatePosition(instance.currentTime);
            else if (playingRef.current) updatePosition(instance.currentTime);
            playingRef.current = instance.playing;
            setPlaying(instance.playing);
        }, 60);
        const pause = () => {
            playEpoch.current++;
            updatePosition(instance.pause());
            setPlaying(false);
        };
        document.addEventListener("audio-workspace-audition", pause);
        return () => {
            mounted.current = false;
            playEpoch.current++;
            clearInterval(timer);
            document.removeEventListener("audio-workspace-audition", pause);
            void instance.dispose();
            player.current = null;
        };
    }, [projectId]);
    const playingRef = useRef(false);
    useEffect(() => {
        playEpoch.current++;
        player.current?.pause();
        updatePosition(0);
        setPlaying(false);
        setInspector(false);
        setMenu(undefined);
        dragRef.current = undefined;
        setDrag(undefined);
        setZoom(1);
    }, [chapterId]);
    useEffect(() => {
        playEpoch.current++;
        player.current?.pause();
        setPlaying(false);
    }, [compositionKey]);
    useEffect(() => {
        if (!root.current) return;
        const observer = new ResizeObserver(([entry]) => setViewportWidth(entry.contentRect.width));
        observer.observe(root.current);
        return () => observer.disconnect();
    }, []);
    useEffect(() => {
        if (!seekRequest) return;
        playEpoch.current++;
        player.current?.pause();
        setPlaying(false);
        updatePosition(Math.max(0, seekRequest.position));
        if (scroll.current) scroll.current.scrollLeft = Math.max(0, seekRequest.position * geometry.pixelsPerSecond - (viewportWidth - 112) / 3);
    }, [seekRequest?.id]);
    useEffect(() => {
        if (!playing || !scroll.current) return;
        const x = position * geometry.pixelsPerSecond, view = scroll.current;
        const usable = view.clientWidth - 112;
        if (x > view.scrollLeft + usable - 28 || x < view.scrollLeft) view.scrollLeft = Math.max(0, x - usable / 3);
    }, [position, playing, geometry.pixelsPerSecond]);

    async function action(fn: () => Promise<unknown>) {
        if (busyRef.current) return;
        busyRef.current = true;
        setBusy(true);
        setError("");
        try {
            await fn();
            if (mounted.current) redraw((value) => value + 1);
        } catch (e) {
            if (mounted.current) setError(errorText(e));
        } finally {
            busyRef.current = false;
            if (mounted.current) setBusy(false);
        }
    }

    async function startPlayback(at: number) {
        const epoch = ++playEpoch.current;
        const instance = player.current;
        document.querySelectorAll("audio").forEach((audio) => audio.pause());
        const schedule = buildAudioSchedule(snapshot, chapterId);
        if (!schedule.clips.length) throw new Error("当前章节没有可播放的片段，请检查静音和独听设置");
        const buffers = await loadBuffers(schedule);
        if (!mounted.current || player.current !== instance || playEpoch.current !== epoch) return;
        await instance?.play(schedule, buffers, at >= schedule.durationSec ? 0 : at);
        setPlaying(Boolean(instance?.playing));
    }

    async function play() {
        if (player.current?.playing) {
            updatePosition(player.current.pause());
            setPlaying(false);
        } else await startPlayback(positionRef.current);
    }

    function seek(seconds: number) {
        playEpoch.current++;
        player.current?.pause();
        setPlaying(false);
        updatePosition(Math.max(0, Math.min(contentDuration, seconds)));
    }

    async function exportMix() {
        await flushPendingDrafts(projectId);
        const frozenSnapshot = await getAudioProjectSnapshot(projectId);
        const schedule = buildAudioSchedule(frozenSnapshot, exportScope === "chapter" ? chapterId : undefined);
        if (!schedule.clips.length) throw new Error("请先将音频放入时间线");
        const buffers = await loadBuffers(schedule);
        const result = await renderAudioMix(schedule, buffers);
        const mediaId = createId("med");
        const chapter = frozenSnapshot.chapters.find((row) => row.id === chapterId);
        const filename = `${projectName}-${exportScope === "chapter" ? chapter?.title ?? "章节" : "完整项目"}.wav`;
        await addAudioExport(projectId, {
            chapterId: exportScope === "chapter" ? chapterId : undefined,
            scope: exportScope === "chapter" ? "chapter" : "project",
            chapterTitle: exportScope === "chapter" ? chapter?.title : undefined,
            fingerprint: JSON.stringify(schedule),
            format: "wav",
            mediaId,
            durationSec: result.durationSec
        }, {id: mediaId, projectId, filename, blob: result.blob, mimeType: "audio/wav"});
        downloadBlob(result.blob, filename);
        setNotice(result.attenuation < 1 ? `已导出 WAV；为避免削波，整体降低 ${Math.abs(result.attenuationDb).toFixed(1)} dB。` : "WAV 已保存到项目并开始下载。");
    }

    async function removeClip(clip: AudioClip) {
        await history.remove(clip);
        onSelect("");
        setInspector(false);
        root.current?.focus({preventScroll: true});
    }

    async function duplicateClip(clip: AudioClip) {
        const rows = await history.duplicate(clip);
        const copy = rows.at(-1); // History appends the new copy after the persisted chapter rows.
        if (copy) onSelect(copy.id);
        root.current?.focus({preventScroll: true});
    }

    function openClipMenu(clip: AudioClip, x: number, y: number) {
        if (busyRef.current || dragRef.current) return;
        onSelect(clip.id);
        setMenu({clip, x, y});
    }

    const shortcuts = useRef({
        play,
        action,
        selected,
        history,
        position,
        splitAvailable,
        removeClip,
        duplicateClip,
        menu
    });
    shortcuts.current = {play, action, selected, history, position, splitAvailable, removeClip, duplicateClip, menu};
    useEffect(() => {
        const handle = (event: KeyboardEvent) => {
            const latest = shortcuts.current;
            const command = resolveTimelineShortcut(event, {
                focused: Boolean(root.current?.contains(document.activeElement)),
                blocked: busyRef.current || Boolean(dragRef.current) || Boolean(latest.menu) || isFormFieldTarget(event.target),
                hasSelection: Boolean(latest.selected), canSplit: latest.splitAvailable,
                canUndo: latest.history.canUndo, canRedo: latest.history.canRedo,
            });
            if (!command) return;
            const tasks = {
                play: latest.play,
                undo: () => latest.history.undo(),
                redo: () => latest.history.redo(),
                remove: () => latest.removeClip(latest.selected!),
                duplicate: () => latest.duplicateClip(latest.selected!),
                split: () => latest.history.split(latest.selected!, latest.position),
            };
            event.preventDefault();
            void latest.action(tasks[command]);
        };
        window.addEventListener("keydown", handle);
        return () => window.removeEventListener("keydown", handle);
    }, []);

    function scrub(event: PointerEvent<HTMLDivElement>) {
        const rect = event.currentTarget.getBoundingClientRect();
        seek((event.clientX - rect.left) / geometry.pixelsPerSecond);
    }

    function beginDrag(event: PointerEvent, clip: AudioClip, kind: DragState["kind"]) {
        event.stopPropagation();
        if (event.button !== 0 || event.ctrlKey || busyRef.current) return;
        event.preventDefault();
        root.current?.focus({preventScroll: true});
        playEpoch.current++;
        onSelect(clip.id);
        player.current?.pause();
        setPlaying(false);
        event.currentTarget.setPointerCapture(event.pointerId);
        const next = {
            clip,
            kind,
            initialX: event.clientX,
            startSec: clip.startSec,
            trimStartSec: clip.trimStartSec,
            trimEndSec: clip.trimEndSec
        };
        dragRef.current = next;
        setDrag(next);
    }

    function moveDrag(event: PointerEvent) {
        event.stopPropagation();
        const current = dragRef.current;
        if (!current) return;
        const clip = current.clip, take = snapshot.takes.find((row) => row.id === clip.takeId);
        if (!take) return;
        const delta = (event.clientX - current.initialX) / geometry.pixelsPerSecond;
        const targets = [0, positionRef.current, ...clips.filter((row) => row.id !== clip.id).flatMap((row) => [row.startSec, row.startSec + row.trimEndSec - row.trimStartSec])];
        const snap = (value: number, length = 0) => snapTimelinePosition(value, length, targets, geometry.pixelsPerSecond, snapping && !event.altKey);
        let next = {...current};
        const minimum = Math.max(.02, clip.fadeInSec + clip.fadeOutSec);
        if (current.kind === "move") next.startSec = snap(clip.startSec + delta, clip.trimEndSec - clip.trimStartSec);
        else if (current.kind === "start") {
            const timelineStart = snap(clip.startSec + delta);
            next.trimStartSec = Math.min(clip.trimEndSec - minimum, Math.max(0, clip.trimStartSec - clip.startSec, clip.trimStartSec + timelineStart - clip.startSec));
            next.startSec = clip.startSec + next.trimStartSec - clip.trimStartSec;
        } else {
            const timelineEnd = snap(clip.startSec + clip.trimEndSec - clip.trimStartSec + delta);
            next.trimEndSec = Math.min(take.durationSec, Math.max(clip.trimStartSec + minimum, clip.trimStartSec + timelineEnd - clip.startSec));
        }
        dragRef.current = next;
        setDrag(next);
    }

    function endDrag(event: PointerEvent) {
        event.stopPropagation();
        const current = dragRef.current;
        dragRef.current = undefined;
        setDrag(undefined);
        if (!current) return;
        const {clip, startSec, trimStartSec, trimEndSec} = current;
        if (startSec !== clip.startSec || trimStartSec !== clip.trimStartSec || trimEndSec !== clip.trimEndSec) void action(() => history.executePatch(clip, {
            startSec,
            trimStartSec,
            trimEndSec
        }));
    }

    function cancelDrag(event: PointerEvent) {
        event.stopPropagation();
        dragRef.current = undefined;
        setDrag(undefined);
    }

    function addTrack(role: AudioTrack["role"]) {
        return action(() => addAudioTrack(projectId, {
            chapterId,
            role,
            name: role === "music" ? "背景音乐" : role === "effects" ? "音效" : "人声",
            order: tracks.length,
            gain: 1,
            muted: false,
            solo: false
        }));
    }

    return <section ref={root} className="at-dock" data-expanded={expanded} data-mobile-mode={mobileMode}
                    aria-label="音频制作时间线" tabIndex={-1}>
        <div className="at-transport">
            <Button variant="ghost" size="icon-sm" aria-label={expanded ? "收起时间线" : "展开时间线"}
                    aria-expanded={expanded} className="at-collapse" onClick={() => setExpanded(!expanded)}>{expanded ?
                <ChevronDown/> : <ChevronUp/>}</Button>
            <Button variant="ghost" size="icon-sm" aria-label="回到开头" title="回到开头" disabled={busy}
                    onClick={() => seek(0)}><SkipBack/></Button>
            <Button className="at-play" size="icon-sm" aria-label={playing ? "暂停" : "播放章节"}
                    title="播放 / 暂停 · Space" disabled={busy || !clips.length}
                    onClick={() => void action(play)}>{playing ? <Pause/> : <Play/>}</Button>
            <Popover><PopoverTrigger asChild><Button variant="ghost" className="at-clock" aria-label="精确定位播放位置"><span>{timeLabel(position)}</span><span>/ {timeLabel(contentDuration)}</span></Button></PopoverTrigger><PopoverContent
                side="top" className="at-position-popover"><Field label="播放位置（秒）"><Input aria-label="播放位置（秒）"
                                                                                              type="number" min={0}
                                                                                              max={contentDuration}
                                                                                              step={.1}
                                                                                              value={Number(position.toFixed(1))}
                                                                                              onChange={(event) => seek(Number(event.target.value) || 0)}/></Field></PopoverContent></Popover>
            <div className="at-edit-actions"><span className="at-divider"/><Button size="icon-sm" variant="ghost"
                                                                                   disabled={busy || !history.canUndo}
                                                                                   aria-label="撤销时间线编辑"
                                                                                   title="撤销 · ⌘/Ctrl Z"
                                                                                   onClick={() => void action(() => history.undo())}><RotateCcw/></Button><Button
                size="icon-sm" variant="ghost" disabled={busy || !history.canRedo} aria-label="重做时间线编辑"
                title="重做 · ⌘/Ctrl Shift Z"
                onClick={() => void action(() => history.redo())}><RotateCw/></Button><Button size="icon-sm"
                                                                                              variant="ghost"
                                                                                              disabled={busy || !splitAvailable}
                                                                                              aria-label="在播放位置分割"
                                                                                              title="在播放位置分割 · S"
                                                                                              onClick={() => selected && void action(() => history.split(selected, position))}><Scissors/></Button>
            </div>
            <Button size="icon-sm" variant="ghost" disabled={busy || !selected} className="at-quick-delete"
                    aria-label="删除选中片段" title="删除片段 · Delete / Backspace（可撤销）"
                    onClick={() => selected && void action(() => removeClip(selected))}><Trash2/></Button>
            <Button size="icon-sm" variant="ghost" disabled={busy || !selected} aria-label="片段更多操作"
                    title="片段更多操作 / 右键菜单" onClick={(event) => {
                if (!selected) return;
                const bounds = event.currentTarget.getBoundingClientRect();
                openClipMenu(selected, bounds.left, bounds.bottom);
            }}><MoreHorizontal/></Button>
            <DropdownMenu open={Boolean(menu)} onOpenChange={(open) => {
                if (!open) setMenu(undefined);
            }}><DropdownMenuTrigger asChild><Button aria-hidden tabIndex={-1}
                                                    className="pointer-events-none fixed size-px opacity-0 p-0" style={{
                left: menu?.x ?? 0,
                top: menu?.y ?? 0
            }}/></DropdownMenuTrigger>
                <DropdownMenuContent aria-label={menu?.track ? "音轨操作" : "片段操作"} className="w-60" align="start"
                                     sideOffset={0} collisionPadding={8} onCloseAutoFocus={(event) => {
                    event.preventDefault();
                    root.current?.focus({preventScroll: true});
                }}>
                    {menu?.clip && <><DropdownMenuLabel
                        className="max-w-56 truncate">{timelineClipLabel(menu.clip, snapshot).title}</DropdownMenuLabel><DropdownMenuSeparator/>
                        <DropdownMenuItem disabled={busy} onSelect={() => {
                            const clip = menu.clip!;
                            seek(clip.startSec);
                            void action(() => startPlayback(clip.startSec));
                        }}><Play/>从片段起点播放</DropdownMenuItem>
                        <DropdownMenuItem disabled={busy} onSelect={() => void action(() => duplicateClip(menu.clip!))}><Copy/>复制到片段后方<DropdownMenuShortcut>⌘/Ctrl
                            D</DropdownMenuShortcut></DropdownMenuItem>
                        <DropdownMenuItem disabled={busy || !canSplit(menu.clip)}
                                          onSelect={() => void action(() => history.split(menu.clip!, position))}><Scissors/>在播放头处分割<DropdownMenuShortcut>S</DropdownMenuShortcut></DropdownMenuItem>
                        <DropdownMenuSub><DropdownMenuSubTrigger
                            disabled={busy}>移到其他音轨</DropdownMenuSubTrigger><DropdownMenuSubContent>{tracks.map(track =>
                            <DropdownMenuItem key={track.id} disabled={track.id === menu.clip!.trackId}
                                              onSelect={() => void action(() => history.executePatch(menu.clip!, {trackId: track.id}))}>{track.name}</DropdownMenuItem>)}</DropdownMenuSubContent></DropdownMenuSub>
                        <DropdownMenuItem disabled={busy} onSelect={() => setInspector(true)}><SlidersHorizontal/>片段属性</DropdownMenuItem><DropdownMenuSeparator/>
                        <DropdownMenuItem variant="destructive" disabled={busy}
                                          onSelect={() => void action(() => removeClip(menu.clip!))}><Trash2/>删除片段<DropdownMenuShortcut>⌫
                            / Del</DropdownMenuShortcut></DropdownMenuItem>
                    </>}
                    {menu?.track && <>
                        <DropdownMenuLabel>{menu.track.name}</DropdownMenuLabel><DropdownMenuSeparator/><DropdownMenuItem
                        disabled={busy}
                        onSelect={() => void action(() => patchAudioTrack(projectId, menu.track!.id, menu.track!.revision, {muted: !menu.track!.muted}))}>{menu.track.muted ? "取消静音" : "静音音轨"}</DropdownMenuItem><DropdownMenuItem
                        disabled={busy}
                        onSelect={() => void action(() => patchAudioTrack(projectId, menu.track!.id, menu.track!.revision, {solo: !menu.track!.solo}))}>{menu.track.solo ? "取消独听" : "独听音轨"}</DropdownMenuItem></>}
                </DropdownMenuContent>
            </DropdownMenu>
            <div className="at-transport-space"/>
            <div className="at-zoom"><Button variant="ghost" size="icon-sm" aria-label="缩小时间线"
                                             disabled={zoom <= .5}
                                             onClick={() => setZoom(Math.max(.5, zoom / 1.5))}><ZoomOut/></Button><Button
                variant="ghost" size="sm" title="完整显示当前章节" onClick={() => {
                setZoom(1);
