            }}><Expand size={13}/><span>适应</span></Button><Button variant="ghost" size="icon-sm"
                                                                    aria-label="放大时间线" disabled={zoom >= 12}
                                                                    onClick={() => setZoom(Math.min(12, zoom * 1.5))}><ZoomIn/></Button>
            </div>
            <Popover open={inspector && Boolean(selected)} onOpenChange={setInspector}><PopoverTrigger asChild><Button
                size="icon-sm" variant={inspector ? "secondary" : "ghost"} disabled={!selected} aria-label="片段属性"
                title="片段属性"><SlidersHorizontal/></Button></PopoverTrigger><PopoverContent side="top" align="end"
                                                                                               className="at-inspector-popover">{selected &&
                <ClipInspector key={`${selected.id}:${selected.revision}`} clip={selected} tracks={tracks}
                               title={timelineClipLabel(selected, snapshot).title} busy={busy}
                               save={(patch) => action(() => history.executePatch(selected, patch))}
                               remove={() => action(async () => {
                                   await removeClip(selected);
                               })}/>}</PopoverContent></Popover>
            <Popover><PopoverTrigger asChild><Button variant="outline" size="sm" className="at-export"
                                                     disabled={busy || !snapshot.clips.length}><Download
                size={14}/><span>{busy ? "处理中" : "导出"}</span></Button></PopoverTrigger><PopoverContent side="top"
                                                                                                            align="end"
                                                                                                            className="at-export-popover"><strong>导出声音作品</strong>
                <p>48 kHz · 立体声 · WAV</p><Field label="导出范围"><WorkspaceSelect value={exportScope}
                                                                                     onValueChange={setExportScope}><SelectOption
                    value="chapter">当前章节</SelectOption><SelectOption
                    value="project">完整项目</SelectOption></WorkspaceSelect></Field><Button className="w-full"
                                                                                             disabled={busy}
                                                                                             onClick={() => void action(exportMix)}><Download
                    size={14}/>{busy ? "正在混合音频…" : "导出 WAV"}</Button></PopoverContent></Popover>
        </div>
        <div className="at-editor">
            <div className="at-toolbar"><span className="at-caption">时间线 <span>{clips.length} 个片段</span></span>
                <div className="at-toolbar-actions"><Button variant={snapping ? "secondary" : "ghost"} size="icon-sm"
                                                            aria-label="吸附片段边缘和播放头" aria-pressed={snapping}
                                                            title="吸附 · 拖动时按 Alt 暂停吸附"
                                                            onClick={() => setSnapping(!snapping)}><Magnet
                    size={13}/></Button><Popover><PopoverTrigger asChild><Button variant="ghost" size="sm"><Plus
                    size={13}/>音轨</Button></PopoverTrigger><PopoverContent side="top" align="end"
                                                                             className="at-track-menu">{(["voice", "music", "effects"] as const).map((role) =>
                    <Button variant="ghost" key={role} disabled={busy}
                            onClick={() => void addTrack(role)}>{role === "voice" ? "人声音轨" : role === "music" ? "背景音乐音轨" : "音效音轨"}</Button>)}</PopoverContent></Popover>
                </div>
            </div>
            {!clips.length ? <div className="at-empty"><Music2 size={22}/>
                <div><strong>让文字有声音</strong><p>选用配音版本，或录音、导入声音后放入时间线。</p></div>
                {onOpenSources &&
                    <Button variant="outline" size="sm" onClick={onOpenSources}><Plus size={13}/>添加声音</Button>}
            </div> : <div ref={scroll} className="at-scroll">
                <div className="at-sheet" style={{width: geometry.width + 112}}>
                    <div className="at-ruler-row">
                        <div className="at-ruler-label">秒</div>
                        <div className="at-ruler" style={{width: geometry.width}} role="slider" tabIndex={0}
                             aria-label="时间标尺，左右方向键定位" aria-valuemin={0} aria-valuemax={contentDuration}
                             aria-valuenow={Math.min(position, contentDuration)} onKeyDown={(event) => {
                            if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) {
                                event.preventDefault();
                                seek(event.key === "Home" ? 0 : event.key === "End" ? contentDuration : position + (event.key === "ArrowLeft" ? -1 : 1) * (event.shiftKey ? 1 : .1));
                            }
                        }} onPointerDown={(event) => {
                            if (event.button !== 0 || busy) return;
                            scrubRef.current = {resume: Boolean(player.current?.playing)};
                            event.currentTarget.setPointerCapture(event.pointerId);
                            scrub(event);
                        }} onPointerMove={(event) => {
                            if (scrubRef.current) scrub(event);
                        }} onPointerUp={() => {
                            const resume = scrubRef.current?.resume;
                            scrubRef.current = undefined;
                            if (resume) void action(() => startPlayback(positionRef.current));
                        }} onPointerCancel={() => {
                            scrubRef.current = undefined;
                        }}>
                            {geometry.ticks.map((tick) => <span key={tick} className="at-tick"
                                                                style={{left: tick * geometry.pixelsPerSecond}}>{formatTimelineTick(tick, geometry.step)}</span>)}
                            <div className="at-ruler-head" style={{left: position * geometry.pixelsPerSecond}}/>
                        </div>
                    </div>
                    {tracks.map((track) => <div className="at-track-row" key={track.id}>
                        <div className="at-track-label" data-role={track.role} onContextMenu={(event) => {
                            event.preventDefault();
                            if (!busyRef.current) setMenu({track, x: event.clientX, y: event.clientY});
                        }}><strong title={track.name}>{track.name}</strong>
                            <div className="at-track-controls"><Button size="icon-sm"
                                                                       variant={track.muted ? "secondary" : "ghost"}
                                                                       aria-label={`${track.name} 静音`}
                                                                       aria-pressed={track.muted} disabled={busy}
                                                                       onClick={() => void action(() => patchAudioTrack(projectId, track.id, track.revision, {muted: !track.muted}))}>M</Button><Button
                                size="icon-sm" variant={track.solo ? "secondary" : "ghost"}
                                aria-label={`${track.name} 独听`} aria-pressed={track.solo} disabled={busy}
                                onClick={() => void action(() => patchAudioTrack(projectId, track.id, track.revision, {solo: !track.solo}))}>S</Button><Popover><PopoverTrigger
                                asChild><Button size="icon-sm" variant="ghost"
                                                aria-label={`${track.name} 音量`}><Volume2
                                size={12}/></Button></PopoverTrigger><PopoverContent side="top"
                                                                                     className="at-volume-popover"><Field
                                label={`${track.name} · 音量`}><WorkspaceSlider label={`${track.name} 音量`} min={0}
                                                                                max={2} step={.05}
                                                                                defaultValue={track.gain}
                                                                                key={`${track.id}:${track.gain}`}
                                                                                onCommit={(gain) => void action(() => patchAudioTrack(projectId, track.id, track.revision, {gain}))}/></Field></PopoverContent></Popover>
                            </div>
                        </div>
                        <div className="at-lane" style={{
                            width: geometry.width,
                            backgroundSize: `${geometry.step * geometry.pixelsPerSecond}px 100%`
                        }} onPointerDown={(event) => {
                            if (event.button !== 0 || event.target !== event.currentTarget) return;
                            seek((event.clientX - event.currentTarget.getBoundingClientRect().left) / geometry.pixelsPerSecond);
                            root.current?.focus({preventScroll: true});
                        }}>
                            <div className="at-playhead" style={{left: position * geometry.pixelsPerSecond}}/>
                            {clips.filter((clip) => clip.trackId === track.id).map((clip) => {
                                const take = snapshot.takes.find((row) => row.id === clip.takeId);
                                const display = drag?.clip.id === clip.id ? {
                                    ...clip,
                                    startSec: drag.startSec,
                                    trimStartSec: drag.trimStartSec,
                                    trimEndSec: drag.trimEndSec
                                } : clip;
                                const label = timelineClipLabel(clip, snapshot);
                                return <div key={clip.id} className="at-clip" data-role={track.role}
                                            data-selected={selectedId === clip.id} data-muted={track.muted} role="group"
                                            aria-label={`${label.speaker}：${label.title}，起点 ${clip.startSec.toFixed(1)} 秒`}
                                            style={{
                                                left: display.startSec * geometry.pixelsPerSecond,
                                                width: Math.max(14, (display.trimEndSec - display.trimStartSec) * geometry.pixelsPerSecond)
                                            }} onPointerDown={(event) => beginDrag(event, clip, "move")}
                                            onPointerMove={moveDrag} onPointerUp={endDrag} onPointerCancel={cancelDrag}
                                            onContextMenu={(event) => {
                                                event.preventDefault();
                                                event.stopPropagation();
                                                openClipMenu(clip, event.clientX, event.clientY);
                                            }} onDoubleClick={() => {
                                    onSelect(clip.id);
                                    setInspector(true);
                                }}>
                                    <Button variant="ghost" className="at-clip-select"
                                            aria-pressed={selectedId === clip.id}
                                            aria-label={`选择 ${label.speaker}：${label.title}`}
                                            title={`${label.speaker} · ${label.title}`} onKeyDown={(event) => {
                                        if (event.key === "ContextMenu" || event.shiftKey && event.key === "F10") {
                                            event.preventDefault();
                                            const bounds = event.currentTarget.getBoundingClientRect();
                                            openClipMenu(clip, bounds.left, bounds.bottom);
                                        }
                                    }} onClick={() => {
                                        onSelect(clip.id);
                                        root.current?.focus({preventScroll: true});
                                    }}><span
                                        className="at-clip-title"><b>{label.speaker}</b>{label.title}</span>{take &&
                                        <Waveform take={take} clip={display}/>}</Button>
                                    {(["start", "end"] as const).map((side) => <Button key={side} variant="ghost"
                                                                                       className={`at-trim at-trim-${side}`}
                                                                                       aria-label={side === "start" ? "拖动裁剪起点" : "拖动裁剪终点"}
                                                                                       title="拖动裁剪；双击片段打开精确属性"
                                                                                       disabled={busy}
                                                                                       onPointerDown={(event) => beginDrag(event, clip, side)}
                                                                                       onPointerMove={moveDrag}
                                                                                       onPointerUp={endDrag}
                                                                                       onPointerCancel={cancelDrag}><span/></Button>)}
                                </div>;
                            })}
                        </div>
                    </div>)}
                </div>
            </div>}
            <div className="at-footer">
                <span>{selected ? "拖动移动 · 右键更多操作 · Delete / ⌫ 删除" : "选择片段开始剪辑"}</span><span>Space 播放<span
                className="at-desktop-hint"> · S 分割 · ⌘/Ctrl D 复制 · ⌘/Ctrl Z 撤销</span></span></div>
        </div>
        {(error || notice) && <div className="at-message" data-error={Boolean(error)} role={error ? "alert" : "status"}>
            <span>{error || notice}</span><Button variant="ghost" size="icon-sm" aria-label="关闭提示" onClick={() => {
            setError("");
            setNotice("");
        }}><X size={12}/></Button></div>}
    </section>;
}

function Waveform({take, clip}: { take: AudioTake; clip: AudioClip }) {
    const [peaks, setPeaks] = useState<ReturnType<typeof createWaveformPeaks>>([]);
    useEffect(() => {
        let cancelled = false;
        void (async () => {
            let buffer = cache.get(take.mediaId);
            if (!buffer) {
                const media = await db.media.get(take.mediaId);
                if (!media) return;
                buffer = await decodeAudioBlob(media.blob);
                cache.set(take.mediaId, buffer);
            }
            const next = createWaveformPeaks(buffer, 800);
            if (!cancelled) setPeaks(next);
        })().catch(() => undefined);
        return () => {
            cancelled = true;
        };
    }, [take.mediaId]);
    const visible = peaks.slice(Math.floor(clip.trimStartSec / take.durationSec * peaks.length), Math.ceil(clip.trimEndSec / take.durationSec * peaks.length));
    const path = visible.map((peak, i) => `M${i / Math.max(1, visible.length - 1) * 800},${15 - peak.max * 13}V${15 - peak.min * 13}`).join(" ");
    return <svg className="at-waveform" viewBox="0 0 800 30" preserveAspectRatio="none" aria-hidden>
        <path d={path} stroke="currentColor" strokeWidth={1}/>
    </svg>;
}

function ClipInspector({clip, tracks, title, busy, save, remove}: {
    clip: AudioClip;
    tracks: AudioTrack[];
    title: string;
    busy: boolean;
    save: (patch: Partial<AudioClip>) => Promise<void>;
    remove: () => Promise<void>
}) {
    const [values, setValues] = useState({
        trackId: clip.trackId,
        startSec: String(clip.startSec),
        trimStartSec: String(clip.trimStartSec),
        trimEndSec: String(clip.trimEndSec),
        gain: String(clip.gain),
        fadeInSec: String(clip.fadeInSec),
        fadeOutSec: String(clip.fadeOutSec)
    });
    const fields = {
        startSec: "时间线位置",
        trimStartSec: "源裁剪起点",
        trimEndSec: "源裁剪终点",
        gain: "音量倍数",
        fadeInSec: "淡入时长",
        fadeOutSec: "淡出时长"
    } as const;
    return <form className="at-inspector" onSubmit={(event) => {
        event.preventDefault();
        void save({trackId: values.trackId, ...Object.fromEntries(Object.keys(fields).map((key) => [key, Number(values[key as keyof typeof fields])]))});
    }}><strong>片段属性</strong><p className="at-inspector-title">{title}</p><Field label="所在音轨"><WorkspaceSelect
        value={values.trackId} onValueChange={(value) => setValues({...values, trackId: value})}>{tracks.map((track) =>
        <SelectOption key={track.id} value={track.id}>{track.name}</SelectOption>)}</WorkspaceSelect></Field>
        <div className="at-inspector-grid">{(Object.keys(fields) as Array<keyof typeof fields>).map((key) => <Field
            key={key} label={`${fields[key]}${key === "gain" ? "" : "（秒）"}`}><Input type="number" min={0}
                                                                                     max={key === "gain" ? 4 : undefined}
                                                                                     step={.01} required
                                                                                     value={values[key]}
                                                                                     onChange={(event) => setValues({
                                                                                         ...values,
                                                                                         [key]: event.target.value
                                                                                     })}/></Field>)}</div>
        <div className="at-inspector-actions"><Button size="icon-sm" variant="ghost" type="button"
                                                      aria-label="移除片段（可撤销）" disabled={busy}
                                                      onClick={() => void remove()}><Trash2/></Button><Button size="sm"
                                                                                                              type="submit"
                                                                                                              disabled={busy}>应用修改</Button>
        </div>
    </form>;
}

import {useEffect, useRef, useState} from "react";
import {toast} from "sonner";
