function useInspectorSheet() {
    const [sheet, setSheet] = useState(() => typeof window !== "undefined" && window.matchMedia("(max-width: 1099px)").matches);
    useEffect(() => {
        const query = window.matchMedia("(max-width: 1099px)");
        const update = () => setSheet(query.matches);
        query.addEventListener("change", update);
        update();
        return () => query.removeEventListener("change", update);
    }, []);
    return sheet;
}

export function AudioWorkspacePage({projectId}: { projectId: string }) {
    useProjectAudioJobs(projectId);
    const data = useLiveQuery(async () => {
        const project = await db.projects.get(projectId) ?? null;
        return {
            project,
            snapshot: project?.kind === "audio" ? await getAudioProjectSnapshot(projectId) : null,
            projectId
        };
    }, [projectId]);
    const [chapterId, setChapterId] = useState("");
    const [segmentId, setSegmentId] = useState("");
    const [takeId, setTakeId] = useState("");
    const [clipId, setClipId] = useState("");
    const [mode, setMode] = useState<"script" | "timeline">("script");
    const [inspectorOpen, setInspectorOpen] = useState(false);
    const [inspectorTab, setInspectorTab] = useState<"voice" | "sources" | "exports">("voice");
    const [sourceRequest, setSourceRequest] = useState<{ id: string; segmentId?: string }>();
    const [voicesOpen, setVoicesOpen] = useState(false);
    const [voiceTarget, setVoiceTarget] = useState<AudioSegment>();
    const [chapterOpen, setChapterOpen] = useState(false);
    const [seekRequest, setSeekRequest] = useState<{ id: string; position: number }>();
    const [error, setError] = useState("");
    const [busy, setBusy] = useState(false);
    const pending = useRef(false);
    const sheet = useInspectorSheet();

    async function action(fn: () => Promise<unknown>) {
        if (pending.current) return;
        pending.current = true;
        setBusy(true);
        setError("");
        try {
            await fn();
        } catch (reason) {
            const message = errorText(reason);
            setError(message);
            toast.error(message);
        } finally {
            pending.current = false;
            setBusy(false);
        }
    }

    if (!data || data.projectId !== projectId) return <div className="p-8 text-muted-foreground">加载音频项目…</div>;
    if (!data.project || !data.snapshot) return <div className="p-8">找不到这个音频项目</div>;
    const {snapshot, project} = data;
    const chapter = snapshot.chapters.find((row) => row.id === chapterId) ?? snapshot.chapters[0];
    if (!chapter) return <div className="p-8">项目缺少音频章节，请重新打开项目。</div>;
    const segment = snapshot.segments.find((row) => row.id === segmentId && row.chapterId === chapter.id);

    function selectSegment(row: AudioSegment) {
        setSegmentId(row.id);
        if (segmentId === row.id) return;
        const takes = snapshot!.takes.filter((take) => take.segmentId === row.id);
        const adopted = takes.find((take) => take.id === row.selectedTakeId) ?? takes.at(-1);
        setTakeId(adopted?.id ?? "");
        const clip = snapshot!.clips.find((item) => item.chapterId === row.chapterId && item.takeId === adopted?.id) ?? snapshot!.clips.find((item) => item.chapterId === row.chapterId && takes.some((take) => take.id === item.takeId));
        setClipId(clip?.id ?? "");
        if (clip) setSeekRequest({id: `${clip.id}:${Date.now()}`, position: clip.startSec});
    }

    function selectClip(id: string) {
        setClipId(id);
        const clip = snapshot!.clips.find((row) => row.id === id);
        const take = snapshot!.takes.find((row) => row.id === clip?.takeId);
        if (take) {
            setTakeId(take.id);
            setSegmentId(take.segmentId ?? "");
        }
    }

    function selectTake(id: string) {
        setTakeId(id);
        const take = snapshot!.takes.find((row) => row.id === id);
        const owner = snapshot!.segments.find((row) => row.id === take?.segmentId);
        if (owner) {
            setChapterId(owner.chapterId);
            setSegmentId(owner.id);
        } else setSegmentId("");
        const clip = snapshot!.clips.find((row) => row.takeId === id && row.chapterId === (owner?.chapterId ?? chapter.id));
        setClipId(clip?.id ?? "");
        if (clip) setSeekRequest({id: `${clip.id}:${Date.now()}`, position: clip.startSec});
    }

    function inspect(row?: AudioSegment) {
        if (row) selectSegment(row);
        setInspectorTab(row ? "voice" : "sources");
        setInspectorOpen(true);
    }

    function saved(take: AudioTake) {
        setTakeId(take.id);
        setClipId("");
        if (take.segmentId) {
            setSegmentId(take.segmentId);
            const owner = snapshot!.segments.find((row) => row.id === take.segmentId);
            if (owner) setChapterId(owner.chapterId);
        } else setSegmentId("");
        setInspectorTab(take.segmentId ? "voice" : "sources");
        setInspectorOpen(true);
    }

    function openVoices(row?: AudioSegment) {
        if (row) selectSegment(row);
        setVoiceTarget(row ?? segment);
        if (sheet) setInspectorOpen(false);
        setVoicesOpen(true);
    }

    const inspector = <AudioInspector projectId={projectId} chapterId={chapter.id} snapshot={snapshot} segment={segment}
                                      takeId={takeId} tab={inspectorTab} onTabChange={setInspectorTab}
                                      onTake={selectTake} onClip={selectClip} onAddSources={(target) => {
        if (sheet) setInspectorOpen(false);
        setSourceRequest({id: String(Date.now()), segmentId: target});
    }} action={action} busy={busy} onVoices={openVoices}/>;
    return <div className="as-workspace" data-mode={mode}>
        <header className="as-toolbar">
            <div className="as-chapter-selector"><Popover open={chapterOpen}
                                                          onOpenChange={setChapterOpen}><PopoverTrigger asChild><Button
                variant="ghost" size="sm"><ListMusic size={15}/><span>{chapter.title}</span><ChevronDown
                size={13}/></Button></PopoverTrigger><PopoverContent align="start" className="as-chapter-menu">
                <div className="as-menu-heading">项目章节</div>
                <div className="mb-3"><SavedText key={`${chapter.id}:title`} projectId={projectId} rowId={chapter.id}
                                                 field="title" value={chapter.title} label="当前章节名称"
                                                 save={async (title, baseline) => {
                                                     const current = await db.audioChapters.get(chapter.id);
                                                     if (!current || current.title !== baseline) throw new DraftConflictError();
                                                     await patchAudioChapter(projectId, current.id, current.revision, {title});
                                                 }}/></div>
                {snapshot.chapters.map((row, index) => <Button key={row.id}
                                                               variant={chapter.id === row.id ? "secondary" : "ghost"}
                                                               className="w-full justify-start" onClick={() => {
                    setChapterId(row.id);
                    setSegmentId("");
                    setTakeId("");
                    setClipId("");
                    setChapterOpen(false);
                }}><span className="text-muted-foreground text-xs">{String(index + 1).padStart(2, "0")}</span><span
                    className="truncate">{row.title}</span>{chapter.id === row.id &&
                    <Check size={14} className="ml-auto"/>}</Button>)}<Button variant="ghost" size="sm"
                                                                              className="mt-2 w-full justify-start"
                                                                              disabled={busy}
                                                                              onClick={() => void action(async () => {
                                                                                  const row = await db.transaction("rw", AUDIO_TRANSACTION_TABLES, async () => {
                                                                                      const created = await addAudioChapter(projectId, {
                                                                                          title: `章节 ${snapshot.chapters.length + 1}`,
                                                                                          order: Math.max(0, ...snapshot.chapters.map((item) => item.order)) + 1
                                                                                      });
                                                                                      await addAudioTrack(projectId, {
                                                                                          chapterId: created.id,
                                                                                          role: "voice",
                                                                                          name: "人声",
                                                                                          order: 0,
                                                                                          gain: 1,
                                                                                          muted: false,
                                                                                          solo: false
                                                                                      });
                                                                                      return created;
                                                                                  });
                                                                                  setChapterId(row.id);
                                                                                  setSegmentId("");
                                                                                  setTakeId("");
                                                                                  setClipId("");
                                                                                  setChapterOpen(false);
                                                                              })}><Plus
                size={14}/>新增章节</Button></PopoverContent></Popover><span
                className="as-project-name">{project.name}</span></div>
            <nav className="as-view-modes" aria-label="音频制作模式"><Button size="sm"
                                                                             variant={mode === "script" ? "secondary" : "ghost"}
                                                                             aria-pressed={mode === "script"}
                                                                             onClick={() => setMode("script")}>脚本</Button><Button
                size="sm" variant={mode === "timeline" ? "secondary" : "ghost"} aria-pressed={mode === "timeline"}
                onClick={() => setMode("timeline")}>剪辑</Button></nav>
            <div className="as-toolbar-actions"><Button size="sm" variant="ghost" onClick={() => openVoices()}><Mic
                size={15}/>音色</Button><Button size="sm" variant="secondary"
                                                disabled={!snapshot.segments.some(row => row.chapterId === chapter.id)}
                                                onClick={() => {
                                                    const target = segment ?? snapshot.segments.find(row => row.chapterId === chapter.id);
                                                    if (target) inspect(target);
                                                }}><Sparkles size={15}/>配音</Button><AudioSources
                request={sourceRequest} compact projectId={projectId} segmentId={segment?.id} onSaved={saved}/><Button
                variant="ghost" size="sm" aria-label={inspectorOpen ? "收起声音面板" : "打开声音面板"} onClick={() => {
                if (!segment) setInspectorTab("sources");
                setInspectorOpen(!inspectorOpen);
            }}>{inspectorOpen ? <PanelRightClose size={16}/> : <PanelRightOpen size={16}/>}<span
                className="as-panel-button-label">声音</span></Button></div>
        </header>
        {error && <div className="as-error" role="alert"><span>{error}</span><Button variant="ghost" size="icon-sm"
                                                                                     aria-label="关闭错误提示"
                                                                                     onClick={() => setError("")}><X/></Button>
        </div>}
        <div className="as-main">
            <main className="as-script-scroll"><ScriptDocument key={chapter.id} chapter={chapter} snapshot={snapshot}
                                                               selectedId={segment?.id ?? ""} busy={busy}
                                                               action={action} onSelect={selectSegment}
                                                               onInspect={(row) => inspect(row)} onVoices={openVoices}/>
            </main>
            {!sheet && inspectorOpen && <aside className="as-inspector">
                <div className="as-inspector-top"><span><Headphones size={14}/>声音工作区</span><Button variant="ghost"
                                                                                                        size="icon-sm"
                                                                                                        aria-label="收起声音工作区"
                                                                                                        onClick={() => setInspectorOpen(false)}><X
                    size={14}/></Button></div>
                {inspector}</aside>}</div>
        <VoiceLibrary key={projectId} projectId={projectId} open={voicesOpen} onOpenChange={setVoicesOpen}
                      speakers={snapshot.speakers} takes={snapshot.takes} selectedId={voiceTarget?.speakerId}
                      onChoose={voiceTarget ? async (id) => {
                          await flushPendingDrafts(projectId);
                          const current = await db.audioSegments.get(voiceTarget.id);
                          if (!current || current.projectId !== projectId || current.speakerId !== voiceTarget.speakerId) throw new Error("段落已改变，请重新选择后应用音色");
                          await patchAudioSegment(projectId, current.id, current.revision, {speakerId: id});
                          setSegmentId(current.id);
                          setInspectorTab("voice");
                          setInspectorOpen(true);
                      } : undefined}/>
        <AudioTimeline projectId={projectId} projectName={project.name} chapterId={chapter.id} snapshot={snapshot}
                       selectedId={clipId} onSelect={selectClip} mobileMode={mode} seekRequest={seekRequest}
                       onOpenSources={() => inspect()}/>
        {sheet && <Sheet open={inspectorOpen} onOpenChange={setInspectorOpen}><SheetContent
            className="as-inspector-sheet"><SheetHeader><SheetTitle>声音与版本</SheetTitle><SheetDescription>{segment ? "当前段落的声音、生成版本和剪辑来源" : "管理项目声音与导出成品"}</SheetDescription></SheetHeader>
            <div className="as-sheet-scroll">{inspector}</div>
        </SheetContent></Sheet>}
    </div>;
}

import {useEffect, useRef, useState} from "react";
import {ArrowDown, ArrowUp, MoreHorizontal, Play, Plus, Trash2, Volume2} from "lucide-react";
import {db} from "@/db/database";
import {addAudioSegment, deleteAudioSegment, patchAudioSegment} from "@/db/audio";
import {appendAudioScript, editAudioScriptLines} from "@/lib/audio/scriptImport";
import type {AudioChapter, AudioProjectSnapshot, AudioSegment} from "@/domain/audio";
import {DraftConflictError} from "@/lib/draftConflict";
import {flushPendingDrafts, useDebouncedDraft} from "@/lib/debouncedDraft";
import {Button} from "@/components/ui/button";
import {Textarea} from "@/components/ui/textarea";
import {DraftStatus} from "@/components/ui/draft-status";
import {Popover, PopoverContent, PopoverTrigger} from "@/components/ui/popover";
import {Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle} from "@/components/ui/dialog";
import {useMedia} from "@/lib/media";
import {SourcePlayer} from "@/components/audioMusic/controls";
import type {AudioAction} from "./AudioInspector";

export function ScriptDocument({chapter, snapshot, selectedId, busy, action, onSelect, onInspect, onVoices}: {
    chapter: AudioChapter;
    snapshot: AudioProjectSnapshot;
    selectedId: string;
    busy: boolean;
    action: AudioAction;
    onSelect: (segment: AudioSegment) => void;
    onInspect: (segment: AudioSegment) => void;
    onVoices: (segment: AudioSegment) => void;
}) {
    const segments = snapshot.segments.filter((row) => row.chapterId === chapter.id);
    const [pasting, setPasting] = useState(false);
    const [pasted, setPasted] = useState("");
    const [focusRequest, setFocusRequest] = useState<{ id: string; atEnd?: boolean }>();
    useEffect(() => {
        if (!focusRequest) return;
        const row = segments.find((item) => item.id === focusRequest.id);
        const input = document.getElementById(`script-input-${focusRequest.id}`) as HTMLTextAreaElement | null;
        if (!row || !input) return;
        input.focus();
        const caret = focusRequest.atEnd ? input.value.length : 0;
        input.setSelectionRange(caret, caret);
        onSelect(row);
        setFocusRequest(undefined);
    }, [focusRequest, segments, onSelect]);

    async function add(text = "") {
        const segment = await addAudioSegment(chapter.projectId, {
            chapterId: chapter.id,
            order: Math.max(0, ...segments.map((row) => row.order)) + 1,
            text,
            notes: ""
        });
        onSelect(segment);
        setFocusRequest({id: segment.id});
    }

    return <div className="as-document">
        {!segments.length ? <div className="as-blank-document"><p>从你的第一段台词开始</p>
            <span>写下脚本，或者导入、录制已有声音。制作方式由你决定。</span>
            <div><Button disabled={busy} onClick={() => void action(() => add())}><Plus/>写下第一段</Button><Button
                variant="ghost" onClick={() => setPasting(true)}>粘贴完整稿件</Button></div>
        </div> : <div className="as-paragraphs">{segments.map((segment, index) => <ScriptParagraph key={segment.id}
                                                                                                   segment={segment}
                                                                                                   index={index}
                                                                                                   siblings={segments}
                                                                                                   snapshot={snapshot}
                                                                                                   selected={selectedId === segment.id}
                                                                                                   busy={busy}
                                                                                                   action={action}
                                                                                                   onSelect={() => onSelect(segment)}
                                                                                                   onInspect={() => onInspect(segment)}
                                                                                                   onVoices={() => onVoices(segment)}
                                                                                                   onFocusNew={(id, atEnd) => setFocusRequest({
                                                                                                       id,
                                                                                                       atEnd
                                                                                                   })}/>)}</div>}
        {segments.length > 0 && <footer className="as-document-footer"><Button size="sm" variant="ghost" disabled={busy}
                                                                               onClick={() => void action(() => add())}><Plus/>添加一行</Button><Button
            size="sm" variant="ghost" onClick={() => setPasting(true)}>粘贴稿件</Button><span>文字编辑自动保存</span>
        </footer>}
        <Dialog open={pasting}
                onOpenChange={setPasting}><DialogContent><DialogHeader><DialogTitle>粘贴稿件</DialogTitle><DialogDescription>每个非空回车行作为一个编辑单位，追加到当前章节。已有内容会保留。</DialogDescription></DialogHeader><Textarea
            value={pasted} onChange={(e) => setPasted(e.target.value)} rows={12} aria-label="完整稿件"
            placeholder="第一段台词…&#10;&#10;下一段台词…"/><Button disabled={busy || !pasted.trim()}
                                                                    onClick={() => void action(async () => {
                                                                        const added = await appendAudioScript(chapter.projectId, chapter.id, pasted);
                                                                        const last = added.at(-1);
                                                                        setPasted("");
                                                                        setPasting(false);
                                                                        if (last) onSelect(last);
                                                                    })}>添加 {pasted.split(/\r?\n/).filter((part) => part.trim()).length} 行</Button></DialogContent></Dialog>
    </div>;
}

function ScriptParagraph({
                             segment,
                             index,
                             siblings,
                             snapshot,
                             selected,
                             busy,
                             action,
                             onSelect,
                             onInspect,
                             onVoices,
                             onFocusNew
                         }: {
    segment: AudioSegment;
    index: number;
    siblings: AudioSegment[];
    snapshot: AudioProjectSnapshot;
    selected: boolean;
    busy: boolean;
    action: AudioAction;
    onSelect: () => void;
    onInspect: () => void;
    onVoices: () => void;
    onFocusNew: (id: string, atEnd?: boolean) => void;
}) {
    const [roleOpen, setRoleOpen] = useState(false);
    const [audition, setAudition] = useState(false);
    const textarea = useRef<HTMLTextAreaElement>(null);
    const speaker = snapshot.speakers.find((row) => row.id === segment.speakerId);
    const takes = snapshot.takes.filter((row) => row.segmentId === segment.id);
    const adopted = takes.find((take) => take.id === segment.selectedTakeId);
    const auditionTake = adopted ?? takes.at(-1);
    const preview = useMedia(audition && selected ? auditionTake?.mediaId : undefined);
    const {draft, setDraft, status, error, retry, useLatest} = useDebouncedDraft({
        scope: segment.projectId,
        draftKey: `${segment.id}:text`,
        initialValue: segment.text,
        persist: async (text, baseline) => {
            const current = await db.audioSegments.get(segment.id);
            if (!current || current.text !== baseline) throw new DraftConflictError();
            await patchAudioSegment(segment.projectId, current.id, current.revision, {text});
        }
    });
    useEffect(() => {
        const input = textarea.current;
        if (!input) return;
        const measure = () => {
            input.style.height = "auto";
            input.style.height = `${input.scrollHeight}px`;
        };
        measure();
        let width = input.getBoundingClientRect().width;
        const observer = new ResizeObserver((entries) => {
            const nextWidth = entries[0]?.contentRect.width;
            if (nextWidth === undefined || Math.abs(nextWidth - width) < 0.5) return;
            width = nextWidth;
            measure();
        });
        observer.observe(input);
        return () => observer.disconnect();
    }, [draft]);

    async function splitLine(start: number, end: number) {
        await flushPendingDrafts(segment.projectId);
        const rows = await editAudioScriptLines({
            projectId: segment.projectId,
            segmentId: segment.id,
            baseline: draft,
            start,
            end
        });
        if (rows[1]) onFocusNew(rows[1].id);
    }

    return <article id={`script-${segment.id}`} className="as-paragraph" data-selected={selected} onFocus={onSelect}>
        <div className="as-paragraph-gutter"><Popover open={roleOpen} onOpenChange={setRoleOpen}><PopoverTrigger
            asChild><Button variant="ghost" size="icon" className="as-role-button"
                            aria-label={`段落 ${index + 1} 选择说话人和音色`}><span
            className="as-voice-avatar">{speaker?.name.slice(0, 1) ??
            <MoreHorizontal size={14}/>}</span></Button></PopoverTrigger><PopoverContent align="start"
                                                                                         className="as-role-popover">
            <h3>这段由谁来讲述</h3>
            <div className="as-role-options"><Button variant={!speaker ? "secondary" : "ghost"}
                                                     className="justify-start" disabled={busy}
                                                     onClick={() => void action(async () => {
                                                         await patchAudioSegment(segment.projectId, segment.id, segment.revision, {speakerId: undefined});
                                                         setRoleOpen(false);
                                                     })}>MiMo 默认音色</Button>{snapshot.speakers.map((row) => <Button
                key={row.id} variant={row.id === speaker?.id ? "secondary" : "ghost"} className="justify-start"
                disabled={busy} onClick={() => void action(async () => {
                await patchAudioSegment(segment.projectId, segment.id, segment.revision, {speakerId: row.id});
                setRoleOpen(false);
            })}>{row.name}<span
                className="text-muted-foreground ml-auto text-xs">{row.mimo ? row.mimo.mode === "design" ? "设计音色" : row.mimo.mode === "clone" ? "克隆音色" : row.voice ?? "MiMo 默认" : row.voice ?? "alloy"}</span></Button>)}
            </div>
            <Button size="sm" variant="ghost" disabled={busy} onClick={() => {
                setRoleOpen(false);
                onVoices();
            }}><Plus/>创作 / 管理音色</Button>
            <div className="as-line-menu-actions"><Button size="sm" variant="ghost" onClick={() => {
                setRoleOpen(false);
                onInspect();
            }}><Volume2 size={13}/>声音与生成</Button>{auditionTake &&
                <Button size="sm" variant="ghost" onClick={() => {
                    setAudition(!audition);
                    setRoleOpen(false);
                }}><Play size={13}/>试听</Button>}<Button size="sm" variant="ghost" disabled={busy || index === 0}
                                                          onClick={() => void action(() => patchAudioSegment(segment.projectId, segment.id, segment.revision, {order: index > 1 ? (siblings[index - 2].order + siblings[index - 1].order) / 2 : siblings[0].order / 2}))}><ArrowUp/>上移</Button><Button
                size="sm" variant="ghost" disabled={busy || index === siblings.length - 1}
                onClick={() => void action(() => patchAudioSegment(segment.projectId, segment.id, segment.revision, {order: index + 2 < siblings.length ? (siblings[index + 1].order + siblings[index + 2].order) / 2 : siblings[index + 1].order + 1}))}><ArrowDown/>下移</Button><Button
                size="sm" variant="ghost" disabled={busy} onClick={() => void action(async () => {
                await flushPendingDrafts(segment.projectId);
                const current = await db.audioSegments.get(segment.id);
                if (current) await deleteAudioSegment(segment.projectId, segment.id, current.revision);
            })}><Trash2/>删除此行</Button></div>
        </PopoverContent></Popover></div>
        <div className="as-paragraph-main"><Textarea id={`script-input-${segment.id}`} ref={textarea}
                                                     className="as-script-input" aria-label={`第 ${index + 1} 行正文`}
                                                     value={draft} onChange={(event) => setDraft(event.target.value)}
                                                     onKeyDown={(event) => {
                                                         if (event.key === "Backspace" && !draft && event.currentTarget.selectionStart === 0 && event.currentTarget.selectionEnd === 0 && index > 0 && !event.nativeEvent.isComposing) {
                                                             event.preventDefault();
                                                             const previous = siblings[index - 1];
                                                             void action(async () => {
                                                                 await flushPendingDrafts(segment.projectId);
                                                                 const current = await db.audioSegments.get(segment.id);
                                                                 if (!current || current.text) throw new DraftConflictError();
                                                                 await deleteAudioSegment(segment.projectId, current.id, current.revision);
                                                                 onFocusNew(previous.id, true);
                                                             });
                                                             return;
                                                         }
                                                         if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
                                                             event.preventDefault();
                                                             const start = event.currentTarget.selectionStart;
                                                             const end = event.currentTarget.selectionEnd;
                                                             void action(() => splitLine(start, end));
                                                         }
                                                     }} onPaste={(event) => {
            const pasted = event.clipboardData.getData("text/plain");
            if (!/[\r\n]/.test(pasted)) return;
            event.preventDefault();
            const start = event.currentTarget.selectionStart;
            const end = event.currentTarget.selectionEnd;
            void action(async () => {
                await flushPendingDrafts(segment.projectId);
                const rows = await editAudioScriptLines({
                    projectId: segment.projectId,
                    segmentId: segment.id,
                    baseline: draft,
                    start,
                    end,
                    pasted
                });
                if (rows.length > 1) onFocusNew(rows.at(-1)!.id);
            });
        }} placeholder="写下正文…" rows={1}/>{status === "error" &&
            <DraftStatus status={status} error={error} onRetry={() => void retry()}
                         onUseLatest={useLatest}/>}{preview &&
            <div className="as-inline-audition"><SourcePlayer src={preview.url} title={`第 ${index + 1} 行`} autoplay/>
            </div>}</div>
    </article>;
}

import {useRef, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {Plus, Sparkles} from "lucide-react";
import {db} from "@/db/database";
import {patchAudioSegment} from "@/db/audio";
import type {AudioSegment, AudioSpeaker} from "@/domain/audio";
import {prepareAudioGeneration, submitAudioGeneration} from "@/lib/audioGeneration/runtime";
import {defaultMimoConnector, speakerSpeechProfile} from "@/lib/audioGeneration/defaults";
import {flushPendingDrafts} from "@/lib/debouncedDraft";
import {Button} from "@/components/ui/button";
import {Textarea} from "@/components/ui/textarea";
import {Checkbox} from "@/components/ui/checkbox";
import {errorText} from "@/components/audioMusic/shared";
import {Disclosure, DisclosureTitle, SelectOption, WorkspaceSelect} from "@/components/audioMusic/controls";
import {MimoConnection} from "./MimoConnection";
import {voiceLabel} from "./VoiceLibrary";

export function SpeechControls({segment, speaker, speakers, onVoices}: {
    segment: AudioSegment; speaker?: AudioSpeaker; speakers: AudioSpeaker[]; onVoices: () => void;
}) {
    const connections = useLiveQuery(() => db.connectors.toArray());
    const profile = speakerSpeechProfile(speaker);
    const connector = profile.mimo ? defaultMimoConnector(connections ?? []) : connections?.find(row => row.definitionId === "apimart" && row.apiKey.trim());
    const [direction, setDirection] = useState("");
    const [optimize, setOptimize] = useState(false);
    const [busy, setBusy] = useState(false);
    const pending = useRef(false);
    const [error, setError] = useState(""), [notice, setNotice] = useState("");

    async function perform(fn: () => Promise<void>) {
        if (pending.current) return;
        pending.current = true;
        setBusy(true);
        setError("");
        setNotice("");
        try {
            await fn();
        } catch (e) {
            setError(errorText(e));
        } finally {
            pending.current = false;
            setBusy(false);
        }
    }

    async function generate() {
        if (!connector) return;
        await flushPendingDrafts(segment.projectId);
        const current = await db.audioSegments.get(segment.id);
        if (!current || current.projectId !== segment.projectId) throw new Error("段落已不存在");
        if (current.speakerId !== segment.speakerId) throw new Error("段落音色已改变，请重新确认后生成");
        if (speaker && (await db.audioSpeakers.get(speaker.id))?.revision !== speaker.revision) throw new Error("音色已改变，请重新确认后生成");
        const mimo = profile.mimo ? {
            ...profile.mimo,
            instruction: [profile.mimo.instruction, direction.trim()].filter(Boolean).join("\n"), ...(profile.mimo.mode === "design" ? {optimizeTextPreview: optimize} : {})
        } : undefined;
        const job = await prepareAudioGeneration({
            projectId: segment.projectId, connectorId: connector.id,
            input: {
                kind: "speech",
                text: current.text, ...profile, ...(mimo ? {mimo} : {}),
                segmentId: current.id,
                segmentRevision: current.revision
            }
        });
        const result = await submitAudioGeneration(segment.projectId, job.id);
        if (result.error) setError(result.error);
        else setNotice(result.status === "saved" ? "配音已保存到下方版本，试听后即可采用。" : "请在生成任务中查看进度。");
    }

    return <section className="as-generation space-y-3" aria-label="段落配音">
        <div className="flex items-center justify-between gap-2"><h3 className="text-sm font-medium">配音</h3><Button
            size="sm" variant="ghost" disabled={busy} onClick={onVoices}><Plus/>创作音色</Button></div>
        <WorkspaceSelect aria-label="这段使用的音色" disabled={busy} value={speaker?.id ?? ""}
                         onValueChange={(id) => void perform(async () => {
                             await flushPendingDrafts(segment.projectId);
                             const row = await db.audioSegments.get(segment.id);
                             if (!row || row.speakerId !== segment.speakerId) throw new Error("段落已更新，请重新选择音色");
                             await patchAudioSegment(segment.projectId, row.id, row.revision, {speakerId: id || undefined});
                         })}><SelectOption value="">MiMo 默认音色</SelectOption>{speakers.map(row => <SelectOption
            key={row.id} value={row.id}>{row.name} · {voiceLabel(row)}</SelectOption>)}</WorkspaceSelect>
        <Button className="w-full" disabled={!connector || busy}
                onClick={() => void perform(generate)}><Sparkles/>{busy ? "处理中…" : "生成这段配音"}</Button>
        {profile.mimo &&
            <Disclosure><DisclosureTitle>演绎与文本（可选）</DisclosureTitle><Textarea aria-label="这段演绎指导"
                                                                                     value={direction} maxLength={4000}
                                                                                     rows={2} disabled={busy}
                                                                                     onChange={(e) => setDirection(e.target.value)}
                                                                                     placeholder="这一段轻声讲述，结尾放慢…"/>{profile.mimo.mode === "design" && <>
                <label className="flex items-start gap-2 py-2 text-sm"><Checkbox disabled={busy} checked={optimize}
                                                                                 onCheckedChange={(value) => setOptimize(value === true)}/>允许润色播报文本</label>
                <p className="text-xs text-muted-foreground">默认保持稿件原文。开启后，实际播报文本会另存到配音版本。</p></>}
            </Disclosure>}
        {connections === undefined ? <p className="as-help">加载配音连接…</p> : !connector ? profile.mimo ?
                <MimoConnection existing={connections.find(row => row.definitionId === "mimo")}/> :
                <p className="as-help">这个旧音色需要 APIMart 连接。可从上方选择 MiMo
                    默认音色，或前往“连接与模型”恢复原连接。</p> :
            <p className="text-xs text-muted-foreground">{profile.mimo ? "MiMo" : "APIMart · 原有音色"} ·
                生成一个新版本，保留当前声音</p>}
        {notice && <p className="as-help" role="status">{notice}</p>}{error &&
        <p className="aw-error" role="alert">{error}</p>}
    </section>;
}

import {useRef, useState} from "react";
