export function voiceLabel(speaker: AudioSpeaker) {
    const profile = speakerSpeechProfile(speaker);
    if (!profile.mimo) return `原有音色 · ${profile.voice}`;
    return profile.mimo.mode === "design" ? "设计音色" : profile.mimo.mode === "clone" ? "克隆声音" : profile.voice === "mimo_default" ? "MiMo 默认" : profile.voice;
}

export function VoiceLibrary({projectId, open, onOpenChange, speakers, takes, selectedId, onChoose}: {
    projectId: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    speakers: AudioSpeaker[];
    takes: AudioTake[];
    selectedId?: string;
    onChoose?: (id: string) => Promise<void>;
}) {
    const [editing, setEditing] = useState<{ id: string; initial?: AudioSpeaker }>();
    const [busy, setBusy] = useState(false), [error, setError] = useState("");

    function changeOpen(next: boolean) {
        if (busy) return;
        onOpenChange(next);
        if (!next) {
            setEditing(undefined);
            setError("");
        }
    }

    return <Dialog open={open} onOpenChange={changeOpen}><DialogContent
        className="max-h-[90dvh] overflow-y-auto sm:max-w-xl" onEscapeKeyDown={(e) => {
        if (busy) e.preventDefault();
    }} onInteractOutside={(e) => {
        if (busy) e.preventDefault();
    }}>
        <DialogHeader><DialogTitle>{editing ? editing.initial ? "编辑音色" : "创作新音色" : "项目音色"}</DialogTitle><DialogDescription>{editing ? "给声音一个名字，描述它或提供一段参考录音。" : "这里的音色可用于所有章节，创作助手创建的音色也会出现在这里。"}</DialogDescription></DialogHeader>
        {editing ? <><Button className="justify-self-start" size="sm" variant="ghost" disabled={busy}
                             onClick={() => setEditing(undefined)}><ArrowLeft/>返回音色列表</Button><VoiceEditor
            key={editing.id} projectId={projectId} initial={editing.initial} takes={takes} onBusyChange={setBusy}
            onSaved={() => setEditing(undefined)}/></> : <>
            <Button className="justify-self-start" onClick={() => setEditing({id: "new"})}><Plus/>创作音色 /
                克隆声音</Button>
            {!speakers.length &&
                <p className="py-5 text-sm text-muted-foreground">还没有自定义音色。段落可以直接使用 MiMo
                    默认音色，也可以在这里创建自己的声音。</p>}
            <div className="divide-y">{speakers.map(row => <div key={row.id} className="flex items-center gap-3 py-3">
                <Mic className="size-4 shrink-0 text-muted-foreground"/>
                <div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{row.name}</p><p
                    className="truncate text-xs text-muted-foreground">{voiceLabel(row)}</p></div>
                <Button size="sm" variant="ghost" disabled={busy}
                        onClick={() => setEditing({id: row.id, initial: row})}>编辑</Button>{onChoose &&
                <Button size="sm" variant={row.id === selectedId ? "secondary" : "outline"} disabled={busy}
                        onClick={() => {
                            setBusy(true);
                            setError("");
                            void onChoose(row.id).then(() => onOpenChange(false)).catch((e: unknown) => setError(errorText(e))).finally(() => setBusy(false));
                        }}>{row.id === selectedId ? <><Check/>已选</> : "使用"}</Button>}</div>)}</div>
            {error && <p role="alert" className="text-sm text-destructive">{error}</p>}
        </>}
    </DialogContent></Dialog>;
}

function VoiceEditor({projectId, initial, takes, onBusyChange, onSaved}: {
    projectId: string;
    initial?: AudioSpeaker;
    takes: AudioTake[];
    onBusyChange: (value: boolean) => void;
    onSaved: () => void;
}) {
    const [name, setName] = useState(initial?.name ?? "");
    const [mode, setMode] = useState<MimoSpeechSettings["mode"]>(initial ? speakerSpeechProfile(initial).mimo?.mode ?? "design" : "design");
    const [voice, setVoice] = useState(initial?.mimo?.mode === "preset" ? initial.voice ?? "mimo_default" : "mimo_default");
    const [description, setDescription] = useState(initial?.mimo?.instruction ?? "");
    const [reference, setReference] = useState(initial?.mimo?.referenceMediaId ?? "");
    const [sampleText, setSampleText] = useState("你好，很高兴用我的声音，为你讲述接下来的故事。");
    const [preview, setPreview] = useState<{ mediaId: string; signature: string }>();
    const [busy, setBusy] = useState(false), [referenceBusy, setReferenceBusy] = useState(false), [error, setError] = useState("");
    const pending = useRef(false);
    const connections = useLiveQuery(() => db.connectors.toArray());
    const connector = defaultMimoConnector(connections ?? []);
    const blocked = busy || referenceBusy;
    const settings: MimoSpeechSettings = {
        mode,
        instruction: description, ...(mode === "clone" ? {referenceMediaId: reference} : {})
    };
    const signature = JSON.stringify({voice, settings, sampleText});
    const valid = mode === "design" ? Boolean(description.trim()) : mode === "clone" ? Boolean(reference) : true;

    async function run(fn: () => Promise<void>) {
        if (pending.current || referenceBusy) return;
        pending.current = true;
        setBusy(true);
        onBusyChange(true);
        setError("");
        try {
            await fn();
        } catch (e) {
            setError(errorText(e));
        } finally {
            pending.current = false;
            setBusy(false);
            onBusyChange(false);
        }
    }

    return <div className="space-y-4">
        {initial && !speakerSpeechProfile(initial).mimo &&
            <p className="text-xs text-muted-foreground">这是原有 APIMart 音色。保存本次编辑后，该角色将使用
                MiMo；已有配音版本保留。</p>}
        <Input aria-label="音色名称" value={name} maxLength={100} disabled={blocked}
               onChange={(e) => setName(e.target.value)} placeholder="给声音起个名字，例如：晚安旁白"/>
        <Tabs value={mode} onValueChange={(value) => setMode(value as MimoSpeechSettings["mode"])}><TabsList
            className="w-full" aria-label="创作音色方式"><TabsTrigger className="flex-1" value="design"
                                                                      disabled={blocked}>描述声音</TabsTrigger><TabsTrigger
            className="flex-1" value="clone" disabled={blocked}>克隆声音</TabsTrigger><TabsTrigger className="flex-1"
                                                                                                   value="preset"
                                                                                                   disabled={blocked}>预置音色</TabsTrigger></TabsList></Tabs>
        {mode === "preset" && <WorkspaceSelect aria-label="预置音色" value={voice} onValueChange={setVoice}
                                               disabled={blocked}>{MIMO_VOICES.map(item => <SelectOption key={item}
                                                                                                         value={item}>{item === "mimo_default" ? "MiMo 默认" : item}</SelectOption>)}</WorkspaceSelect>}
        {mode === "design" &&
            <Textarea aria-label="描述声音" disabled={blocked} rows={4} value={description} maxLength={8000}
                      onChange={(e) => setDescription(e.target.value)}
                      placeholder="温暖、沉稳的女声，略带气息感，像在深夜为你讲述一个故事。"/>}
        {mode === "clone" &&
            <VoiceReferencePicker projectId={projectId} takes={takes} value={reference} onChange={setReference}
                                  disabled={busy} onBusyChange={(value) => {
                setReferenceBusy(value);
                onBusyChange(value);
            }}/>}
        {mode !== "design" &&
            <Disclosure><DisclosureTitle>演绎指导（可选）</DisclosureTitle><Textarea aria-label="音色演绎指导"
                                                                                   disabled={blocked} rows={3}
                                                                                   value={description} maxLength={8000}
                                                                                   onChange={(e) => setDescription(e.target.value)}
                                                                                   placeholder="语速稍慢、轻声讲述…"/></Disclosure>}
        <Disclosure><DisclosureTitle>试音文本</DisclosureTitle><Textarea aria-label="试音文本" disabled={blocked}
                                                                         value={sampleText} maxLength={8192} rows={3}
                                                                         onChange={(e) => setSampleText(e.target.value)}/></Disclosure>
        {preview && <><AudioPlayer mediaId={preview.mediaId} title="音色试音"
                                   compact/>{preview.signature !== signature &&
            <p className="text-xs text-muted-foreground">设置已改变，可重新生成试音。</p>}{mode === "design" && preview.signature === signature &&
            <Button variant="ghost" size="sm" disabled={blocked} onClick={() => {
                setReference(preview.mediaId);
                setDescription("");
                setMode("clone");
                setPreview({
                    ...preview,
                    signature: JSON.stringify({
                        voice,
                        settings: {mode: "clone", instruction: "", referenceMediaId: preview.mediaId},
                        sampleText
                    })
                });
            }}>用这次试音固定音色</Button>}</>}
        {!connector && connections !== undefined &&
            <MimoConnection key={connections.find(row => row.definitionId === "mimo")?.id ?? "new"}
                            existing={connections.find(row => row.definitionId === "mimo")}/>}
        <div className="flex flex-wrap gap-2"><Button variant="outline"
                                                      disabled={blocked || !valid || !sampleText.trim() || !connector}
                                                      onClick={() => void run(async () => {
                                                          if (!connector) return;
                                                          const job = await prepareAudioGeneration({
                                                              projectId,
                                                              connectorId: connector.id,
                                                              input: {
                                                                  kind: "speech",
                                                                  text: sampleText,
                                                                  voice,
                                                                  speed: 1,
                                                                  mimo: settings
                                                              }
                                                          });
                                                          const result = await submitAudioGeneration(projectId, job.id);
                                                          const output = result.results.find(row => row.takeId && row.mediaId);
                                                          if (!output?.mediaId) throw new Error(result.error || "试音尚未完成，请在生成任务中查看");
                                                          setPreview({mediaId: output.mediaId, signature});
                                                      })}><Sparkles/>{busy ? "处理中…" : "生成试音"}</Button><Button
            disabled={blocked || !name.trim() || !valid} onClick={() => void run(async () => {
            const input = {name: name.trim(), voice, speed: 1, mimo: settings};
            if (initial) await patchAudioSpeaker(projectId, initial.id, initial.revision, input); else await addAudioSpeaker(projectId, input);
            onSaved();
        })}>保存音色</Button></div>
        <p className="text-xs text-muted-foreground">保存配置即可在台词中选用；生成试音使用 MiMo
            账户。试音会保留在项目声音中。</p>
        {error && <p role="alert" className="text-sm text-destructive">{error}</p>}
    </div>;
}

import {
    Children as ReactChildren,
    createContext,
    isValidElement,
    type ReactNode,
    useContext,
    useEffect,
    useRef,
    useState
} from "react";
import {Slider} from "@/components/ui/slider";
import {ChevronRight, Pause, Play, SkipBack, SkipForward, Volume2, VolumeX} from "lucide-react";
import {Select, SelectContent, SelectItem, SelectTrigger, SelectValue} from "@/components/ui/select";
import {Button} from "@/components/ui/button";

const EMPTY_VALUE = "__workspace_no_selection__";

/** Keep one set of studio selection primitives across both workspaces. */
export function WorkspaceSelect({value, onValueChange, disabled, className, children, "aria-label": ariaLabel}: {
    value: string;
    onValueChange: (value: string) => void;
    disabled?: boolean;
    className?: string;
    children: ReactNode;
    "aria-label"?: string;
}) {
    return <Select value={value || EMPTY_VALUE}
                   onValueChange={(next) => onValueChange(next === EMPTY_VALUE ? "" : next)} disabled={disabled}>
        <SelectTrigger aria-label={ariaLabel} className={`aw-select ${className ?? ""}`}><SelectValue/></SelectTrigger>
        <SelectContent>{children}</SelectContent>
    </Select>;
}

export function SelectOption({value, children}: { value: string; children: ReactNode }) {
    return <SelectItem value={value || EMPTY_VALUE}>{children}</SelectItem>;
}

/** Adapt scalar workspace values to the shared shadcn slider. */
export function WorkspaceSlider({
                                    value,
                                    defaultValue,
                                    min = 0,
                                    max = 1,
                                    step = 0.01,
                                    onChange,
                                    onCommit,
                                    label,
                                    disabled,
                                    className
                                }: {
    value?: number;
    defaultValue?: number;
    min?: number;
    max?: number;
    step?: number;
    onChange?: (value: number) => void;
    onCommit?: (value: number) => void;
    label: string;
    disabled?: boolean;
    className?: string;
}) {
    return <Slider
        className={`aw-slider ${className ?? ""}`}
        value={value === undefined ? undefined : [value]}
        defaultValue={defaultValue === undefined ? [min] : [defaultValue]}
        min={min} max={max} step={step}
        onValueChange={onChange ? ([next]) => onChange(next) : undefined}
        onValueCommit={onCommit ? ([next]) => onCommit(next) : undefined}
        aria-label={label} disabled={disabled}
    />;
}

export type AudioPlaybackActions = {
    onPrevious?: () => void;
    onNext?: () => void;
    onEnded?: () => void;
    onPlayingChange?: (playing: boolean) => void;
    toggleRequest?: number;
};

export function SourcePlayer({
                                 src,
                                 title,
                                 autoplay = false,
                                 onPrevious,
                                 onNext,
                                 onEnded,
                                 onPlayingChange,
                                 toggleRequest
                             }: { src: string; title: string; autoplay?: boolean } & AudioPlaybackActions) {
    const audio = useRef<HTMLAudioElement>(null);
    const [playing, setPlaying] = useState(false);
    const [position, setPosition] = useState(0);
    const [duration, setDuration] = useState(0);
    const [volume, setVolume] = useState(1);
    const [error, setError] = useState("");
    useEffect(() => {
        const stop = (event: Event) => {
            if (event.target !== audio.current) audio.current?.pause();
        };
        document.addEventListener("play", stop, true);
        const element = audio.current;
        return () => {
            document.removeEventListener("play", stop, true);
            element?.pause();
        };
    }, []);
    useEffect(() => {
        setPosition(0);
        setDuration(0);
        setPlaying(false);
        setError("");
    }, [src]);
    const lastToggle = useRef(toggleRequest);
    useEffect(() => {
        if (toggleRequest === lastToggle.current) return;
        lastToggle.current = toggleRequest;
        const element = audio.current;
        if (!element) return;
        if (!element.paused) element.pause();
        else void element.play().catch(() => setError("播放被浏览器阻止，请再次点击播放。"));
    }, [toggleRequest]);
    const format = (seconds: number) => `${Math.floor(seconds / 60)}:${String(Math.floor(seconds % 60)).padStart(2, "0")}`;
    return <div className="aw-custom-player">
        <audio ref={audio} src={src} autoPlay={autoplay} preload="metadata"
               onLoadedMetadata={(e) => setDuration(Number.isFinite(e.currentTarget.duration) ? e.currentTarget.duration : 0)}
               onDurationChange={(e) => setDuration(Number.isFinite(e.currentTarget.duration) ? e.currentTarget.duration : 0)}
               onTimeUpdate={(e) => setPosition(e.currentTarget.currentTime)} onPlay={() => {
            setPlaying(true);
            onPlayingChange?.(true);
            document.dispatchEvent(new CustomEvent("audio-workspace-audition"));
        }} onPause={() => {
            setPlaying(false);
            onPlayingChange?.(false);
        }} onEnded={() => {
            setPlaying(false);
            onPlayingChange?.(false);
            onEnded?.();
        }} onError={() => setError("此音频无法播放，请检查文件格式或重新导入。")}/>
        {(onPrevious || onNext) && <Button size="icon-sm" variant="ghost" aria-label="上一首" disabled={!onPrevious}
                                           onClick={onPrevious}><SkipBack size={16}/></Button>}
        <Button size="icon-sm" variant="ghost" aria-label={`${playing ? "暂停" : "播放"} ${title}`} onClick={() => {
            if (playing) audio.current?.pause(); else void audio.current?.play().catch(() => setError("播放被浏览器阻止，请再次点击播放。"));
        }}>{playing ? <Pause size={16}/> : <Play size={16}/>}</Button>
        {(onPrevious || onNext) &&
            <Button size="icon-sm" variant="ghost" aria-label="下一首" disabled={!onNext} onClick={onNext}><SkipForward
                size={16}/></Button>}
        <span className="aw-time">{format(position)}</span>
        <WorkspaceSlider label={`${title} 播放进度`} className="aw-playback-slider" value={Math.min(position, duration)}
                         max={duration || 1} disabled={!duration} step={0.01} onChange={(seconds) => {
            if (audio.current) audio.current.currentTime = seconds;
            setPosition(seconds);
        }}/>
        <span className="aw-time aw-muted">{format(duration)}</span>
        <Button size="icon-sm" variant="ghost" aria-label={volume ? "静音试听" : "恢复试听音量"} onClick={() => {
            const next = volume ? 0 : 1;
            if (audio.current) audio.current.volume = next;
            setVolume(next);
        }}>{volume ? <Volume2 size={15}/> : <VolumeX size={15}/>}</Button>
        <WorkspaceSlider label="试听音量" className="aw-volume-slider" value={volume} onChange={(next) => {
            if (audio.current) audio.current.volume = next;
            setVolume(next);
        }}/>
        {error && <span role="alert" className="aw-error">{error}</span>}
    </div>;
}

const DisclosureContext = createContext({
    open: false, toggle: () => {
    }
});

export function Disclosure({children, defaultOpen = false, className = ""}: {
    children: ReactNode;
    defaultOpen?: boolean;
    className?: string
}) {
    const [open, setOpen] = useState(defaultOpen);
    return <DisclosureContext.Provider value={{open, toggle: () => setOpen((value) => !value)}}>
        <section data-aw-disclosure
                 className={className}>{ReactChildren.map(children, (child) => isValidElement(child) && child.type === DisclosureTitle ? child : open ? child : null)}</section>
    </DisclosureContext.Provider>;
}

export function DisclosureTitle({children, className = ""}: { children: ReactNode; className?: string }) {
    const {open, toggle} = useContext(DisclosureContext);
    return <Button variant="ghost" type="button" aria-expanded={open} className={`aw-disclosure-title ${className}`}
                   onClick={toggle}><ChevronRight size={13} className={open ? "rotate-90" : ""}/>{children}</Button>;
}

import {useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {db} from "@/db/database";
import type {MediaKind, MediaRecord} from "@/domain/types";
import {reusableMedia} from "@/lib/mediaPicker";
import {MediaPreview} from "./MediaThumb";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";

/** Inline in the slot dialog: selection reuses an ID and never owns/deletes its Blob. */
export function MediaPicker({projectId, kinds, disabled, selectedIds, onSelect, onClose}: {
    projectId: string;
    kinds: readonly MediaKind[];
    disabled: boolean;
    selectedIds: readonly string[];
    onSelect: (record: MediaRecord) => void;
    onClose: () => void;
}) {
    const [query, setQuery] = useState("");
    const records = useLiveQuery(() => db.media.where("projectId").equals(projectId).toArray(), [projectId]);
    const items = reusableMedia(records ?? [], projectId, kinds, query);
    return (
        <section aria-label="选择已有素材" className="space-y-3 rounded-xl border p-3">
            <div className="flex items-center justify-between gap-2">
                <div>
                    <h3 className="text-sm font-medium">选择已有素材</h3>
                    <p className="text-muted-foreground mt-1 text-xs">仅显示当前{projectId === "studio" ? "工作室" : "项目"}的{kinds.length === 1 ? (kinds[0] === "image" ? "图片" : "视频") : "图片与视频"}，无需再次上传。</p>
                </div>
                <Button type="button" variant="ghost" size="sm" disabled={disabled} onClick={onClose}>收起</Button>
            </div>
            <Input aria-label="搜索已有素材" placeholder="按文件名搜索…" value={query} disabled={disabled}
                   onChange={(event) => setQuery(event.target.value)}/>
            {records === undefined ?
                <p className="text-muted-foreground text-sm" role="status">加载中…</p> : items.length === 0 ? (
                    <p className="text-muted-foreground py-4 text-sm">{query.trim() ? "没有匹配的素材。" : "还没有可复用的素材，可以先上传文件。"}</p>
                ) : <div className="grid max-h-64 grid-cols-2 gap-2 overflow-auto sm:grid-cols-3">
                    {items.map((record) => <button key={record.id} type="button"
                                                   disabled={disabled || selectedIds.includes(record.id)}
                                                   className="hover:border-brand focus-visible:ring-ring overflow-hidden rounded-lg border text-left focus-visible:ring-2 disabled:opacity-50"
                                                   onClick={() => onSelect(record)}
                                                   aria-label={`选择素材 ${record.filename}`}>
                        <MediaPreview mediaId={record.id} className="h-24 w-full"/>
                        <span className="block truncate px-2 pt-2 text-xs"
                              title={record.filename}>{record.filename}</span>
                        <span
                            className="text-muted-foreground block px-2 pb-2 text-[11px]">{selectedIds.includes(record.id) ? "已添加" : record.mimeType.startsWith("video/") ? "视频" : "图片"}</span>
                    </button>)}
                </div>}
        </section>
    );
}

import {useEffect, useRef, useState} from "react";
import {useBlocker} from "@tanstack/react-router";
import {useLiveQuery} from "dexie-react-hooks";
import {toast} from "sonner";
import type {MemoryInput, MemorySourceRef, ProjectMemory,} from "@/domain/projectMemory";
import {
    createProjectMemory,
    getProjectMemory,
    MemoryConflictError,
    promoteProjectMemory,
    updateProjectMemory,
} from "@/db/projectMemories";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {Textarea} from "@/components/ui/textarea";
import {Field} from "@/components/ui/field";
import {Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle,} from "@/components/ui/dialog";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {readMemory} from "./readMemory";
import {CATEGORY_LABELS} from "./memoryLabels";
import "./memory.css";

export const EMPTY_MEMORY: MemoryInput = {
    category: "convention",
    title: "",
    topicKey: "",
    body: "",
    applicability: "",
    tags: [],
};

export function MemoryEditor({
                                 projectId,
                                 initial = EMPTY_MEMORY,
                                 memory,
                                 source,
                                 sourceExcerpt,
                                 onClose,
                                 onSaved,
                                 onPendingChange,
                             }: {
    projectId: string;
    initial?: MemoryInput;
    memory?: ProjectMemory;
    source?: MemorySourceRef;
    sourceExcerpt?: string;
    onClose: () => void;
    onSaved: (memory: ProjectMemory) => void;
    onPendingChange?: (pending: boolean) => void;
}) {
    const baseline: MemoryInput = {
        inclusion: initial.inclusion ?? "relevant",
        category: initial.category,
        title: initial.title,
        topicKey: initial.topicKey,
        body: initial.body,
        applicability: initial.applicability,
        tags: initial.tags,
    };
    const [draft, setDraft] = useState<MemoryInput>(() => ({
        ...baseline,
        tags: [...initial.tags],
    }));
    const [tagsText, setTagsText] = useState(initial.tags.join("，"));
    const [expectedRevision, setExpectedRevision] = useState(memory?.revision);
    const [readAttempt, setReadAttempt] = useState(0);
    const currentRead = useLiveQuery(
        () =>
            readMemory(async () =>
                memory
                    ? ((await getProjectMemory(projectId, memory.id)) ?? null)
                    : null,
            ),
        [projectId, memory?.id, readAttempt],
    );
    const current = currentRead?.data;
    const [pending, setPending] = useState(false);
    const [error, setError] = useState("");
    const [conflictIds, setConflictIds] = useState<string[]>([]);
    const [discard, setDiscard] = useState(false);
    const lock = useRef(false);
    useEffect(() => {
        onPendingChange?.(pending);
        return () => onPendingChange?.(false);
    }, [pending, onPendingChange]);
    const conflictsRead = useLiveQuery(
        () =>
            readMemory(async () =>
                (
                    await Promise.all(
                        conflictIds.map((id) => getProjectMemory(projectId, id)),
                    )
                ).filter((item): item is ProjectMemory => !!item),
            ),
        [projectId, conflictIds.join("|"), readAttempt],
    );
    const conflicts = conflictsRead?.data;
    const readError = currentRead?.error || conflictsRead?.error;
    const dirty =
        JSON.stringify(draft) !== JSON.stringify(baseline) ||
        tagsText !== initial.tags.join("，");
    const blocker = useBlocker({
        shouldBlockFn: () => dirty || pending,
        withResolver: true,
        enableBeforeUnload: dirty || pending,
    });

    function close() {
        if (pending) return;
        if (dirty) setDiscard(true);
        else onClose();
    }

    function change(patch: Partial<MemoryInput>) {
        setDraft((value) => ({...value, ...patch}));
        setConflictIds([]);
        setError("");
    }

    async function save(replace?: { id: string; expectedRevision: number }) {
        if (lock.current) return;
        lock.current = true;
        setPending(true);
        setError("");
        const input = {
            ...draft,
            topicKey: draft.topicKey.trim() || draft.title,
            tags: tagsText
                .split(/[,，]/)
                .map((tag) => tag.trim())
                .filter(Boolean),
        };
        try {
            if (memory) {
                const updated = await updateProjectMemory(
                    projectId,
                    memory.id,
                    input,
                    expectedRevision!,
                );
                onSaved(updated);
                toast.success("记忆已更新");
            } else {
                const result = source
                    ? await promoteProjectMemory(projectId, source, input, {replace})
                    : await createProjectMemory(projectId, input, {replace});
                onSaved(result.memory);
                toast.success(
                    result.duplicate
                        ? "这条记忆已经保存，无需重复添加"
                        : "已保存到项目记忆",
                );
            }
        } catch (failure) {
            setError(
                failure instanceof Error
                    ? failure.message
                    : "保存失败，编辑内容已保留，请重试",
            );
            if (failure instanceof MemoryConflictError)
                setConflictIds(failure.existingIds);
        } finally {
            lock.current = false;
            setPending(false);
        }
    }

    return (
        <>
            <Dialog
                open
                onOpenChange={(open) => {
                    if (!open) close();
                }}
            >
                <DialogContent
                    className="memory-editor-dialog"
                    onEscapeKeyDown={(event) => {
                        if (pending) event.preventDefault();
                    }}
                >
                    <DialogHeader>
                        <DialogTitle>
                            {memory ? "编辑记忆" : source ? "保存为项目记忆" : "添加项目记忆"}
                        </DialogTitle>
                        <DialogDescription>
                            写下后续创作可以复用的内容，并明确它适用的条件。
                        </DialogDescription>
                    </DialogHeader>
                    <form
                        onSubmit={(event) => {
                            event.preventDefault();
                            void save();
                        }}
                        className="memory-editor-form"
                    >
                        <fieldset disabled={pending} className="memory-editor-fields">
                            {sourceExcerpt && (
                                <details className="memory-source-excerpt">
                                    <summary>查看这条记忆的原始依据</summary>
                                    <p>{sourceExcerpt}</p>
                                    <small>
                                        来自已确认的历史总结。请再次检查它是否仍适用于当前项目。
                                    </small>
                                </details>
                            )}
                            <div className="memory-form-pair">
                                <Field label="分类">
                                    <select
                                        className="memory-select"
                                        value={draft.category}
                                        onChange={(event) =>
                                            change({
                                                category: event.target.value as MemoryInput["category"],
                                            })
                                        }
                                    >
                                        {Object.entries(CATEGORY_LABELS).map(([value, label]) => (
                                            <option value={value} key={value}>
                                                {label}
                                            </option>
                                        ))}
                                    </select>
                                </Field>
                                <Field label="标题">
                                    <Input
                                        autoFocus
                                        required
                                        maxLength={120}
                                        value={draft.title}
                                        onChange={(event) => change({title: event.target.value})}
                                        placeholder="例如：角色对白的语气"
                                    />
                                </Field>
                            </div>
                            <Field label="记忆正文">
                                <Textarea
                                    required
                                    rows={6}
                                    maxLength={6000}
                                    value={draft.body}
                                    onChange={(event) => change({body: event.target.value})}
                                    placeholder="保留明确、可复用的结论，而不是整段聊天记录。"
                                />
                            </Field>
                            <Field label="引用方式"><select className="memory-select"
                                                            value={draft.inclusion ?? "relevant"}
                                                            onChange={(event) => change({inclusion: event.target.value as MemoryInput["inclusion"]})}>
                                <option value="relevant">按需引用</option>
                                <option value="project">项目通用</option>
                            </select></Field>
                            <p className="memory-field-hint">{draft.inclusion === "project" ? "在本项目的对话中优先带入，仍受上下文预算限制。请确认适用于整个项目。" : "根据当前问题和任务选择，仅在相关时带入。"}</p>
                            <Field label="适用条件">
                                <Textarea
                                    rows={2}
                                    maxLength={2000}
                                    value={draft.applicability}
                                    onChange={(event) =>
                                        change({applicability: event.target.value})
                                    }
                                    placeholder="适用于哪些场景，有什么例外？"
                                />
                            </Field>
                            <div className="memory-form-pair">
                                <Field label="主题（用于检查重复）">
                                    <Input
                                        maxLength={120}
                                        value={draft.topicKey}
                                        onChange={(event) =>
                                            change({topicKey: event.target.value})
                                        }
                                        placeholder="留空时使用标题"
                                    />
                                </Field>
                                <Field label="标签（逗号分隔）">
                                    <Input
                                        maxLength={600}
                                        value={tagsText}
                                        onChange={(event) => setTagsText(event.target.value)}
                                        placeholder="角色，对白"
                                    />
                                </Field>
                            </div>
                        </fieldset>
                        {memory && current && current.revision !== expectedRevision && (
                            <div className="memory-conflicts" role="status">
                                <strong>这条记忆已在其他地方更新</strong>
                                <p>
                                    最新版本 {current.revision}：{current.title}
                                </p>
                                <p>{current.body}</p>
                                <p>适用条件：{current.applicability || "未单独限定"}</p>
                                <p>引用方式：{current.inclusion === "project" ? "项目通用" : "按需引用"}</p>
                                <Button
                                    type="button"
                                    variant="outline"
                                    disabled={pending}
                                    onClick={() => {
                                        setExpectedRevision(current.revision);
                                        setError("");
                                    }}
                                >
                                    已核对最新版本，保留我的草稿继续编辑
                                </Button>
                            </div>
                        )}
                        {memory && current === null && (
                            <p className="memory-error" role="alert">
                                这条记忆已被删除。编辑内容仍保留，可复制后另行添加。
                            </p>
                        )}
                        {readError && (
                            <div className="memory-error" role="alert">
                                <p>暂时无法读取记忆：{readError}。草稿已保留。</p>
                                <Button
                                    type="button"
                                    variant="outline"
                                    size="sm"
                                    disabled={pending}
                                    onClick={() => setReadAttempt((value) => value + 1)}
                                >
                                    重新读取
                                </Button>
                            </div>
                        )}
                        {error && (
                            <p className="memory-error" role="alert">
                                {error}。编辑内容仍保留。
                            </p>
                        )}
                        {!!conflicts?.length && (
                            <div className="memory-conflicts">
                                <p>
                                    已有相同主题的内容。你可以修改主题，也可以明确替代其中一条。
                                </p>
                                {conflicts.map((item) => (
                                    <div key={item.id}>
                                        <strong>{item.title}</strong>
                                        <p>{item.body}</p>
                                        {!memory && (
                                            <Button
                                                type="button"
                                                variant="outline"
                                                size="sm"
                                                disabled={pending}
                                                onClick={() =>
                                                    void save({
                                                        id: item.id,
                                                        expectedRevision: item.revision,
                                                    })
                                                }
                                            >
                                                保存并替代此条
                                            </Button>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}
                        <div className="memory-editor-actions">
                            <Button
                                type="button"
                                variant="ghost"
                                disabled={pending}
                                onClick={close}
                            >
                                取消
                            </Button>
                            <Button
                                type="submit"
                                disabled={
                                    pending ||
                                    !!readError ||
                                    (!!memory &&
                                        (!current || current.revision !== expectedRevision)) ||
                                    !draft.title.trim() ||
                                    !draft.body.trim()
                                }
                            >
                                {pending ? "保存中…" : memory ? "保存修改" : "确认并保存"}
                            </Button>
                        </div>
                    </form>
                </DialogContent>
            </Dialog>
            <AlertDialog
                open={discard || blocker.status === "blocked"}
                onOpenChange={(open) => {
                    if (!open) {
                        setDiscard(false);
                        blocker.reset?.();
                    }
                }}
            >
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>放弃尚未保存的修改？</AlertDialogTitle>
                        <AlertDialogDescription>
                            当前编辑的内容尚未写入项目记忆，离开后将丢失。
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel disabled={pending}>继续编辑</AlertDialogCancel>
                        <AlertDialogAction
                            disabled={pending}
                            onClick={() => {
                                if (blocker.status === "blocked") blocker.proceed();
                                else onClose();
                            }}
                        >
                            放弃修改
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </>
    );
}

