                                    <option key={value} value={value}>
                                        {label}
                                    </option>
                                ))}
                            </select>
                            <select
                                className="memory-select"
                                aria-label="筛选记忆状态"
                                value={status}
                                onChange={(event) => setStatus(event.target.value)}
                            >
                                <option value="">全部状态</option>
                                {Object.entries(STATUS_LABELS).map(([value, label]) => (
                                    <option key={value} value={value}>
                                        {label}
                                    </option>
                                ))}
                            </select>
                        </div>
                    </div>
                    <div className="memory-list-meta">
                        <span>{records.length} 条记忆</span>
                        <span>{active} 条已确认</span>
                    </div>
                    <div className="memory-list-scroll">
                        {!result ? (
                            <p className="memory-empty" role="status">
                                正在读取项目记忆…
                            </p>
                        ) : result.error ? (
                            <p className="memory-error" role="alert">
                                {result.error}
                            </p>
                        ) : records.length ? (
                            records.map((memory) => (
                                <button
                                    key={memory.id}
                                    type="button"
                                    className={`memory-list-item${selectedId === memory.id ? " is-selected" : ""}`}
                                    aria-pressed={selectedId === memory.id}
                                    onClick={() => setSelectedId(memory.id)}
                                >
                                    <div>
                    <span className="memory-category">
                      {CATEGORY_LABELS[memory.category]}{memory.inclusion === "project" ? " · 项目通用" : ""}
                    </span>
                                        <span className={`memory-status is-${memory.status}`}>
                      {STATUS_LABELS[memory.status]}
                    </span>
                                    </div>
                                    <h2>{memory.title}</h2>
                                    <p>{memory.body}</p>
                                    <small>
                                        {sourceLabel(memory)}
                                        <span>{memoryDate(memory.updatedAt)}</span>
                                    </small>
                                </button>
                            ))
                        ) : (
                            <div className="memory-empty">
                                <BookOpen size={28} strokeWidth={1.3}/>
                                <h2>
                                    {result.records.length ? "没有匹配的记忆" : "让好方法留下来"}
                                </h2>
                                <p>
                                    {result.records.length
                                        ? "试试其他关键词，或调整筛选条件。"
                                        : "可以手动写下一条规范，也可以从任务的已确认总结中，保存值得复用的决策和经验。"}
                                </p>
                                {!result.records.length && (
                                    <Button variant="outline" onClick={() => setEditor("new")}>
                                        写下第一条记忆
                                    </Button>
                                )}
                            </div>
                        )}
                    </div>
                </section>
                <section className="memory-detail-panel" aria-label="记忆详情">
                    {selected ? (
                        <MemoryDetail
                            key={selected.id}
                            memory={selected}
                            onBack={() => setSelectedId(undefined)}
                            onEdit={() => setEditor(selected)}
                        />
                    ) : (
                        <div className="memory-detail-placeholder">
                            <BookOpen size={36} strokeWidth={1}/>
                            <h2>{selectedId ? "这条记忆已被删除" : "项目的创作共识"}</h2>
                            <p>选择一条记忆，查看它的适用条件、原始依据与修订过程。</p>
                            <small>已启用的记忆会按当前需求引用；也可标记为项目通用。</small>
                        </div>
                    )}
                </section>
            </div>
            {editor && (
                <MemoryEditor
                    key={editor === "new" ? "new" : `${editor.id}:${editor.revision}`}
                    projectId={projectId}
                    initial={editor === "new" ? undefined : editor}
                    memory={editor === "new" ? undefined : editor}
                    onClose={() => setEditor(undefined)}
                    onSaved={(memory) => {
                        setEditor(undefined);
                        setSelectedId(memory.id);
                        setQuery("");
                        setCategory("");
                        setStatus("");
                    }}
                />
            )}
        </main>
    );
}

function MemoryDetail({
                          memory,
                          onBack,
                          onEdit,
                      }: {
    memory: ProjectMemory;
    onBack: () => void;
    onEdit: () => void;
}) {
    const {projectId, id} = memory;
    const [readAttempt, setReadAttempt] = useState(0);
    const sourceRead = useLiveQuery(
        () => readMemory(() => getMemorySourceState(projectId, id)),
        [projectId, id, memory.revision, readAttempt],
    );
    const source = sourceRead?.data;
    const versionsRead = useLiveQuery(
        () => readMemory(() => listProjectMemoryVersions(projectId, id)),
        [projectId, id, readAttempt],
    );
    const versions = versionsRead?.data;
    const [conflictIds, setConflictIds] = useState<string[]>([]);
    const conflictsRead = useLiveQuery(
        () =>
            readMemory(async () =>
                (
                    await Promise.all(
                        conflictIds.map((otherId) => getProjectMemory(projectId, otherId)),
                    )
                ).filter((row): row is ProjectMemory => !!row),
            ),
        [projectId, conflictIds.join("|"), readAttempt],
    );
    const conflicts = conflictsRead?.data;
    const readError =
        sourceRead?.error || versionsRead?.error || conflictsRead?.error;
    const [deleting, setDeleting] = useState(false);
    const [pending, setPending] = useState(false);
    const [error, setError] = useState("");
    const lock = useRef(false);

    async function act(action: () => Promise<unknown>, success: string) {
        if (lock.current) return;
        lock.current = true;
        setPending(true);
        setError("");
        try {
            await action();
            setConflictIds([]);
            toast.success(success);
        } catch (failure) {
            setError(failure instanceof Error ? failure.message : "操作失败，请重试");
            if (failure instanceof MemoryConflictError)
                setConflictIds(failure.existingIds);
        } finally {
            lock.current = false;
            setPending(false);
        }
    }

    const excerpt =
        memory.source.kind === "manual" ? undefined : memory.source.excerpt;
    return (
        <>
            <div className="memory-detail-toolbar">
                <Button
                    className="memory-mobile-back"
                    variant="ghost"
                    size="sm"
                    onClick={onBack}
                >
                    <ArrowLeft/>
                    返回列表
                </Button>
                <span>版本 {memory.revision}</span>
                <div>
                    <Button
                        variant="ghost"
                        size="icon-sm"
                        disabled={pending || memory.status === "superseded"}
                        aria-label="编辑这条记忆"
                        onClick={onEdit}
                    >
                        <Pencil/>
                    </Button>
                    <Button
                        variant="ghost"
                        size="icon-sm"
                        disabled={pending}
                        aria-label="删除这条记忆"
                        onClick={() => setDeleting(true)}
                    >
                        <Trash2/>
                    </Button>
                </div>
            </div>
            <div className="memory-detail-scroll">
                {readError && (
                    <div className="memory-error" role="alert">
                        <p>部分信息暂时无法读取：{readError}</p>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setReadAttempt((value) => value + 1)}
                        >
                            重新读取详情
                        </Button>
                    </div>
                )}
                <div className="memory-detail-kicker">
                    <span>{CATEGORY_LABELS[memory.category]}</span>
                    <span className={`memory-status is-${memory.status}`}>
            {STATUS_LABELS[memory.status]}
          </span>
                </div>
                <h2 className="memory-detail-title">{memory.title}</h2>
                <p className="memory-detail-body">{memory.body}</p>
                {!!memory.tags.length && (
                    <div className="memory-tags">
                        {memory.tags.map((tag) => (
                            <span key={tag}>#{tag}</span>
                        ))}
                    </div>
                )}
                <section className="memory-detail-section">
                    <h3>适用条件<span>{memory.inclusion === "project" ? "项目通用 · 优先引用" : "按需引用"}</span></h3>
                    <p>
                        {memory.applicability || "未单独限定，请结合当前创作目标判断。"}
                    </p>
                </section>
                <section className="memory-detail-section">
                    <h3>
                        来源与依据<span>{sourceLabel(memory)}</span>
                    </h3>
                    <p>
                        {source?.message ??
                            (sourceRead?.error ? "来源读取失败，请重试" : "正在核对来源…")}
                    </p>
                    {source?.href && (
                        <Link to={source.href} className="memory-source-link">
                            查看原任务
                            <ArrowUpRight size={14}/>
                        </Link>
                    )}
                    {excerpt && (
                        <details className="memory-source-excerpt">
                            <summary>保存时的原文摘录</summary>
                            <p>{excerpt}</p>
                        </details>
                    )}
                    {memory.source.kind !== "manual" &&
                        memory.source.evidence?.map((item) => (
                            <details className="memory-source-excerpt" key={item.id}>
                                <summary>
                                    {item.label}
                                    {item.truncated ? " · 摘录" : ""}
                                </summary>
                                <p>{item.body}</p>
                            </details>
                        ))}
                </section>
                <section className="memory-detail-section">
                    <h3>
            <span className="memory-section-label">
              <History size={15}/>
              修订历史
            </span>
                        <span>{versions?.length ?? 0} 版</span>
                    </h3>
                    {versions?.map((version) => (
                        <details className="memory-version" key={version.versionId}>
                            <summary>
                <span>
                  版本 {version.revision} ·{" "}
                    {STATUS_LABELS[version.snapshot.status]}
                </span>
                                <small>{memoryDate(version.snapshot.updatedAt)}</small>
                            </summary>
                            <h4>{version.snapshot.title}</h4>
                            <p>{version.snapshot.body}</p>
                            <small>
                                适用条件：{version.snapshot.applicability || "未单独限定"} · {version.snapshot.inclusion === "project" ? "项目通用" : "按需引用"}
                            </small>
                        </details>
                    ))}
                </section>
                <p className="memory-detail-date">
                    创建于 {memoryDate(memory.createdAt)} · 最近更新{" "}
                    {memoryDate(memory.updatedAt)}
                </p>
            </div>
            <div className="memory-detail-footer">
                {!!conflicts?.length && (
                    <div className="memory-conflicts">
                        <p>以下记忆已启用。核对内容后，可用当前记忆明确替代。</p>
                        {conflicts.map((other) => (
                            <div key={other.id}>
                                <strong>{other.title}</strong>
                                <p>{other.body}</p>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    disabled={pending}
                                    onClick={() =>
                                        void act(
                                            () =>
                                                replaceProjectMemory(projectId, other.id, id, {
                                                    oldRevision: other.revision,
                                                    newRevision: memory.revision,
                                                }),
                                            "已替代旧记忆并启用当前条目",
                                        )
                                    }
                                >
                                    以当前记忆替代此条
                                </Button>
                            </div>
                        ))}
                    </div>
                )}
                {error && (
                    <p className="memory-error" role="alert">
                        {error}
                    </p>
                )}
                {memory.status === "superseded" ? (
                    <p>此条目已被新记忆替代，保留作为历史依据。</p>
                ) : (
                    <>
                        <p>
                            {memory.status === "active"
                                ? "停用后内容和修订历史仍会保留。"
                                : memory.status === "pending_review"
                                    ? "来自备份。请核对正文与适用条件后再启用。"
                                    : "这条记忆已暂停使用，可随时重新启用。"}
                        </p>
                        <Button
                            variant="outline"
                            size="sm"
                            disabled={pending}
                            onClick={() =>
                                void act(
                                    () =>
                                        setProjectMemoryStatus(
                                            projectId,
                                            id,
                                            memory.status === "active" ? "disabled" : "active",
                                            memory.revision,
                                        ),
                                    memory.status === "active" ? "记忆已停用" : "记忆已确认启用",
                                )
                            }
                        >
                            {memory.status === "active" && <Pause/>}
                            {memory.status === "active"
                                ? "停用记忆"
                                : memory.status === "pending_review"
                                    ? "确认并启用"
                                    : "重新启用"}
                        </Button>
                    </>
                )}
            </div>
            <AlertDialog
                open={deleting}
                onOpenChange={(open) => {
                    if (!pending) setDeleting(open);
                }}
            >
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>永久删除“{memory.title}”？</AlertDialogTitle>
                        <AlertDialogDescription>
                            这条记忆及其全部修订历史都会被删除，原始任务总结会保留。如果暂时不再适用，可以取消后选择停用。
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    {error && (
                        <p role="alert" className="memory-error">
                            {error}
                        </p>
                    )}
                    <AlertDialogFooter>
                        <AlertDialogCancel disabled={pending}>保留记忆</AlertDialogCancel>
                        <Button
                            variant="destructive"
                            disabled={pending}
                            onClick={() =>
                                void act(async () => {
                                    await deleteProjectMemory(projectId, id, memory.revision);
                                    setDeleting(false);
                                    onBack();
                                }, "记忆及修订历史已删除")
                            }
                        >
                            {pending ? "删除中…" : "永久删除"}
                        </Button>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </>
    );
}

import type {ProjectMemory} from "@/domain/projectMemory";

export const CATEGORY_LABELS = {
    convention: "项目规范",
    preference: "创作偏好",
    decision: "关键决策",
    lesson: "经验教训",
};
export const STATUS_LABELS = {
    active: "已确认",
    disabled: "已停用",
    superseded: "已被替代",
    pending_review: "待复核",
};
export const memoryDate = (value: string) =>
    new Date(value).toLocaleString("zh-CN", {
        month: "short",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
    });
export const sourceLabel = (memory: ProjectMemory) =>
    memory.source.kind === "manual"
        ? "手动记录"
        : memory.source.kind === "imported"
            ? "项目备份"
            : "任务总结";

import {useRef, useState} from "react";
import {Sparkles} from "lucide-react";
import {db} from "@/db/database";
import {patchMusicDraft} from "@/db/music";
import type {MusicDraft, MusicSettings} from "@/domain/music";
import {prepareAudioGeneration, submitAudioGeneration} from "@/lib/audioGeneration/runtime";
import {flushPendingDrafts, useDebouncedDraft} from "@/lib/debouncedDraft";
import {DraftConflictError} from "@/lib/draftConflict";
import {Checkbox} from "@/components/ui/checkbox";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {Textarea} from "@/components/ui/textarea";
import {DraftStatus} from "@/components/ui/draft-status";
import {Tabs, TabsList, TabsTrigger} from "@/components/ui/tabs";
import {Disclosure, DisclosureTitle, SelectOption, WorkspaceSelect} from "@/components/audioMusic/controls";
import {ConnectionSelect, errorText, Field} from "@/components/audioMusic/shared";
import {musicVariant, type MusicVariant} from "./draftVariants";

export function MusicCreation({
                                  record,
                                  switching,
                                  changeVariant,
                                  connectorId,
                                  setConnectorId,
                                  onSubmitted,
                                  onSubmittingChange
                              }: {
    record: MusicDraft;
    switching: boolean;
    changeVariant: (target: MusicVariant) => void;
    connectorId: string;
    setConnectorId: (id: string) => void;
    onSubmitted: () => void;
    onSubmittingChange: (value: boolean) => void;
}) {
    const [busy, setBusy] = useState(false);
    const pending = useRef(false);
    const [error, setError] = useState("");
    const {draft, setDraft, status, error: saveError, retry, useLatest} = useDebouncedDraft<MusicSettings>({
        scope: record.projectId, draftKey: `${record.id}:settings`, initialValue: record.settings,
        persist: async (settings, baseline) => {
            const current = await db.musicDrafts.get(record.id);
            if (!current || JSON.stringify(current.settings) !== JSON.stringify(baseline)) throw new DraftConflictError();
            await patchMusicDraft(record.projectId, current.id, current.revision, {settings});
        },
    });
    const update = (patch: Partial<MusicSettings>) => setDraft((previous) => ({...previous, ...patch} as MusicSettings));

    async function generate() {
        if (pending.current) return;
        pending.current = true;
        setBusy(true);
        onSubmittingChange(true);
        setError("");
        try {
            await flushPendingDrafts(record.projectId);
            const current = await db.musicDrafts.get(record.id);
            if (!current) throw new Error("创作草稿不存在");
            const job = await prepareAudioGeneration({
                projectId: record.projectId,
                connectorId,
                input: {kind: "music", settings: current.settings, draftId: current.id, draftRevision: current.revision}
            });
            await submitAudioGeneration(record.projectId, job.id);
            onSubmitted();
        } catch (e) {
            setError(errorText(e));
        } finally {
            pending.current = false;
            setBusy(false);
            onSubmittingChange(false);
        }
    }

    return <div className="mw-creation">
        <div className="mw-compose-scroll">
            <div className="mw-mode-bar">
                {draft.engine === "suno" ? <Tabs value={musicVariant(draft)}
                                                 onValueChange={(value) => changeVariant(value as MusicVariant)}><TabsList
                        aria-label="创作模式"><TabsTrigger disabled={switching || busy}
                                                           value="suno-simple">简单</TabsTrigger><TabsTrigger
                        disabled={switching || busy} value="suno-custom">自定义</TabsTrigger></TabsList></Tabs> :
                    <span className="text-sm font-medium">Flow Music</span>}
                <WorkspaceSelect aria-label="音乐引擎与模型" disabled={switching || busy}
                                 value={draft.engine === "suno" ? draft.version : "flowmusic"}
                                 onValueChange={(value) => {
                                     if (value === "flowmusic") changeVariant("flowmusic");
                                     else if (draft.engine === "suno") update({version: value as "v6" | "v6-mini" | "v6-wild"});
                                     else changeVariant("suno-simple");
                                 }}>{draft.engine === "suno" ? <><SelectOption value="v6">Suno
                        v6</SelectOption><SelectOption value="v6-wild">Suno v6-wild</SelectOption><SelectOption
                        value="v6-mini">Suno v6-mini</SelectOption></> :
                    <SelectOption value="suno">Suno</SelectOption>}<SelectOption value="flowmusic">Flow
                    Music</SelectOption></WorkspaceSelect>
            </div>
            {draft.engine === "suno" ? <>
                {draft.custom && draft.instrumental ?
                    <p className="mw-instrumental-note">已填写的歌词会保留，切回歌曲后可继续编辑。用下方风格描述这首纯音乐。</p> :
                    <Field label={draft.custom ? "歌词" : "描述你想听到的音乐"}><Textarea disabled={busy || switching}
                                                                                          className="mw-main-input"
                                                                                          rows={draft.custom ? 9 : 7}
                                                                                          aria-label={draft.custom ? "歌词" : "音乐描述"}
                                                                                          maxLength={draft.custom ? 5000 : 3000}
                                                                                          value={draft.prompt}
                                                                                          onChange={(e) => update({prompt: e.target.value})}
                                                                                          placeholder={draft.custom ? "[Verse]\n写下第一句歌词…\n\n[Chorus]\n让旋律记住这一刻" : "午后公路上的独立流行，温暖的吉他，轻快而自在。\n\n写下场景、情绪，或一个灵感。"}/></Field>}
                <label className="mw-check"><Checkbox disabled={busy || switching} checked={draft.instrumental}
                                                      onCheckedChange={(value) => update({instrumental: value === true})}/>纯音乐<span>不含人声</span></label>
                {draft.custom &&
                    <Field label="风格"><Textarea disabled={busy || switching} aria-label="音乐风格" rows={3}
                                                  maxLength={1000} value={draft.style}
                                                  onChange={(e) => update({style: e.target.value})}
                                                  placeholder="独立流行、木吉他、温暖的女声…"/></Field>}
                <Disclosure><DisclosureTitle>更多设置</DisclosureTitle><Field
                    label={draft.custom ? "作品名称（可选）" : "草稿名称（可选）"}><Input disabled={busy || switching}
                                                                                      aria-label={draft.custom ? "作品名称" : "草稿名称"}
                                                                                      value={draft.title} maxLength={80}
                                                                                      onChange={(e) => update({title: e.target.value})}/></Field>{draft.custom && <>
                    <Field label="避免的风格"><Input disabled={busy || switching} aria-label="避免的风格"
                                                     value={draft.negativeTags}
                                                     onChange={(e) => update({negativeTags: e.target.value})}/></Field><Field
                    label="期望时长（秒）"><Input disabled={busy || switching} aria-label="期望时长" type="number"
                                                min={10} max={360} value={draft.durationSec ?? ""}
                                                onChange={(e) => update({durationSec: e.target.value ? Number(e.target.value) : undefined})}/><small>留空自动决定；可填写
                    10–360 秒。</small></Field></>}</Disclosure>
            </> : <>
                <Field label="描述你想听到的音乐"><Textarea disabled={busy || switching} className="mw-main-input"
                                                            aria-label="音乐描述" rows={7} value={draft.soundPrompt}
                                                            onChange={(e) => update({soundPrompt: e.target.value})}
                                                            placeholder="写下风格、情绪、乐器，或让你产生灵感的场景…"/></Field>
                <Disclosure defaultOpen={Boolean(draft.lyrics)}><DisclosureTitle>歌词（可选）</DisclosureTitle><Textarea
                    disabled={busy || switching} aria-label="歌词" rows={7} value={draft.lyrics}
                    onChange={(e) => update({lyrics: e.target.value})} placeholder="写下你的歌词…"/></Disclosure>
                <Disclosure><DisclosureTitle>更多设置</DisclosureTitle><Field label="作品名称（可选）"><Input
                    disabled={busy || switching} aria-label="作品名称" value={draft.title}
                    onChange={(e) => update({title: e.target.value})}/></Field><Field label="期望时长（秒）"><Input
                    disabled={busy || switching} aria-label="期望时长" type="number" min={1} max={240}
                    value={draft.lengthSec ?? ""}
                    onChange={(e) => update({lengthSec: e.target.value ? Number(e.target.value) : undefined})}/></Field><Field
                    label="BPM"><Input disabled={busy || switching} aria-label="BPM" type="number" min={1}
                                       value={draft.bpm ?? ""}
                                       onChange={(e) => update({bpm: e.target.value || undefined})}/></Field><Field
                    label="随机种子"><Input disabled={busy || switching} aria-label="随机种子" value={draft.seed ?? ""}
                                            onChange={(e) => update({seed: e.target.value || undefined})}/></Field></Disclosure>
            </>}
            <DraftStatus status={status} error={saveError} onRetry={() => void retry()} onUseLatest={useLatest}/>
        </div>
        <div className="mw-generate"><ConnectionSelect value={connectorId} onChange={setConnectorId}/><Button
            className="w-full" disabled={!connectorId || busy || switching || status === "error"}
            onClick={() => void generate()}><Sparkles/>{busy ? "提交生成中…" : "生成音乐"}</Button><p>使用所选 APIMart
            账户计费</p>{error && <p role="alert" className="aw-error">{error}</p>}</div>
    </div>;
}

import {Disclosure, DisclosureTitle, SelectOption, WorkspaceSelect} from "@/components/audioMusic/controls";
