function columnPlaceholder(id: ShotColumnId): string {
    switch (id) {
        case "content":
            return "镜头内容";
        case "durationSec":
            return "秒";
        case "notes":
            return "备注";
        case "scene":
            return "未选择场景";
        case "characters":
            return "未选择角色";
        default:
            return SHOT_COLUMNS.find((column) => column.id === id)?.label ?? "";
    }
}

/** Shared shot-row height: min band + hard cap; text scrolls inside. */
