    deleteScene,
    deleteStyle,
} from "@/db/repo";
import {firstResultId} from "@/domain/slot";
import {
    type Character,
    CHARACTER_SLOTS,
    type Prop,
    PROP_SLOTS,
    type Scene,
    SCENE_SLOTS,
    STUDIO_LIBRARY_ID,
    STYLE_SLOTS,
