                size={23} strokeWidth={1.5} aria-hidden/><h3>媒体与资料</h3><p>图片、视频、音频和文档</p>
                <span>{materials?.filter(material => ["image", "video", "audio", "document"].includes(material.kind)).length ?? 0} 份素材<ArrowUpRight
