function coverOfProject(shots: Shot[], projectId: Id): Id | undefined {
    return shots
        .filter((shot) => shot.projectId === projectId)
        .sort((left, right) => left.order - right.order)
        .find((shot) => shot.firstFrame.result?.mediaId)?.firstFrame.result?.mediaId;
}

export function ProjectGalleryPage() {
    const navigate = useNavigate();
    const projects = useLiveQuery(() => db.projects.toArray(), []);
    const shots = useLiveQuery(() => db.shots.toArray(), []) ?? [];
    const profiles = useLiveQuery(() => db.ipProfiles.toArray(), []) ?? [];
    const ipLinks = useLiveQuery(() => db.projectIpLinks.toArray(), []) ?? [];
    const [ipFilter, setIpFilter] = useState("all");
    const [showArchived, setShowArchived] = useState(false);
    const [createIpId, setCreateIpId] = useState<string | null>(null);
    const [binding, setBinding] = useState<{ projectId: string; name: string; ipId: string | null }>();
    const [bindingBusy, setBindingBusy] = useState(false);
    const [bindingError, setBindingError] = useState("");
    const [query, setQuery] = useState("");
    const [sort, setSort] = useState<LibrarySort>("updated");
    const [kindFilter, setKindFilter] = useState<ProjectKindId | "all">("all");
    const [createKind, setCreateKind] = useState<ProjectKindId>("video");
    const [submitting, setSubmitting] = useState(false);
    const creatingRef = useRef(false);
    const selectedKind = PROJECT_KINDS.find((kind) => kind.id === createKind)!;
    const filteredKind = PROJECT_KINDS.find((kind) => kind.id === kindFilter);
    const [creating, setCreating] = useState(false);
    const [name, setName] = useState("未命名项目");
    const [mode, setMode] = useState<ProjectMode>("film");
    const [aspectPreset, setAspectPreset] = useState<AspectPresetId>("16:9");
    const [renameId, setRenameId] = useState<string>();
    const [renameValue, setRenameValue] = useState("");
    const [deleteId, setDeleteId] = useState<string>();

    const visible = useMemo(
        () => filterAndSortLibrary((projects ?? []).filter((project) => {
            const ipId = ipLinks.find((link) => link.projectId === project.id)?.ipId;
            return (kindFilter === "all" || (project.kind ?? "video") === kindFilter) && Boolean(project.archivedAt) === showArchived && (ipFilter === "all" || (ipFilter === "independent" ? !ipId : ipId === ipFilter));
        }), query, sort),
        [projects, query, sort, ipLinks, ipFilter, showArchived, kindFilter],
    );


    async function handleCreate() {
        if (!selectedKind.available || !name.trim() || creatingRef.current) return;
        creatingRef.current = true;
        setSubmitting(true);
        try {
            const project = createKind === "audio" || createKind === "music"
                ? await createAudioMusicProject(name.trim(), createKind, createIpId)
                : await createProject(name.trim(), mode, aspectPreset, createIpId);
            setCreating(false);
            setName("未命名项目");
            setMode("film");
            setAspectPreset("16:9");
            await navigate({to: "/p/$projectId", params: {projectId: project.id}});
        } catch (err) {
            toast.error(err instanceof Error ? err.message : "创建失败");
        } finally {
            creatingRef.current = false;
            setSubmitting(false);
        }
    }

    return (
        <div className="px-4 py-6 sm:px-10 sm:py-8">
            <LibraryHeader title="项目" query={query} onQuery={setQuery} sort={sort} onSort={setSort}
                           extra={<Button size="sm" onClick={() => {
                               setCreateKind(kindFilter === "all" ? "video" : kindFilter);
                               setCreating(true);
                           }}><Plus aria-hidden/>新建项目</Button>}
            />
            <p className="text-muted-foreground mt-3 text-sm leading-6">从一个想法出发，找到适合它的创作形式。</p>
            <div className="mt-6 flex flex-wrap gap-1 border-b pb-3" role="group" aria-label="按创作类型筛选">
                <button type="button" aria-pressed={kindFilter === "all"} onClick={() => setKindFilter("all")}
                        className={cn("rounded-lg px-3 py-2 text-sm transition-colors focus-visible:outline-2 focus-visible:outline-ring", kindFilter === "all" ? "bg-muted text-foreground" : "text-muted-foreground hover:bg-muted/50")}>全部
                </button>
                {PROJECT_KINDS.map((kind) => {
                    const Icon = kind.icon;
                    return <button key={kind.id} type="button" aria-pressed={kindFilter === kind.id}
                                   onClick={() => setKindFilter(kind.id)}
                                   className={cn("flex items-center gap-2 rounded-lg px-3 py-2 text-sm transition-colors focus-visible:outline-2 focus-visible:outline-ring", kindFilter === kind.id ? "bg-muted text-foreground" : "text-muted-foreground hover:bg-muted/50")}>
                        <Icon className="size-4" aria-hidden/>{kind.label}
                        {!kind.available && <span className="text-muted-foreground text-[10px]">即将推出</span>}
                    </button>;
                })}
            </div>
            <div className="mt-4 flex flex-wrap items-center gap-3 text-sm">
                <label className="flex items-center gap-2">所属 IP
                    <Select value={ipFilter} onValueChange={setIpFilter}><SelectTrigger aria-label="筛选所属 IP"
                                                                                        className="max-w-52"><SelectValue/></SelectTrigger><SelectContent><SelectItem
                        value="all">全部</SelectItem><SelectItem
                        value="independent">独立项目</SelectItem>{profiles.map((ip) => <SelectItem key={ip.id}
                                                                                                   value={ip.id}>{ip.name}{ip.archived ? "（已归档）" : ""}</SelectItem>)}
                    </SelectContent></Select>
                </label>
                <label className="flex items-center gap-2"><Checkbox checked={showArchived}
                                                                     onCheckedChange={(checked) => setShowArchived(checked === true)}/>查看已归档项目</label>
            </div>
            <div className="mt-6">
                {filteredKind && !filteredKind.available ? <ProjectKindPlaceholder kind={filteredKind}/> : <>
                    {projects === undefined &&
                        <p className="text-muted-foreground py-12 text-center text-sm" role="status">加载项目中…</p>}
                    {projects !== undefined && !visible.length &&
                        <div className="rounded-2xl border border-dashed px-6 py-16 text-center">
                            <h2 className="text-base font-medium">{query.trim() || ipFilter !== "all" || showArchived ? "没有找到匹配的项目" : "从第一部作品开始"}</h2>
                            <p className="text-muted-foreground mt-2 text-sm">{query.trim() ? "试试其他关键词，或清除搜索。" : "视频、音频与音乐创作已开放，选择类型开始制作。"}</p>
                            {query.trim() ? <Button className="mt-5" variant="outline"
                                                    onClick={() => setQuery("")}>清除搜索</Button> :
                                <Button className="mt-5" variant="outline" onClick={() => {
                                    setCreateKind(kindFilter === "all" ? "video" : kindFilter);
                                    setCreating(true);
                                }}>新建项目</Button>}
                        </div>}
                    <LibraryGrid>
                        {visible.map((project) => (
                            <CoverCard
                                key={project.id}
                                frame="poster"
                                title={project.name}
                                subtitle={`${PROJECT_KINDS.find((kind) => kind.id === (project.kind ?? "video"))?.label ?? "未知类型"} · ${profiles.find((ip) => ip.id === ipLinks.find((link) => link.projectId === project.id)?.ipId)?.name ?? "独立项目"} · ${project.archivedAt ? "已归档" : formatUpdatedAt(project.updatedAt)}`}
                                mediaId={project.coverMediaId ?? coverOfProject(shots, project.id)}
                                onOpen={() =>
                                    void navigate({to: "/p/$projectId", params: {projectId: project.id}})
                                }
                                actions={[
                                    {
                                        label: "项目素材",
                                        onSelect: () => void navigate({to: "/assets", search: {project: project.id}}),
                                    },
                                    {
                                        label: "所属 IP",
                                        onSelect: () => {
                                            setBindingError("");
                                            setBinding({
                                                projectId: project.id,
                                                name: project.name,
                                                ipId: ipLinks.find((link) => link.projectId === project.id)?.ipId ?? null
                                            });
                                        },
                                    },
                                    {
                                        label: project.archivedAt ? "恢复项目" : "归档项目",
                                        onSelect: () => {
                                            void setProjectArchived(project.id, !project.archivedAt).catch((error: unknown) => toast.error(error instanceof Error ? error.message : "操作失败"));
                                        },
                                    },
                                    {
                                        label: "重命名",
                                        onSelect: () => {
                                            setRenameId(project.id);
                                            setRenameValue(project.name);
                                        },
                                    },
                                    {
                                        label: "备份项目（zip）",
                                        onSelect: () => {
                                            void flushPendingDrafts(project.id)
                                                .then(() => exportProjectZip(project.id))
                                                .then((blob) => downloadBlob(blob, `${project.name}.zip`))
                                                .catch((error: unknown) => toast.error(
                                                    error instanceof Error ? `备份失败：${error.message}` : "备份失败，请重试",
                                                ));
                                        },
                                    },
                                    {
                                        label: "删除",
                                        tone: "danger",
                                        onSelect: () => setDeleteId(project.id),
                                    },
                                ]}
                            />
                        ))}
                    </LibraryGrid>
                </>}
            </div>

            <Dialog open={creating} onOpenChange={(open) => {
                if (!creatingRef.current) setCreating(open);
            }}>
                <DialogContent className="max-h-[85dvh] overflow-y-auto sm:max-w-xl">
                    <DialogHeader>
                        <DialogTitle>新建项目</DialogTitle>
                        <DialogDescription>选择视频、音频或音乐项目，也可以关联已有 IP。</DialogDescription>
                    </DialogHeader>
                    <fieldset disabled={submitting}>
                        <legend className="text-sm font-medium">创作类型</legend>
                        <div className="mt-2 grid grid-cols-3 gap-2 sm:grid-cols-5">
                            {PROJECT_KINDS.map((kind) => {
                                const Icon = kind.icon;
                                return <button type="button" key={kind.id} aria-pressed={createKind === kind.id}
                                               onClick={() => setCreateKind(kind.id)}
                                               className={cn("flex min-h-24 flex-col items-center justify-center gap-2 rounded-xl border px-2 py-3 text-sm focus-visible:outline-2 focus-visible:outline-ring", createKind === kind.id ? "border-brand bg-brand/5" : "text-muted-foreground hover:bg-muted/50")}>
                                    <Icon className="size-5" aria-hidden/><span>{kind.label}</span>
                                    <span className="text-[10px]">{kind.available ? "已开放" : "即将推出"}</span>
                                </button>;
                            })}
                        </div>
                    </fieldset>
                    {!selectedKind.available ? <ProjectKindPlaceholder kind={selectedKind}/> : <>
                        <label htmlFor="new-project-name" className="text-sm font-medium">项目名称</label>
                        <Input
                            id="new-project-name"
                            disabled={submitting}
                            value={name}
                            onChange={(event) => setName(event.target.value)}
                            placeholder="项目名称"
                        />
                        {createKind === "video" && <>
                            <fieldset disabled={submitting}>
                                <legend className="text-sm font-medium">视频形式</legend>
                                <div className="mt-2 grid grid-cols-2 gap-3">
                                    {(
                                        [
                                            {value: "film", title: "单片", hint: "直接进入故事，适合短片和电影"},
                                            {value: "series", title: "连载", hint: "按集管理故事、分镜和制作"},
                                        ] satisfies { value: ProjectMode; title: string; hint: string }[]
                                    ).map((option) => (
                                        <button
                                            key={option.value}
                                            type="button"
                                            aria-pressed={mode === option.value}
                                            className={cn(
                                                "rounded-xl border p-4 text-left transition-colors",
                                                mode === option.value
                                                    ? "border-brand bg-brand/5"
                                                    : "hover:bg-muted/50",
                                            )}
                                            onClick={() => setMode(option.value)}
                                        >
                                            <span className="block text-sm font-medium">{option.title}</span>
                                            <span className="text-muted-foreground mt-1 block text-xs leading-5">
                    {option.hint}
                  </span>
                                        </button>
                                    ))}
                                </div>
                            </fieldset>
                            <fieldset disabled={submitting}>
                                <legend className="text-sm font-medium">画幅比例</legend>
                                <div className="mt-2 grid grid-cols-3 gap-2">
                                    {ASPECT_PRESET_IDS.map((preset) => (
                                        <button
                                            key={preset}
                                            type="button"
                                            aria-pressed={aspectPreset === preset}
                                            className={cn(
                                                "rounded-xl border px-3 py-2.5 text-center text-sm font-medium transition-colors",
                                                aspectPreset === preset
                                                    ? "border-brand bg-brand/5"
                                                    : "hover:bg-muted/50",
                                            )}
                                            onClick={() => setAspectPreset(preset)}
                                        >
                                            {ASPECT_PRESETS[preset].label}
                                        </button>
                                    ))}
                                </div>
                                <p className="text-muted-foreground mt-2 text-xs">
                                    生成模型与分辨率可在创建后的项目设定中分别配置
                                </p>
                            </fieldset>
                        </>}
                        <div className="space-y-2"><span className="text-sm font-medium">所属 IP</span><ProjectIpPicker
                            value={createIpId} onChange={setCreateIpId} disabled={submitting}/></div>
                        <p className="text-muted-foreground text-xs leading-5">项目类型创建后固定。可选择所属
                            IP，也可以独立创作。</p>
                    </>}
                    <DialogFooter>
                        <Button disabled={submitting} variant="outline" onClick={() => setCreating(false)}>
                            {selectedKind.available ? "取消" : "关闭"}
                        </Button>
                        <Button disabled={!selectedKind.available || !name.trim() || submitting} variant="brand"
                                onClick={() => void handleCreate()}>
                            {submitting ? "创建中…" : selectedKind.available ? "创建项目" : "即将推出"}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            <Dialog open={Boolean(binding)} onOpenChange={(open) => {
                if (!open && !bindingBusy) setBinding(undefined);
            }}>
                <DialogContent><DialogHeader><DialogTitle>项目所属 IP</DialogTitle><DialogDescription>{binding?.name} ·
                    关联仅整理项目归属，不会改写已有内容。</DialogDescription></DialogHeader>
                    <ProjectIpPicker value={binding?.ipId ?? null}
                                     onChange={(ipId) => setBinding((value) => value ? {...value, ipId} : value)}
                                     disabled={bindingBusy}/>
                    {bindingError && <p role="alert" className="text-destructive text-sm">{bindingError}</p>}
                    <DialogFooter><Button variant="outline" disabled={bindingBusy}
                                          onClick={() => setBinding(undefined)}>取消</Button>
                        <Button disabled={bindingBusy} onClick={async () => {
                            if (!binding || bindingBusy) return;
                            setBindingBusy(true);
                            setBindingError("");
                            try {
                                await bindProjectIp(binding.projectId, binding.ipId);
                                setBinding(undefined);
                            } catch (error) {
                                setBindingError(error instanceof Error ? error.message : "保存失败");
                            } finally {
                                setBindingBusy(false);
                            }
                        }}>{bindingBusy ? "保存中…" : "保存"}</Button></DialogFooter>
                </DialogContent>
            </Dialog>

            <Dialog open={Boolean(renameId)} onOpenChange={(open) => !open && setRenameId(undefined)}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>重命名项目</DialogTitle>
                    </DialogHeader>
                    <Input
                        autoFocus
                        value={renameValue}
                        onChange={(event) => setRenameValue(event.target.value)}
                    />
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setRenameId(undefined)}>
                            取消
                        </Button>
                        <Button
                            onClick={() => {
                                if (renameId) void renameProject(renameId, renameValue);
                                setRenameId(undefined);
                            }}
                        >
                            保存
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            <AlertDialog open={Boolean(deleteId)} onOpenChange={(open) => !open && setDeleteId(undefined)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>删除项目</AlertDialogTitle>
                        <AlertDialogDescription>
                            删除后无法恢复（除非你已经备份过项目）。
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>取消</AlertDialogCancel>
                        <AlertDialogAction
                            className="bg-destructive hover:bg-destructive/90"
                            onClick={() => {
                                if (deleteId) void deleteProject(deleteId);
                                setDeleteId(undefined);
                            }}
                        >
                            删除
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

export async function importStudioProject(file: File) {
    try {
        return await importProjectZip(file);
    } catch (err) {
        toast.error(err instanceof PackageError ? err.message : "导入失败");
        return undefined;
    }
}

import {useState} from 'react';
import {useLiveQuery} from 'dexie-react-hooks';
import {toast} from 'sonner';
import {getSearchConnectionState, removeSearchConnection, saveSearchConnection} from '@/db/searchConnections';
import {testSearchConnection} from '@/lib/ai/tavily';
import {Button} from '@/components/ui/button';
import {Input} from '@/components/ui/input';
import {Field} from '@/components/ui/field';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle
} from '@/components/ui/dialog';

export function SearchConnection() {
    const state = useLiveQuery(getSearchConnectionState, []);
    const [open, setOpen] = useState(false);
    const [key, setKey] = useState('');
    const [enabled, setEnabled] = useState(true);
    const [busy, setBusy] = useState(false);
    const [feedback, setFeedback] = useState('');

    async function act(action: 'save' | 'remove' | 'test') {
        setBusy(true);
        setFeedback('');
        try {
            if (action === 'test') {
                const result = await testSearchConnection(key);
                setFeedback(result.message);
            } else {
                if (action === 'save') await saveSearchConnection({apiKey: key, enabled});
                else await removeSearchConnection();
                setKey('');
                setOpen(false);
                toast.success(action === 'save' ? '已保存搜索连接' : '已移除搜索连接');
            }
        } catch {
            setFeedback('操作失败，请重试；填写的内容已保留');
        } finally {
            setBusy(false);
        }
    }

    return <section className="mt-8 border-t pt-6" aria-label="联网搜索">
        <div className="flex flex-wrap items-start justify-between gap-4">
            <div className="min-w-0 flex-1"><h2 className="text-base font-medium">联网搜索</h2><p
                className="text-muted-foreground mt-2 text-sm leading-6">Tavily ·
                为智能模式提供网络搜索与网页读取。单独配置密钥，使用当前对话模型分析资料。</p><p
                className="text-muted-foreground mt-1 text-xs">{state?.configured ? state.enabled ? '已配置 · 已启用' : '已配置 · 已停用' : '未配置'}</p>
            </div>
            <Button variant="outline" size="sm" disabled={!state} onClick={() => {
                setKey('');
                setEnabled(state?.enabled ?? true);
                if (!state?.configured) setEnabled(true);
                setFeedback('');
                setOpen(true);
            }}>配置 Tavily</Button>
        </div>
        <Dialog open={open} onOpenChange={(value) => {
            if (!busy) {
                setOpen(value);
                if (!value) setKey('');
            }
        }}>
            <DialogContent>
                <DialogHeader><DialogTitle>Tavily 联网搜索</DialogTitle><DialogDescription>密钥仅保存在本机，不进入项目备份或
                    AI 上下文。保存不发送请求；测试仅查询鉴权，不执行搜索。</DialogDescription></DialogHeader>
                <Field label="Tavily API Key"><Input type="password" value={key} disabled={busy}
                                                     onChange={(event) => setKey(event.target.value)}
                                                     placeholder={state?.configured ? '已保存密钥（留空则保持）' : 'tvly-…'}
                                                     autoComplete="off"/></Field>
                <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={enabled}
                                                                          disabled={busy}
                                                                          onChange={(event) => setEnabled(event.target.checked)}/>启用联网搜索</label>
                <p className="text-muted-foreground text-xs leading-5">启用后会为后续智能对话开启「联网调研」技能；你仍可在对话的技能菜单中关闭。搜索和读取网页可能消耗服务额度。</p>
                {feedback && <p role="status" className="text-sm leading-6">{feedback}</p>}
                <DialogFooter className="flex-wrap gap-2 sm:justify-between">
                    {state?.configured && <Button variant="ghost" disabled={busy}
                                                  onClick={() => void act('remove')}>移除搜索连接</Button>}
                    <div className="flex flex-wrap gap-2"><Button variant="outline" disabled={busy}
                                                                  onClick={() => void act('test')}>测试搜索连接</Button><Button
                        disabled={busy || !key.trim() && !state?.configured}
                        onClick={() => void act('save')}>保存搜索连接</Button></div>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    </section>;
}

import {useRef, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {Link} from "@tanstack/react-router";
import {ArrowUpRight, Layers} from "lucide-react";
import {db} from "@/db/database";
import {promoteLegacyMaterial} from "@/db/materials";
import {type MediaRecord, STUDIO_LIBRARY_ID} from "@/domain/types";
import {slotMediaIds} from "@/domain/slot";
import type {MaterialEntity, MaterialKind, MaterialPayload, SettingMaterialKind} from "@/domain/materials";
import {Button} from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle
} from "@/components/ui/dialog";
import {MaterialPreview} from "./MaterialPreview";
import {KIND_LABELS, MaterialScopeSelect, parseScope, useMaterialDraftGuard} from "./MaterialControls";

type LegacyRow = { id: string; kind: MaterialKind | "media"; name: string; ownerId: string; payload: MaterialPayload };

function mediaKind(media: MediaRecord): MaterialKind {
    return media.mimeType.startsWith("image/") ? "image" : media.mimeType.startsWith("video/") ? "video" : media.mimeType.startsWith("audio/") ? "audio" : "document";
}

export function LegacyMaterialSources({view, scope, search, kind, onCreated}: {
    view: "media" | "settings";
    scope: string;
    search: string;
    kind: string;
    onCreated: (id: string) => void
}) {
    const [selected, setSelected] = useState<LegacyRow | null>(null);
    const [target, setTarget] = useState(scope.startsWith("ip:") ? scope : "global");
    const [pending, setPending] = useState(false);
    const pendingRef = useRef(false);
    const [error, setError] = useState("");
    const {requestClose, dialog} = useMaterialDraftGuard(false, pending);
    const data = useLiveQuery(async () => {
        if (scope.startsWith("ip:")) return {rows: [] as LegacyRow[], projects: [], media: [] as MediaRecord[]};
        const ownerId = scope.startsWith("project:") ? scope.slice(8) : STUDIO_LIBRARY_ID;
        const [media, characters, scenes, props, styles, projects] = await Promise.all([
            scope === "all" ? db.media.toArray() : db.media.where("projectId").equals(ownerId).toArray(),
            view === "media" ? [] : scope === "all" ? db.characters.toArray() : db.characters.where("projectId").equals(ownerId).toArray(),
            view === "media" ? [] : scope === "all" ? db.scenes.toArray() : db.scenes.where("projectId").equals(ownerId).toArray(),
            view === "media" ? [] : scope === "all" ? db.props.toArray() : db.props.where("projectId").equals(ownerId).toArray(),
            view === "media" ? [] : scope === "all" ? db.styles.toArray() : db.styles.where("projectId").equals(ownerId).toArray(),
            db.projects.toArray(),
        ]);
        const rows: LegacyRow[] = view === "media" ? media.map((item) => ({
            id: item.id,
            kind: "media",
            name: item.filename || "未命名文件",
            ownerId: item.projectId,
            payload: {type: "file", blob: item.blob, filename: item.filename, mimeType: item.mimeType}
        })) : [
            ["character", characters], ["scene", scenes], ["prop", props], ["style", styles],
        ].flatMap(([entityKind, entities]) => (entities as MaterialEntity[]).map((entity) => ({
            id: entity.id,
            name: entity.name || "未命名设定",
            kind: entityKind as SettingMaterialKind,
            ownerId: entity.projectId,
            payload: {
                type: "setting" as const,
                kind: entityKind as SettingMaterialKind,
                entity,
                media: media.filter((item) => item.projectId === entity.projectId && Object.values(entity.slots).flatMap((slot) => slot ? slotMediaIds(slot) : []).includes(item.id))
            }
        })));
        return {rows, projects, media};
    }, [view, scope]);
    if (scope.startsWith("ip:")) return null;
    const rows = data?.rows.filter((row) => (scope === "all" || (scope.startsWith("project:") ? row.ownerId === scope.slice(8) : row.ownerId === STUDIO_LIBRARY_ID)) && (!search.trim() || row.name.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase())) && (kind === "all" || (row.kind === "media" ? mediaKind(data.media.find((item) => item.id === row.id)!) : row.kind) === kind));

    async function promote() {
        if (!selected || pendingRef.current) return;
        pendingRef.current = true;
        setPending(true);
        setError("");
        try {
            const material = await promoteLegacyMaterial(selected.kind, selected.id, parseScope(target));
            setSelected(null);
            onCreated(material.id);
        } catch (cause) {
            setError(cause instanceof Error ? cause.message : "无法提升素材，请重试");
        } finally {
            pendingRef.current = false;
            setPending(false);
        }
    }

    return <section className="material-legacy" aria-label="现有项目与工作室素材">
        <header>
            <div><h2><Layers size={16} aria-hidden/>现有素材</h2>
                <p>保留原来的编辑方式。提升为独立版本后，可在新的项目中复用。</p></div>
            <span>{rows?.length ?? "…"} 项</span></header>
        {!rows ? <p role="status">读取现有素材…</p> : rows.length === 0 ?
            <p className="material-muted">当前筛选下没有现有素材。</p> :
            <div className="material-grid">{rows.map((row) => <Button variant="ghost" className="material-card"
                                                                      key={`${row.kind}-${row.id}`} onClick={() => {
                setSelected(row);
                setError("");
                setTarget("global");
            }}><MaterialPreview payload={row.payload}/>
                <div className="material-card-caption">
                    <strong>{row.name}</strong><span>{row.ownerId === STUDIO_LIBRARY_ID ? "工作室原件" : data?.projects.find((project) => project.id === row.ownerId)?.name ?? "原项目已删除"}</span>
                </div>
            </Button>)}</div>}
        {selected && <Dialog open onOpenChange={(open) => {
            if (!open) requestClose(() => setSelected(null));
        }}><DialogContent
            className="material-dialog"><DialogHeader><DialogTitle>{selected.name}</DialogTitle><DialogDescription>从原件建立独立素材快照。以后编辑或删除原件，不会改变已保存的版本。</DialogDescription></DialogHeader><MaterialPreview
            payload={selected.payload} inspect/>
            {selected.kind !== "media" && <LegacySettingLink row={selected}/>}
            <label className="material-field">提升到<MaterialScopeSelect value={target} onChange={setTarget}
                                                                         disabled={pending}/></label>
            {error && <p role="alert" className="material-error">{error}</p>}
            <DialogFooter><Button variant="outline" disabled={pending}
                                  onClick={() => setSelected(null)}>关闭</Button><Button disabled={pending}
                                                                                         onClick={() => void promote()}>{pending ? "正在保存…" : "保存为独立素材"}</Button></DialogFooter>
        </DialogContent></Dialog>}{dialog}
    </section>;
}

export function LegacySettingLink({row}: { row: Pick<LegacyRow, "kind" | "id" | "ownerId"> }) {
    const collection = row.kind === "character" ? "characters" : row.kind === "scene" ? "scenes" : row.kind === "prop" ? "props" : "styles";
    const href = row.ownerId === STUDIO_LIBRARY_ID ? `/${collection}/${encodeURIComponent(row.id)}` : `/p/${encodeURIComponent(row.ownerId)}/assets/${collection}/${encodeURIComponent(row.id)}`;
    return <Link to={href}
                 className="material-source-link">编辑原{row.kind === "media" ? "素材" : KIND_LABELS[row.kind]}<ArrowUpRight
        size={14} aria-hidden/></Link>;
}

import {useRef, useState} from "react";
import {Link} from "@tanstack/react-router";
import {useLiveQuery} from "dexie-react-hooks";
import {Archive, ArrowUpRight, History, Trash2, Upload, X} from "lucide-react";
import {db} from "@/db/database";
import {releaseMaterialUse} from "@/db/repo";
import {
    addFileMaterialVersion,
    deleteMaterial,
    promoteMaterial,
    refreshSettingMaterial,
    setMaterialArchived,
    updateMaterialMetadata,
    updateMaterialUse,
    useMaterialInProject
} from "@/db/materials";
import type {LibraryMaterial} from "@/domain/materials";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {Textarea} from "@/components/ui/textarea";
import {Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle} from "@/components/ui/sheet";
import {
    AlertDialog,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle
} from "@/components/ui/alert-dialog";
import {MaterialPreview} from "./MaterialPreview";
import {
    KIND_LABELS,
    MaterialScopeSelect,
    MaterialSelect,
    parseScope,
    scopeValue,
    useMaterialDraftGuard
} from "./MaterialControls";
import {MATERIAL_ACCEPT} from "./MaterialImportDialog";
import {LegacySettingLink} from "./LegacyMaterialSources";

export function MaterialDetailPanel({id, onClose, onSelect}: {
    id: string;
    onClose: () => void;
    onSelect: (id: string) => void
}) {
    const material = useLiveQuery(async () => await db.libraryMaterials.get(id) ?? null, [id]);
    return material ? <MaterialEditor key={id} material={material} onClose={onClose} onSelect={onSelect}/> :
        <Sheet open onOpenChange={(open) => {
            if (!open) onClose();
        }}><SheetContent
            className="material-detail"><SheetHeader><SheetTitle>素材详情</SheetTitle><SheetDescription>{material === null ? "素材不存在或已删除" : "正在读取素材…"}</SheetDescription></SheetHeader></SheetContent></Sheet>;
}

function MaterialEditor({material, onClose, onSelect}: {
    material: LibraryMaterial;
    onClose: () => void;
    onSelect: (id: string) => void
}) {
    const [draft, setDraft] = useState<{ revision: number; name: string; notes: string; tags: string } | null>(null);
    const [pending, setPending] = useState(false);
    const pendingRef = useRef(false);
    const [error, setError] = useState("");
    const [notice, setNotice] = useState("");
    const [selectedRevision, setSelectedRevision] = useState<number | null>(null);
    const [projectId, setProjectId] = useState(material.scope.kind === "project" ? material.scope.id : "");
    const [targetScope, setTargetScope] = useState("global");
    const [promoting, setPromoting] = useState(false);
    const [deleting, setDeleting] = useState(false);
    const [releasing, setReleasing] = useState<string | null>(null);
    const fileInput = useRef<HTMLInputElement>(null);
    const guard = useMaterialDraftGuard(Boolean(draft), pending);
    const data = useLiveQuery(async () => ({
        versions: (await db.materialVersions.where("materialId").equals(material.id).toArray()).sort((a, b) => b.revision - a.revision),
        uses: await db.materialUses.where("materialId").equals(material.id).toArray(),
        events: (await db.materialEvents.where("materialId").equals(material.id).toArray()).sort((a, b) => b.createdAt.localeCompare(a.createdAt)),
        projects: await db.projects.toArray(),
        ips: await db.ipProfiles.toArray(),
        links: await db.projectIpLinks.toArray(),
        derived: (await db.libraryMaterials.toArray()).filter((item) => item.source?.materialId === material.id),
    }), [material.id]);
    const version = data?.versions.find((item) => item.revision === (selectedRevision ?? material.revision));
    const values = draft ?? {
        revision: material.revision,
        name: material.name,
        notes: material.notes,
        tags: material.tags.join("，")
    };
    const materialScope = material.scope;
    const targetProjects = data?.projects.filter((project) => !project.archivedAt && (materialScope.kind === "global" || materialScope.kind === "project" && materialScope.id === project.id || materialScope.kind === "ip" && data.links.some((link) => link.projectId === project.id && link.ipId === materialScope.id)));

    function edit(patch: Partial<typeof values>) {
        setDraft({...values, ...patch});
        setError("");
    }

    async function action(work: () => Promise<unknown>, message: string) {
        if (pendingRef.current) return;
        pendingRef.current = true;
        setPending(true);
        setError("");
        setNotice("");
        try {
            await work();
            setNotice(message);
        } catch (cause) {
            setError(cause instanceof Error ? cause.message : "操作失败，请重试");
        } finally {
            pendingRef.current = false;
            setPending(false);
        }
    }

    const operationsDisabled = pending || Boolean(draft);
    const scopeLabel = materialScope.kind === "global" ? "全局素材" : materialScope.kind === "ip" ? `IP · ${data?.ips.find((ip) => ip.id === materialScope.id)?.name ?? "已不可用"}` : `项目 · ${data?.projects.find((project) => project.id === materialScope.id)?.name ?? "已删除"}`;
    const hasReferences = Boolean(data?.uses.length || data?.derived.length);
    return <><Sheet open onOpenChange={(open) => {
        if (!open) guard.requestClose(onClose);
    }}><SheetContent className="material-detail" showCloseButton={false}>
        <SheetHeader className="material-detail-heading">
            <div><p className="material-eyebrow">{KIND_LABELS[material.kind]} · {scopeLabel}</p>
                <SheetTitle>{material.name}</SheetTitle><SheetDescription>版本 {material.revision}{material.archived ? " · 已归档" : " · 可复用"}</SheetDescription>
            </div>
            <Button size="icon" variant="ghost" aria-label="关闭素材详情" disabled={pending}
                    onClick={() => guard.requestClose(onClose)}><X/></Button></SheetHeader>
        <div className="material-detail-body">
            <MaterialPreview payload={version?.payload} inspect/>
            {data && data.versions.length > 1 &&
                <label className="material-field">查看历史版本<MaterialSelect label="查看历史版本"
                                                                              value={String(selectedRevision ?? material.revision)}
                                                                              onChange={(value) => setSelectedRevision(Number(value))}
                                                                              options={data.versions.map((item) => ({
                                                                                  value: String(item.revision),
                                                                                  label: `版本 ${item.revision} · ${new Date(item.createdAt).toLocaleDateString("zh-CN")}`
                                                                              }))}/></label>}
            {selectedRevision !== null && selectedRevision !== material.revision &&
                <p className="material-muted">当前预览历史版本；“用于项目”始终采用最新版本 {material.revision}。</p>}
            <section className="material-detail-section"><h3>素材信息</h3>
                <label className="material-field">名称<Input value={values.name} disabled={pending || material.archived}
                                                             onChange={(event) => edit({name: event.target.value})}/></label>
                <label className="material-field">备注<Textarea value={values.notes}
                                                                disabled={pending || material.archived} rows={3}
                                                                onChange={(event) => edit({notes: event.target.value})}
                                                                placeholder="用途、注意事项或创作背景"/></label>
                <label className="material-field">标签<Input value={values.tags} disabled={pending || material.archived}
                                                             onChange={(event) => edit({tags: event.target.value})}
                                                             placeholder="用逗号分隔"/></label>
                {draft && <div className="material-inline-actions"><Button disabled={pending || !values.name.trim()}
                                                                           onClick={() => void action(async () => {
                                                                               await updateMaterialMetadata(material.id, {
                                                                                   name: values.name,
                                                                                   notes: values.notes,
                                                                                   tags: values.tags.split(/[,，]/).map((tag) => tag.trim()).filter(Boolean)
                                                                               }, values.revision);
                                                                               setDraft(null);
                                                                           }, "素材信息已保存，生成新的版本。")}>保存修改</Button><Button
                    variant="ghost" disabled={pending} onClick={() => setDraft(null)}>撤销修改</Button></div>}
            </section>
            <section className="material-detail-section"><h3>来源与版本</h3><p
                className="material-muted">{material.source ? `来自${material.source.materialId ? "另一份素材" : material.source.projectId === "studio" ? "工作室原件" : "项目原件"}，此处保存独立快照。` : "直接导入，原文件保存在素材版本中。"}</p>
                {version?.payload.type === "setting" && material.source?.entityId && material.source.projectId &&
                    <LegacySettingLink row={{
                        id: material.source.entityId,
                        ownerId: material.source.projectId,
                        kind: version.payload.kind
                    }}/>}
                {version?.payload.type === "setting" &&
                    <p className="material-muted">在原设定编辑页修改，返回后保存新快照；已有项目仍固定使用原版本。</p>}
                <div className="material-inline-actions"><Button variant="outline"
                                                                 disabled={operationsDisabled || material.archived}
                                                                 onClick={() => {
                                                                     if (version?.payload.type === "setting") void action(() => refreshSettingMaterial(material.id, material.revision), "已从原设定保存新版本。"); else fileInput.current?.click();
                                                                 }}><Upload
                    size={14}/>{version?.payload.type === "setting" ? "从原设定保存新版本" : "上传新版本"}
                </Button><Button variant="outline" disabled={operationsDisabled || material.archived}
                                 onClick={() => setPromoting(!promoting)}>复制到其他位置</Button></div>
                <input ref={fileInput} hidden type="file" accept={MATERIAL_ACCEPT} onChange={(event) => {
                    const file = event.target.files?.[0];
                    event.target.value = "";
                    if (file) void action(() => addFileMaterialVersion(material.id, file, material.revision), "新版本已保存，项目内容没有自动改变。");
                }}/>
                {promoting && <div className="material-action-block"><MaterialScopeSelect value={targetScope}
                                                                                          onChange={setTargetScope}
                                                                                          disabled={operationsDisabled}/><Button
                    disabled={operationsDisabled || scopeValue(material.scope) === targetScope}
                    onClick={() => void action(async () => {
                        const copy = await promoteMaterial(material.id, parseScope(targetScope));
                        setPromoting(false);
                        onSelect(copy.id);
                    }, "独立副本已保存。")}>保存独立副本</Button></div>}
            </section>
            <section className="material-detail-section"><h3>用于项目</h3><p
                className="material-muted">创建项目专属副本并固定版本，后续更新需手动确认。媒体会进入项目素材，不会自动替换镜头。</p>
                <div className="material-action-block"><MaterialSelect label="使用素材的目标项目" placeholder="选择项目"
                                                                       value={projectId}
                                                                       disabled={operationsDisabled || material.archived}
                                                                       onChange={setProjectId}
                                                                       options={(targetProjects ?? []).map((project) => ({
                                                                           value: project.id,
                                                                           label: project.name
                                                                       }))}/><Button
                    disabled={operationsDisabled || material.archived || !targetProjects?.some((project) => project.id === projectId)}
                    onClick={() => void action(() => useMaterialInProject(material.id, projectId), "已加入项目，版本固定。")}>用于项目</Button>
                </div>
                {data?.uses.length === 0 && <p className="material-muted">尚未用于项目。</p>}
                <ul className="material-use-list">{data?.uses.map((use) => <li key={use.id}>
                    <div><Link to="/p/$projectId"
                               params={{projectId: use.projectId}}>{data.projects.find((project) => project.id === use.projectId)?.name ?? "项目已删除"}<ArrowUpRight
                        size={12}/></Link><span>版本 {use.revision}{use.supersededBy ? " · 历史引用" : " · 当前采用"}</span>{use.targetKind !== "media" &&
                        <LegacySettingLink row={{kind: use.targetKind, id: use.targetId, ownerId: use.projectId}}/>}
                    </div>
                    <div className="material-inline-actions">{!use.supersededBy && use.revision < material.revision &&
                        <Button variant="outline" size="sm" disabled={operationsDisabled || material.archived}
                                onClick={() => void action(() => updateMaterialUse(use.id), "新版项目副本已加入，已有编辑内容和素材引用没有替换。")}>加入新版副本
                            v{material.revision}</Button>}<Button variant="ghost" size="sm"
                                                                  disabled={operationsDisabled} onClick={() => {
                        setError("");
                        setReleasing(use.id);
                    }}>{use.targetKind === "media" ? "移除未使用副本" : "解除引用"}</Button></div>
                </li>)}</ul>
            </section>
            <section className="material-detail-section"><h3><History size={14} aria-hidden/>操作记录</h3>
                <ul className="material-event-list">{data?.events.slice(0, 30).map((event) => <li key={event.id}>
                    <span>{({
                        create: "导入素材",
                        promote: "建立独立快照",
                        version: "保存新版本",
                        archive: "归档素材",
                        restore: "恢复素材",
                        use: "加入项目",
                        "update-use": "加入新版项目副本",
                        release: "移除未使用副本"
                    } as Record<string, string>)[event.action] ?? "素材变更"}{event.detail ? ` · ${event.detail}` : ""}</span>
                    <time>{new Date(event.createdAt).toLocaleString("zh-CN")}</time>
                </li>)}</ul>
            </section>
            {error && <p role="alert" className="material-error">{error}</p>}{notice &&
            <p role="status" className="material-notice">{notice}</p>}{pending && <p role="status">正在保存…</p>}
            <div className="material-inline-actions material-danger-zone"><Button variant="outline"
                                                                                  disabled={operationsDisabled}
                                                                                  onClick={() => void action(() => setMaterialArchived(material.id, !material.archived), material.archived ? "已恢复素材。" : "已归档，已有项目引用继续保留。")}><Archive
                size={14}/>{material.archived ? "恢复素材" : "归档"}</Button><Button variant="ghost"
                                                                                     disabled={operationsDisabled || !data || hasReferences || !material.archived}
                                                                                     onClick={() => setDeleting(true)}><Trash2
                size={14}/>永久删除</Button></div>
            {!material.archived && !hasReferences && <p className="material-muted">需要永久删除时，请先归档素材。</p>}
            {hasReferences &&
                <p className="material-muted">当前有 {data?.uses.length} 条项目引用、{data?.derived.length} 份衍生素材，不能永久删除；可归档。</p>}
        </div>
    </SheetContent></Sheet>{guard.dialog}<AlertDialog open={deleting} onOpenChange={(open) => {
        if (!pending) setDeleting(open);
    }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>永久删除“{material.name}”？</AlertDialogTitle><AlertDialogDescription>删除所有版本和文件，操作不可撤销。保存前会再次检查引用。</AlertDialogDescription></AlertDialogHeader>{error &&
        <p role="alert" className="material-error">{error}</p>}<AlertDialogFooter><Button variant="outline"
                                                                                          disabled={pending}
                                                                                          onClick={() => setDeleting(false)}>取消</Button><Button
        variant="destructive" disabled={pending} onClick={() => void action(async () => {
        await deleteMaterial(material.id);
        setDeleting(false);
        onClose();
    }, "")}>永久删除</Button></AlertDialogFooter></AlertDialogContent></AlertDialog>
        <AlertDialog open={Boolean(releasing)} onOpenChange={(open) => {
            if (!pending && !open) setReleasing(null);
        }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>移除这条项目引用？</AlertDialogTitle><AlertDialogDescription>删除该项目未被镜头、封面或任务历史使用的文件及使用记录，保留素材库原件。创作设定请先在项目编辑页删除，再解除引用。</AlertDialogDescription></AlertDialogHeader>{error &&
            <p role="alert" className="material-error">{error}</p>}<AlertDialogFooter><Button variant="outline"
                                                                                              disabled={pending}
                                                                                              onClick={() => setReleasing(null)}>取消</Button><Button
            variant="destructive" disabled={pending || !releasing} onClick={() => void action(async () => {
            await releaseMaterialUse(releasing!);
            setReleasing(null);
        }, "项目引用已移除，素材库版本继续保留。")}>确认移除</Button></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

import {useEffect, useRef, useState} from "react";
import {Button} from "@/components/ui/button";
import {type ParsedReference, REFERENCE_LIMITS} from "@/domain/references";
import {assertReferenceSignature} from "@/lib/references/parse";

/** Reuse the bounded document parsers; display plain text, never document HTML. */
export function MaterialDocumentPreview({blob, mime}: { blob: Blob; mime: string }) {
    const [text, setText] = useState("");
    const [error, setError] = useState("");
    const [pending, setPending] = useState(false);
    const active = useRef<AbortController | null>(null);
    useEffect(() => () => {
        active.current?.abort();
    }, []);

    async function read() {
        if (active.current) return;
        const controller = new AbortController();
        active.current = controller;
        setPending(true);
        setError("");
        try {
            if (blob.size > REFERENCE_LIMITS.documentBytes) throw new Error(`文件超过 ${REFERENCE_LIMITS.documentBytes / 1024 / 1024} MB，请下载后查看。`);
            const buffer = await blob.arrayBuffer();
            controller.signal.throwIfAborted();
            const kind = mime === "application/pdf" ? "pdf" : "docx";
            assertReferenceSignature(new Uint8Array(buffer), kind, mime);
            const parsed = kind === "pdf" ? await (await import("@/lib/references/pdf")).parsePdfReference(buffer, controller.signal) : await readDocx(buffer, controller.signal);
            if (!controller.signal.aborted) setText(parsed.chunks.map((chunk) => chunk.text).join("\n").slice(0, 16000) || "没有可提取的文字，请下载原文件查看。");
        } catch (cause) {
            if (!controller.signal.aborted) setError(cause instanceof Error ? cause.message : "无法预览，请下载原文件查看。");
        } finally {
            if (!controller.signal.aborted) {
                setPending(false);
                active.current = null;
            }
        }
    }

    return <div className="material-document-text">{text ? <><p>文字摘录（最多 16000 字，排版以原文件为准）</p>
        <pre>{text}</pre>
    </> : <Button variant="outline" size="sm" disabled={pending}
                  onClick={() => void read()}>{pending ? "提取文字中…" : "预览文档文字"}</Button>}{error &&
        <p role="alert" className="material-error">{error}</p>}</div>;
}

function readDocx(buffer: ArrayBuffer, signal: AbortSignal): Promise<ParsedReference> {
    const worker = new Worker(new URL("../../../lib/references/docx.worker.ts", import.meta.url), {type: "module"});
    return new Promise((resolve, reject) => {
        const finish = (error?: unknown, result?: ParsedReference) => {
            clearTimeout(timer);
            signal.removeEventListener("abort", abort);
            worker.terminate();
            if (error) reject(error); else resolve(result!);
        };
        const abort = () => finish(new Error("预览已取消"));
        const timer = setTimeout(() => finish(new Error("文档提取超时，请下载原文件查看。")), REFERENCE_LIMITS.workerTimeoutMs);
        worker.onmessage = (event: MessageEvent<{
            result?: ParsedReference;
            error?: string
        }>) => finish(event.data.error ? new Error(event.data.error) : undefined, event.data.result);
        worker.onerror = () => finish(new Error("无法读取文档，请下载原文件查看。"));
        signal.addEventListener("abort", abort, {once: true});
        if (signal.aborted) abort(); else worker.postMessage(buffer, [buffer]);
    });
}

import {useEffect, useState} from "react";
import {FileText, Music2, PackageOpen} from "lucide-react";
import type {MaterialPayload} from "@/domain/materials";
import {MaterialDocumentPreview} from "./MaterialDocumentPreview";

export function MaterialPreview({payload, inspect = false}: { payload?: MaterialPayload; inspect?: boolean }) {
    const file = payload?.type === "file" ? payload : payload?.media.find((item) => item.mimeType.startsWith("image/"));
    const blob = file?.blob;
    const mime = file?.mimeType ?? "";
    const [url, setUrl] = useState<string>();
    const [text, setText] = useState("");
    useEffect(() => {
        if (!blob) {
            setUrl(undefined);
            return;
        }
        const next = URL.createObjectURL(blob);
        setUrl(next);
        return () => URL.revokeObjectURL(next);
    }, [blob]);
    useEffect(() => {
        let active = true;
        setText("");
        if (inspect && (mime === "text/plain" || mime === "text/markdown") && blob) void blob.slice(0, 16000).text().then((value) => {
            if (active) setText(value);
        }).catch(() => {
            if (active) setText("预览读取失败，可下载原文件查看。");
        });
        return () => {
            active = false;
        };
    }, [blob, mime, inspect]);
    if (!payload) return <div className="material-preview"><PackageOpen aria-hidden/><span>读取预览…</span></div>;
    return <>
        <div className={`material-preview ${inspect ? "material-preview-inspect" : ""}`}>
            {url && /^image\/(png|jpeg|webp|gif|avif|bmp)$/.test(mime) ?
                <img src={url} alt={inspect ? "素材预览" : ""} loading="lazy"/>
                : url && mime.startsWith("video/") ?
                    <video src={url} controls={inspect} muted={!inspect} playsInline preload="metadata"
                           aria-label="视频素材预览"/>
                    : mime.startsWith("audio/") ? <><Music2 aria-hidden/>{inspect && url ?
                            <audio src={url} controls preload="metadata" aria-label="音频素材预览"/> : <span>音频</span>}</>
                        : payload.type === "setting" ? <><PackageOpen
                                aria-hidden/><span>{payload.entity.name || "创作设定"}</span></>
                            : inspect && text ?
                                <pre>{text}{blob && blob.size > 16000 ? "\n…仅预览前 16000 字节" : ""}</pre>
                                : <><FileText aria-hidden/><span>{payload.filename}</span>{inspect &&
                                    <p>文档以文件形式保存，可提取文字预览或下载查看完整内容。</p>}{inspect && blob && ["application/pdf", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"].includes(mime) &&
                                    <MaterialDocumentPreview key={url} blob={blob} mime={mime}/>}</>}
            {inspect && payload.type === "file" && url &&
                <a href={url} download={payload.filename} className="material-download">下载原文件</a>}
        </div>
        {inspect && payload.type === "setting" &&
            <dl className="material-setting-preview">{Object.entries(payload.entity).filter(([key, value]) => ["name", "bio", "appearance", "personality", "motivation", "voice", "location", "timeOfDay", "atmosphere", "geography", "lighting", "notes", "kind", "material", "size", "usage", "continuity", "palette", "lens", "composition", "negativePrompt"].includes(key) && typeof value === "string" && value.trim()).map(([key, value]) =>
                <div key={key}>
                    <dt>{({
                        name: "名称",
                        bio: "简介",
                        appearance: "外观",
                        personality: "性格",
                        motivation: "动机",
                        voice: "声音",
                        location: "地点",
                        timeOfDay: "时间",
                        atmosphere: "氛围",
                        geography: "空间",
                        lighting: "光线",
                        notes: "备注",
                        kind: "类型",
                        material: "材质",
                        size: "尺寸",
                        usage: "用途",
                        continuity: "连续性",
                        palette: "色彩",
                        lens: "镜头气质",
                        composition: "构图",
                        negativePrompt: "避免出现"
                    } as Record<string, string>)[key]}</dt>
                    <dd>{String(value)}</dd>
                </div>)}</dl>}</>;
}

import {type MouseEvent, type ReactNode, useCallback, useEffect, useRef} from "react";
import {cn} from "@/lib/utils";

type SparkEasing = "linear" | "ease-in" | "ease-in-out" | "ease-out";

type Spark = {
    x: number;
    y: number;
    angle: number;
    startTime: number;
};

function prefersReducedMotion() {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/**
 * Click sparks from React Bits. Canvas is aria-hidden and pointer-events none;
 * clicks bubble from children. No-ops when the user prefers reduced motion.
 */
export function ClickSpark({
                               sparkColor = "#fff",
                               sparkSize = 10,
                               sparkRadius = 15,
                               sparkCount = 8,
                               duration = 400,
                               easing = "ease-out",
                               extraScale = 1,
                               className,
                               children,
                           }: {
    sparkColor?: string;
    sparkSize?: number;
    sparkRadius?: number;
    sparkCount?: number;
    duration?: number;
    easing?: SparkEasing;
    extraScale?: number;
    className?: string;
    children?: ReactNode;
}) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const sparksRef = useRef<Spark[]>([]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const parent = canvas.parentElement;
        if (!parent) return;

        let resizeTimeout = 0;
        const resizeCanvas = () => {
            const {width, height} = parent.getBoundingClientRect();
            if (canvas.width !== width || canvas.height !== height) {
                canvas.width = width;
                canvas.height = height;
            }
        };
        const handleResize = () => {
            window.clearTimeout(resizeTimeout);
            resizeTimeout = window.setTimeout(resizeCanvas, 100);
        };
        const observer = new ResizeObserver(handleResize);
        observer.observe(parent);
        resizeCanvas();
        return () => {
            observer.disconnect();
            window.clearTimeout(resizeTimeout);
        };
    }, []);

    const easeFunc = useCallback(
        (t: number) => {
            switch (easing) {
                case "linear":
                    return t;
                case "ease-in":
                    return t * t;
                case "ease-in-out":
                    return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
                default:
                    return t * (2 - t);
            }
        },
        [easing],
    );

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;

        let animationId = 0;
        const draw = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            sparksRef.current = sparksRef.current.filter((spark) => {
                const elapsed = performance.now() - spark.startTime;
                if (elapsed >= duration) return false;

                const eased = easeFunc(elapsed / duration);
                const distance = eased * sparkRadius * extraScale;
                const lineLength = sparkSize * (1 - eased);
                const x1 = spark.x + distance * Math.cos(spark.angle);
                const y1 = spark.y + distance * Math.sin(spark.angle);
                const x2 = spark.x + (distance + lineLength) * Math.cos(spark.angle);
                const y2 = spark.y + (distance + lineLength) * Math.sin(spark.angle);

                ctx.strokeStyle = sparkColor;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.stroke();
                return true;
            });

            animationId = window.requestAnimationFrame(draw);
        };

        animationId = window.requestAnimationFrame(draw);
        return () => window.cancelAnimationFrame(animationId);
    }, [sparkColor, sparkSize, sparkRadius, duration, easeFunc, extraScale]);

    const handleClick = (event: MouseEvent<HTMLDivElement>) => {
        if (prefersReducedMotion()) return;
        const canvas = canvasRef.current;
        if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const x = event.clientX - rect.left;
        const y = event.clientY - rect.top;
        const now = performance.now();
        sparksRef.current.push(
            ...Array.from({length: sparkCount}, (_, i) => ({
                x,
                y,
                angle: (2 * Math.PI * i) / sparkCount,
                startTime: now,
            })),
        );
    };

    return (
        <div className={cn("relative h-full w-full", className)} onClick={handleClick}>
            {children}
            <canvas
                ref={canvasRef}
                aria-hidden
                className="pointer-events-none absolute inset-0 z-50 block size-full select-none"
            />
        </div>
    );
}

import * as React from "react";
import * as SliderPrimitive from "@radix-ui/react-slider";
import {cn} from "@/lib/utils";

function Slider({
                    className,
                    defaultValue,
                    value,
                    min = 0,
                    max = 100,
                    "aria-label": ariaLabel,
                    ...props
                }: React.ComponentProps<typeof SliderPrimitive.Root>) {
    const values = React.useMemo(
        () => Array.isArray(value) ? value : Array.isArray(defaultValue) ? defaultValue : [min, max],
        [value, defaultValue, min, max],
    );

    return (
        <SliderPrimitive.Root
            data-slot="slider"
            defaultValue={defaultValue}
            value={value}
            min={min}
            max={max}
            className={cn(
                "relative flex w-full touch-none items-center select-none data-[disabled]:opacity-50 data-[orientation=vertical]:h-full data-[orientation=vertical]:min-h-44 data-[orientation=vertical]:w-auto data-[orientation=vertical]:flex-col",
                className,
            )}
            {...props}
        >
            <SliderPrimitive.Track
                data-slot="slider-track"
                className="bg-muted relative grow overflow-hidden rounded-full data-[orientation=horizontal]:h-1.5 data-[orientation=horizontal]:w-full data-[orientation=vertical]:h-full data-[orientation=vertical]:w-1.5"
            >
                <SliderPrimitive.Range
                    data-slot="slider-range"
                    className="bg-primary absolute data-[orientation=horizontal]:h-full data-[orientation=vertical]:w-full"
                />
            </SliderPrimitive.Track>
            {values.map((_, index) => (
                <SliderPrimitive.Thumb
                    data-slot="slider-thumb"
                    key={index}
                    aria-label={ariaLabel ? values.length > 1 ? `${ariaLabel} ${index + 1}` : ariaLabel : undefined}
                    className="border-primary bg-background ring-ring/50 block size-4 shrink-0 rounded-full border shadow-sm transition-[color,box-shadow] hover:ring-4 focus-visible:ring-4 focus-visible:outline-hidden disabled:pointer-events-none disabled:opacity-50"
                />
            ))}
        </SliderPrimitive.Root>
    );
}

