export function connectorRunIdentity(connector: ConnectorConfig): AgentRun["connector"] {
    const url = new URL(connector.baseUrl.trim());
    if (!/^https?:$/.test(url.protocol) || url.username || url.password || url.search || url.hash) {
        throw new Error("连接地址必须是无凭据、查询参数或片段的 HTTP(S) 地址");
    }
    return {id: connector.id, definitionId: connector.definitionId, baseUrl: url.toString().replace(/\/+$/, "")};
}

export function assertRetryConnector(run: AgentRun, connector: ConnectorConfig): void {
    const identity = connectorRunIdentity(connector);
    if (identity.id !== run.connector.id || identity.definitionId !== run.connector.definitionId || identity.baseUrl !== run.connector.baseUrl) {
        throw new Error("原连接已更改，请恢复原连接配置或发送新消息");
    }
}

export function canRetryRun(run: AgentRun, runs: AgentRun[], messages: ChatMessage[]): boolean {
    if (run.status === "running" || run.status === "waiting_approval" || run.status === "completed" || run.hasToolCalls) return false;
    const latest = [...runs].sort((a, b) => a.createdAt.localeCompare(b.createdAt)).at(-1);
    if (latest?.id !== run.id) return false;
    const lastUser = [...messages].filter((m) => m.role === "user").sort((a, b) => a.createdAt.localeCompare(b.createdAt)).at(-1);
    return lastUser?.id === run.userMessageId;
}

export async function beginAgentRun(input: {
    threadId: string;
    connector: ConnectorConfig;
    model: string;
    content?: string;
    attachments?: ReferenceAttachment[];
    retryOfRunId?: string;
    reasoningEffort?: AgentReasoningEffort;
    interactionMode?: AgentInteractionMode;
    createTask?: boolean;
    modelMetadata?: ChatModelMetadata;
}): Promise<AgentRun> {
    const identity = connectorRunIdentity(input.connector);
    if (!input.model.trim() || !input.connector.apiKey.trim()) throw new Error("请选择模型并配置 API Key");
    const visionCapability = await resolveVisionCapability(input.model, identity.definitionId, input.modelMetadata);
    return db.transaction("rw", db.tables, async () => {
        const thread = await db.chatThreads.get(input.threadId);
        if (!thread) throw new Error("对话不存在");
        if ((thread.taskMode || input.createTask) && !thread.projectId) throw new Error("任务模式请先选择项目");
        if (thread.projectId && !await db.projects.get(thread.projectId)) throw new Error("关联项目已不存在，无法执行");
        if (await db.agentTaskWrapups.where("threadId").equals(thread.id).filter((record) => record.status === "preparing").count()) throw new Error("总结正在整理，请先等待或停止");
        const runs = await db.agentRuns.where("threadId").equals(thread.id).toArray();
        if (runs.some((run) => run.status === "running" || run.status === "waiting_approval" || (run.hasToolCalls && (run.status === "interrupted" || run.status === "failed")))) throw new Error("此对话已有执行，请等待完成或恢复中断状态");
        const history = await db.chatMessages.where("threadId").equals(thread.id).sortBy("createdAt");
        // Keep order deterministic even when several IndexedDB writes share a millisecond.
        const at = new Date(Math.max(Date.now(), ...history.map((m) => Date.parse(m.createdAt) + 1).filter(Number.isFinite))).toISOString();
        const agent = await getGeneralAgentConfig();
        const previous = input.retryOfRunId ? runs.find((run) => run.id === input.retryOfRunId) : undefined;
        if (input.retryOfRunId && (!previous || !canRetryRun(previous, runs, history))) {
            throw new Error("只能重新生成当前最后一次未完成的回复；后续已有消息时请发送新问题");
        }
        if (previous) {
            if (previous.projectId !== thread.projectId) throw new Error("原执行项目归属已变化");
            assertRetryConnector(previous, input.connector);
            if (previous.model !== input.model.trim()) throw new Error("重新生成必须使用原模型");
        }
        const reasoningEffort = previous ? previous.reasoningEffort : input.reasoningEffort;
        assertReasoningEffort(identity, input.model, reasoningEffort);
        const content = input.content?.trim() || (input.attachments?.length ? "请结合附加的参考资料协助我。" : "");
        if (!previous && !content) throw new Error("消息不能为空");
        let task = await db.agentTasks.where("threadId").equals(thread.id).first();
        if (input.createTask && !task && !previous) task = await createAgentTaskForThread(thread.id, {
            title: deriveChatTitle(content),
            goal: content
        });
        if (task && task.projectId !== thread.projectId) throw new Error("任务与对话项目归属不一致");
        if (task && task.lifecycle !== "open") throw new Error("请先重新打开任务，再继续对话");
        if (previous?.taskId && previous.taskId !== task?.id) throw new Error("原任务关联已失效");

        const userMessageId = previous?.userMessageId ?? createId("cmsg");
        const runId = createId("run");
        const assistantMessageId = createId("cmsg");
        const interactionMode = previous ? previous.interactionMode ?? "smart" : input.interactionMode ?? thread.interactionMode ?? "smart";
        const taskMode = previous ? previous.taskMode === true : thread.taskMode === true;
        const taskContext = await getTaskContext(thread.id, agent.instructions, taskMode, interactionMode, thread.projectId);
        const instructions = taskContext.instructions;
        const skills = assembleSkills(agent.enabledSkillIds ?? []);
        const selectedToolNames = interactionMode === "conversation" ? [] : (previous ? previous.enabledToolNames ?? [] : [...new Set([...skills.enabledToolNames, ...taskContext.taskToolNames])]);
        const allowedToolNames = filterProjectMemoryTools(selectedToolNames, thread.projectId, interactionMode);
        const toolLoading = previous ? previous.toolLoading : interactionMode === "conversation" ? undefined : createToolLoading(agent.enabledSkillIds ?? [], allowedToolNames, taskContext.projectKind);
        const enabledToolNames = toolLoading ? [...new Set([...allowedToolNames, DISCOVERY_TOOL_NAME])] : allowedToolNames;
        const skillInstructions = interactionMode === "conversation" ? "" : (previous ? previous.skillInstructions ?? "" : toolLoading ? toolLoadingInstructions(toolLoading) : skills.skillInstructions);
        const policy = normalizeContextPolicy(thread.contextPolicy);
        const selectedHistory = selectContextHistory(history, policy);
        const summary = policy.autoCompress ? findApplicableSummary(selectedHistory, await db.contextCompactions.where("threadId").equals(thread.id).toArray()) : undefined;
        const capacity = resolveContextCapacity(input.model, input.modelMetadata, identity.definitionId, policy);
        const memorySelection = previous?.memorySelection ?? (thread.projectId ? await getMemorySelection({
            projectId: thread.projectId,
            threadId: thread.id,
            draft: content,
            recentUserTurns: selectedHistory.filter(m => m.role === 'user').map(m => m.content),
            taskTitle: task?.title,
            taskGoal: task?.goal,
            capacity: capacity.capacity
        }) : undefined);
        const selectedReferences = previous?.context?.selectedReferences ?? await selectReferenceContext(thread.projectId, input.attachments ?? [], referenceSelectionCharacterBudget(capacity.capacity));
        if (selectedReferences?.images?.length) requireVision(previous?.visionCapability ?? visionCapability);
        const baseMessages = buildContextMessages(instructions, skillInstructions, selectedHistory, content, summary, memorySelection?.envelope, selectedReferences);
        const requestMessages = previous?.context?.baseMessages ?? previous?.requestMessages ?? baseMessages;
        const context = previous ? previous.context : {
            policy,
            history: selectedHistory,
            baseMessages,
            draft: content,
            selectedReferences,
            summaryId: summary?.id,
            memoryEnvelope: memorySelection?.envelope, ...capacity
        };
        const run: AgentRun = {
            context,
            memorySelection,
            memoryAudit: [],
            referenceAudit: [],
            visionCapability: previous?.visionCapability ?? visionCapability,
            projectId: thread.projectId,
            projectContext: previous?.projectContext ?? taskContext.projectContext,
            id: runId,
            threadId: thread.id,
            taskId: previous?.taskId ?? task?.id,
            plan: previous?.plan ?? task?.plan,
            agentId: previous?.agentId ?? agent.id,
            agentSnapshot: previous?.agentSnapshot ?? {name: agent.name, instructions},
            userMessageId,
            assistantMessageId,
            retryOfRunId: previous?.id,
            model: input.model.trim(),
            connector: identity,
            requestMessages,
            protocol: previous?.protocol ?? (previous?.hasToolCalls ? "chat-completions" : selectAgentProtocol(identity, input.model, reasoningEffort, enabledToolNames.length > 0)),
            ...(reasoningEffort !== undefined ? {reasoningEffort} : {}),
            permissionMode: previous ? previous.permissionMode ?? "ask" : agent.permissionMode ?? "ask",
            interactionMode,
            taskMode,
            enabledToolNames,
            toolLoading,
            skillInstructions,
            status: "running",
            checkpoint: 0,
            createdAt: at,
            updatedAt: at,
        };
        if (!previous) await db.chatMessages.add({
            id: userMessageId,
            threadId: thread.id,
            role: "user",
            content, ...(selectedReferences ? {
                attachments: selectedReferences.references,
                referenceContext: selectedReferences
            } : {}),
            createdAt: at,
            status: "complete"
        });
        await db.chatMessages.add({
            id: assistantMessageId,
            threadId: thread.id,
            role: "assistant",
            content: "",
            createdAt: new Date(Date.parse(at) + 1).toISOString(),
            status: "streaming",
            runId
        });
        await db.agentRuns.add(run);
        if (task) await db.agentTasks.update(task.id, {updatedAt: at});
        await db.chatThreads.update(thread.id, {
            updatedAt: at, connectorId: identity.id, model: run.model,
            ...(!previous && (thread.title === "新话题" || thread.title === "新对话")
                ? {title: deriveChatTitle(content)} : {}),
        });
        return run;
    });
}

export async function checkpointAgentRun(runId: string, sequence: number, output: AgentRunOutput): Promise<void> {
    await db.transaction("rw", db.agentRuns, db.chatMessages, async () => {
        const run = await db.agentRuns.get(runId);
        if (!run) throw new Error("执行已删除");
        if (run.status !== "running" || sequence <= run.checkpoint) return;
        const message = await db.chatMessages.get(run.assistantMessageId);
        if (!message || message.runId !== run.id) throw new Error("执行消息不存在");
        await db.chatMessages.update(message.id, {...output});
        await db.agentRuns.update(run.id, {checkpoint: sequence, updatedAt: nowIso()});
    });
}

export async function finishAgentRun(runId: string, status: Exclude<AgentRunStatus, "running" | "waiting_approval">, output?: AgentRunOutput, error?: string, finishReason?: string): Promise<void> {
    await db.transaction("rw", db.agentRuns, db.chatMessages, async () => {
        const run = await db.agentRuns.get(runId);
        if (!run || (run.status !== "running" && run.status !== "waiting_approval")) return;
        const message = await db.chatMessages.get(run.assistantMessageId);
        if (!message || message.runId !== run.id) throw new Error("执行消息不存在");
        const at = nowIso();
        const messageStatus = {
            completed: "complete",
            failed: "error",
            cancelled: "aborted",
            interrupted: "interrupted"
        } as const;
        await db.chatMessages.update(message.id, {...output, status: messageStatus[status], error});
        await db.agentRuns.update(run.id, {status, error, finishReason, updatedAt: at, endedAt: at});
    });
}

/** Caller must own the thread's Web Lock; elapsed wall time is not proof of abandonment. */
export async function interruptThreadRuns(threadId: string): Promise<void> {
    await db.transaction("rw", [db.agentRuns, db.agentToolCalls, db.chatMessages, db.contextCompactions, db.agentGenerationJobs, db.agentGenerationBatches, db.agentGenerationBatchItems], async () => {
        const runs = await db.agentRuns.where("threadId").equals(threadId).toArray();
        for (const run of runs) {
            await upgradeLegacyPlanCalls(run.id);
            await recoverBatchPreparationCalls(run.id);
            if (run.status !== "running") continue;
            await db.contextCompactions.where("runId").equals(run.id).filter((record) => record.status === "running").modify({
                status: "interrupted",
                error: "整理已中断，未启用未完成的摘要。请手动继续或重新生成。",
                updatedAt: nowIso()
            });
            const running = await db.agentToolCalls.where("runId").equals(run.id).filter((call) => call.status === "running").toArray();
            for (const call of running) await db.agentToolCalls.update(call.id, await interruptedToolState(call));
            const calls = await db.agentToolCalls.where("runId").equals(run.id).toArray();
            // A crash may fall between persisting an approval request and parking the
            // run. Restore its actionable waiting state instead of stranding the call
            // behind an interrupted run that cannot accept an approval or resume.
            if (calls.some((call) => call.status === "awaiting_approval") && !calls.some((call) => call.status === "unknown")) {
                await db.agentRuns.update(run.id, {status: "waiting_approval", updatedAt: nowIso()});
                await db.chatMessages.update(run.assistantMessageId, {status: "pending", error: undefined});
                continue;
            }
            await finishAgentRun(run.id, "interrupted", undefined, run.hasToolCalls
                ? "执行已中断。继续时将使用已保存的步骤与结果；结果不确定的操作需要先核实。"
                : "上次生成已中断，已保留收到的内容。重新生成会创建一次新的请求。");
        }
    });
}


/** One immutable metrics record per model step, safe to replay after local recovery. */
export async function recordAgentModelMetrics(runId: string, metrics: AgentModelMetrics): Promise<void> {
    await db.transaction("rw", db.agentRuns, async () => {
        const run = await db.agentRuns.get(runId);
        if (!run || run.status !== "running") return;
        if (!Number.isSafeInteger(metrics.step) || metrics.step < 1 || metrics.step !== run.modelStep) throw new Error("模型用量所属步骤无效");
        if (run.modelMetrics?.some((item) => item.step === metrics.step)) return;
        const modelMetrics = [...(run.modelMetrics ?? []), metrics].sort((a, b) => a.step - b.step);
        const usage: AgentTokenUsage = {};
        const completeSteps = modelMetrics.length === run.modelStep;
        for (const name of ["inputTokens", "outputTokens", "totalTokens", "cachedInputTokens"] as const) {
            if (completeSteps && modelMetrics.every((item) => item.usage?.[name] !== undefined)) {
                const sum = modelMetrics.reduce((total, item) => total + item.usage![name]!, 0);
                if (Number.isSafeInteger(sum)) usage[name] = sum;
            }
        }
        // Streaming generation speed excludes first-token latency, tool execution and
        // approval waits. JSON responses cannot reveal a first-token timestamp.
        const duration = modelMetrics.reduce((total, item) => total + (item.firstTokenAt === undefined ? 0 : item.endedAt - item.firstTokenAt), 0);
        const measurable = completeSteps && modelMetrics.every((item) => item.firstTokenAt !== undefined && item.endedAt > item.firstTokenAt);
        const outputTokensPerSecond = measurable && duration > 0 && usage.outputTokens !== undefined ? usage.outputTokens * 1000 / duration : undefined;
        await db.agentRuns.update(runId, {
            modelMetrics,
            usage: Object.keys(usage).length ? usage : undefined,
            outputTokensPerSecond
        });
    });
}

import {db} from "@/db/database";
import {type AgentConfig, type AgentPermissionMode, GENERAL_AGENT_ID} from "@/domain/agent";
import {assembleSkills, DEFAULT_SKILL_IDS} from "@/lib/agent/skills";
import {nowIso} from "@/lib/ids";

const SKILL_DEFAULTS_VERSION = 3;

/** May also run in the transaction that creates a run. */
export async function getGeneralAgentConfig(): Promise<AgentConfig> {
    return db.transaction("rw", db.agents, async () => {
        const existing = await db.agents.get(GENERAL_AGENT_ID);
        if (existing) {
            // Enable the foundational creative skills once for existing installations.
            // A saved version prevents later reads from undoing the user's switch choices.
            if ((existing.skillDefaultsVersion ?? 0) < SKILL_DEFAULTS_VERSION) {
                const version = existing.skillDefaultsVersion ?? 0;
                let enabledSkillIds = existing.enabledSkillIds?.length === 0 ? []
                    : version < 1 ? [...DEFAULT_SKILL_IDS] : [...(existing.enabledSkillIds ?? DEFAULT_SKILL_IDS)];
                if (enabledSkillIds.length) {
                    if (version < 2) enabledSkillIds.push("ip-management", "material-library");
                    if (version < 3) enabledSkillIds.push("audio-production", "music-creation");
                }
                const migrated: AgentConfig = {
                    ...existing,
                    permissionMode: existing.permissionMode ?? "ask",
                    enabledSkillIds: [...new Set(enabledSkillIds)],
                    skillDefaultsVersion: SKILL_DEFAULTS_VERSION,
                    updatedAt: nowIso()
                };
                await db.agents.put(migrated);
                return migrated;
            }
            return {
                ...existing,
                permissionMode: existing.permissionMode ?? "ask",
                enabledSkillIds: existing.enabledSkillIds ?? [...DEFAULT_SKILL_IDS]
            };
        }
        const agent: AgentConfig = {
            id: GENERAL_AGENT_ID,
            name: "创作助手",
            instructions: "你是小光点的通用创作助手，帮助用户梳理创意、剧本和制作计划。准确说明已完成的工作，不要声称执行了没有实际调用的工具或修改了系统数据。",
            permissionMode: "ask",
            enabledSkillIds: [...DEFAULT_SKILL_IDS],
            skillDefaultsVersion: SKILL_DEFAULTS_VERSION,
            updatedAt: nowIso(),
        };
        await db.agents.add(agent);
        return agent;
    });
}

export async function updateGeneralAgentConfig(patch: {
    permissionMode?: AgentPermissionMode;
    enabledSkillIds?: string[]
}): Promise<void> {
    if (patch.permissionMode !== undefined && !["ask", "assist", "full"].includes(patch.permissionMode)) throw new Error("未知授权模式");
    if (patch.enabledSkillIds) assembleSkills(patch.enabledSkillIds);
    await db.transaction("rw", db.agents, async () => {
        const agent = await getGeneralAgentConfig();
        await db.agents.update(agent.id, {...patch, updatedAt: nowIso()});
    });
}

import {readGenerationTarget} from "@/lib/agent/generationRuntime";
import {db} from "./database";
import {editableAgentTask} from "./agentTasks";
import type {AgentTaskRecord, TaskRecordInput, TaskRecordSource} from "@/domain/agentTaskRecords";
import {TASK_RECORD_CLAIMS, TASK_RECORD_KINDS} from "@/domain/agentTaskRecords";
import type {AgentTask, AgentToolCall} from "@/domain/agent";
import {createId, nowIso} from "@/lib/ids";
import {
    ownedTaskAudioGenerationJob,
    SOUND_GENERATION_TOOLS,
    taskAudioGenerationSource,
    taskAudioToolSource
} from "./taskAudioGenerationEvidence";

export async function listTaskRecords(taskId: string): Promise<AgentTaskRecord[]> {
    return db.agentTaskRecords.where("taskId").equals(taskId).sortBy("updatedAt");
}

export async function listTaskRecordVersions(taskId: string, recordId: string) {
    const record = await db.agentTaskRecords.get(recordId);
    if (!record || record.taskId !== taskId) throw new Error("记录不属于当前任务");
    return db.agentTaskRecordVersions.where("recordId").equals(recordId).sortBy("revision");
}

/** A completed ledger entry may describe a failed remote job or an apply conflict. */
export function provesCompletedEffect(call: AgentToolCall): boolean {
    let value: unknown;
    try {
        value = JSON.parse(call.result ?? "null");
    } catch {
        return false;
    }
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    const result = value as Record<string, unknown>;
    if (result.error || result.ok === false || result.success === false) return false;
    if (["submit_generation", "check_generation", "apply_generation"].includes(call.name)) {
        const media = result.result as { mediaId?: unknown; kind?: unknown } | undefined;
        return (call.name === "apply_generation" ? result.status === "applied" && result.applied === true : result.status === "downloaded" || result.status === "applied") &&
            typeof media?.mediaId === "string" && !!media.mediaId && (media.kind === "image" || media.kind === "video");
    }
    // Other network tools can report a check without producing a business result.
    return call.effect === "write" && result.applied !== false;
}

export async function validateTaskSources(task: Pick<AgentTask, "id" | "threadId">, sources: TaskRecordSource[], claim: TaskRecordInput["claim"], author: "ai" | "user") {
    if (!Array.isArray(sources) || sources.length > 12) throw new Error("来源最多 12 项");
    let userEvidence = false, completedEffect = false;
    for (const source of sources) {
        if (!source.id || source.id.length > 120) throw new Error("来源标识无效");
        if (source.type === "message") {
            const message = await db.chatMessages.get(source.id);
            if (!message || message.threadId !== task.threadId || message.role !== "user" || (!message.content.trim() && !message.attachments?.length)) throw new Error("只能引用当前对话真实的用户消息");
            userEvidence = true;
        } else if (source.type === "tool") {
            const call = await db.agentToolCalls.get(source.id);
            const run = call && await db.agentRuns.get(call.runId);
            if (!call || !run || call.threadId !== task.threadId || run.threadId !== task.threadId || run.taskId !== task.id || call.status !== "completed" || !call.result || call.effect === "bookkeeping") throw new Error("来源不是当前任务已完成的业务工具结果");
            if ((SOUND_GENERATION_TOOLS as readonly string[]).includes(call.name)) {
                const evidence = await taskAudioToolSource(task, call);
                completedEffect ||= evidence?.supportsResult === true;
            } else completedEffect ||= provesCompletedEffect(call);
        } else if (source.type === "generation") {
            const evidence = await taskGenerationSource(task, source.id);
            completedEffect ||= evidence.supportsResult;
        } else throw new Error("来源类型无效");
    }
    if (author === "ai" && claim === "decision" && !userEvidence) throw new Error("确认决策必须引用用户消息");
    if (author === "ai" && claim === "result" && !completedEffect) throw new Error("完成结果必须引用已完成的实际业务操作");
    if (author === "ai" && claim === "observation" && sources.length === 0) throw new Error("调研观察必须附真实来源；未核实内容请记为方案或待解决问题");
}

/** Transaction-internal write, shared by guarded manual saves and ledger-atomic tools. */
export async function writeTaskRecord(task: AgentTask, input: TaskRecordInput, options: {
    id?: string;
    expectedRevision?: number;
    author: "user" | "ai";
    runId?: string;
    requirementSnapshot?: boolean
}): Promise<AgentTaskRecord> {
    if (task.lifecycle !== "open") throw new Error("请先重新打开任务");
    if (!TASK_RECORD_KINDS.includes(input.kind) || !TASK_RECORD_CLAIMS.includes(input.claim) || !input.title.trim() || input.title.length > 120 || !input.body.trim() || input.body.length > (options.requirementSnapshot ? 100_000 : 12_000)) throw new Error("记录类型或内容无效：标题最多 120 字，正文最多 12,000 字");
    if (input.todoId && !task.plan.some((item) => item.id === input.todoId)) throw new Error("关联 Todo 不存在");
    await validateTaskSources(task, input.sources, input.claim, options.author);
    const existing = options.id ? await db.agentTaskRecords.get(options.id) : undefined;
    if (options.id && (!existing || existing.taskId !== task.id)) throw new Error("记录不属于当前任务");
    if (existing && options.expectedRevision !== existing.revision) throw new Error("记录已更新，请重新读取后修改");
    if (!existing && options.expectedRevision !== undefined) throw new Error("新记录不应指定旧版本");
    if (!existing && options.runId) {
        const duplicate = (await listTaskRecords(task.id)).find((record) => record.runId === options.runId && record.author === options.author && record.kind === input.kind && record.claim === input.claim && record.title === input.title.trim() && record.body === input.body.trim() && record.todoId === input.todoId && JSON.stringify(record.sources) === JSON.stringify(input.sources));
        if (duplicate) return duplicate;
    }
    const at = nowIso();
    const record: AgentTaskRecord = {
        ...input,
        title: input.title.trim(),
        body: input.body.trim(),
        id: existing?.id ?? createId("trec"),
        taskId: task.id,
        revision: (existing?.revision ?? 0) + 1,
        author: options.author,
        runId: options.runId,
        createdAt: existing?.createdAt ?? at,
        updatedAt: at
    };
    await db.agentTaskRecords.put(record);
    await db.agentTaskRecordVersions.add({
        ...record,
        recordId: record.id,
        versionId: `${record.id}:${record.revision}`
    });
    await db.agentTasks.update(task.id, {updatedAt: at});
    return record;
}

export async function saveTaskRecord(taskId: string, input: TaskRecordInput, options: {
    id?: string;
    expectedRevision?: number
} = {}): Promise<AgentTaskRecord> {
    return db.transaction("rw", db.tables, async () => writeTaskRecord(await editableAgentTask(taskId), input, {
        ...options,
        author: "user"
    }));
}

/** Genuine generation evidence is owned by the task and reflects current local media/slot state. */
export async function taskGenerationSource(task: Pick<AgentTask, "id" | "threadId">, jobId: string) {
    const soundJob = await db.audioGenerationJobs.get(jobId);
    if (soundJob) return taskAudioGenerationSource(task, soundJob);
    const job = await db.agentGenerationJobs.get(jobId);
    const run = job && await db.agentRuns.get(job.runId);
    if (!job || !run || run.taskId !== task.id || job.threadId !== task.threadId || run.threadId !== task.threadId || !job.batchId) throw new Error("生成结果不属于当前任务批次");
    const batch = await db.agentGenerationBatches.get(job.batchId);
    if (!batch || batch.taskId !== task.id || batch.threadId !== task.threadId) throw new Error("生成批次来源已失效");
    const media = job.result && await db.media.get(job.result.mediaId);
    const available = !!media && media.projectId === job.projectId && !!media.blob.size && media.mimeType.startsWith(`${job.kind}/`) && ['downloaded', 'applied', 'conflict'].includes(job.status);
    let applied = false;
    try {
        applied = available && (await readGenerationTarget(job.target)).slot.result?.mediaId === media!.id;
    } catch { /* Downloaded output survives target deletion. */
    }
    return {
        id: job.id,
        batchId: job.batchId,
        status: job.status,
        result: job.result,
        label: `${job.kind === 'image' ? '图片' : '视频'} · ${job.model}`,
        available,
        applied,
        supportsResult: available,
        body: JSON.stringify({
            jobId: job.id,
            batchId: job.batchId,
            status: job.status,
            target: job.target,
            result: available ? job.result : undefined,
            available,
            applied,
            error: job.error
        })
    };
}

/** Shared source inventory; no remote refresh and no attribution to reading runs. */
export async function listTaskGenerationSources(task: AgentTask) {
    return db.transaction("r", db.tables, async () => {
        const sources: Awaited<ReturnType<typeof taskGenerationSource>>[] = [];
        const runs = await db.agentRuns.where("taskId").equals(task.id).toArray();
        const runIds = new Set(runs.filter(run => run.threadId === task.threadId).map(run => run.id));
        const jobs = await db.agentGenerationJobs.where("threadId").equals(task.threadId).toArray();
        for (const job of jobs.filter(job => job.batchId && runIds.has(job.runId))) {
            const batch = await db.agentGenerationBatches.get(job.batchId!);
            if (batch?.taskId === task.id && batch.threadId === task.threadId) sources.push(await Promise.resolve(taskGenerationSource(task, job.id)));
        }
        const soundJobs = await db.audioGenerationJobs.where("projectId").equals(task.projectId).toArray();
        for (const job of soundJobs) {
            if (await Promise.resolve(ownedTaskAudioGenerationJob(task, job))) sources.push(await Promise.resolve(taskAudioGenerationSource(task, job)));
        }
        return sources;
    });
}

import {db} from "./database";
import {isTaskBusy} from "@/lib/agent/taskState";
import {collectWrapupSnapshot} from "@/lib/agent/wrapupEvidence";
import {emptyWrapupContent, validateWrapupContent} from "@/lib/agent/wrapupSchema";
import type {AgentTask} from "@/domain/agent";
import type {AgentTaskWrapup, TaskWrapupState, WrapupContent} from "@/domain/agentTaskWrapup";
import {createId, nowIso} from "@/lib/ids";
import {ownedTaskAudioGenerationJob} from "./taskAudioGenerationEvidence";

async function owned(taskId: string) {
    const task = await db.agentTasks.get(taskId);
    if (!task || !await db.chatThreads.get(task.threadId)) throw new Error('任务或关联对话不存在');
    return task;
}

async function ready(taskId: string, except?: string) {
    const task = await owned(taskId);
    if (!task.projectId || !await db.projects.get(task.projectId)) throw new Error('关联项目已不存在，无法整理总结');
    if (task.lifecycle !== 'open') throw new Error('请先重新打开任务');
    if (isTaskBusy(await db.agentRuns.where('threadId').equals(task.threadId).toArray())) throw new Error('请先处理当前执行，再整理总结');
    if ((await db.agentTaskWrapups.where('taskId').equals(taskId).toArray()).some(w => w.status === 'preparing' && w.id !== except)) throw new Error('总结正在整理，请先等待或停止');
    return task;
}

async function saveVersion(record: AgentTaskWrapup) {
    await db.agentTaskWrapups.put(record);
    await db.agentTaskWrapupVersions.add({...record, versionId: `${record.id}:${record.revision}`});
    return record;
}

async function recordFor(taskId: string, id: string, revision: number) {
    const task = await owned(taskId), record = await db.agentTaskWrapups.get(id);
    if (!record || record.taskId !== taskId || record.threadId !== task.threadId) throw new Error('总结不属于当前任务');
    if (record.revision !== revision) throw new Error('总结已更新，请重新读取后操作');
    const latest = (await db.agentTaskWrapups.where('taskId').equals(taskId).toArray()).sort((a, b) => a.createdAt.localeCompare(b.createdAt)).at(-1);
    if (latest?.id !== record.id) throw new Error('已有新的总结草稿，请重新读取；当前编辑内容仍可保留');
    return {task, record};
}

export async function getTaskWrapupState(taskId: string): Promise<TaskWrapupState> {
    return db.transaction('r', db.tables, async () => {
        const task = await owned(taskId), snapshot = await collectWrapupSnapshot(task, true);
        const records = (await db.agentTaskWrapups.where('taskId').equals(taskId).toArray()).sort((a, b) => a.createdAt.localeCompare(b.createdAt));
        const latest = records.at(-1),
            confirmed = records.filter(w => !!w.confirmedAt).sort((a, b) => a.confirmedAt!.localeCompare(b.confirmedAt!) || a.createdAt.localeCompare(b.createdAt)).at(-1);
        const history = (await db.agentTaskWrapupVersions.where('taskId').equals(taskId).toArray()).sort((a, b) => b.createdAt.localeCompare(a.createdAt) || b.revision - a.revision);
        return {
            latest,
            confirmed,
            history,
            stale: !!latest && latest.snapshot.fingerprint !== snapshot.fingerprint,
            currentEvidence: snapshot.evidence,
            completionBlockers: await completionBlockers(task, confirmed, snapshot.fingerprint)
        };
    });
}

async function completionBlockers(task: AgentTask, confirmed: AgentTaskWrapup | undefined, fingerprint: string) {
    const reasons: string[] = [];
    if (!task.projectId || !await db.projects.get(task.projectId)) reasons.push("关联项目已不存在");
    if (isTaskBusy(await db.agentRuns.where('threadId').equals(task.threadId).toArray())) reasons.push('请先处理当前执行');
    if ((await db.agentTaskWrapups.where('taskId').equals(task.id).toArray()).some(w => w.status === 'preparing')) reasons.push('总结仍在整理');
    if (task.plan.some(p => p.status !== 'completed')) reasons.push('还有未完成的 Todo');
    for (const job of await db.audioGenerationJobs.where("projectId").equals(task.projectId).toArray()) {
        if (["submitting", "uncertain", "submitted", "running", "remote-completed", "downloading"].includes(job.status) && await Promise.resolve(ownedTaskAudioGenerationJob(task, job))) {
            reasons.push("声音生成仍有进行中或待核实结果");
            break;
        }
    }
    const ownedBatches = await db.agentGenerationBatches.where('taskId').equals(task.id).toArray();
    for (const batch of ownedBatches) {
        const items = await db.agentGenerationBatchItems.where('batchId').equals(batch.id).toArray();
        const jobs = await db.agentGenerationJobs.where('batchId').equals(batch.id).toArray();
        if (batch.status === 'draft' || items.some(item => item.state === 'queued') || jobs.some(job => ['submitting', 'submitted', 'running', 'downloading', 'remote_completed', 'unknown'].includes(job.status))) {
            reasons.push('批量生成还有未确认草稿、排队或待核实结果');
            break;
        }
    }
    const latest = (await db.agentTaskWrapups.where('taskId').equals(task.id).toArray()).sort((a, b) => a.createdAt.localeCompare(b.createdAt)).at(-1);
    if (latest?.id !== confirmed?.id) reasons.push('请先检查最新总结草稿，旧版确认不能代表本次验收');
    if (!confirmed?.confirmedAt) reasons.push('请先保存并确认任务总结');
    else {
        if (confirmed.snapshot.fingerprint !== fingerprint) reasons.push('总结依据已变化，请重新整理并确认');
        if (confirmed.content.acceptance.some(a => a.status !== 'met')) reasons.push('验收要求尚未全部确认通过');
        if (confirmed.content.unresolved.length) reasons.push('总结仍有未解决事项');
        const runIds = new Set((await db.agentRuns.where("taskId").equals(task.id).toArray()).map(run => run.id));
        if ((await db.agentToolCalls.where("threadId").equals(task.threadId).toArray()).some(call => runIds.has(call.runId) && ["unknown", "running", "pending", "awaiting_approval", "approved"].includes(call.status)) || (await db.agentGenerationJobs.where("threadId").equals(task.threadId).toArray()).some(job => runIds.has(job.runId) && ["unknown", "submitting", "submitted", "running", "remote_completed", "downloading"].includes(job.status))) reasons.push("执行或生成仍有待核实结果");
    }
    return reasons;
}

export async function assertTaskWrapupCompletion(task: AgentTask, expected?: { id: string; revision: number }) {
    if (!expected) throw new Error('请从当前已确认总结完成任务');
    const record = await db.agentTaskWrapups.get(expected.id);
    if (!record || record.taskId !== task.id || record.threadId !== task.threadId || record.revision !== expected.revision || !record.confirmedAt) throw new Error('已确认总结已变化，请重新检查');
    const records = await db.agentTaskWrapups.where('taskId').equals(task.id).toArray();
    const newest = records.filter(r => !!r.confirmedAt).sort((a, b) => a.confirmedAt!.localeCompare(b.confirmedAt!) || a.createdAt.localeCompare(b.createdAt)).at(-1);
    if (newest?.id !== record.id) throw new Error('有更新的确认版本，请重新检查');
    const blockers = await completionBlockers(task, record, (await collectWrapupSnapshot(task)).fingerprint);
    if (blockers.length) throw new Error(blockers.join('；'));
}

export async function startTaskWrapup(taskId: string, author: 'ai' | 'user'): Promise<AgentTaskWrapup> {
    return db.transaction('rw', db.tables, async () => {
        const task = await ready(taskId), snapshot = await collectWrapupSnapshot(task);
        const earlier = (await db.agentTaskWrapups.where('taskId').equals(taskId).toArray()).sort((a, b) => a.createdAt.localeCompare(b.createdAt));
        const previous = [...earlier].reverse().find(r => r.status === 'draft');
        const at = new Date(Math.max(Date.now(), ...earlier.map(r => Date.parse(r.createdAt) + 1))).toISOString();
        const content = emptyWrapupContent(snapshot.criteria);
        if (author === 'user' && previous) {
            const sources = new Map(snapshot.evidence.map(e => [e.id, e]));
            content.overview = previous.content.overview;
            for (const key of ['decisions', 'lessons', 'unresolved'] as const) content[key] = previous.content[key].map(item => ({
                ...item,
                sourceIds: item.sourceIds.filter(id => sources.has(id))
            }));
            for (const item of previous.content.results) {
                if (item.sourceIds.every(id => sources.get(id)?.available && sources.get(id)?.outcome !== 'unresolved')) content.results.push({...item});
                else content.unresolved.push({
                    text: `重新核实原成果：${item.text}`.slice(0, 2400),
                    sourceIds: item.sourceIds.filter(id => sources.has(id))
                });
            }
            // Never silently discard an unresolved concern while refreshing its evidence.
            if (content.unresolved.length > 30) throw new Error('原稿有较多待核实成果，请先保留并整理原稿后重试');
        }
        return saveVersion({
            id: createId('wrap'),
            taskId,
            threadId: task.threadId,
            revision: 1,
            status: author === 'ai' ? 'preparing' : 'draft',
            author,
            content,
            snapshot,
            createdAt: at,
            updatedAt: at
        });
    });
}

export async function createManualWrapup(taskId: string) {
    return startTaskWrapup(taskId, 'user');
}

export async function saveWrapup(taskId: string, id: string, content: WrapupContent, expectedRevision: number) {
    return db.transaction('rw', db.tables, async () => {
        await ready(taskId);
        const {task, record} = await recordFor(taskId, id, expectedRevision);
        if (record.status !== 'draft' || record.confirmedAt) throw new Error('已确认总结保留为历史，请建立新草稿');
        if (record.snapshot.fingerprint !== (await collectWrapupSnapshot(task)).fingerprint) throw new Error('总结依据已变化，请重新整理；原草稿已保留');
        return saveVersion({
            ...record,
            content: validateWrapupContent(content, record.snapshot, 'user'),
            author: 'user',
            revision: record.revision + 1,
            updatedAt: nowIso()
        });
    });
}

export async function confirmWrapup(taskId: string, id: string, expectedRevision: number) {
    return db.transaction('rw', db.tables, async () => {
        const existing = await db.agentTaskWrapups.get(id);
        if (existing?.taskId === taskId && existing.confirmedAt && (existing.revision === expectedRevision || existing.revision === expectedRevision + 1)) {
            await owned(taskId);
            return existing;
        }
        const {task, record} = await recordFor(taskId, id, expectedRevision);
        await ready(taskId);
        if (record.status !== 'draft') throw new Error('请先生成或保存总结草稿');
        if (!record.content.overview.trim()) throw new Error('请先填写总结概述');
        if (record.snapshot.fingerprint !== (await collectWrapupSnapshot(task)).fingerprint) throw new Error('总结依据已变化，请重新整理');
        const content = validateWrapupContent(record.content, record.snapshot, 'user');
        return saveVersion({
            ...record,
            content,
            confirmedAt: nowIso(),
            revision: record.revision + 1,
            updatedAt: nowIso()
        });
    });
}

export async function publishTaskWrapup(id: string, content: unknown, signal: AbortSignal) {
    return db.transaction('rw', db.tables, async () => {
        signal.throwIfAborted();
        const record = await db.agentTaskWrapups.get(id);
        if (!record || record.status !== 'preparing') throw new Error('整理已停止或任务已删除');
        const task = await ready(record.taskId, id);
        if (record.snapshot.fingerprint !== (await collectWrapupSnapshot(task)).fingerprint) throw new Error('整理期间依据发生变化，请重新准备总结');
        return saveVersion({
            ...record,
            content: validateWrapupContent(content, record.snapshot, 'ai'),
            status: 'draft',
            revision: record.revision + 1,
            updatedAt: nowIso()
        });
    });
}

export async function stopTaskWrapup(taskId: string, id: string, status: 'failed' | 'interrupted', error: string) {
    return db.transaction('rw', [db.agentTaskWrapups, db.agentTaskWrapupVersions, db.agentTasks, db.chatThreads], async () => {
        const record = await db.agentTaskWrapups.get(id);
        if (!record || record.taskId !== taskId || record.status !== 'preparing') return;
        await owned(taskId);
        await saveVersion({
            ...record,
            status,
            error: error.slice(0, 300),
            revision: record.revision + 1,
            updatedAt: nowIso()
        });
    });
}

export async function cancelTaskWrapup(taskId: string, id: string) {
    await stopTaskWrapup(taskId, id, 'interrupted', '整理已停止，原有总结仍保留；重新整理需要你明确操作。');
}

import {db} from "./database";
import type {AgentToolCall} from "@/domain/agent";
import {nowIso} from "@/lib/ids";

/** This exact built-in only prepares local drafts with an atomic result ledger. */
export function isUnknownBatchPreparation(call: AgentToolCall): boolean {
    return call.name === "prepare_generation_batch" && call.effect === "bookkeeping" &&
        call.atomic === true && !call.highRisk && !call.requiresConfirmation &&
        call.recovery === undefined && call.status === "unknown" && call.result === undefined;
}

/** Reconcile old misclassified preflight failures without executing tools or HTTP.
 * Caller holds the thread lock. Inconsistent evidence remains unknown.
 */
export async function recoverBatchPreparationCalls(runId: string): Promise<void> {
    await db.transaction("rw", db.agentRuns, db.agentToolCalls, db.agentGenerationBatches,
        db.agentGenerationBatchItems, db.agentGenerationJobs, async () => {
            const run = await db.agentRuns.get(runId);
            if (!run || !["running", "interrupted", "failed", "waiting_approval"].includes(run.status)) return;
            const calls = await db.agentToolCalls.where("runId").equals(runId).filter(isUnknownBatchPreparation).toArray();
            for (const call of calls) {
                if (call.threadId !== run.threadId) continue;
                // A paid-job record contradicts this tool's local-only contract.
                if (await db.agentGenerationJobs.where("callId").equals(call.id).count()) continue;
                const batches = await db.agentGenerationBatches.where("sourceCallId").equals(call.id).toArray();
                if (batches.length > 1) continue;
                const batch = batches[0];
                if (batch) {
                    const items = await db.agentGenerationBatchItems.where("batchId").equals(batch.id).toArray();
                    if (batch.runId !== run.id || batch.threadId !== run.threadId || batch.originCallId !== call.id ||
                        batch.taskId !== run.taskId || run.projectId && batch.projectId !== run.projectId ||
                        !items.length || items.length !== batch.itemIds.length || new Set(batch.itemIds).size !== items.length ||
                        items.some(item => !batch.itemIds.includes(item.id) || item.threadId !== run.threadId || item.projectId !== batch.projectId)) continue;
                    await db.agentToolCalls.update(call.id, {
                        status: "completed", error: undefined, updatedAt: nowIso(),
                        result: JSON.stringify({
                            batchId: batch.id,
                            status: batch.status,
                            targetCount: new Set(items.map(item => item.targetKey)).size,
                            candidateCount: items.length,
                            submitted: false,
                            recovered: true
                        })
                    });
                } else {
                    const error = '已核实本地没有此次操作创建的批量草稿，未提交生成。原失败原因未保存，请检查参数后重新准备草稿；图片比例使用 size，不要传 aspectRatio 或 mode。';
                    await db.agentToolCalls.update(call.id, {
                        status: "failed", error, updatedAt: nowIso(),
                        result: JSON.stringify({
                            error,
                            code: "BATCH_PREPARATION_NOT_COMMITTED",
                            submitted: false,
                            recovered: true
                        })
                    });
                }
            }
        });
}

/** Only this historic built-in already committed its mutation and result atomically.
 * Never infer repeatability for arbitrary bookkeeping/network tools. Caller owns the thread lock. */
export function isLegacyAtomicPlanCall(call: AgentToolCall): boolean {
    return call.name === "update_run_plan" && call.effect === "bookkeeping" && !call.highRisk &&
        call.atomic === undefined && call.recovery === undefined && !call.requiresConfirmation &&
        call.result === undefined && ["pending", "approved", "running", "unknown"].includes(call.status);
}

export async function upgradeLegacyPlanCalls(runId: string): Promise<void> {
    await db.transaction("rw", db.agentToolCalls, async () => {
        const calls = await db.agentToolCalls.where("runId").equals(runId).toArray();
        for (const call of calls) {
            if (!isLegacyAtomicPlanCall(call)) continue;
            await db.agentToolCalls.update(call.id, {
                atomic: true,
                ...(call.status === "unknown" ? {
                    status: call.decision === "approve" ? "approved" : "pending",
                    error: undefined
                } : {}),
                updatedAt: nowIso(),
            });
        }
    });
}

/** Caller holds the thread Web Lock and includes generation jobs in its transaction. */
export async function interruptedToolState(call: AgentToolCall): Promise<Pick<AgentToolCall, "status" | "error" | "updatedAt">> {
    let resumable = Boolean(call.atomic) || call.recovery === "repeatable";
    if (call.recovery === "generation") {
        const job = await db.agentGenerationJobs.where("callId").equals(call.id).first();
        resumable = Boolean(job && job.runId === call.runId && job.threadId === call.threadId &&
            job.status !== "unknown" && (job.providerTaskId || job.result || job.status === "failed"));
    }
    return {
        status: resumable ? (call.decision === "approve" ? "approved" : "pending") : "unknown",
        error: resumable ? undefined : "操作结果尚不确定，不能自动重跑。",
        updatedAt: nowIso(),
    };
}

import {MUSIC_REVIEW_MAX_BYTES, parseMusicGenerationReview} from "@/lib/agent/musicGenerationReviewSnapshot";
