import {REFERENCE_TOOL_NAMES} from "@/lib/agent/referenceToolNames";
import {writeTaskRecord} from "./agentTaskRecords";
import {generationSubmitSchema} from "@/lib/agent/generationProfiles";
import {targetRevision} from "@/lib/productionRevision";
import {interruptedToolState, recoverBatchPreparationCalls, upgradeLegacyPlanCalls} from "./agentToolRecovery";
import {formatTaskPlan, validateTaskPlan} from "@/lib/agent/taskState";
import {db} from "@/db/database";
import type {
    AgentPlanItem,
    AgentResponseItem,
    AgentRun,
    AgentRunOutput,
    AgentToolCall,
    AgentToolPreview,
    AgentWireToolCall
} from "@/domain/agent";
