export class AifenjingDB extends Dexie {
    audioChapters!: Table<AudioChapter, string>;
    audioSpeakers!: Table<AudioSpeaker, string>;
    audioSegments!: Table<AudioSegment, string>;
    audioTakes!: Table<AudioTake, string>;
    audioTracks!: Table<AudioTrack, string>;
    audioClips!: Table<AudioClip, string>;
    audioExports!: Table<AudioExport, string>;
    musicDrafts!: Table<MusicDraft, string>;
    musicWorks!: Table<MusicWork, string>;
    audioGenerationJobs!: Table<AudioGenerationJob, string>;
    ipProfiles!: Table<IpProfile, string>;
    projectIpLinks!: Table<ProjectIpLink, string>;
    libraryMaterials!: Table<LibraryMaterial, string>;
    materialVersions!: Table<MaterialVersion, string>;
    materialUses!: Table<MaterialUse, string>;
    materialEvents!: Table<MaterialEvent, string>;
    searchConnections!: Table<SearchConnection, string>;
    projectReferences!: Table<ProjectReference, string>;
    referenceChunks!: Table<ReferenceChunk, string>;
    projectMemories!: Table<ProjectMemory, string>;
    projectMemoryVersions!: Table<ProjectMemoryVersion, string>;
    agentTaskWrapups!: Table<AgentTaskWrapup, string>;
    agentTaskWrapupVersions!: Table<AgentTaskWrapupVersion, string>;
    agentGenerationBatches!: Table<GenerationBatch, string>;
    agentGenerationBatchItems!: Table<GenerationBatchItem, string>;
    agentGenerationJobs!: Table<AgentGenerationJob, string>;
    contextCompactions!: Table<ContextCompaction, string>;
    agentTasks!: Table<AgentTask, string>;
    agentToolCalls!: Table<AgentToolCall, string>;
    agents!: Table<AgentConfig, string>;
    agentRuns!: Table<AgentRun, string>;
    productionProposals!: Table<ProductionProposal, string>;
    projects!: Table<Project, string>;
    characters!: Table<Character, string>;
    scenes!: Table<Scene, string>;
    props!: Table<Prop, string>;
    styles!: Table<VisualStyle, string>;
    episodes!: Table<Episode, string>;
    shots!: Table<Shot, string>;
    media!: Table<MediaRecord, string>;
    /** Studio-global AI connectors — never included in project ZIP export. */
    connectors!: Table<ConnectorConfig, string>;
    /** Retired duplicate IDs remain usable by existing frozen runs/jobs only. */
    connectorAliases!: Table<ConnectorConfig, string>;
    /** Studio-global Agent chat threads — never included in project ZIP export. */
    agentTaskRecords!: Table<AgentTaskRecord, string>;
    agentTaskRecordVersions!: Table<AgentTaskRecordVersion, string>;
    chatThreads!: Table<ChatThread, string>;
    /** Studio-global Agent chat messages — never included in project ZIP export. */
    chatMessages!: Table<ChatMessage, string>;

    constructor() {
        super("aifenjing");
        this.version(1).stores({
            projects: "id, updatedAt",
            characters: "id, projectId, updatedAt",
            scenes: "id, projectId, updatedAt",
            shots: "id, projectId, order",
            media: "id, projectId",
        });
        this.version(2).stores({
            projects: "id, updatedAt",
            characters: "id, projectId, updatedAt",
            scenes: "id, projectId, updatedAt",
            props: "id, projectId, updatedAt",
            styles: "id, projectId, updatedAt",
            shots: "id, projectId, order",
            media: "id, projectId",
        });
        this.version(3)
            .stores({
                projects: "id, updatedAt",
                characters: "id, projectId, updatedAt",
                scenes: "id, projectId, updatedAt",
                props: "id, projectId, updatedAt",
                styles: "id, projectId, updatedAt",
                episodes: "id, projectId, order, updatedAt",
                shots: "id, projectId, episodeId, order",
                media: "id, projectId",
            })
            .upgrade(async (tx) => {
                const projects = await tx.table("projects").toArray();
                const episodesTable = tx.table("episodes");
                const shotsTable = tx.table("shots");
                const at = nowIso();

                for (const project of projects) {
                    const existing = await episodesTable.where("projectId").equals(project.id).count();
                    if (existing > 0) continue;

                    const rawStory =
                        project.story && typeof project.story === "object"
                            ? (project.story as Record<string, unknown>)
                            : {};
                    const episodeStory = normalizeEpisodeStory(rawStory);
                    const episodeId = createId("ep");
                    await episodesTable.add({
                        id: episodeId,
                        projectId: project.id,
                        order: 0,
                        title: "",
                        story: episodeStory,
                        createdAt: String(project.createdAt ?? at),
                        updatedAt: at,
                    });
                    await tx.table("projects").put({
                        ...project,
                        story: normalizeSeriesStory(rawStory),
                        columnSettings: {visible: [...DEFAULT_VISIBLE_COLUMNS]},
                    });

                    const shots = await shotsTable.where("projectId").equals(project.id).toArray();
                    for (const shot of shots) {
                        const record = {...(shot as Record<string, unknown>)};
                        const slots = parseShotPictureSlots(record);
                        delete record.frame;
                        delete record.reference;
                        delete record.frameMediaId;
                        delete record.referenceMediaId;
                        await shotsTable.put({
                            ...record,
                            episodeId: String(record.episodeId ?? episodeId),
                            ...slots,
                        });
                    }
                }
            });
        this.version(4).stores({
            projects: "id, updatedAt",
            characters: "id, projectId, updatedAt",
            scenes: "id, projectId, updatedAt",
            props: "id, projectId, updatedAt",
            styles: "id, projectId, updatedAt",
            episodes: "id, projectId, order, updatedAt",
            shots: "id, projectId, episodeId, order",
            media: "id, projectId",
            connectors: "id, definitionId, updatedAt",
        });
        this.version(5).stores({
            projects: "id, updatedAt",
            characters: "id, projectId, updatedAt",
            scenes: "id, projectId, updatedAt",
            props: "id, projectId, updatedAt",
            styles: "id, projectId, updatedAt",
            episodes: "id, projectId, order, updatedAt",
            shots: "id, projectId, episodeId, order",
            media: "id, projectId",
            connectors: "id, definitionId, updatedAt",
            chatThreads: "id, updatedAt",
            chatMessages: "id, threadId, createdAt",
        });
        // Additive preference migration; existing indexes do not change.
        this.version(6).stores({}).upgrade(async (tx) => {
            const projects = await tx.table<Project>("projects").toArray();
            const episodes = tx.table<Episode>("episodes");
            for (const project of projects) {
                const owned = await episodes.where("projectId").equals(project.id).toArray();
                for (const episode of owned) {
                    await episodes.update(episode.id, {shotFilters: getEpisodeShotFilters(episode, project)});
                }
            }
        });
        this.version(7).stores({productionProposals: "id, projectId, episodeId, status, createdAt"});
        this.version(8).stores({
            agents: "id",
            agentRuns: "id, threadId, status, createdAt",
        }).upgrade(async (tx) => {
            await tx.table<ChatMessage>("chatMessages").filter((message) =>
                message.status === "streaming" || message.status === "pending",
            ).modify((message) => {
                message.status = "interrupted";
                message.error = "上次生成已中断，已保留收到的内容。可重新发送问题。";
            });
        });
        this.version(9).stores({agentToolCalls: "id, runId, threadId, &[runId+providerCallId], status"});
        this.version(10).stores({
            agentTasks: "id, &threadId, lifecycle, updatedAt",
            agentRuns: "id, threadId, taskId, status, createdAt"
        });
        this.version(11).stores({contextCompactions: "id, threadId, runId, status, createdAt"});
        this.version(12).stores({agentGenerationJobs: "id, &callId, runId, threadId, projectId, status, fingerprint, updatedAt"});
        this.version(13).stores({
            agentTaskRecords: "id, taskId, [taskId+kind], updatedAt",
            agentTaskRecordVersions: "versionId, taskId, recordId, &[recordId+revision]"
        });
        this.version(14).stores({
            agentTaskWrapups: "id, taskId, threadId, status, createdAt",
            agentTaskWrapupVersions: "versionId, taskId, threadId, &[id+revision]"
        });
        this.version(15).stores({
            chatThreads: "id, projectId, updatedAt",
            agentTasks: "id, &threadId, projectId, lifecycle, updatedAt",
            agentRuns: "id, threadId, taskId, projectId, status, createdAt"
        });
        this.version(16).stores({
            projectMemories: "id, projectId, [projectId+status], updatedAt",
            projectMemoryVersions: "versionId, projectId, memoryId, &[memoryId+revision]"
        });
        this.version(19).stores({searchConnections: "id"});
        this.version(18).stores({
            agentGenerationBatches: "id, &sourceCallId, projectId, threadId, runId, taskId, status, updatedAt",
            agentGenerationBatchItems: "id, batchId, projectId, threadId, &jobId",
            agentGenerationJobs: "id, &callId, &batchItemId, batchId, runId, threadId, projectId, status, fingerprint, updatedAt",
        });
        this.version(17).stores({
            projectReferences: "id, projectId, mediaId, [projectId+digest], updatedAt",
            referenceChunks: "id, projectId, referenceId, &[referenceId+revision+index]"
        });
        // Deduplicate before creating the unique index: preserve old IDs outside the
        // selectable connector table, without rewriting frozen run/job fingerprints.
        this.version(20).stores({connectorAliases: "id, definitionId"}).upgrade(async (tx) => {
            const connectors = tx.table<ConnectorConfig>("connectors");
            const rows = await connectors.toArray();
            rows.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt) || b.id.localeCompare(a.id));
            const seen = new Set<string>();
            for (const row of rows) {
                if (!seen.has(row.definitionId)) {
                    seen.add(row.definitionId);
                    continue;
                }
                await tx.table<ConnectorConfig>("connectorAliases").put(row);
                await connectors.delete(row.id);
            }
        });
        this.version(21).stores({connectors: "id, &definitionId, updatedAt"});
        this.version(22).stores({
            ipProfiles: "id, updatedAt",
            projectIpLinks: "projectId, ipId",
            libraryMaterials: "id, kind, scope.kind, scope.id, updatedAt",
            materialVersions: "id, materialId, &[materialId+revision]",
            materialUses: "id, materialId, projectId, targetId, [materialId+projectId]",
            materialEvents: "id, materialId, createdAt",
        });
        this.version(23).stores({
            projects: "id, kind, updatedAt",
            audioChapters: "id, projectId, order",
            audioSpeakers: "id, projectId",
            audioSegments: "id, projectId, chapterId, speakerId, order",
            audioTakes: "id, projectId, segmentId, mediaId",
            audioTracks: "id, projectId, chapterId, order",
            audioClips: "id, projectId, chapterId, trackId, takeId",
            audioExports: "id, projectId, mediaId",
            musicDrafts: "id, projectId",
            musicWorks: "id, projectId, mediaId",
            audioGenerationJobs: "id, projectId, &intentId, status, updatedAt",
        });
    }
}

export const db = new AifenjingDB();

import {db} from './database';
import type {Table} from 'dexie';
import type {
    LibraryMaterial,
    MaterialEntity,
    MaterialKind,
    MaterialPayload,
    MaterialScope,
    MaterialUse,
    MaterialVersion,
    SettingMaterialKind
} from '@/domain/materials';
import {remapSlot, slotMediaIds} from '@/domain/slot';
import {createId, nowIso} from '@/lib/ids';
import {STUDIO_LIBRARY_ID} from '@/domain/types';

const tables = () => [db.projects, db.ipProfiles, db.projectIpLinks, db.libraryMaterials, db.materialVersions, db.materialUses, db.materialEvents, db.media, db.characters, db.scenes, db.props, db.styles];
const MAX_FILE_SIZE = 512 * 1024 * 1024;
const MIME_KINDS: Record<string, MaterialKind> = {
    'image/png': 'image',
    'image/jpeg': 'image',
    'image/webp': 'image',
    'image/gif': 'image',
    'image/avif': 'image',
    'video/mp4': 'video',
    'video/webm': 'video',
    'video/quicktime': 'video',
    'audio/mpeg': 'audio',
    'audio/mp3': 'audio',
    'audio/wav': 'audio',
    'audio/x-wav': 'audio',
    'audio/ogg': 'audio',
    'audio/mp4': 'audio',
    'audio/webm': 'audio',
    'audio/flac': 'audio',
    'audio/aac': 'audio',
    'text/plain': 'document',
    'text/markdown': 'document',
    'application/pdf': 'document',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'document',
};
const EXT_MIME: Record<string, string> = {
    png: 'image/png',
    jpg: 'image/jpeg',
    jpeg: 'image/jpeg',
    webp: 'image/webp',
    gif: 'image/gif',
    avif: 'image/avif',
    mp4: 'video/mp4',
    webm: 'video/webm',
    mov: 'video/quicktime',
    mp3: 'audio/mpeg',
    wav: 'audio/wav',
    ogg: 'audio/ogg',
    m4a: 'audio/mp4',
    flac: 'audio/flac',
    aac: 'audio/aac',
    txt: 'text/plain',
    md: 'text/markdown',
    pdf: 'application/pdf',
    docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
};

function filePayload(blob: Blob, filename: string, mime: string): { kind: MaterialKind; payload: MaterialPayload } {
    if (!blob || !Number.isFinite(blob.size) || blob.size <= 0) throw new Error('文件为空，无法加入素材库');
    if (blob.size > MAX_FILE_SIZE) throw new Error('单个素材文件不能超过 512 MB');
    const extension = filename.split('.').pop()?.toLowerCase() ?? '';
    if (['svg', 'html', 'htm', 'js', 'exe', 'xml'].includes(extension)) throw new Error('不支持此文件格式，请使用图片、视频、音频、TXT、Markdown、PDF 或 DOCX');
    const mimeType = (mime || EXT_MIME[extension] || '').toLowerCase();
    const kind = MIME_KINDS[mimeType.split(";")[0].trim()];
    if (!kind) throw new Error('不支持此文件格式，请使用图片、视频、音频、TXT、Markdown、PDF 或 DOCX');
    return {kind, payload: {type: 'file', blob: blob.slice(0, blob.size, mimeType), filename, mimeType}};
}

function validName(name: string): string {
    if (typeof name !== 'string' || !name.trim() || name.length > 300) throw new Error('请填写 1–300 字的素材名称');
    return name.trim();
}

async function assertScope(scope: MaterialScope): Promise<void> {
    if (scope.kind === 'global') return;
    if (scope.kind === 'ip') {
        const ip = await db.ipProfiles.get(scope.id);
        if (!ip || ip.archived) throw new Error('所属 IP 不存在或已归档，请先恢复 IP');
    } else if (scope.kind === 'project') {
        const project = await db.projects.get(scope.id);
        if (!project || project.archivedAt) throw new Error('所属项目不存在或已归档');
    } else throw new Error('素材归属无效');
}

async function activeMaterial(id: string, expectedRevision?: number): Promise<LibraryMaterial> {
    const material = await db.libraryMaterials.get(id);
    if (!material) throw new Error('素材不存在');
    if (material.archived) throw new Error('素材已归档，请先恢复');
    if (expectedRevision !== undefined && material.revision !== expectedRevision) throw new Error('素材已更新，请重新加载后再操作');
    await assertScope(material.scope);
    return material;
}

async function versionOf(material: LibraryMaterial): Promise<MaterialVersion> {
    const version = await db.materialVersions.where('[materialId+revision]').equals([material.id, material.revision]).first();
    if (!version) throw new Error('素材版本缺失，无法继续操作');
    return version;
}

async function event(materialId: string, action: string, detail = ''): Promise<void> {
    await db.materialEvents.add({id: createId('mev'), materialId, action, detail, createdAt: nowIso()});
}

async function insertMaterial(name: string, kind: MaterialKind, scope: MaterialScope, payload: MaterialPayload, source?: LibraryMaterial['source'], metadata?: Pick<LibraryMaterial, 'notes' | 'tags'>): Promise<LibraryMaterial> {
    await assertScope(scope);
    const at = nowIso();
    const material: LibraryMaterial = {
        id: createId('mat'),
        name: validName(name),
        kind,
        scope: structuredClone(scope),
        revision: 1,
        archived: false,
        notes: metadata?.notes ?? '',
        tags: [...(metadata?.tags ?? [])],
        source,
        createdAt: at,
        updatedAt: at
    };
    await db.libraryMaterials.add(material);
    await db.materialVersions.add({id: createId('mvr'), materialId: material.id, revision: 1, payload, createdAt: at});
    await event(material.id, source ? 'promote' : 'create');
    return material;
}

async function nextVersion(material: LibraryMaterial, payload: MaterialPayload, patch: Partial<Pick<LibraryMaterial, 'name' | 'notes' | 'tags'>> = {}): Promise<void> {
    const at = nowIso();
    const revision = material.revision + 1;
    await db.materialVersions.add({id: createId('mvr'), materialId: material.id, revision, payload, createdAt: at});
    await db.libraryMaterials.put({...material, ...patch, revision, updatedAt: at});
    await event(material.id, 'version', `v${revision}`);
}

function settingTable(kind: SettingMaterialKind): Table<MaterialEntity, string> {
    return (kind === 'character' ? db.characters : kind === 'scene' ? db.scenes : kind === 'prop' ? db.props : db.styles) as Table<MaterialEntity, string>;
}

function isSetting(kind: MaterialKind | 'media'): kind is SettingMaterialKind {
    return ['character', 'scene', 'prop', 'style'].includes(kind);
}

async function snapshotSetting(kind: SettingMaterialKind, entityId: string): Promise<Extract<MaterialPayload, {
    type: 'setting'
}>> {
    const entity = await settingTable(kind).get(entityId);
    if (!entity) throw new Error('来源设定不存在');
    if (entity.projectId !== STUDIO_LIBRARY_ID && !await db.projects.get(entity.projectId)) throw new Error('来源项目不存在');
    const media = [];
    const ids = new Set<string>();
    for (const slot of Object.values(entity.slots)) if (slot) {
        for (const id of slotMediaIds(slot)) ids.add(id);
        for (const [kindExpected, references] of [['image', slot.referenceImageIds], ['video', slot.referenceVideoIds], ...(slot.result ? [[slot.result.kind, [slot.result.mediaId]]] : [])] as Array<[string, string[]]>) {
            for (const id of references) {
                const item = await db.media.get(id);
                if (!item || item.projectId !== entity.projectId) throw new Error('来源设定引用的素材缺失或不属于同一项目');
                if (filePayload(item.blob, item.filename, item.mimeType).kind !== kindExpected) throw new Error('来源设定素材类型与槽位不一致');
            }
        }
    }
    for (const id of ids) {
        const item = (await db.media.get(id))!;
        media.push({...item, blob: item.blob.slice(0, item.blob.size, item.mimeType)});
    }
    return {type: 'setting', kind, entity: structuredClone(entity), media};
}

export async function createFileMaterial(file: File, scope: MaterialScope, name?: string): Promise<LibraryMaterial> {
    const {kind, payload} = filePayload(file, file.name, file.type);
    return db.transaction('rw', tables(), async () => await insertMaterial(name ?? file.name, kind, scope, payload));
}

export async function promoteLegacyMaterial(kind: MaterialKind | 'media', entityId: string, scope: MaterialScope): Promise<LibraryMaterial> {
    return db.transaction('rw', tables(), async () => {
        if (isSetting(kind)) {
            const payload = await snapshotSetting(kind, entityId);
            return insertMaterial(payload.entity.name, kind, scope, payload, {
                projectId: payload.entity.projectId,
                entityId
            });
        }
        const media = await db.media.get(entityId);
        if (!media) throw new Error('来源素材不存在');
        if (media.projectId !== STUDIO_LIBRARY_ID && !await db.projects.get(media.projectId)) throw new Error('来源项目不存在');
        const parsed = filePayload(media.blob, media.filename, media.mimeType);
        if (kind !== 'media' && kind !== parsed.kind) throw new Error('来源素材类型不匹配');
        return insertMaterial(media.filename, parsed.kind, scope, parsed.payload, {
            projectId: media.projectId,
            entityId
        });
    });
}

export async function promoteMaterial(id: string, scope: MaterialScope): Promise<LibraryMaterial> {
    return db.transaction('rw', tables(), async () => {
        const material = await activeMaterial(id);
        const version = await versionOf(material);
        return insertMaterial(material.name, material.kind, scope, version.payload, {
            materialId: id,
            revision: material.revision
        }, material);
    });
}

export async function addFileMaterialVersion(id: string, file: File, expectedRevision: number): Promise<void> {
    const parsed = filePayload(file, file.name, file.type);
    await db.transaction('rw', tables(), async () => {
        const material = await activeMaterial(id, expectedRevision);
        if (material.kind !== parsed.kind) throw new Error('新版本必须与原素材属于同一类型');
        await nextVersion(material, parsed.payload);
    });
}

export async function refreshSettingMaterial(id: string, expectedRevision: number): Promise<void> {
    await db.transaction('rw', tables(), async () => {
        const material = await activeMaterial(id, expectedRevision);
        if (!isSetting(material.kind) || !material.source?.entityId) throw new Error('此素材没有可刷新版本的来源设定');
        const payload = await snapshotSetting(material.kind, material.source.entityId);
        if (payload.entity.projectId !== material.source.projectId) throw new Error('来源设定归属已变化');
        await nextVersion(material, payload);
    });
}

export async function updateMaterialMetadata(id: string, patch: Partial<Pick<LibraryMaterial, 'name' | 'notes' | 'tags'>>, expectedRevision: number): Promise<void> {
    const safe: typeof patch = {};
    if (patch.name !== undefined) safe.name = validName(patch.name);
    if (patch.notes !== undefined) {
        if (typeof patch.notes !== 'string' || patch.notes.length > 20_000) throw new Error('素材备注过长');
        safe.notes = patch.notes;
    }
    if (patch.tags !== undefined) {
        if (!Array.isArray(patch.tags) || patch.tags.length > 50 || patch.tags.some(tag => typeof tag !== 'string' || tag.length > 100)) throw new Error('标签无效或过长');
        safe.tags = [...new Set(patch.tags.map(tag => tag.trim()).filter(Boolean))];
    }
    await db.transaction('rw', tables(), async () => {
        const material = await activeMaterial(id, expectedRevision);
        await nextVersion(material, (await versionOf(material)).payload, safe);
    });
}

export async function setMaterialArchived(id: string, archived: boolean): Promise<void> {
    await db.transaction('rw', tables(), async () => {
        const material = await db.libraryMaterials.get(id);
        if (!material) throw new Error('素材不存在');
        if (material.archived === archived) return;
        if (!archived) await assertScope(material.scope);
        await nextVersion(material, (await versionOf(material)).payload);
        await db.libraryMaterials.update(id, {archived});
        await event(id, archived ? 'archive' : 'restore');
    });
}

export async function deleteMaterial(id: string): Promise<void> {
    await db.transaction('rw', tables(), async () => {
        const material = await db.libraryMaterials.get(id);
        if (!material) throw new Error('素材不存在');
        if (!material.archived) throw new Error('请先归档素材，再彻底删除');
        if (await db.materialUses.where('materialId').equals(id).count()) throw new Error('素材仍被项目使用，无法彻底删除');
        if (await db.libraryMaterials.filter(item => item.source?.materialId === id).count()) throw new Error('素材仍是其他素材的来源，无法彻底删除');
        await db.materialVersions.where('materialId').equals(id).delete();
        await db.libraryMaterials.delete(id);
        await event(id, 'delete', material.name);
    });
}

function fingerprint(entity: MaterialEntity): string {
    // Stable sorting prevents incidental key order from looking like an authored edit.
    const stable = (value: unknown): unknown => Array.isArray(value) ? value.map(stable) : value && typeof value === 'object' ? Object.fromEntries(Object.entries(value).sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => [key, stable(item)])) : value;
    return JSON.stringify(stable(entity));
}

async function assertProjectScope(material: LibraryMaterial, projectId: string): Promise<void> {
    if (material.scope.kind === 'global') return;
    if (material.scope.kind === 'project') {
        if (material.scope.id !== projectId) throw new Error('项目专属素材只能用于所属项目，请先明确加入通用或 IP 素材');
        return;
    }
    const link = await db.projectIpLinks.get(projectId);
    if (link?.ipId !== material.scope.id) throw new Error('IP 专属素材只能用于关联同一 IP 的项目');
}

async function adopt(material: LibraryMaterial, projectId: string): Promise<MaterialUse> {
    await assertProjectScope(material, projectId);
    const project = await db.projects.get(projectId);
    if (!project || project.archivedAt) throw new Error('目标项目不存在或已归档');
    const version = await versionOf(material);
    const at = nowIso();
    const use: MaterialUse = {
        id: createId('mus'),
        materialId: material.id,
        revision: material.revision,
        projectId,
        targetKind: 'media',
        targetId: '',
        mediaIds: [],
        createdAt: at,
        updatedAt: at
    };
    const payload = version.payload;
    if (payload.type === 'file') {
        filePayload(payload.blob, payload.filename, payload.mimeType);
        use.targetId = createId('med');
        use.mediaIds = [use.targetId];
        await db.media.add({
            id: use.targetId,
            projectId,
            libraryRetained: true,
            blob: payload.blob,
            filename: payload.filename,
            mimeType: payload.mimeType
        });
    } else {
        const map = new Map<string, string>();
        for (const item of payload.media) {
            const id = createId('med');
            map.set(item.id, id);
            filePayload(item.blob, item.filename, item.mimeType);
            await db.media.add({...item, id, projectId, libraryRetained: true});
            use.mediaIds.push(id);
        }
        for (const slot of Object.values(payload.entity.slots)) for (const id of slotMediaIds(slot)) if (!map.has(id)) throw new Error('素材版本包含缺失的图片或视频');
        const prefixes = {character: 'chr', scene: 'scn', prop: 'prp', style: 'sty'};
        const entity: MaterialEntity = {
            ...structuredClone(payload.entity),
            id: createId(prefixes[payload.kind]),
            projectId,
            createdAt: at,
            updatedAt: at,
            slots: Object.fromEntries(Object.entries(payload.entity.slots).filter(([, slot]) => slot).map(([key, slot]) => [key, remapSlot(slot!, id => id ? map.get(id) : undefined)])),
            extra: {...payload.entity.extra, sourceMaterialId: material.id, sourceMaterialRevision: material.revision}
        };
        await settingTable(payload.kind).add(entity);
        use.targetId = entity.id;
        use.targetKind = payload.kind;
        use.targetFingerprint = fingerprint(entity);
    }
    await db.materialUses.add(use);
    await db.projects.update(projectId, {updatedAt: at});
    await event(material.id, 'use', projectId);
    return use;
}

export async function useMaterialInProject(id: string, projectId: string): Promise<MaterialUse> {
    return db.transaction('rw', tables(), async () => {
        const material = await activeMaterial(id);
        await assertProjectScope(material, projectId);
        const project = await db.projects.get(projectId);
        if (!project || project.archivedAt) throw new Error('目标项目不存在或已归档');
        const existing = await db.materialUses.where('[materialId+projectId]').equals([id, projectId]).filter(use => use.revision === material.revision && !use.supersededBy).toArray();
        for (const use of existing) {
            const target = use.targetKind === 'media' ? await db.media.get(use.targetId) : await settingTable(use.targetKind).get(use.targetId);
            if (target?.projectId === projectId) return use;
        }
        return adopt(material, projectId);
    });
}

export async function updateMaterialUse(useId: string): Promise<MaterialUse> {
    return db.transaction('rw', tables(), async () => {
        const use = await db.materialUses.get(useId);
        if (!use) throw new Error('素材使用记录不存在');
        if (use.supersededBy) throw new Error('此使用记录已有更新，请选择最新记录');
        const material = await activeMaterial(use.materialId);
        await assertProjectScope(material, use.projectId);
        const project = await db.projects.get(use.projectId);
        if (!project || project.archivedAt) throw new Error('目标项目不存在或已归档');
        if (use.revision === material.revision) {
            const target = use.targetKind === 'media' ? await db.media.get(use.targetId) : await settingTable(use.targetKind).get(use.targetId);
            if (!target || target.projectId !== use.projectId) throw new Error('项目内的素材副本已删除或归属变化，请重新加入项目');
            return use;
        }
        if (use.targetKind !== 'media') {
            const entity = await settingTable(use.targetKind).get(use.targetId);
            if (!entity || entity.projectId !== use.projectId) throw new Error('项目内的设定已删除或归属变化');
            if (fingerprint(entity) !== use.targetFingerprint) throw new Error('项目内的设定已有本地修改，不能更新。请另行加入新版本以保留修改');
        }
        const next = await adopt(material, use.projectId);
        await db.materialUses.put({...use, supersededBy: next.id, updatedAt: nowIso()});
        await event(material.id, 'update-use', `${use.revision} → ${next.revision}`);
        return next;
    });
}

export async function listMaterialUsage(id: string): Promise<MaterialUse[]> {
    return db.materialUses.where('materialId').equals(id).toArray();
}

import {db} from "./database";
import {
    patchShot,
    PRODUCTION_TABLES,
    setCharacterSlot,
    setPropSlot,
    setSceneSlot,
    setShotSlot,
    setStyleSlot
} from "./repo";
import type {ProductionChange, ProductionProposal, ProductionTarget, ProposalSource} from "@/domain/production";
import type {GenerationResult, GenerationSlot} from "@/domain/types";
import {emptySlot} from "@/domain/slot";
import {createId, nowIso} from "@/lib/ids";
import {targetRevision, validateProductionTarget} from "@/lib/productionRevision";
import {flushPendingDrafts} from "@/lib/debouncedDraft";

async function readTarget(target: ProductionTarget) {
    if (!(await db.projects.get(target.projectId))) throw new Error("项目不存在");
    const entity = target.kind === "shot" ? await db.shots.get(target.entityId)
        : target.kind === "character" ? await db.characters.get(target.entityId)
            : target.kind === "scene" ? await db.scenes.get(target.entityId)
                : target.kind === "prop" ? await db.props.get(target.entityId) : await db.styles.get(target.entityId);
    if (!entity || entity.projectId !== target.projectId) throw new Error("变更目标不存在或不属于当前项目");
    if (target.kind === "shot") {
        const episode = await db.episodes.get(target.episodeId);
        if (!episode || episode.projectId !== target.projectId || !("episodeId" in entity) || entity.episodeId !== target.episodeId) {
            throw new Error("镜头不属于当前故事");
        }
    }
    let slot: GenerationSlot | undefined;
    if (target.slot) {
        if ("slots" in entity) {
            const slots: Partial<Record<string, GenerationSlot>> = entity.slots;
            slot = slots[target.slot] ?? emptySlot();
        } else if (target.slot === "firstFrame" || target.slot === "lastFrame" || target.slot === "clip") {
            slot = entity[target.slot];
        }
    }
    return {entity, slot, revision: targetRevision(entity)};
}

function normalizeChange(target: ProductionTarget, change: ProductionChange): ProductionChange {
    if (change.kind === "shot-text") {
        if (target.kind !== "shot" || target.slot) throw new Error("文字提案必须指向镜头文字");
        const patch: Extract<ProductionChange, { kind: "shot-text" }>["patch"] = {};
        for (const key of ["content", "notes"] as const) {
            if (Object.hasOwn(change.patch, key)) {
                if (typeof change.patch[key] !== "string") throw new Error("内容与备注必须是文字");
                patch[key] = change.patch[key];
            }
        }
        if (Object.hasOwn(change.patch, "durationSec")) {
            const duration = change.patch.durationSec;
            if (typeof duration !== "number" || !Number.isFinite(duration) || duration < 0) throw new Error("时长必须是非负数");
            patch.durationSec = duration;
        }
        if (!Object.keys(patch).length) throw new Error("提案没有可修改的内容");
        return {kind: "shot-text", patch};
    }
    if (change.kind !== "slot-result" || !target.slot || !change.result?.mediaId ||
        (change.result.kind !== "image" && change.result.kind !== "video")) throw new Error("素材提案缺少有效目标或结果");
    if (change.result.kind === "video" && !(target.kind === "shot" && target.slot === "clip")) throw new Error("此槽位只能接收图片");
    return {kind: "slot-result", result: {mediaId: change.result.mediaId, kind: change.result.kind}};
}

async function validateResult(projectId: string, result: GenerationResult | undefined) {
    if (!result) return;
    const media = await db.media.get(result.mediaId);
    if (!media || media.projectId !== projectId || media.blob.size === 0 || !media.mimeType.startsWith(`${result.kind}/`)) {
        throw new Error("素材不存在、类型不匹配或不属于当前项目，请重新选择");
    }
}

function normalizeSource(source: ProposalSource): ProposalSource {
    const nonempty = (value: unknown): value is string => typeof value === "string" && Boolean(value.trim());
    if (source.kind === "manual") return {kind: "manual"};
    if (source.kind !== "generation" || !nonempty(source.intentId) || !nonempty(source.provider) || !nonempty(source.model) || !Array.isArray(source.sourceRevisions)) {
        throw new Error("生成来源信息不完整");
    }
    if (source.providerTaskId !== undefined && !nonempty(source.providerTaskId)) throw new Error("供应商任务标识无效");
    for (const item of source.sourceRevisions) {
        if (!item || !nonempty(item.kind) || !nonempty(item.id) || !nonempty(item.revision) || !/^sha256-v1:[a-f0-9]{64}$/.test(item.revision)) {
            throw new Error("生成来源版本无效");
        }
    }
    return {
        kind: "generation", intentId: source.intentId, provider: source.provider, model: source.model,
        providerTaskId: source.providerTaskId,
        sourceRevisions: source.sourceRevisions.map(({kind, id, revision}) => ({kind, id, revision}))
    };
}

export async function createProductionProposal(input: {
    target: ProductionTarget; change: ProductionChange; source: ProposalSource; expectedRevision?: string;
}): Promise<ProductionProposal> {
    const target = validateProductionTarget(input.target);
    const change = normalizeChange(target, input.change);
    const source = normalizeSource(input.source);
    if (source.kind === "generation" && (!input.expectedRevision || !source.sourceRevisions.some((item) =>
        item.kind === target.kind && item.id === target.entityId && item.revision === input.expectedRevision))) {
        throw new Error("生成提案必须提供匹配目标的原始版本");
    }
    await flushPendingDrafts(target.projectId);
    return db.transaction("rw", PRODUCTION_TABLES, async () => {
        const current = await readTarget(target);
        if (input.expectedRevision !== undefined && current.revision !== input.expectedRevision) throw new Error("目标已被修改，请重新查看后创建提案");
        const before: ProductionProposal["before"] = {};
        if (change.kind === "shot-text" && "content" in current.entity) {
            for (const key of ["content", "notes", "durationSec"] as const) {
                if (Object.hasOwn(change.patch, key)) Object.assign(before, {[key]: current.entity[key]});
            }
        } else if (change.kind === "slot-result") {
            await validateResult(target.projectId, change.result);
            before.result = current.slot?.result;
        }
        const at = nowIso();
        const proposal: ProductionProposal = {
            id: createId("prpchange"), projectId: target.projectId,
            episodeId: target.kind === "shot" ? target.episodeId : undefined, target, change, source, before,
            baseRevision: current.revision, status: "pending", createdAt: at, updatedAt: at
        };
        await db.productionProposals.add(proposal);
        return proposal;
    });
}

async function writeResult(target: ProductionTarget, slot: GenerationSlot) {
    switch (target.kind) {
        case "shot":
            if (!target.slot) throw new Error("缺少素材槽位");
            return setShotSlot(target.entityId, target.slot, slot);
        case "character":
            return setCharacterSlot(target.entityId, target.slot, slot);
        case "scene":
            return setSceneSlot(target.entityId, target.slot, slot);
        case "prop":
            return setPropSlot(target.entityId, target.slot, slot);
        case "style":
            return setStyleSlot(target.entityId, target.slot, slot);
    }
}

async function mutateProposal(id: string, projectId: string, action: "apply" | "cancel" | "undo") {
    await flushPendingDrafts(projectId);
    return db.transaction("rw", PRODUCTION_TABLES, async () => {
        const proposal = await db.productionProposals.get(id);
        if (!proposal || proposal.projectId !== projectId) throw new Error("提案不存在或不属于当前项目");
        const completed = action === "apply" ? "applied" : action === "cancel" ? "cancelled" : "undone";
        if (proposal.status === completed) return proposal;
        if (proposal.status !== (action === "undo" ? "applied" : "pending")) throw new Error("提案状态已变化，无法执行此操作");
        if (action !== "cancel") {
            const target = validateProductionTarget(proposal.target);
            if (target.projectId !== projectId) throw new Error("提案目标与项目不匹配");
            const current = await readTarget(target);
            const expected = action === "undo" ? proposal.appliedRevision : proposal.baseRevision;
            if (current.revision !== expected) throw new Error(action === "undo"
                ? "目标已有新的修改，无法撤销；你的当前内容已保留"
                : "目标已被修改，提案未应用。请取消此提案，查看最新内容后重新创建");
            const change = normalizeChange(target, proposal.change);
            if (change.kind === "shot-text") {
                const patch = action === "undo" ? {...proposal.before} : change.patch;
                delete (patch as ProductionProposal["before"]).result;
                await patchShot(target.entityId, patch);
            } else {
                const result = action === "undo" ? proposal.before.result : change.result;
                await validateResult(projectId, result);
                await writeResult(target, {...(current.slot ?? emptySlot()), result});
            }
            if (action === "apply") proposal.appliedRevision = (await readTarget(target)).revision;
        }
        const updated: ProductionProposal = {...proposal, status: completed, updatedAt: nowIso()};
        await db.productionProposals.put(updated);
        return updated;
    });
}

export const applyProductionProposal = (id: string, projectId: string) => mutateProposal(id, projectId, "apply");
export const cancelProductionProposal = (id: string, projectId: string) => mutateProposal(id, projectId, "cancel");
export const undoProductionProposal = (id: string, projectId: string) => mutateProposal(id, projectId, "undo");

