export async function deleteStyle(id: Id): Promise<void> {
    await db.transaction("rw", PRODUCTION_TABLES, async () => {
        const style = await db.styles.get(id);
        if (!style) return;
        const mediaIds = collectSlotsMedia(Object.values(style.slots));
