}

export type UpsertConnectorInput = {
    definitionId: ConnectorDefinitionId;
    protocol: ConnectorProtocol;
    baseUrl: string;
    apiKey: string;
    label?: string;
};

/** One saved config per catalog definitionId. */
export async function upsertConnector(input: UpsertConnectorInput): Promise<ConnectorConfig> {
    const baseUrl = normalizeBaseUrl(input.baseUrl);
    const apiKey = input.apiKey.trim();
    if (!baseUrl) throw new Error("请填写 Base URL");
    if (!apiKey) throw new Error("请填写 API Key");

    return db.transaction("rw", db.connectors, db.connectorAliases, async () => {
        const existing = await getConnectorByDefinition(input.definitionId);
        const record: ConnectorConfig = {
            id: existing?.id ?? createId("conn"),
            definitionId: input.definitionId,
            protocol: input.protocol,
            label: input.label?.trim() || undefined,
            baseUrl,
            apiKey,
            updatedAt: nowIso(),
        };
        await db.connectors.put(record);
        // Explicit edits (including key rotation) apply to retained historical IDs.
        await db.connectorAliases.where("definitionId").equals(input.definitionId).modify((alias) => {
            Object.assign(alias, {...record, id: alias.id});
        });
        return record;
    });
}

/** Resolve a frozen historical ID without exposing retired duplicates in pickers. */
export async function resolveConnector(id: Id): Promise<ConnectorConfig | undefined> {
    return (await db.connectors.get(id)) ?? db.connectorAliases.get(id);
}

export async function deleteConnector(id: Id): Promise<void> {
    await db.transaction("rw", db.connectors, db.connectorAliases, async () => {
        const config = await resolveConnector(id);
        if (!config) return;
        await db.connectors.where("definitionId").equals(config.definitionId).delete();
        await db.connectorAliases.where("definitionId").equals(config.definitionId).delete();
    });
}

export async function listChatThreads(): Promise<ChatThread[]> {
    return db.chatThreads.orderBy("updatedAt").reverse().toArray();
}

export async function getChatThread(id: Id): Promise<ChatThread | undefined> {
    return db.chatThreads.get(id);
}

export async function createChatThread(options?: {
    projectId?: Id;
    taskMode?: boolean;
    title?: string;
    connectorId?: Id;
    model?: string;
}): Promise<ChatThread> {
    const at = nowIso();
    const thread: ChatThread = {
        contextPolicy: normalizeContextPolicy((await getGeneralAgentConfig()).contextPolicy),
        id: createId("cth"),
        title: options?.title?.trim() || "新对话",
        taskMode: options?.taskMode === true,
        projectId: options?.projectId,
        connectorId: options?.connectorId,
        model: options?.model?.trim() || undefined,
        createdAt: at,
        updatedAt: at,
    };
    await db.transaction("rw", [db.chatThreads, db.projects], async () => {
        if (thread.projectId && (thread.projectId === STUDIO_LIBRARY_ID || !await db.projects.get(thread.projectId))) throw new Error("请选择可用项目");
        await db.chatThreads.add(thread);
    });
    return thread;
}

export async function updateChatThread(
    id: Id,
    patch: Partial<Pick<ChatThread, "title" | "connectorId" | "model" | "reasoningSelection" | "interactionMode">>,
): Promise<void> {
    await db.transaction("rw", db.chatThreads, async () => {
        const existing = await db.chatThreads.get(id);
        if (!existing) return;
        const next: ChatThread = {
            ...existing,
            updatedAt: nowIso(),
        };
        if (patch.title !== undefined) {
            const title = patch.title.trim();
            next.title = title || existing.title;
        }
        if (patch.connectorId !== undefined) {
            next.connectorId = patch.connectorId || undefined;
        }
        if (patch.model !== undefined) {
            const model = patch.model.trim();
            next.model = model || undefined;
        }
        if (patch.interactionMode !== undefined) next.interactionMode = patch.interactionMode;
        if (patch.reasoningSelection !== undefined) next.reasoningSelection = patch.reasoningSelection;
        await db.chatThreads.put(next);
    });
}

export async function deleteChatThread(id: Id): Promise<void> {
    await db.transaction("rw", [...PRODUCTION_TABLES, db.chatThreads, db.chatMessages, db.agentRuns, db.agentToolCalls, db.agentTasks, db.contextCompactions, db.agentTaskRecords, db.agentTaskRecordVersions, db.agentTaskWrapups, db.agentTaskWrapupVersions], async () => {
        const jobs = await db.agentGenerationJobs.where("threadId").equals(id).toArray();
        const batches = await db.agentGenerationBatches.where("threadId").equals(id).toArray();
        const items = await db.agentGenerationBatchItems.where("threadId").equals(id).toArray();
        const jobMedia = new Set([...jobs.flatMap(job => [...job.inputs.map(input => input.mediaId), ...(job.result ? [job.result.mediaId] : [])]), ...items.flatMap(item => item.draft.inputs.map(input => input.mediaId)), ...batches.flatMap(batch => batch.applications.flatMap(a => [a.result.mediaId, ...(a.before ? [a.before.mediaId] : [])]))]);
        await db.agentGenerationBatches.where("threadId").equals(id).delete();
        await db.agentGenerationBatchItems.where("threadId").equals(id).delete();
        await db.agentGenerationJobs.where("threadId").equals(id).delete();
        await db.contextCompactions.where("threadId").equals(id).delete();
        for (const task of await db.agentTasks.where("threadId").equals(id).toArray()) {
            await db.agentTaskWrapups.where("taskId").equals(task.id).delete();
            await db.agentTaskWrapupVersions.where("taskId").equals(task.id).delete();
            await db.agentTaskRecords.where("taskId").equals(task.id).delete();
            await db.agentTaskRecordVersions.where("taskId").equals(task.id).delete();
        }
        await db.agentTasks.where("threadId").equals(id).delete();
        await db.agentToolCalls.where("threadId").equals(id).delete();
        await db.agentRuns.where("threadId").equals(id).delete();
        await db.chatMessages.where("threadId").equals(id).delete();
        await db.chatThreads.delete(id);
        for (const mediaId of jobMedia) await deleteMediaIfOrphan(mediaId);
    });
}

export async function listChatMessages(threadId: Id): Promise<ChatMessage[]> {
    return db.chatMessages.where("threadId").equals(threadId).sortBy("createdAt");
}

export async function appendChatMessage(input: {
    threadId: Id;
    role: ChatMessageRole;
    content?: string;
    status?: ChatMessageStatus;
}): Promise<ChatMessage> {
    const at = nowIso();
    const message: ChatMessage = {
        id: createId("cmsg"),
        threadId: input.threadId,
        role: input.role,
        content: input.content ?? "",
        createdAt: at,
        status: input.status,
    };
    await db.transaction("rw", db.chatThreads, db.chatMessages, async () => {
        const thread = await db.chatThreads.get(input.threadId);
        if (!thread) throw new Error("对话不存在");
        await db.chatMessages.put(message);
        await db.chatThreads.put({...thread, updatedAt: at});
    });
    return message;
}

export async function updateChatMessage(
    id: Id,
    patch: Partial<Pick<ChatMessage, "content" | "status" | "reasoning" | "reasoningDurationMs">>,
): Promise<void> {
    await db.transaction("rw", db.chatMessages, async () => {
        const existing = await db.chatMessages.get(id);
        if (!existing || existing.runId) return;
        await db.chatMessages.update(id, patch);
    });
}

/** Bind once before any conversation execution; changing projects starts a new thread. */
export async function bindChatThreadProject(threadId: string, projectId: string, expectedProjectId?: string): Promise<void> {
    await db.transaction("rw", [db.chatThreads, db.projects, db.agentRuns, db.chatMessages, db.agentTasks], async () => {
        const thread = await db.chatThreads.get(threadId);
        if (!thread || thread.projectId !== expectedProjectId) throw new Error("对话项目已变化，请重新读取");
        if (projectId === STUDIO_LIBRARY_ID || !await db.projects.get(projectId)) throw new Error("请选择可用项目");
        if (thread.projectId === projectId) return;
        if (thread.projectId || await db.agentRuns.where("threadId").equals(threadId).count() || await db.chatMessages.where("threadId").equals(threadId).count() || await db.agentTasks.where("threadId").equals(threadId).count()) throw new Error("已有对话不能切换项目，请新建对话");
        await db.chatThreads.update(threadId, {projectId, updatedAt: nowIso()});
    });
}

export async function assertVideoProject(projectId: Id): Promise<Project> {
    const project = await db.projects.get(projectId);
    if (!project) throw new Error("项目不存在");
    if (getProjectKind(project) !== "video") throw new Error("此操作仅适用于视频项目");
    return project;
}

export async function createAudioMusicProject(name: string, kind: "audio" | "music", ipId?: Id | null): Promise<Project> {
    if (kind !== "audio" && kind !== "music") throw new Error("不支持的项目类型");
    const project = {...emptyProject(name), kind};
    await db.transaction("rw", [db.projects, ...AUDIO_TABLES, db.ipProfiles, db.projectIpLinks], async () => {
        if (ipId) {
            const profile = await db.ipProfiles.get(ipId);
            if (!profile || profile.archived) throw new Error("请选择未归档的 IP");
            await db.projectIpLinks.add({projectId: project.id, ipId, updatedAt: nowIso()});
        }
        await db.projects.add(project);
        if (kind === "audio") {
            const chapter = newAudioRow<AudioChapter>(project.id, "ach", {title: "第一章", order: 0});
            await db.audioChapters.add(chapter);
            await db.audioTracks.add(newAudioRow<AudioTrack>(project.id, "atr", {
                chapterId: chapter.id,
                role: "voice",
                name: "人声",
                order: 0,
                gain: 1,
                muted: false,
                solo: false
            }));
        } else await db.musicDrafts.add(newAudioRow<MusicDraft>(project.id, "mdr", {settings: defaultMusicSettings()}));
    });
    return project;
}

import type {AgentTask, AgentToolCall} from "@/domain/agent";
import type {AudioGenerationJob} from "@/domain/audioGeneration";
import {inspectAudioGenerationOutputs} from "@/lib/audioGeneration/outputEvidence";
import {describeAudioGeneration} from "@/lib/audioGeneration/presentation";
import {db} from "./database";

type TaskOwner = Pick<AgentTask, "id" | "threadId">;
export const SOUND_GENERATION_TOOLS = ["audio_generate_speech", "music_generate", "audio_generation_check"] as const;

/** Origin belongs to the submitting task, never to a later status-reading call. */
export async function ownedTaskAudioGenerationJob(task: TaskOwner, job: AudioGenerationJob): Promise<boolean> {
    if (job.source.kind !== "agent" || job.dormant) return false;
    const current = await db.agentTasks.get(task.id);
    const run = await db.agentRuns.get(job.source.runId);
    const call = await db.agentToolCalls.get(job.source.callId);
    let args: unknown;
    try {
        args = JSON.parse(call?.arguments ?? "null");
    } catch {
        return false;
    }
    return !!current && current.threadId === task.threadId && current.projectId === job.projectId &&
        !!run && run.taskId === task.id && run.threadId === task.threadId && run.projectId === job.projectId &&
        !!call && call.runId === run.id && call.threadId === task.threadId && call.decision === "approve" && call.requiresConfirmation === true &&
        !!args && typeof args === "object" && "projectId" in args && args.projectId === job.projectId &&
        call.name === (job.input.kind === "speech" ? "audio_generate_speech" : "music_generate");
}

export async function taskAudioGenerationSource(task: TaskOwner, job: AudioGenerationJob) {
    if (!await ownedTaskAudioGenerationJob(task, job)) throw new Error("声音生成来源不属于当前任务或项目");
    const outputs = await inspectAudioGenerationOutputs(job);
    const presentation = describeAudioGeneration(job);
    const available = outputs.availableCount > 0;
    // A partial output is inspectable, but cannot certify the whole generation.
    const supportsResult = outputs.allAvailable && ["saved", "target-conflict"].includes(job.status);
    const applied = supportsResult && (outputs.selectedCount > 0 || outputs.timelineClipCount > 0);
    const input = job.input;
    const target = input.kind === "speech"
        ? {segmentId: input.segmentId, segmentRevision: input.segmentRevision}
        : {draftId: input.draftId, draftRevision: input.draftRevision};
    const body = JSON.stringify({
        jobId: job.id, projectId: job.projectId, kind: input.kind, revision: job.revision,
        source: job.source, status: job.status, statusLabel: presentation.label,
        checkedAt: presentation.checkedAt, target,
        taskObservations: job.taskObservations?.slice(0, 100).map(({
                                                                       taskId,
                                                                       checkedAt,
                                                                       status,
                                                                       lastVerified
                                                                   }) => ({
            taskId,
            checkedAt,
            status,
            lastVerified: lastVerified ? {status: lastVerified.status, observedAt: lastVerified.observedAt} : undefined
        })),
        outputs, available, supportsResult, appliedToCurrentTarget: applied,
        note: "来源保留原提交执行；读取不代表本轮提交。远端完成、当前本地成果和选用/入轨分别核实；未试听，不能据此判断声音质量。",
    });
    return {
        id: job.id,
        label: `${input.kind === "speech" ? "配音" : "音乐"} · ${job.connector.provider}`,
        available,
        applied,
        supportsResult,
        body
    };
}

/** Read-only validation of a saved sound tool result against its current durable job. */
export async function taskAudioToolSource(task: TaskOwner, call: AgentToolCall) {
    if (!(SOUND_GENERATION_TOOLS as readonly string[]).includes(call.name)) return undefined;
    let value: unknown;
    try {
        value = JSON.parse(call.result ?? "null");
    } catch {
        return undefined;
    }
    if (!value || typeof value !== "object" || !("id" in value) || typeof value.id !== "string") return undefined;
    const job = await db.audioGenerationJobs.get(value.id);
    if (!job || !await ownedTaskAudioGenerationJob(task, job)) return undefined;
    if (call.name !== "audio_generation_check" && (job.source.kind !== "agent" || job.source.callId !== call.id)) return undefined;
    if (call.name === "audio_generation_check") {
        let args: unknown;
        try {
            args = JSON.parse(call.arguments);
        } catch {
            return undefined;
        }
        if (!args || typeof args !== "object" || !("jobId" in args) || args.jobId !== job.id || !("projectId" in args) || args.projectId !== job.projectId) return undefined;
    }
    return taskAudioGenerationSource(task, job);
}

export type ImageEntityKind = 'shot' | 'character' | 'scene' | 'prop' | 'style';
export type ImageSourceKind = 'current' | 'reference' | 'candidate';
export type ImageSourceLocator =
    | {
    kind: 'slot';
    entityKind: ImageEntityKind;
    entityId: string;
    slot: string;
    source: 'current' | 'reference';
    mediaId?: string
}
    | { kind: 'reference'; referenceId: string }
    | { kind: 'job'; jobId: string };

export interface DiscoveredImage {
    id: string;
    projectId: string;
    projectName: string;
    episodeId?: string;
    episodeTitle?: string;
    entityKind: ImageEntityKind | 'reference';
    entityId: string;
    entityLabel: string;
    slot: string;
    slotLabel: string;
    source: ImageSourceKind;
    mediaId?: string;
    mimeType?: string;
    available: boolean;
    unavailableReason?: string;
    revision: string;
    locator: ImageSourceLocator;
    currentlyApplied?: boolean;
    target: { label: string; href: string };
}

export interface ImageDiscoveryResult {
    discoveryCallId: string;
    status: 'resolved' | 'ambiguous_project' | 'not_found';
    projects: Array<{ id: string; name: string }>;
    projectCount: number;
    candidates: DiscoveredImage[];
    total: number;
    offset: number;
    hasMore: boolean;
    note: string;
}

export interface ImageDiscoveryProvenance {
    discoveryCallId: string;
    candidateId: string;
    readCallId: string;
    mediaDigest: string
}

/** Only code-owned result metadata becomes a source link; no HTML or pixel auto-load. */
export function projectImageSources(name: string, result?: string): DiscoveredImage[] {
    if (!['discover_project_images', 'read_project_image'].includes(name) || !result) return [];
    try {
        const value = JSON.parse(result) as { candidates?: unknown[]; source?: unknown };
        const rows = name === 'discover_project_images' ? value.candidates : value.source ? [value.source] : [];
        if (!Array.isArray(rows)) return [];
        return rows.slice(0, 20).filter((raw): raw is DiscoveredImage => {
            if (!raw || typeof raw !== 'object') return false;
            const row = raw as DiscoveredImage;
            return [row.id, row.projectName, row.entityLabel, row.slotLabel].every((item) => typeof item === 'string') && ['current', 'reference', 'candidate'].includes(row.source) && typeof row.target?.href === 'string' && /^\/p\/(?!\/)/.test(row.target.href);
        });
    } catch {
        return [];
    }
}

/** Verified APIMart standard-channel profiles, independent of connector credentials. */
export const OUTPUT_PROFILE_VERSION = "2026-09-18";
export const IMAGE_RATIOS = ["1:1", "3:2", "2:3", "4:3", "3:4", "5:4", "4:5", "16:9", "9:16", "2:1", "1:2", "3:1", "1:3", "21:9", "9:21"] as const;
export const IMAGE_EXT_RATIOS = ["1:1", "16:9", "9:16", "4:3", "3:4", "3:2", "2:3", "5:4", "4:5", "21:9"] as const;
export const VIDEO_RATIOS = ["21:9", "16:9", "4:3", "1:1", "3:4", "9:16"] as const;
export const IMAGE_RESOLUTIONS = ["1k", "2k", "4k"] as const;
export const IMAGE_QUALITIES = ["low", "medium", "high", "xhigh", "max", "auto"] as const;
export const IMAGE_EXT_VERSIONS = ["flare", "sunburst"] as const;
export const VIDEO_RESOLUTIONS = ["768P", "2K"] as const;
export const APIMART_IMAGE_MODELS = ["gpt-image-2", "gpt-image-2.5-flare", "gpt-image-2.5-sunburst", "gpt-image-2.5-ext"] as const;
export type ApimartImageModel = typeof APIMART_IMAGE_MODELS[number];

export function isApimartImageModel(model: string): model is ApimartImageModel {
    return (APIMART_IMAGE_MODELS as readonly string[]).includes(model);
}

export function isApimartImage25(model: string): boolean {
    return model === "gpt-image-2.5-flare" || model === "gpt-image-2.5-sunburst";
}

export function isApimartImageExt(model: string): boolean {
    return model === "gpt-image-2.5-ext";
}

export function apimartImageSizes(model: string): readonly string[] {
    return isApimartImageExt(model) ? IMAGE_EXT_RATIOS : IMAGE_RATIOS;
}

// Strings deliberately retain unknown/older profiles for review after import.
export interface ImageGenerationDefaults {
    provider: string;
    model: string;
    profileVersion: string;
    size: string;
    resolution: string;
    quality?: string;
    version?: string;
    extra?: Record<string, unknown>;
}

export interface VideoGenerationDefaults {
    provider: string;
    model: string;
    profileVersion: string;
    mode: string;
    aspectRatio: string;
    resolution: string;
    duration: number;
    extra?: Record<string, unknown>;
}

export interface ProjectGenerationDefaults {
    image?: ImageGenerationDefaults;
    video?: VideoGenerationDefaults;
    extra?: Record<string, unknown>;
}

export function defaultImageGeneration(ratio = "16:9", model: ApimartImageModel = "gpt-image-2"): ImageGenerationDefaults {
    const sizes = apimartImageSizes(model);
    return {
        provider: "apimart", model, profileVersion: OUTPUT_PROFILE_VERSION,
        size: (sizes as readonly string[]).includes(ratio) ? ratio : "16:9", resolution: "1k",
        ...(isApimartImage25(model) ? {quality: "auto"} : {}),
        ...(isApimartImageExt(model) ? {version: "flare"} : {}),
    };
}

export function defaultVideoGeneration(ratio = "16:9"): VideoGenerationDefaults {
    return {
        provider: "apimart",
        model: "MiniMax-H3",
        profileVersion: OUTPUT_PROFILE_VERSION,
        mode: "text",
        aspectRatio: VIDEO_RATIOS.includes(ratio as typeof VIDEO_RATIOS[number]) ? ratio : "16:9",
        resolution: "2K",
        duration: 5
    };
}

function record(raw: unknown, label: string): Record<string, unknown> {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new Error(`${label}格式无效`);
    return raw as Record<string, unknown>;
}

function textField(raw: Record<string, unknown>, key: string): string {
    if (typeof raw[key] !== "string") throw new Error(`生成配置 ${key} 必须是文本`);
    return raw[key];
}

function optionalText(raw: Record<string, unknown>, key: string): string | undefined {
    return raw[key] === undefined ? undefined : textField(raw, key);
}

function extras(raw: Record<string, unknown>, known: string[]): Record<string, unknown> | undefined {
    const result = {...(raw.extra === undefined ? {} : record(raw.extra, "扩展配置"))};
    for (const [key, value] of Object.entries(raw)) {
        if (key !== "extra" && !known.includes(key)) result[key] = value;
    }
    return Object.keys(result).length ? result : undefined;
}

const IMAGE_KNOWN = ["provider", "model", "profileVersion", "size", "resolution", "quality", "version"];

/** Shape validation only: unknown models/unsupported values survive ZIP round trips. */
export function parseGenerationDefaults(raw: unknown): ProjectGenerationDefaults | undefined {
    if (raw === undefined) return undefined;
    const root = record(raw, "生成默认值");
    const parsed: ProjectGenerationDefaults = {extra: extras(root, ["image", "video"])};
    if (root.image !== undefined) {
        const image = record(root.image, "图片默认值");
        const quality = optionalText(image, "quality");
        const version = optionalText(image, "version");
        parsed.image = {
            provider: textField(image, "provider"), model: textField(image, "model"),
            profileVersion: textField(image, "profileVersion"), size: textField(image, "size"),
            resolution: textField(image, "resolution"), extra: extras(image, IMAGE_KNOWN),
            ...(quality !== undefined ? {quality} : {}),
            ...(version !== undefined ? {version} : {}),
        };
    }
    if (root.video !== undefined) {
        const video = record(root.video, "视频默认值");
        if (typeof video.duration !== "number" || !Number.isFinite(video.duration)) throw new Error("视频时长必须是有限数值");
        parsed.video = {
            provider: textField(video, "provider"),
            model: textField(video, "model"),
            profileVersion: textField(video, "profileVersion"),
            mode: textField(video, "mode"),
            aspectRatio: textField(video, "aspectRatio"),
            resolution: textField(video, "resolution"),
            duration: video.duration,
            extra: extras(video, ["provider", "model", "profileVersion", "mode", "aspectRatio", "resolution", "duration"]),
        };
    }
    return parsed;
}

export function validateGenerationDefaults(raw: unknown): string[] {
    let config: ProjectGenerationDefaults | undefined;
    try {
        config = parseGenerationDefaults(raw);
    } catch (error) {
        return [error instanceof Error ? error.message : "生成默认值格式无效"];
    }
    const issues: string[] = [];
    if (config?.image) {
        const image = config.image;
        if (image.provider !== "apimart" || !isApimartImageModel(image.model) || image.profileVersion !== OUTPUT_PROFILE_VERSION) {
            issues.push("图片配置版本或模型尚不支持，请明确选择已验证的 APIMart 图片模型或清除配置");
        } else {
            if (![...apimartImageSizes(image.model), "auto"].includes(image.size)) {
                issues.push(isApimartImageExt(image.model) ? "请选择 GPT Image 2.5 Ext 支持的图片比例" : "请选择 GPT Image 2 支持的图片比例");
            }
            if (!(IMAGE_RESOLUTIONS as readonly string[]).includes(image.resolution)) issues.push("图片清晰度须为 1k、2k 或 4k");
            if (isApimartImage25(image.model)) {
                if (image.quality !== undefined && !(IMAGE_QUALITIES as readonly string[]).includes(image.quality)) issues.push("请选择 GPT Image 2.5 支持的画质");
                if (image.version !== undefined) issues.push("标准 GPT Image 2.5 不使用 Ext 版本参数");
            } else if (isApimartImageExt(image.model)) {
                if (image.quality !== undefined) issues.push("GPT Image 2.5 Ext 不支持画质参数");
                if (image.version !== undefined && !(IMAGE_EXT_VERSIONS as readonly string[]).includes(image.version)) issues.push("请选择 Ext 版本 flare 或 sunburst");
            } else {
                if (image.quality !== undefined) issues.push("GPT Image 2 不支持画质参数");
                if (image.version !== undefined) issues.push("GPT Image 2 不使用 Ext 版本参数");
            }
        }
    }
    if (config?.video) {
        const video = config.video;
        if (video.provider !== "apimart" || video.model !== "MiniMax-H3" || video.profileVersion !== OUTPUT_PROFILE_VERSION) {
            issues.push("视频配置版本或模型尚不支持，请明确选择 MiniMax H3 或清除配置");
        }
        if (!(VIDEO_RESOLUTIONS as readonly string[]).includes(video.resolution)) issues.push("MiniMax H3 分辨率须为 768P 或 2K");
        if (!Number.isInteger(video.duration) || video.duration < 4 || video.duration > 15) issues.push("MiniMax H3 时长须为 4–15 秒整数");
        if (video.mode === "frames") {
            if (video.aspectRatio !== "adaptive") issues.push("首尾帧生视频的比例由输入图片决定，请选择跟随输入图片");
        } else if (video.mode === "text" || video.mode === "reference") {
            if (!(VIDEO_RATIOS as readonly string[]).includes(video.aspectRatio) && !(video.mode === "reference" && video.aspectRatio === "adaptive")) {
                issues.push("请选择当前视频方式支持的比例");
            }
        } else issues.push("请选择文字、首尾帧或参考素材生视频方式");
    }
    return issues;
}

/** Common native parameters only; prompt/media-role preflight belongs to generation. */
export function generationParameters(config: ProjectGenerationDefaults, kind: "image" | "video"): Record<string, string | number> {
    const selected = kind === "image" ? {image: config.image} : {video: config.video};
    const errors = validateGenerationDefaults(selected);
    if (errors.length) throw new Error(errors.join("；"));
    if (kind === "image" && config.image) {
        return {
            model: config.image.model, size: config.image.size, resolution: config.image.resolution, n: 1,
            ...(config.image.quality ? {quality: config.image.quality} : {}),
            ...(config.image.version ? {version: config.image.version} : {}),
        };
    }
    if (kind === "video" && config.video) {
        const video = config.video;
        return {
            model: video.model, resolution: video.resolution, duration: video.duration,
            ...(video.mode === "frames" ? {} : {aspect_ratio: video.aspectRatio})
        };
    }
    throw new Error("尚未配置此类生成默认值");
}

