import type {AgentRun, AgentTask, AgentToolCall} from "@/domain/agent";
import type {AgentGenerationJob} from "@/domain/agentGeneration";
import type {GenerationBatch, GenerationBatchItem} from "@/domain/agentGenerationBatch";
import type {ChatMessage} from "@/domain/types";

export interface ActivityAttention {
    id: string;
    kind: "unknown" | "approval" | "batch" | "resume";
    label: string;
    detail: string;
    action: string;
    target: { runId: string; callId?: string; batchId?: string };
}

type AttentionInput = {
    threadId: string;
    runs: readonly Pick<AgentRun, "id" | "threadId" | "taskId" | "status" | "hasToolCalls" | "createdAt" | "pauseReason">[];
    calls: readonly Pick<AgentToolCall, "id" | "runId" | "threadId" | "title" | "status">[];
    batches: readonly Pick<GenerationBatch, "id" | "runId" | "threadId" | "taskId" | "title" | "status">[];
    items: readonly Pick<GenerationBatchItem, "batchId" | "threadId" | "state">[];
    jobs: readonly Pick<AgentGenerationJob, "id" | "runId" | "threadId" | "batchId" | "callId" | "status">[];
    tasks: readonly Pick<AgentTask, "id" | "threadId" | "lifecycle">[];
    messages: readonly Pick<ChatMessage, "threadId" | "role" | "createdAt">[];
    projectUnavailable?: boolean;
};

/** Keep durable batch work visible after the model finishes; never suggest resuming stale runs. */
export function selectActivityAttention(input: AttentionInput): ActivityAttention[] {
    const {threadId} = input;
    const runs = input.runs.filter(run => run.threadId === threadId);
    const runIds = new Set(runs.map(run => run.id));
    const calls = input.calls.filter(call => call.threadId === threadId && runIds.has(call.runId));
    const jobs = input.jobs.filter(job => job.threadId === threadId && runIds.has(job.runId));
    const taskClosed = (taskId?: string) => Boolean(taskId && !input.tasks.some(task => task.id === taskId && task.threadId === threadId && task.lifecycle === "open"));
    const result: ActivityAttention[] = [];
    for (const batch of input.batches) {
        if (batch.threadId !== threadId || !runIds.has(batch.runId)) continue;
        const batchJobs = jobs.filter(job => job.batchId === batch.id && job.runId === batch.runId);
        const unknown = batchJobs.some(job => job.status === "unknown");
        const blocked = input.projectUnavailable || taskClosed(batch.taskId);
        const target = {runId: batch.runId, batchId: batch.id};
        if (unknown) {
            result.push({
                id: `batch:${batch.id}`,
                kind: "unknown",
                label: "生成结果待核实",
                detail: `${batch.title}${blocked ? " · 当前仅可查看记录" : " · 请先核实已提交的请求"}`,
                action: "查看批次",
                target
            });
        } else if (!blocked && batch.status === "draft") {
            result.push({
                id: `batch:${batch.id}`,
                kind: "batch",
                label: "待你确认生成",
                detail: `${batch.title} · 确认后可能产生费用`,
                action: "检查并确认",
                target
            });
        } else if (!blocked && ["ready", "paused"].includes(batch.status) && (input.items.some(item => item.threadId === threadId && item.batchId === batch.id && item.state === "queued") || batchJobs.some(job => ["submitting", "submitted", "running", "remote_completed", "downloading"].includes(job.status)))) {
            result.push({
                id: `batch:${batch.id}`,
                kind: "batch",
                label: batch.status === "ready" ? "批次等待开始" : "批次已暂停",
                detail: batch.title,
                action: "查看并继续",
                target
            });
        }
    }
    const unknownCalls = new Set<string>();
    for (const call of calls) {
        if (call.status !== "unknown" && !jobs.some(job => !job.batchId && job.callId === call.id && job.status === "unknown")) continue;
        unknownCalls.add(call.id);
        result.push({
            id: `call:${call.id}`,
            kind: "unknown",
            label: "操作结果待核实",
            detail: call.title,
            action: "查看操作",
            target: {runId: call.runId, callId: call.id}
        });
    }
    for (const run of runs) {
        if (input.projectUnavailable || taskClosed(run.taskId) || !run.hasToolCalls || !["waiting_approval", "interrupted", "failed"].includes(run.status)) continue;
        if (runs.some(other => other.id !== run.id && other.createdAt >= run.createdAt) || input.messages.some(message => message.threadId === threadId && message.role === "user" && message.createdAt > run.createdAt)) continue;
        const runCalls = calls.filter(call => call.runId === run.id);
        // Approval cannot proceed while an existing operation is unresolved.
        if (runCalls.some(call => unknownCalls.has(call.id) || call.status === "running")) continue;
        const approvals = runCalls.filter(call => call.status === "awaiting_approval");
        for (const call of approvals) result.push({
            id: `call:${call.id}`,
            kind: "approval",
            label: "待你批准操作",
            detail: call.title,
            action: "查看并决定",
            target: {runId: run.id, callId: call.id}
        });
        if (!approvals.length) result.push({
            id: `run:${run.id}`,
            kind: "resume",
            label: run.pauseReason === "model_step_limit" ? "阶段已暂停" : "执行已中断",
            detail: "进度已保存，可检查后继续",
            action: "查看执行",
            target: {runId: run.id}
        });
    }
    const order = {unknown: 0, approval: 1, batch: 2, resume: 3};
    return result.sort((a, b) => order[a.kind] - order[b.kind]);
}

import {z} from "zod";
import {db} from "@/db/database";
import {resolveConnector} from "@/db/repo";
import {assertAudioProject, assertAudioRevision, ownedAudioRow} from "@/db/audioShared";
import {AtomicToolRollbackError} from "@/db/agentTools";
import type {AgentToolPreview} from "@/domain/agent";
import type {AgentToolContext, AgentToolDefinition} from "./tools";
import type {AudioGenerationInput} from "@/domain/audioGeneration";
import {requireBoundProjectScope} from "./projectScope";
import {targetRevision} from "@/lib/productionRevision";
import {
  prepareAudioGeneration,
  readAudioJobSummary,
  refreshAudioGeneration,
  submitAudioGeneration
} from "@/lib/audioGeneration/runtime";
import {validateGenerationInput} from "@/lib/audioGeneration/input";
import {SPEECH_VOICES} from "@/lib/ai/apimartAudio";
import {MIMO_MODELS, MIMO_VOICES} from "@/lib/ai/mimoSpeech";
import {mimoSpeechSpec} from "./mimoSpeechSpec";
import {defaultMimoConnector, speakerSpeechProfile} from "@/lib/audioGeneration/defaults";
import {validateSpeechReference} from "@/lib/audioGeneration/reference";
import * as s from "./businessSchemas";

const base = {projectId: s.id, connectorId: s.id};
const speech = s.object({
    projectId: s.id,
    connectorId: s.optional(s.id),
    text: s.text(8192),
    voice: s.optional(s.choice([...SPEECH_VOICES, ...MIMO_VOICES])),
    speed: s.optional(s.number(.25, 4)),
    mimo: s.optional(mimoSpeechSpec),
    speakerId: s.optional(s.id),
    speakerRevision: s.optional(s.number(1, 1e9, true)),
    segmentId: s.optional(s.id),
    segmentRevision: s.optional(s.number(1, 1e9, true))
});
const music = s.object({...base, draftId: s.id, draftRevision: s.number(1, 1e9, true)});
const jobSpec = s.object({projectId: s.id, jobId: s.id});
type Submission = {
    projectId: string;
    connectorId: string;
    input: AudioGenerationInput;
    speakerId?: string;
    speakerRevision?: number
};

async function scope(projectId: string, context: AgentToolContext) {
    context.signal.throwIfAborted();
    await requireBoundProjectScope(context, projectId);
    await assertAudioProject(projectId);
}

async function inputState(args: Submission, context: AgentToolContext) {
    await scope(args.projectId, context);
    validateGenerationInput(args.input);
    let speaker;
    if (args.speakerId) {
        speaker = await ownedAudioRow(db.audioSpeakers, args.projectId, args.speakerId);
        if (args.speakerRevision === undefined) throw new Error("指定说话人时必须提供当前版本");
        assertAudioRevision(speaker, args.speakerRevision);
    }
    const connector = await resolveConnector(args.connectorId);
    const provider = args.input.kind === "speech" && args.input.mimo ? "mimo" : "apimart";
    if (!connector || connector.definitionId !== provider || !connector.apiKey.trim()) throw new Error(`需要已配置的 ${provider === "mimo" ? "MiMo" : "APIMart"} 连接`);
    const reference = args.input.kind === "speech" ? await validateSpeechReference(args.projectId, args.input) : undefined;
    let target: unknown;
    if (args.input.kind === "speech") {
        await assertAudioProject(args.projectId, "audio");
        if (args.input.segmentId) {
            const row = await ownedAudioRow(db.audioSegments, args.projectId, args.input.segmentId);
            if (args.input.segmentRevision === undefined) throw new Error("指定段落时必须提供当前版本");
            assertAudioRevision(row, args.input.segmentRevision);
            target = row;
        }
    } else {
        await assertAudioProject(args.projectId, "music");
        if (!args.input.draftId || args.input.draftRevision === undefined) throw new Error("请先准备音乐草稿");
        const row = await ownedAudioRow(db.musicDrafts, args.projectId, args.input.draftId);
        assertAudioRevision(row, args.input.draftRevision);
        target = row;
    }
    return {
        revision: targetRevision({
            args,
            target: {target, speaker},
            reference: reference ? {
                mediaId: reference.mediaId,
                fingerprint: reference.fingerprint,
                filename: reference.filename
            } : undefined,
            connector: {
                id: connector.id,
                definitionId: connector.definitionId,
                baseUrl: connector.baseUrl,
                credentialRevision: targetRevision(connector.apiKey)
            }
        }), connector, reference
    };
}

async function preview(args: Submission, context: AgentToolContext): Promise<AgentToolPreview> {
    const state = await inputState(args, context);
    const changes = args.input.kind === "speech"
        ? [args.input.mimo ? `MiMo · ${MIMO_MODELS[args.input.mimo.mode]} · ${args.input.mimo.mode === "preset" ? args.input.voice : args.input.mimo.mode === "design" ? "设计音色" : "克隆音色"}` : `APIMart · gpt-4o-mini-tts · ${args.input.voice} · ${args.input.speed} 倍速`,
            ...(args.input.mimo ? [`音色与演绎指导：${args.input.mimo.instruction}`, ...(state.reference ? [`参考声音：${state.reference.filename}（${state.reference.mediaId}）`] : []), ...(args.input.mimo.optimizeTextPreview ? ["允许智能润色或自动生成播报文本；稿件原文保留。"] : [])] : []), `文字：${args.input.text.slice(0, 1600)}`, "生成一个新配音版本，保留当前选用和时间线。"]
        : [`APIMart · ${args.input.settings.engine}`, "完整歌词和生成参数见本次音乐确认", "生成结果保存到音乐项目；不覆盖已有作品。"];
    return {
        summary: args.input.kind === "speech" ? "生成配音（付费）" : "生成音乐（付费）", revision: state.revision, changes,
        ...(args.input.kind === "music" ? {
            music: {
                version: 1 as const,
                projectId: args.projectId,
                projectName: (await db.projects.get(args.projectId))!.name,
                draftId: args.input.draftId!,
                draftRevision: args.input.draftRevision!,
                connectorId: args.connectorId,
                connectorLabel: state.connector.label || "APIMart",
                settings: args.input.settings
            }
        } : {}),
        target: {label: "打开作品项目", href: `/p/${encodeURIComponent(args.projectId)}`}
    };
}

async function runSubmission(args: Submission, context: AgentToolContext, resolveCurrent?: () => Promise<Submission>) {
    const intentId = `agent-audio:${context.callId}`;
    const validate = async () => {
        const call = await db.agentToolCalls.get(context.callId), run = await db.agentRuns.get(context.runId);
        if (!call || call.runId !== context.runId || call.threadId !== context.threadId || call.status !== "running" || call.decision !== "approve" || !call.requiresConfirmation || run?.status !== "running") throw new AtomicToolRollbackError("生成请求尚未得到有效确认或执行已停止");
        if (!context.preview?.revision || context.preview.revision !== (await inputState(resolveCurrent ? await resolveCurrent() : args, context)).revision) throw new AtomicToolRollbackError("生成目标、参数或连接已变化，请重新准备并确认");
    };
    try {
        await scope(args.projectId, context);
        const existing = await db.audioGenerationJobs.where("intentId").equals(intentId).first();
        if (existing) {
            if (existing.projectId !== args.projectId || existing.source.kind !== "agent" || existing.source.callId !== context.callId || existing.source.runId !== context.runId) throw new Error("生成任务归属不匹配");
            // A recovery repeats only local lookup / GET, never the paid submission.
            if (existing.status !== "prepared") {
                await refreshAudioGeneration(args.projectId, existing.id, {signal: context.signal});
                return readAudioJobSummary(args.projectId, existing.id);
            }
        }
        await validate();
        const job = existing ?? await prepareAudioGeneration({
            ...args,
            intentId,
            source: {kind: "agent", callId: context.callId, runId: context.runId}
        });
        await submitAudioGeneration(args.projectId, job.id, {signal: context.signal, beforeSubmit: validate});
        return readAudioJobSummary(args.projectId, job.id);
    } catch (error) {
        if (error instanceof AtomicToolRollbackError) throw error;
        // The durable job describes uncertainty if a POST started; preflight errors have no effect.
        const job = await db.audioGenerationJobs.where("intentId").equals(intentId).first();
        if (job && job.status !== "prepared") return {
            ...await readAudioJobSummary(args.projectId, job.id),
            error: job.error ?? (error instanceof Error ? error.message : "生成未完成")
        };
        throw new AtomicToolRollbackError(error instanceof Error ? error.message : "生成准备失败");
    }
}

async function speechArgs(raw: unknown, context: AgentToolContext, recover = false): Promise<Submission> {
    const args = speech.schema.parse(raw);
    await scope(args.projectId, context);
    if (recover) {
        const existing = await db.audioGenerationJobs.where("intentId").equals(`agent-audio:${context.callId}`).first();
        if (existing && existing.status !== "prepared" && existing.projectId === args.projectId && existing.source.kind === "agent" && existing.source.callId === context.callId && existing.source.runId === context.runId) {
            return {projectId: args.projectId, connectorId: existing.connector.id, input: existing.input};
        }
    }
    let speakerId = args.speakerId;
    if (args.segmentId) {
        const segment = await ownedAudioRow(db.audioSegments, args.projectId, args.segmentId);
        if (speakerId && segment.speakerId && speakerId !== segment.speakerId) throw new Error("说话人与段落绑定不一致");
        speakerId ??= segment.speakerId;
    }
    if (args.speakerRevision !== undefined && !speakerId) throw new Error("说话人版本需要指定说话人");
    const speaker = speakerId ? await ownedAudioRow(db.audioSpeakers, args.projectId, speakerId) : undefined;
    if (speaker && args.speakerRevision !== undefined) assertAudioRevision(speaker, args.speakerRevision);
    const inherited = speakerSpeechProfile(speaker);
    const explicitApimart = !args.mimo && args.voice !== undefined && (SPEECH_VOICES as readonly string[]).includes(args.voice);
    const explicitMimoPreset = !args.mimo && args.voice !== undefined && (MIMO_VOICES as readonly string[]).includes(args.voice);
    const mimo = explicitApimart ? undefined : args.mimo ?? (explicitMimoPreset ? {
        mode: "preset" as const,
        instruction: ""
    } : inherited.mimo);
    const voice = args.voice ?? (args.mimo ? "mimo_default" : inherited.voice);
    const speed = args.speed ?? (mimo ? 1 : inherited.speed);
    const connectorId = args.connectorId ?? defaultMimoConnector(await db.connectors.toArray())?.id;
    if (!connectorId) throw new Error("请先配置 MiMo 连接，或明确提供 APIMart 连接");
    return {
        projectId: args.projectId, connectorId, ...(speaker ? {
            speakerId: speaker.id,
            speakerRevision: speaker.revision
        } : {}),
        input: {
            kind: "speech",
            text: args.text,
            voice,
            speed, ...(mimo ? {mimo} : {}),
            segmentId: args.segmentId,
            segmentRevision: args.segmentRevision
        }
    };
}

async function musicArgs(raw: unknown, context?: AgentToolContext): Promise<Submission> {
    const args = music.schema.parse(raw);
    if (context) {
        await scope(args.projectId, context);
        const existing = await db.audioGenerationJobs.where("intentId").equals(`agent-audio:${context.callId}`).first();
        if (existing && existing.status !== "prepared" && existing.projectId === args.projectId && existing.source.kind === "agent" && existing.source.callId === context.callId && existing.source.runId === context.runId) {
            return {projectId: args.projectId, connectorId: args.connectorId, input: existing.input};
        }
    }
    const draft = await ownedAudioRow(db.musicDrafts, args.projectId, args.draftId);
    assertAudioRevision(draft, args.draftRevision);
    return {
        projectId: args.projectId,
        connectorId: args.connectorId,
        input: {kind: "music", settings: draft.settings, draftId: draft.id, draftRevision: draft.revision}
    };
}

