const targetTables = () => [db.projects, db.episodes, db.shots, db.characters, db.scenes, db.props, db.styles];

export async function readGenerationTarget(target: ProductionTarget) {
    if (target.projectId !== "studio" && !await db.projects.get(target.projectId)) throw new Error("生成目标项目已删除");
    const entity = target.kind === "shot" ? await db.shots.get(target.entityId) : target.kind === "character" ? await db.characters.get(target.entityId)
        : target.kind === "scene" ? await db.scenes.get(target.entityId) : target.kind === "prop" ? await db.props.get(target.entityId) : await db.styles.get(target.entityId);
    if (!entity || entity.projectId !== target.projectId) throw new Error("生成目标不存在或归属不匹配");
    if (target.kind === "shot") {
        const episode = await db.episodes.get(target.episodeId);
        if (!episode || episode.projectId !== target.projectId || !("episodeId" in entity) || entity.episodeId !== target.episodeId) throw new Error("生成目标不属于当前故事");
    }
    if (!target.slot) throw new Error("生成目标缺少素材槽位");
    const slot = "slots" in entity ? (entity.slots as Partial<Record<string, GenerationSlot>>)[target.slot] ?? emptySlot()
        : target.kind === "shot" ? entity[target.slot!] : emptySlot();
    return {
        entity,
        slot,
        revision: targetRevision(entity),
        label: "name" in entity ? entity.name : `镜头 ${entity.shotNumber || entity.order + 1}`
    };
}

export function generationTargetHref(target: ProductionTarget): string {
    const id = encodeURIComponent(target.entityId);
    if (target.kind === "shot") return `/p/${encodeURIComponent(target.projectId)}/e/${encodeURIComponent(target.episodeId)}/shots?shot=${id}`;
    const plural = target.kind === "character" ? "characters" : target.kind === "scene" ? "scenes" : target.kind === "prop" ? "props" : "styles";
    return target.projectId === "studio" ? `/${plural}/${id}` : `/p/${encodeURIComponent(target.projectId)}/assets/${plural}/${id}`;
}

async function connector(id: string, frozen?: Pick<AgentGenerationJob, "provider" | "baseUrl">) {
    const item = await resolveConnector(id);
    if (!item || (item.definitionId !== "apimart" && item.definitionId !== "aihubmix") || !item.apiKey.trim()) throw new Error("生成供应商尚未配置有效密钥");
    const url = new URL(item.baseUrl);
    if (!/^https?:$/.test(url.protocol) || url.username || url.password || url.search || url.hash || !url.pathname.endsWith("/v1")) throw new Error("供应商 Base URL 无效");
    if (frozen && (item.definitionId !== frozen.provider || item.baseUrl !== frozen.baseUrl)) throw new Error("供应商配置已变化，请恢复原配置后查询已有任务；不会重新提交");
    return item;
}

function safeTaskId(id: string, config: ConnectorConfig) {
    if (!id.trim() || id.includes(config.apiKey.trim()) || /[\\/?#%]/.test(id) || id === "." || id === "..") throw new Error("供应商任务标识格式异常，提交结果需人工核实");
    return id;
}

async function inputRevision(media: MediaRecord) {
    const digest = await crypto.subtle.digest("SHA-256", await media.blob.arrayBuffer());
    return targetRevision({
        id: media.id, projectId: media.projectId, mimeType: media.mimeType, size: media.blob.size,
        hash: [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("")
    });
}

function cleanError(error: unknown, config?: ConnectorConfig) {
    const text = error instanceof Error ? error.message : "生成操作失败";
    return redactCredentials(text, config?.apiKey ?? "").slice(0, 700);
}

export async function prepareGenerationSnapshot(raw: GenerationSubmitArgs, signal: AbortSignal) {
    signal.throwIfAborted();
    const args = generationSubmitSchema.parse(raw);
    await flushPendingDrafts(args.target.projectId);
    const config = await connector(args.connectorId);
    const provider = config.definitionId as "apimart" | "aihubmix";
    const request = profileRequest(args, provider);
    const snapshot = await db.transaction("r", [...targetTables(), db.media], async () => {
        const current = await readGenerationTarget(request.target);
        const records = await db.media.bulkGet(request.inputs.map((input) => input.mediaId));
        return {current, records};
    });
    const inputs = [];
    let bytes = 0;
    for (const [index, input] of request.inputs.entries()) {
        const media = snapshot.records[index];
        const kind = input.role === "reference-video" ? "video" : "image";
        if (!media || media.projectId !== request.target.projectId || !media.blob.size || !media.mimeType.startsWith(`${kind}/`)) throw new Error("输入素材已删除、为空、类型错误或属于其他项目");
        if (kind === "image" && !["image/png", "image/jpeg", "image/webp", "image/gif"].includes(media.mimeType)) throw new Error("参考图片格式尚未支持");
        if (provider === "apimart" && media.blob.size > 20 * 1024 * 1024) throw new Error("APIMart 参考图不能超过20MiB");
        if (provider === "apimart" && args.model === "MiniMax-H3") {
            if (!["image/png", "image/jpeg", "image/webp"].includes(media.mimeType)) throw new Error("MiniMax H3 本地参考图仅支持 PNG、JPEG、WebP");
            const {width, height} = await generationImageDimensions(media.blob);
            if (width < 256 || height < 256 || width > 5760 || height > 5760 || width / height < 0.4 || width / height > 2.5) throw new Error("MiniMax H3 图片宽高须为256–5760px，比例0.4–2.5");
        }
        bytes += Math.ceil(media.blob.size / 3) * 4;
        inputs.push({...input, revision: await inputRevision(media)});
    }
    if (provider === "aihubmix" && bytes + new TextEncoder().encode(args.prompt).length + 8192 > 32 * 1024 * 1024) throw new Error("AIHubMix 内联素材请求超过32MiB限制");
    signal.throwIfAborted();
    const fingerprint = targetRevision({
        target: request.target,
        connectorId: config.id,
        provider,
        baseUrl: config.baseUrl,
        model: args.model,
        parameters: request.parameters,
        inputs,
        baseRevision: snapshot.current.revision
    });
    return {args, config, provider, request, inputs, fingerprint, current: snapshot.current, records: snapshot.records};
}

export async function prepareAgentGeneration(raw: GenerationSubmitArgs, context: AgentToolContext): Promise<AgentToolPreview> {
    await assertProjectToolScope(context, "submit_generation", {projectId: raw.target.projectId}, true);
    const snapshot = await prepareGenerationSnapshot(raw, context.signal);
    return {
        summary: `使用 ${snapshot.provider} / ${snapshot.args.model} 为「${snapshot.current.label}」生成${snapshot.request.kind === "image" ? "图片" : "视频"}`,
        changes: [`槽位：${snapshot.request.target.slot}`, `提示词：${snapshot.args.prompt.slice(0, 1500)}`, `参数：${JSON.stringify(snapshot.request.parameters).slice(0, 1800)}`, `参考素材：${snapshot.inputs.length} 项；此操作可能产生供应商费用，完成后需要单独写入目标。`],
        revision: snapshot.fingerprint,
        target: {label: snapshot.current.label, href: generationTargetHref(snapshot.request.target)}
    };
}

async function jobForContext(jobId: string, context: Pick<AgentToolContext, 'threadId' | 'signal'> & Partial<AgentToolContext>) {
    const job = await db.agentGenerationJobs.get(jobId);
    if (!job || job.threadId !== context.threadId || !await db.chatThreads.get(job.threadId) || !await db.agentRuns.get(job.runId)) throw new Error("生成任务不存在或不属于当前对话");
    if (job.batchId) await ownedGenerationBatch(job.batchId, context.threadId);
    if (context.runId && context.callId) await assertProjectToolScope(context as AgentToolContext, "generation_job", {projectId: job.projectId}, true);
    return job;
}

export async function loadGenerationInputs(job: AgentGenerationJob) {
    const rows: MediaRecord[] = [];
    for (const input of job.inputs) {
        const media = await db.media.get(input.mediaId);
        if (!media || media.projectId !== job.projectId || await inputRevision(media) !== input.revision) throw new Error("生成输入素材已变化，保留任务但不使用新的素材");
        rows.push(media);
    }
    return rows;
}

async function dataUri(media: MediaRecord) {
    const bytes = new Uint8Array(await media.blob.arrayBuffer());
    let binary = "";
    for (let offset = 0; offset < bytes.length; offset += 32768) binary += String.fromCharCode(...bytes.subarray(offset, offset + 32768));
    return `data:${media.mimeType};base64,${btoa(binary)}`;
}

async function nativeRequest(job: AgentGenerationJob, config: ConnectorConfig, context: Pick<AgentToolContext, 'threadId' | 'signal'> & Partial<AgentToolContext>, options: GenerationRuntimeOptions): Promise<AIHubMixGenerationRequest> {
    const records = await loadGenerationInputs(job);
    const input: AIHubMixGenerationRequest = {model: job.model, prompt: String(job.parameters.prompt)};
    for (const [key, value] of Object.entries(job.parameters)) if (!["mode", "quality"].includes(key)) input[key] = value;
    if (job.provider === "aihubmix" && job.parameters.quality) input.extra = {quality: job.parameters.quality};
    if (job.provider === "apimart" && isApimartImage25(job.model) && typeof job.parameters.quality === "string") input.quality = job.parameters.quality;
    const urls: string[] = [];
    for (const media of records) {
        context.signal.throwIfAborted();
        if (job.provider === "apimart") {
            const uploaded = await uploadApimartImage(config, new Blob([media.blob], {type: media.mimeType}), {
                signal: context.signal,
                fetchImpl: options.fetchImpl,
                filename: media.filename
            });
            if (!uploaded.ok) throw new Error(uploaded.message);
            urls.push(uploaded.image.url);
        } else urls.push(await dataUri(media));
    }
    if (urls.length) {
        if (job.provider === "apimart") {
            if (job.kind === "image") input.image_urls = urls;
            else input.image_with_roles = job.inputs.map((item, index) => ({
                url: urls[index],
                role: item.role.replaceAll("-", "_")
            }));
        } else if (job.kind === "image") input.images = urls;
        else if (job.parameters.mode === "frames") input.frame_images = job.inputs.map((item, index) => ({
            frame_type: item.role.replaceAll("-", "_"),
            image_url: {url: urls[index]}
        }));
        else input.input_references = job.inputs.map((item, index) => ({
                type: item.role === "reference-video" ? "video_url" : "image_url",
                url: urls[index]
            }));
    }
    return input;
}

export async function submitAgentGeneration(raw: GenerationSubmitArgs, context: AgentToolContext, options: GenerationRuntimeOptions = {}): Promise<AgentGenerationJob> {
    context.signal.throwIfAborted();
    const saved = await db.agentGenerationJobs.where("callId").equals(context.callId).first();
    if (saved) {
        if (saved.runId !== context.runId || saved.threadId !== context.threadId) throw new Error("生成记录归属不匹配");
        return monitorAgentGeneration(saved.id, context, options);
    }
    let snapshot;
    try {
        await assertProjectToolScope(context, "submit_generation", {projectId: raw.target.projectId}, true);
        snapshot = await prepareGenerationSnapshot(raw, context.signal);
        if (context.preview?.revision && context.preview.revision !== snapshot.fingerprint) throw new Error("生成目标、输入或配置已变化，请重新确认，尚未付费提交");
    } catch (error) {
        throw new AtomicToolRollbackError(cleanError(error));
    }
    const at = nowIso();
    const claim = await claimGenerationJob({
        version: 1,
        id: createId("genjob"),
        runId: context.runId,
        threadId: context.threadId,
        callId: context.callId,
        projectId: snapshot.request.target.projectId,
        connectorId: snapshot.config.id,
        provider: snapshot.provider,
        baseUrl: snapshot.config.baseUrl,
        model: snapshot.args.model,
        kind: snapshot.request.kind,
        target: snapshot.request.target,
        baseRevision: snapshot.current.revision,
        sourceRevisions: [{
            kind: snapshot.request.target.kind,
            id: snapshot.request.target.entityId,
            revision: snapshot.current.revision
        }],
        parameters: snapshot.request.parameters,
        inputs: snapshot.inputs,
        fingerprint: snapshot.fingerprint,
        status: "submitting",
        createdAt: at,
        updatedAt: at
    }).catch((error: unknown) => {
        throw new AtomicToolRollbackError(cleanError(error, snapshot.config));
    });
    if (!claim.claimed) return monitorAgentGeneration(claim.job.id, context, options);
    const job = claim.job;
    return submitClaimedGeneration(job, snapshot.config, context, options, async () => {
        // Reference uploads may take time; never submit paid work against a changed target.
        const latest = await readGenerationTarget(job.target);
        if (latest.revision !== job.baseRevision) throw new Error("生成目标已修改，尚未付费提交");
        context.signal.throwIfAborted();
        const active = await db.agentRuns.get(context.runId);
        const activeCall = await db.agentToolCalls.get(context.callId);
        if (!await db.agentGenerationJobs.get(job.id) || !active || active.status !== "running" || !activeCall || activeCall.status !== "running") throw new Error("生成记录或执行已停止，尚未付费提交");
        await assertProjectToolScope(context, "submit_generation", {projectId: job.projectId}, true);
    });
}

/** Shared paid transport. Caller must own the job and provide a final durable dispatch guard. */
export async function submitClaimedGeneration(job: AgentGenerationJob, config: ConnectorConfig,
                                              context: Pick<AgentToolContext, 'threadId' | 'signal'>, options: GenerationRuntimeOptions, beforePost: () => Promise<void>) {
    let postStarted = false;
    try {
        const request = await nativeRequest(job, config, context, options);
        // Hash inputs outside Dexie after uploads/encoding, then validate current records
        // and caller ownership together immediately before either provider's paid POST.
        const inputs = await loadGenerationInputs(job);
        await db.transaction("r", db.tables, async () => {
            await beforePost();
            const latest = await resolveConnector(config.id);
            if (!latest?.apiKey.trim() || latest.definitionId !== job.provider ||
                latest.baseUrl !== job.baseUrl || latest.apiKey !== config.apiKey) {
                throw new Error("供应商配置已变化，尚未付费提交");
            }
            for (const input of inputs) {
                const current = await db.media.get(input.id);
                if (!current || current.projectId !== input.projectId || current.mimeType !== input.mimeType || current.blob.size !== input.blob.size) {
                    throw new Error("生成输入素材已变化，尚未付费提交");
                }
            }
        });
        context.signal.throwIfAborted();
        postStarted = true;
        if (job.provider === "apimart") {
            const result = await (job.kind === "image" ? submitApimartImageGeneration : submitApimartVideoGeneration)(config, request, {
                signal: context.signal,
                fetchImpl: options.fetchImpl,
                idempotencyKey: job.id
            });
            if (!result.ok) {
                await updateGenerationJob(job.id, {
                    status: result.kind === "validation" || result.kind === "http" && [400, 401, 402, 403, 404, 422, 429].includes(result.httpStatus ?? 0) ? "failed" : "unknown",
                    error: cleanError(new Error(result.message), config)
                });
                return monitorAgentGeneration(job.id, context, options);
            }
            // n=1 profiles create exactly one task. Preserve first received identity before further work.
            await updateGenerationJob(job.id, {
                providerTaskId: safeTaskId(result.tasks[0].id, config),
                status: "submitted"
            });
            if (result.tasks.length !== 1) {
                await updateGenerationJob(job.id, {
                    status: "unknown",
                    providerTaskIds: result.tasks.map((task) => safeTaskId(task.id, config)),
                    error: "供应商返回多个任务，已保留任务标识，请核实账户记录，不能自动选择结果或重复提交"
                });
                throw new GenerationPendingError(job.id, "供应商返回多个任务，需要人工核实，不能自动选择或重新提交");
            }
        } else {
            const result = await (job.kind === "image" ? submitAIHubMixImageGeneration : submitAIHubMixVideoGeneration)(config, request, {
                signal: context.signal,
                fetchImpl: options.fetchImpl
            });
            if (!result.ok) {
                await updateGenerationJob(job.id, {
                    ...(result.taskId ? {providerTaskId: safeTaskId(result.taskId, config)} : {}),
                    status: result.taskId ? "submitted" : result.kind === "validation" || result.kind === "http" && [400, 401, 402, 403, 404, 422, 429].includes(result.httpStatus ?? 0) ? "failed" : "unknown",
                    error: cleanError(new Error(result.message), config)
                });
                if (!result.taskId) return monitorAgentGeneration(job.id, context, options);
            } else {
                await updateGenerationJob(job.id, {
                    providerTaskId: safeTaskId(result.task.id, config),
                    status: "submitted"
                });
                // Synchronous completion may carry the only copy of base64 output.
                if (result.task.status === "completed") return await acceptHubTask(job.id, result.task, config, context, options);
            }
        }
    } catch (error) {
        const current = await db.agentGenerationJobs.get(job.id);
        if (!current) throw error;
        await updateGenerationJob(current.id, {
            status: current.providerTaskId ? current.status : postStarted ? "unknown" : "failed",
            error: cleanError(error, config)
        });
        if (!postStarted) throw new AtomicToolRollbackError(cleanError(error, config));
        if (context.signal.aborted) throw new GenerationPendingError(current.id, "已停止本地等待；远端提交结果需核实，不能当作远端取消");
        throw new GenerationPendingError(current.id, cleanError(error, config));
    }
    return monitorAgentGeneration(job.id, context, options);
}

async function validateBlob(blob: Blob, kind: "image" | "video") {
    if (!blob.size) throw new Error("供应商结果文件为空");
    const bytes = new Uint8Array(await blob.slice(0, 32).arrayBuffer());
    const ascii = (start: number, end: number) => String.fromCharCode(...bytes.slice(start, end));
    let mime = "";
    if (bytes[0] === 137 && ascii(1, 4) === "PNG") mime = "image/png";
    else if (bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255) mime = "image/jpeg";
    else if (ascii(0, 3) === "GIF") mime = "image/gif";
    else if (ascii(0, 4) === "RIFF" && ascii(8, 12) === "WEBP") mime = "image/webp";
    else if (ascii(4, 8) === "ftyp") mime = "video/mp4";
    else if (bytes[0] === 0x1a && bytes[1] === 0x45 && bytes[2] === 0xdf && bytes[3] === 0xa3) mime = "video/webm";
    if (!mime.startsWith(`${kind}/`)) throw new Error("下载内容不是可识别的目标图片/视频，未写入素材");
    return new Blob([blob], {type: mime});
}

async function saveBlob(job: AgentGenerationJob, blob: Blob) {
    const verified = await validateBlob(blob, job.kind);
    const ext = verified.type.split("/")[1];
    return storeGenerationMedia(job.id, {
        id: createId("media"),
        projectId: job.projectId,
        mimeType: verified.type,
        filename: `${job.model}-${job.id}.${ext}`,
        blob: verified
    });
}

async function acceptHubTask(jobId: string, task: AIHubMixTask, config: ConnectorConfig, context: Pick<AgentToolContext, 'threadId' | 'signal'> & Partial<AgentToolContext>, options: GenerationRuntimeOptions) {
    let job = await jobForContext(jobId, context);
    if (task.model !== job.model) throw new Error("供应商实际模型与已确认模型不同，保留任务但不应用结果");
    if (task.status === "failed" || task.status === "cancelled") return updateGenerationJob(jobId, {
        status: "failed",
        providerStatus: cleanError(new Error(task.providerStatus), config),
        error: cleanError(new Error(task.error?.message ?? "远端任务失败或已取消"), config)
    });
    if (task.status !== "completed") return updateGenerationJob(jobId, {
        status: task.status === "running" ? "running" : "submitted",
        providerStatus: cleanError(new Error(task.providerStatus), config),
        error: undefined
    });
    if (task.outputs.length !== 1) throw new Error("预期单个生成结果，供应商返回数量不匹配，请核实任务");
    job = await updateGenerationJob(jobId, {
        status: "downloading",
        providerStatus: cleanError(new Error(task.providerStatus), config),
        error: undefined
    });
    const output = task.outputs[0];
    let blob: Blob;
    if (output.b64Json) {
        let decoded: string;
        try {
            decoded = atob(output.b64Json);
        } catch {
            throw new Error("生成结果 Base64 格式无效");
        }
        blob = new Blob([Uint8Array.from(decoded, (character) => character.charCodeAt(0))]);
    } else {
        const result = await downloadAIHubMixResult(config, task, output, {
            signal: context.signal,
            fetchImpl: options.fetchImpl
        });
        if (!result.ok) throw new Error(result.message);
        blob = result.blob;
    }
    context.signal.throwIfAborted();
    return saveBlob(job, blob);
}

export async function checkAgentGeneration(jobId: string, context: Pick<AgentToolContext, 'threadId' | 'signal'> & Partial<AgentToolContext>, options: GenerationRuntimeOptions = {}): Promise<AgentGenerationJob> {
    context.signal.throwIfAborted();
    let job;
    try {
        job = await jobForContext(jobId, context);
    } catch (error) {
        throw new AtomicToolRollbackError(cleanError(error));
    }
    if (["downloaded", "applied", "conflict", "failed"].includes(job.status)) return job;
    if (job.status === "unknown") return job;
    if (!job.providerTaskId) {
        if (job.status === "submitting") job = await updateGenerationJob(jobId, {
            status: "unknown",
            error: "付费提交结果尚未确认；无任务标识，不能自动再次提交。请到供应商后台核实。"
        });
        return job;
    }
    let config: ConnectorConfig | undefined;
    try {
        config = await connector(job.connectorId, job);
        if (job.provider === "aihubmix") {
            const response = await (job.kind === "image" ? getAIHubMixImageTask : getAIHubMixVideoTask)(config, job.providerTaskId, {
                signal: context.signal,
                fetchImpl: options.fetchImpl
            });
            if (!response.ok) throw new Error(response.message);
            return await acceptHubTask(jobId, response.task, config, context, options);
        }
        const response = await getApimartTask(config, job.providerTaskId, {
            signal: context.signal,
            fetchImpl: options.fetchImpl
        });
        if (!response.ok) throw new Error(response.message);
        const task = response.task;
        if (task.status === "failed" || task.status === "cancelled") return updateGenerationJob(jobId, {
            status: "failed",
            providerStatus: cleanError(new Error(task.providerStatus), config),
            error: cleanError(new Error(task.error?.message ?? "远端任务失败或已取消"), config)
        });
        if (task.status !== "completed") return updateGenerationJob(jobId, {
            status: task.status === "processing" ? "running" : "submitted",
            providerStatus: cleanError(new Error(task.providerStatus), config),
            progress: task.progress,
            error: undefined
        });
        const urls = (job.kind === "image" ? task.images : task.videos).flatMap((item) => item.urls);
        if (urls.length !== 1) throw new Error("预期单个生成结果，供应商返回数量或类型不匹配");
        const url = new URL(urls[0]);
        if (!/^https?:$/.test(url.protocol) || url.username || url.password) throw new Error("供应商结果下载地址无效");
        job = await updateGenerationJob(jobId, {
            status: "downloading",
            providerStatus: cleanError(new Error(task.providerStatus), config),
            progress: task.progress,
            error: undefined
        });
        // Public signed CDN result: never attach connector credentials or cookies.
        const download = await (options.fetchImpl ?? fetch)(url.href, {
            signal: context.signal,
            credentials: "omit",
            redirect: "error"
        });
        if (!download.ok) throw new Error(`结果下载失败（${download.status}），请检查过期时间、网络和跨域限制`);
        const blob = await download.blob();
        context.signal.throwIfAborted();
        return await saveBlob(job, blob);
    } catch (error) {
        await updateGenerationJob(jobId, {error: cleanError(error, config)});
        if (context.signal.aborted) throw new GenerationPendingError(jobId, "已停止本地查询或下载；远端任务仍可能继续，稍后可恢复查询");
        throw new GenerationPendingError(jobId, cleanError(error, config));
    }
}

function wait(ms: number, signal: AbortSignal) {
    return new Promise<void>((resolve, reject) => {
        signal.throwIfAborted();
        const abort = () => {
            clearTimeout(timer);
            signal.removeEventListener("abort", abort);
            reject(new DOMException("本地监控已停止", "AbortError"));
        };
        const timer = setTimeout(() => {
            signal.removeEventListener("abort", abort);
            resolve();
        }, ms);
        signal.addEventListener("abort", abort, {once: true});
    });
}

export async function monitorAgentGeneration(jobId: string, context: Pick<AgentToolContext, 'threadId' | 'signal'> & Partial<AgentToolContext>, options: GenerationRuntimeOptions = {}) {
    for (let step = 0; step < (options.maxPolls ?? 40); step++) {
        const job = await checkAgentGeneration(jobId, context, options);
        if (job.status === "unknown") throw new GenerationPendingError(jobId, job.error ?? "提交结果未知，请核实供应商账户，不会自动重试");
        if (["downloaded", "applied", "conflict", "failed"].includes(job.status)) return job;
        try {
            await wait(options.pollIntervalMs ?? Math.min(15000, 3000 + step * 2000), context.signal);
        } catch {
            throw new GenerationPendingError(jobId, "本地监控已停止；远端任务没有取消，继续执行时只查询已有任务");
        }
    }
    throw new GenerationPendingError(jobId, "本轮等待已暂停；任务仍在远端处理，继续执行可恢复查询，无需重新提交");
}

export async function prepareGenerationApply(jobId: string, context: AgentToolContext): Promise<AgentToolPreview> {
    const job = await jobForContext(jobId, context);
    if (job.batchId) throw new Error("批量候选需要由用户在批量结果中选择并写入");
    if (!job.result) throw new Error("生成结果尚未下载到本地，不能写入目标");
    await flushPendingDrafts(job.projectId);
    let label = "已删除或失效的目标";
    try {
        label = (await readGenerationTarget(job.target)).label;
    } catch { /* Apply records a visible conflict while preserving output. */
    }
    return {
        summary: `将生成${job.kind === "image" ? "图片" : "视频"}写入「${label}」`,
        changes: [`目标槽位：${job.target.slot}`, `结果素材：${job.result.mediaId}`, "不会改变镜头文字、时长或人工状态。"],
        revision: job.baseRevision,
        target: {label, href: generationTargetHref(job.target)}
    };
}

export async function applyAgentGeneration(jobId: string, context: AgentToolContext) {
    let original;
    try {
        original = await jobForContext(jobId, context);
        await flushPendingDrafts(original.projectId);
    } catch (error) {
        throw new AtomicToolRollbackError(cleanError(error));
    }
    if (original.batchId) throw new AtomicToolRollbackError("批量候选需要由用户在批量结果中选择并写入");
    if (!original.result || !["downloaded", "conflict", "applied"].includes(original.status)) throw new AtomicToolRollbackError("没有可写入的本地生成结果");
    if (original.status === "applied") return executeAtomicTool(context, async () => generationJobSummary(await jobForContext(jobId, context)));
    // Hash Blob inputs outside Dexie; atomic callback rechecks immutable record metadata.
    let records: MediaRecord[];
    try {
        records = await loadGenerationInputs(original);
    } catch (error) {
        return executeAtomicTool(context, async () => generationJobSummary(await updateGenerationJob(original.id, {
            status: "conflict",
            error: cleanError(error)
        })));
    }
    return executeAtomicTool(context, async () => {
        const job = await jobForContext(jobId, context);
        if (job.status === "applied") return generationJobSummary(job);
        if (!job.result || !["downloaded", "conflict"].includes(job.status)) throw new Error("没有可写入的本地生成结果");
        let current;
        try {
            current = await readGenerationTarget(job.target);
        } catch {
            return generationJobSummary(await updateGenerationJob(job.id, {
                status: "conflict",
                error: "目标已删除或归属变化；生成结果已保留，未写入目标"
            }));
        }
        if (current.revision !== job.baseRevision || context.preview?.revision && context.preview.revision !== job.baseRevision) {
            return generationJobSummary(await updateGenerationJob(job.id, {
                status: "conflict",
                error: "目标已被修改；生成结果已保留，请手动确认后使用已有素材"
            }));
        }
        for (const record of records) {
            const saved = await db.media.get(record.id);
            if (!saved || saved.projectId !== record.projectId || saved.mimeType !== record.mimeType || saved.blob.size !== record.blob.size) throw new Error("输入素材已变化，结果未应用");
        }
        const result = await db.media.get(job.result.mediaId);
        if (!result || result.projectId !== job.projectId || !result.blob.size || !result.mimeType.startsWith(`${job.kind}/`)) throw new Error("生成结果素材已删除或类型不匹配");
        const slot = {...current.slot, result: job.result};
        switch (job.target.kind) {
            case "shot":
                await setShotSlot(job.target.entityId, job.target.slot!, slot);
                break;
            case "character":
                await setCharacterSlot(job.target.entityId, job.target.slot, slot);
                break;
            case "scene":
                await setSceneSlot(job.target.entityId, job.target.slot, slot);
                break;
            case "prop":
                await setPropSlot(job.target.entityId, job.target.slot, slot);
                break;
            case "style":
                await setStyleSlot(job.target.entityId, job.target.slot, slot);
                break;
        }
        return generationJobSummary(await updateGenerationJob(job.id, {status: "applied", error: undefined}));
    });
}

import {z} from "zod";
import type {ConnectorConfig, MediaKind} from "@/domain/types";
import type {ProjectGenerationDefaults} from "@/domain/output";
import {validateGenerationDefaults} from "@/domain/output";
import type {
    GenerationPreference,
    GenerationPreferences,
    GenerationPreferenceState,
    GenerationSelection
} from "@/domain/generationPreferences";
import {generationSubmitSchema, profileRequest} from "./generationProfiles";

/** Accept full local connectors or a sanitized capability list; never return credentials. */
export type GenerationConnector = Pick<ConnectorConfig, "id" | "definitionId"> & {
    configured?: boolean;
    apiKey?: string
};

export interface GenerationRecommendation {
    source: "explicit" | "project" | "global" | "ai" | "none";
    /** ready validates configuration only; submission must still validate real inputs and target. */
    status: "ready" | "ambiguous" | "needs-selection";
    recommendation?: GenerationSelection;
    draft?: Partial<GenerationSelection>;
    candidateConnectorIds: string[];
    issues: string[];
}

const selectionSchema = generationSubmitSchema.pick({connectorId: true, model: true, parameters: true}).strict();
const preferenceParametersSchema = generationSubmitSchema.shape.parameters.removeDefault().omit({mode: true}).strict();
const preferenceSchema = selectionSchema.extend({parameters: preferenceParametersSchema.default({})}).strict();
const configured = (connector: GenerationConnector) => connector.configured ?? Boolean(connector.apiKey?.trim());

function validateSelection(kind: MediaKind, raw: unknown, connectors: readonly GenerationConnector[]): GenerationSelection {
    const selection = selectionSchema.parse(raw);
    const connector = connectors.find((item) => item.id === selection.connectorId);
    if (!connector || !configured(connector)) throw new Error("所选供应商连接已删除或尚未配置，请重新选择");
    if (connector.definitionId !== "apimart" && connector.definitionId !== "aihubmix") throw new Error("当前供应商暂不支持已验证的图片／视频生成配置");
    // Parameter-only validation uses local fixture roles, never stores/submits them.
    // Real input presence, ownership, size and mode remain the submission boundary's job.
    const mode = selection.parameters.mode ?? "text";
    profileRequest({
        ...selection, prompt: "参数配置校验", target: kind === "video"
            ? {kind: "shot", projectId: "validation", episodeId: "validation", entityId: "validation", slot: "clip"}
            : {kind: "character", projectId: "validation", entityId: "validation", slot: "front"},
        inputs: kind === "image" || mode === "text" ? [] : [{
            mediaId: "validation",
            role: mode === "frames" ? "first-frame" : "reference-image"
        }],
    }, connector.definitionId);
    return structuredClone(selection);
}

/** Strict save/read validation; context-dependent input mode is deliberately not remembered. */
export function validateGenerationPreference(kind: MediaKind, raw: unknown, connectors: readonly GenerationConnector[]): GenerationPreference {
    if (kind !== "image" && kind !== "video") throw new Error("生成偏好类型无效");
    const preference = preferenceSchema.parse(raw);
    if (preference.parameters.aspectRatio === "adaptive") throw new Error("跟随输入图片的比例仅适用于本次生成，请不要存为全局默认");
    return validateSelection(kind, preference, connectors) as GenerationPreference;
}

/** Invalid persisted choices stay in storage for explicit repair, never silently replaced. */
export function inspectGenerationPreferences(raw: unknown, connectors: readonly GenerationConnector[]): GenerationPreferenceState {
    if (raw === undefined) return {preferences: {}, issues: {}};
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {
        preferences: {},
        issues: {image: ["保存的生成偏好格式无效，请清除或重新保存"], video: ["保存的生成偏好格式无效，请清除或重新保存"]}
    };
    const record = raw as Record<string, unknown>;
    if (Object.keys(record).some((key) => key !== "image" && key !== "video")) return {
        preferences: {},
        issues: {
            image: ["保存的生成偏好包含不支持的字段，请重新保存"],
            video: ["保存的生成偏好包含不支持的字段，请重新保存"]
        }
    };
    const state: GenerationPreferenceState = {preferences: {}, issues: {}};
    for (const kind of ["image", "video"] as const) {
        if (record[kind] === undefined) continue;
        try {
            state.preferences[kind] = validateGenerationPreference(kind, record[kind], connectors);
        } catch (error) {
            state.issues[kind] = [preferenceError(error)];
        }
    }
    return state;
}

function preferenceError(error: unknown): string {
    // Schema details can repeat user-provided unknown field names; show only safe diagnosis.
    return error instanceof z.ZodError ? "配置字段或参数格式无效，请重新选择" : error instanceof Error ? error.message : "生成配置无效，请重新选择";
}

/** Independent recommendation only. Does not merge into or mutate the AI/user draft. */
export function recommendGenerationSelection(input: {
    kind: MediaKind;
    connectors: readonly GenerationConnector[];
    projectDefaults?: ProjectGenerationDefaults;
    preferences?: GenerationPreferences;
    preferenceIssues?: GenerationPreferenceState["issues"];
    aiSuggestion?: GenerationSelection;
    explicitSelection?: GenerationSelection;
}): GenerationRecommendation {
    const {kind, connectors} = input;
    const valid = (source: GenerationRecommendation["source"], candidate: GenerationSelection): GenerationRecommendation => {
        try {
            return {
                source,
                status: "ready",
                recommendation: validateSelection(kind, candidate, connectors),
                candidateConnectorIds: [candidate.connectorId],
                issues: []
            };
        } catch (error) {
            return {source, status: "needs-selection", candidateConnectorIds: [], issues: [preferenceError(error)]};
        }
    };
    if (input.explicitSelection !== undefined) return valid("explicit", input.explicitSelection);
    const project = input.projectDefaults?.[kind];
    if (project !== undefined) {
        const errors = validateGenerationDefaults({[kind]: project});
        if (errors.length) return {
            source: "project",
            status: "needs-selection",
            candidateConnectorIds: [],
            issues: errors
        };
        const candidates = connectors.filter((connector) => connector.definitionId === project.provider && configured(connector));
        const image = input.projectDefaults?.image;
        const parameters = kind === "image" && image
            ? {
                size: image.size, resolution: image.resolution,
                ...(image.quality ? {quality: image.quality as GenerationSelection["parameters"]["quality"]} : {}),
                ...(image.version ? {version: image.version as GenerationSelection["parameters"]["version"]} : {}),
            }
            : input.projectDefaults?.video ? {
                mode: input.projectDefaults.video.mode as "text" | "frames" | "reference",
                aspectRatio: input.projectDefaults.video.aspectRatio,
                resolution: input.projectDefaults.video.resolution,
                duration: input.projectDefaults.video.duration
            } : {};
        const draft = {model: project.model, parameters};
        if (candidates.length !== 1) return {
            source: "project",
            status: candidates.length > 1 ? "ambiguous" : "needs-selection",
            draft,
            candidateConnectorIds: candidates.map((connector) => connector.id),
            issues: [candidates.length > 1 ? "项目有多个可用的 APIMart 连接，请明确选择本次使用的连接" : "项目默认使用 APIMart，但当前没有已配置的 APIMart 连接"]
        };
        return valid("project", {...draft, connectorId: candidates[0]!.id});
    }
    if (input.preferenceIssues?.[kind]?.length) return {
        source: "global",
        status: "needs-selection",
        candidateConnectorIds: [],
        issues: [...input.preferenceIssues[kind]!]
    };
    if (input.preferences?.[kind] !== undefined) {
        try {
            return valid("global", validateGenerationPreference(kind, input.preferences[kind], connectors));
        } catch (error) {
            return {
                source: "global",
                status: "needs-selection",
                candidateConnectorIds: [],
                issues: [preferenceError(error)]
            };
        }
    }
    if (input.aiSuggestion !== undefined) return valid("ai", input.aiSuggestion);
    return {
        source: "none",
        status: "needs-selection",
        candidateConnectorIds: [],
        issues: ["尚未选择图片／视频生成配置，请选择供应商、模型和参数"]
    };
}

import {z} from 'zod';
import {db} from '@/db/database';
import {getReferenceSource} from '@/db/references';
import {
    CHARACTER_SLOTS,
    episodeLabel,
    type GenerationSlot,
    type MediaRecord,
    PROP_SLOTS,
    SCENE_SLOTS,
    STUDIO_LIBRARY_ID,
    STYLE_SLOTS
} from '@/domain/types';
import {parseGenerationSlot, parseShotPictureSlots} from '@/domain/slot';
import type {DiscoveredImage, ImageDiscoveryResult, ImageEntityKind, ImageSourceLocator} from '@/domain/imageDiscovery';
import type {AgentReferenceInput} from '@/domain/referenceInput';
import type {AgentToolContext} from './tools';
import {frozenProjectScope} from './projectScope';
import {targetRevision} from '@/lib/productionRevision';

const text = z.string().trim().min(1).max(200);
export const imageDiscoverySchema = z.object({
    projectQuery: text.optional(),
    projectId: text.optional(),
    episodeQuery: text.optional(),
    entityKind: z.enum(['shot', 'character', 'scene', 'prop', 'style']).optional(),
    query: z.string().trim().max(500).optional(),
    slot: text.optional(),
    source: z.enum(['current', 'reference', 'candidate']).default('current'),
    offset: z.number().int().min(0).max(100000).default(0),
    limit: z.number().int().min(1).max(20).default(10)
}).strict();
const tables = {shot: 'shots', character: 'characters', scene: 'scenes', prop: 'props', style: 'styles'} as const;
const catalogs = {
    shot: [{id: 'firstFrame', label: '首帧'}, {id: 'lastFrame', label: '尾帧'}, {
        id: 'clip',
        label: '视频参考'
    }], character: CHARACTER_SLOTS, scene: SCENE_SLOTS, prop: PROP_SLOTS, style: STYLE_SLOTS
};
const normalized = (value: string) => value.trim().toLocaleLowerCase();
const matches = (value: string, query: string) => normalized(value).includes(normalized(query));
const label = (value: unknown) => String(value ?? '').slice(0, 120);

interface Entity {
    id: string;
    projectId: string;
    episodeId?: string;
    name?: string;
    shotNumber?: string;
    content?: string;
    order?: number;
    slots?: Record<string, GenerationSlot>;

    [key: string]: unknown
}

function slots(kind: ImageEntityKind, entity: Entity): Record<string, GenerationSlot> {
    return kind === 'shot' ? parseShotPictureSlots(entity) : Object.fromEntries(catalogs[kind].map(({id}) => [id, parseGenerationSlot(entity.slots?.[id])]));
}

function target(projectId: string, kind: ImageEntityKind, entity: Entity) {
    const enc = encodeURIComponent;
    return {
        label: label(entity.name ?? `镜头 ${entity.shotNumber}`),
        href: kind === 'shot' ? `/p/${enc(projectId)}/e/${enc(entity.episodeId!)}/shots?shot=${enc(entity.id)}` : `/p/${enc(projectId)}/assets/${tables[kind]}/${enc(entity.id)}`
    };
}

async function sourceState(projectId: string, locator: ImageSourceLocator) {
    let identity: unknown, mediaId: string | undefined, currentlyApplied: boolean | undefined;
    if (locator.kind === 'slot') {
        const entity = await db.table<Entity, string>(tables[locator.entityKind]).get(locator.entityId);
        if (!entity || entity.projectId !== projectId) throw new Error('图片所属目标已删除，请重新查找');
        if (entity.episodeId) {
            const episode = await db.episodes.get(entity.episodeId);
            if (!episode || episode.projectId !== projectId) throw new Error('图片分集已不存在');
        }
        const slot = slots(locator.entityKind, entity)[locator.slot];
        if (!slot) throw new Error('图片槽位已不存在');
        mediaId = locator.source === 'current' ? slot.result?.mediaId : slot.referenceImageIds.includes(locator.mediaId ?? '') ? locator.mediaId : undefined;
        identity = {
            entityId: entity.id,
            episodeId: entity.episodeId,
            label: entity.name ?? entity.shotNumber,
            slot: locator.slot,
            source: locator.source,
            association: locator.source === 'current' ? slot.result : slot.referenceImageIds
        };
    } else if (locator.kind === 'reference') {
        const reference = await db.projectReferences.get(locator.referenceId);
        if (!reference || reference.projectId !== projectId || reference.kind !== 'image') throw new Error('图片参考资料已不存在');
        mediaId = reference.mediaId;
        identity = {
            id: reference.id,
            revision: reference.revision,
            status: reference.status,
            digest: reference.digest,
            mediaId
        };
    } else {
        const job = await db.agentGenerationJobs.get(locator.jobId);
        if (!job || job.projectId !== projectId || job.kind !== 'image' || !['downloaded', 'applied', 'conflict'].includes(job.status)) throw new Error('候选图片已不可用');
        const owner = await db.table<Entity, string>(tables[job.target.kind]).get(job.target.entityId);
        if (!owner || owner.projectId !== projectId || job.target.kind === 'shot' && owner.episodeId !== job.target.episodeId) throw new Error('候选目标已不存在');
        mediaId = job.result?.mediaId;
        currentlyApplied = !!mediaId && slots(job.target.kind, owner)[job.target.slot ?? 'firstFrame']?.result?.mediaId === mediaId;
        identity = {id: job.id, result: job.result, target: job.target, currentlyApplied};
    }
    const media = mediaId ? await db.media.get(mediaId) : undefined;
    const references = mediaId ? (await db.projectReferences.where('mediaId').equals(mediaId).toArray()).filter((row) => row.projectId === projectId) : [];
    const active = references.filter((row) => row.status === 'ready' || row.status === 'partial').sort((a, b) => b.createdAt.localeCompare(a.createdAt) || a.id.localeCompare(b.id))[0];
    const attachment = locator.kind === 'reference' ? references.find((row) => row.id === locator.referenceId) : active;
    let unavailableReason = !mediaId ? '当前目标没有此类图片' : !media || media.projectId !== projectId ? '图片文件已移除或归属不匹配' : !['image/png', 'image/jpeg', 'image/webp'].includes(media.mimeType) ? '仅支持 PNG、JPEG 或 WebP 图片' : media.blob.size <= 0 || media.blob.size > 10 * 1024 * 1024 ? '图片为空或超过 10 MiB' : undefined;
    if (attachment && !['ready', 'partial'].includes(attachment.status) || !attachment && references.length) unavailableReason = '图片参考资料已撤下或尚未准备完成';
    const reference = attachment ? {referenceId: attachment.id, revision: attachment.revision} : undefined;
    const revision = targetRevision({
        identity,
        media: media ? {
            id: media.id,
            projectId: media.projectId,
            mimeType: media.mimeType,
            size: media.blob.size,
            filename: media.filename
        } : null,
        reference,
        referenceState: attachment?.status
    });
    return {media, mediaId, revision, reference, unavailableReason, currentlyApplied};
}

export async function discoverProjectImages(raw: unknown, context: AgentToolContext): Promise<ImageDiscoveryResult> {
    context.signal.throwIfAborted();
    const args = imageDiscoverySchema.parse(raw), bound = await frozenProjectScope(context);
    if (!bound && !args.projectId && !args.projectQuery) throw new Error('请提供用户指定的项目名称或已确认的项目 ID');
    if (bound && args.projectId && bound !== args.projectId) throw new Error('此对话只能查看绑定项目的图片');
    let projects = bound ? [await db.projects.get(bound)] : args.projectId ? [await db.projects.get(args.projectId)] : await db.projects.toArray();
    projects = projects.filter((item) => !!item && item.id !== STUDIO_LIBRARY_ID);
    if (args.projectQuery) {
        const exact = projects.filter((row) => normalized(row!.name) === normalized(args.projectQuery!));
        projects = exact.length ? exact : projects.filter((row) => matches(row!.name, args.projectQuery!));
    }
    projects.sort((a, b) => a!.name.localeCompare(b!.name) || a!.id.localeCompare(b!.id));
    const base = {
        discoveryCallId: context.callId,
        projects: projects.slice(0, 20).map((row) => ({id: row!.id, name: label(row!.name)})),
        projectCount: projects.length,
        candidates: [] as DiscoveredImage[],
        total: 0,
        offset: args.offset,
        hasMore: false
    };
    if (projects.length !== 1) return {
        ...base,
        status: projects.length ? 'ambiguous_project' : 'not_found',
        note: projects.length ? '多个项目匹配，请确认项目后重新查找；此结果不授予图片读取。' : '未找到匹配项目。'
    };
    const project = projects[0]!;
    const episodes = (await db.episodes.where('projectId').equals(project.id).toArray()).sort((a, b) => a.order - b.order || a.id.localeCompare(b.id));
    const exactEpisodes = args.episodeQuery ? episodes.filter((row) => row.id === args.episodeQuery || normalized(episodeLabel(row)) === normalized(args.episodeQuery!) || normalized(row.title) === normalized(args.episodeQuery!)) : episodes;
    const selectedEpisodes = exactEpisodes.length ? exactEpisodes : episodes.filter((row) => matches(episodeLabel(row), args.episodeQuery!));
    const episodeMap = new Map(selectedEpisodes.map((row) => [row.id, row]));
    const rows: Array<Omit<DiscoveredImage, 'id' | 'revision' | 'available' | 'mediaId' | 'mimeType'>> = [];
    const kinds: ImageEntityKind[] = args.entityKind ? [args.entityKind] : ['shot', 'character', 'scene', 'prop', 'style'];
    const jobs = args.source === 'candidate' ? await db.agentGenerationJobs.where('projectId').equals(project.id).toArray() : [];
    for (const kind of kinds) {
        let entities = await db.table<Entity, string>(tables[kind]).where('projectId').equals(project.id).toArray();
        if (kind === 'shot') entities = entities.filter((row) => episodeMap.has(row.episodeId!));
        else if (args.episodeQuery) continue;
        if (args.query) {
            const exact = entities.filter((row) => row.id === args.query || normalized(String(row.shotNumber ?? row.name)) === normalized(args.query!));
            entities = exact.length ? exact : entities.filter((row) => matches(`${row.name ?? ''} ${row.shotNumber ?? ''} ${row.content ?? ''}`, args.query!));
        }
        entities.sort((a, b) => (episodeMap.get(a.episodeId!)?.order ?? 0) - (episodeMap.get(b.episodeId!)?.order ?? 0) || (a.order ?? 0) - (b.order ?? 0) || a.id.localeCompare(b.id));
        for (const entity of entities) {
            for (const entry of catalogs[kind].filter((entry) => (!args.slot || entry.id === args.slot || entry.label === args.slot) && (entry.id !== 'clip' || args.source === 'reference'))) {
                const episode = episodeMap.get(entity.episodeId!);
                const common = {
                    projectId: project.id,
                    projectName: label(project.name),
                    episodeId: entity.episodeId,
                    episodeTitle: episode ? episodeLabel(episode).slice(0, 120) : undefined,
                    entityKind: kind,
                    entityId: entity.id,
                    entityLabel: label(kind === 'shot' ? `镜头 ${entity.shotNumber}` : entity.name),
                    slot: entry.id,
                    slotLabel: entry.label,
                    source: args.source,
                    target: target(project.id, kind, entity)
                };
                if (args.source === 'candidate') {
                    for (const job of jobs.filter((job) => job.target.kind === kind && job.target.entityId === entity.id && (job.target.slot ?? 'firstFrame') === entry.id && job.kind === 'image' && ['downloaded', 'applied', 'conflict'].includes(job.status)).sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id))) rows.push({
                        ...common,
                        locator: {kind: 'job', jobId: job.id}
                    });
                } else if (args.source === 'reference') {
                    for (const mediaId of slots(kind, entity)[entry.id].referenceImageIds) rows.push({
                        ...common,
                        locator: {
                            kind: 'slot',
                            entityKind: kind,
                            entityId: entity.id,
                            slot: entry.id,
                            source: 'reference',
                            mediaId
                        }
                    });
                } else rows.push({
                    ...common,
                    locator: {kind: 'slot', entityKind: kind, entityId: entity.id, slot: entry.id, source: 'current'}
                });
            }
        }
    }
    if (args.source === 'reference' && !args.entityKind && !args.episodeQuery && !args.slot) {
        for (const reference of (await db.projectReferences.where('projectId').equals(project.id).toArray()).filter((row) => row.kind === 'image' && (!args.query || matches(row.filename, args.query))).sort((a, b) => a.id.localeCompare(b.id))) rows.push({
            projectId: project.id,
            projectName: label(project.name),
            entityKind: 'reference',
            entityId: reference.id,
            entityLabel: label(reference.filename),
            slot: 'reference',
            slotLabel: '资料库图片',
            source: 'reference',
            locator: {kind: 'reference', referenceId: reference.id},
            target: {label: label(reference.filename), href: `/p/${encodeURIComponent(project.id)}`}
        });
    }
    const candidates: DiscoveredImage[] = [];
    for (const row of rows.slice(args.offset, args.offset + args.limit)) {
        const state = await sourceState(project.id, row.locator);
        candidates.push({
            ...row,
            id: targetRevision({projectId: project.id, locator: row.locator}),
            revision: state.revision,
            mediaId: state.mediaId,
            mimeType: state.media?.mimeType,
            available: !state.unavailableReason,
            unavailableReason: state.unavailableReason, ...(state.currentlyApplied !== undefined ? {currentlyApplied: state.currentlyApplied} : {})
        });
    }
    context.signal.throwIfAborted();
    await frozenProjectScope(context);
    const result: ImageDiscoveryResult = {
        ...base,
        status: 'resolved',
        candidates,
        total: rows.length,
        hasMore: args.offset + candidates.length < rows.length,
        note: '仅查找图片身份，尚未读取像素。不同分集、槽位和候选保持独立；有歧义时请确认，比较请求可明确选择多张。current 仅表示当前槽位结果，不用参考图或旧候选代替缺失结果。'
    };
    while (JSON.stringify(result).length > 60000 && candidates.length) candidates.pop();
    result.hasMore = args.offset + candidates.length < rows.length;
    return result;
}

/** Resolve a grant only from a completed discovery ledger belonging to this run. */
export async function resolveDiscoveredImage(runId: string, discoveryCallId: string, candidateId: string) {
    const run = await db.agentRuns.get(runId), call = await db.agentToolCalls.get(discoveryCallId);
    const thread = run && await db.chatThreads.get(run.threadId);
    if (!run || !thread || run.projectId !== thread.projectId || !call || call.runId !== runId || call.threadId !== run.threadId || call.name !== 'discover_project_images' || call.status !== 'completed' || !call.result) throw new Error('图片查找来源无效，请在当前执行重新查找');
    const result = JSON.parse(call.result) as ImageDiscoveryResult;
    const candidate = result.discoveryCallId === discoveryCallId && result.status === 'resolved' ? result.candidates.find((row) => row.id === candidateId) : undefined;
    if (!candidate || !candidate.available || !candidate.mediaId || candidate.projectId === STUDIO_LIBRARY_ID || run.projectId && candidate.projectId !== run.projectId || !await db.projects.get(candidate.projectId)) throw new Error('图片候选不可读取或项目归属不匹配，请重新查找');
    const state = await sourceState(candidate.projectId, candidate.locator);
    if (state.unavailableReason || state.revision !== candidate.revision || state.mediaId !== candidate.mediaId) throw new Error('图片来源已变化，请重新查找后读取');
    if (state.reference) await getReferenceSource(candidate.projectId, state.reference);
    return {candidate, media: state.media!, reference: state.reference};
}

export async function imageDigest(media: MediaRecord): Promise<string> {
    return [...new Uint8Array(await crypto.subtle.digest('SHA-256', await media.blob.arrayBuffer()))].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

export async function validateDiscoveredInput(input: AgentReferenceInput, runId: string | undefined): Promise<void> {
    const provenance = input.discovery;
    if (!runId || !provenance || input.images?.length !== 1 || input.coverage?.length) throw new Error('图片查找来源缺失');
    const read = await db.agentToolCalls.get(provenance.readCallId), run = await db.agentRuns.get(runId);
    if (!read || !run || read.name !== 'read_project_image' || read.status !== 'completed' || read.runId !== runId || read.threadId !== run.threadId || !read.result) throw new Error('图片读取来源不属于当前执行');
    const args = JSON.parse(read.arguments) as { discoveryCallId?: string; candidateId?: string };
    const saved = (JSON.parse(read.result) as { referenceInput?: AgentReferenceInput }).referenceInput;
    if (args.discoveryCallId !== provenance.discoveryCallId || args.candidateId !== provenance.candidateId || targetRevision(saved) !== targetRevision(input)) throw new Error('图片读取身份与执行记录不匹配');
    const resolved = await resolveDiscoveredImage(runId, provenance.discoveryCallId, provenance.candidateId);
    if (input.projectId !== resolved.candidate.projectId || input.images[0].mediaId !== resolved.media.id || JSON.stringify(input.references) !== JSON.stringify(resolved.reference ? [resolved.reference] : [])) throw new Error('图片读取范围与来源不匹配');
    if (await imageDigest(resolved.media) !== provenance.mediaDigest) throw new Error('图片内容已变化，请重新查找后读取');
    // Hashing awaits Blob reads; the source association can change while it runs,
    // including during the final post-encoding validation before dispatch.
    await resolveDiscoveredImage(runId, provenance.discoveryCallId, provenance.candidateId);
}

import {db} from '@/db/database';
import type {AgentReferenceInput} from '@/domain/referenceInput';
import type {AgentToolContext} from './tools';
import {assertMaterialVersion} from './materialContent';
import {frozenProjectScope} from './projectScope';
import {targetRevision} from '@/lib/productionRevision';
import {assertReferenceSignature} from '@/lib/references/parse';
import {parseReferenceFile} from '@/lib/references/import';
import {assertImageQueueCapacity} from './imageQueue';

export async function materialBlobDigest(blob: Blob): Promise<string> {
    return [...new Uint8Array(await crypto.subtle.digest('SHA-256', await blob.arrayBuffer()))].map(byte => byte.toString(16).padStart(2, '0')).join('');
}

async function source(materialId: string, revision: number, context: AgentToolContext, mediaId?: string) {
    const {material, version} = await assertMaterialVersion(materialId, revision, context);
    const payload = version.payload;
    const file = payload.type === 'file' ? payload : payload.media.find(row => row.id === mediaId);
    if (!file || payload.type === 'file' && mediaId) throw new Error('素材文件不存在；设定素材请先读取详情，选择准确图片 ID');
    return {material, version, file};
}

export async function queueMaterialImage(materialId: string, revision: number, context: AgentToolContext, mediaId?: string) {
    await assertImageQueueCapacity(context);
    const {file, version} = await source(materialId, revision, context, mediaId);
    if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.mimeType) || file.blob.size <= 0 || file.blob.size > 10 * 1024 * 1024) throw new Error('仅支持 10 MiB 以内的 PNG、JPEG 或 WebP 素材图片');
    const bytes = new Uint8Array(await file.blob.arrayBuffer());
    assertReferenceSignature(bytes, 'image', file.mimeType);
    await parseReferenceFile(bytes.buffer, 'image', file.mimeType, context.signal);
    const digest = await materialBlobDigest(file.blob);
    await source(materialId, revision, context, mediaId);
    const projectId = await frozenProjectScope(context) ?? 'studio';
    const referenceInput: AgentReferenceInput = {
        projectId, references: [],
        material: {
            kind: 'image',
            materialId,
            revision,
            readCallId: context.callId, ...(mediaId ? {mediaId} : {}),
            digest
        },
        images: [{
            projectId,
            mediaId: `material:${version.id}:${mediaId ?? 'file'}`,
            filename: file.filename,
            mimeType: file.mimeType,
            size: file.blob.size
        }],
    };
    return {
        status: 'queued',
        materialId,
        revision,
        referenceInput,
        note: '已准备素材图片；下一轮向当前模型发送真实像素后才能分析。文件名和元信息不代表图片内容。'
    };
}

/** A saved read grants only this version in this run. Revalidate before and after encoding. */
export async function resolveMaterialInput(input: AgentReferenceInput, projectId: string | undefined, runId?: string) {
    const proof = input.material;
    if (!proof || !runId || input.discovery || input.references.length || input.coverage?.length || input.projectId !== (projectId ?? 'studio')) throw new Error('素材读取来源缺失或范围不匹配');
    const run = await db.agentRuns.get(runId), call = await db.agentToolCalls.get(proof.readCallId);
    if (!run || run.projectId !== projectId || !call || call.runId !== runId || call.threadId !== run.threadId || call.status !== 'completed' || call.name !== `material_read_${proof.kind}` || !call.result) throw new Error('素材读取记录不属于当前执行');
    const args = JSON.parse(call.arguments) as { materialId?: string; revision?: number; mediaId?: string };
    const saved = (JSON.parse(call.result) as { referenceInput?: AgentReferenceInput }).referenceInput;
    if (args.materialId !== proof.materialId || args.revision !== proof.revision || args.mediaId !== proof.mediaId || targetRevision(saved) !== targetRevision(input)) throw new Error('素材身份与读取记录不一致');
    const context: AgentToolContext = {
        projectId,
        runId,
        threadId: run.threadId,
        callId: call.id,
        signal: new AbortController().signal
    };
    const {file, version} = await source(proof.materialId, proof.revision, context, proof.mediaId);
    if (proof.kind === 'image') {
        const image = input.images?.[0];
        if (input.images?.length !== 1 || !image || image.projectId !== input.projectId || image.mediaId !== `material:${version.id}:${proof.mediaId ?? 'file'}` || image.mimeType !== file.mimeType || image.size !== file.blob.size || !['image/png', 'image/jpeg', 'image/webp'].includes(file.mimeType) || file.blob.size > 10 * 1024 * 1024) throw new Error('素材图片身份或格式已变化');
    } else if (input.images?.length) throw new Error('文档读取不能附带图片');
    if (await materialBlobDigest(file.blob) !== proof.digest) throw new Error('素材内容已变化，请重新读取');
    await source(proof.materialId, proof.revision, context, proof.mediaId);
    return file;
}

import {db} from '@/db/database';
