            if (material.scope.kind === 'project' && material.scope.id !== args.projectId || material.scope.kind === 'ip' && material.scope.id !== project.link?.ipId) throw new Error('素材归属与目标项目不兼容；IP 素材需同一 IP，项目素材需同一项目。可先明确确认保存为通用素材');
            return {
