        parseArguments: (raw) => image.parse(raw),
        parameters: {
            type: "object",
            additionalProperties: false,
            properties: {
                mediaId: {type: "string", minLength: 1, maxLength: 200},
                discoveryCallId: {type: "string", minLength: 1, maxLength: 200},
