    todoId: optional(text(80, 1))
};

async function owner(context: AgentToolContext, name: string) {
    context.signal.throwIfAborted();
    const projectId = await frozenProjectScope(context);
    if (!projectId) throw new Error("任务需要绑定项目");
    const run = await db.agentRuns.get(context.runId), call = await db.agentToolCalls.get(context.callId);
    const thread = await db.chatThreads.get(context.threadId);
    if (!run || !thread || run.threadId !== thread.id || run.status !== "running" || !call || call.runId !== run.id || call.threadId !== thread.id || call.name !== name || call.status !== "running" || !run.enabledToolNames?.includes(name) || run.interactionMode === "conversation") throw new Error("任务工具执行归属或权限无效");
    const siblings = await db.agentRuns.where("threadId").equals(thread.id).toArray();
    if (siblings.some((other) => other.id !== run.id && other.createdAt >= run.createdAt)) throw new Error("只能由当前最新执行维护任务");
    const task = await db.agentTasks.where("threadId").equals(thread.id).first();
    if (!run.taskMode && !run.taskId) throw new Error("只有任务模式可以创建或维护任务");
    if (run.taskId && (!task || task.id !== run.taskId || task.projectId !== projectId)) throw new Error("任务关联已失效");
    if (task && task.lifecycle !== "open") throw new Error("请先重新打开任务");
    return {run, thread, task};
}

/** Task artifacts are appendable; never copy their entire history into a tool result. */
function taskResult(task: AgentTask) {
    return {...task, artifacts: task.artifacts.slice(-10), artifactCount: task.artifacts.length};
}

function requiredTask(task?: AgentTask): AgentTask {
    if (!task) throw new Error("需求明确后先创建任务");
    return task;
}

function tool<T>(name: string, title: string, description: string, spec: Spec<T>, execute: (args: T, context: AgentToolContext, state: Awaited<ReturnType<typeof owner>>) => Promise<unknown>): AgentToolDefinition {
    return {
        name,
        title,
        description,
        parameters: spec.json,
        effect: "bookkeeping",
        atomic: true,
        highRisk: () => false,
        parseArguments: (raw) => spec.schema.parse(raw),
        execute: (args, context) => executeAtomicTool(context, async () => {
            const value = await execute(spec.schema.parse(args), context, await owner(context, name));
            return name === "task_read" ? {...(value as Record<string, unknown>), sourceProjectionVersion: 1} : value;
        })
    };
}

export const TASK_TOOLS: readonly AgentToolDefinition[] = [
    tool("task_read", "读取任务工作区", "读取当前任务、记录索引及真实用户消息和工具结果的来源 ID。未建任务时读取需求对话。offset/limit 翻页列表；传 source 和 contentOffset/contentLimit 分段读取来源全文，每次最多6000字，不访问其他任务。", object({
        offset: optional(number(0, 100000, true)),
        limit: optional(number(1, 10, true)),
        source: optional(source),
        contentOffset: optional(number(0, 10000000, true)),
        contentLimit: optional(number(1, 6000, true))
    }), async (args, _context, {task, thread}) => {
        const offset = args.offset ?? 0, limit = args.limit ?? 5;
        const messages = (await db.chatMessages.where("threadId").equals(thread.id).sortBy("createdAt")).filter((m) => m.role === "user" && !!m.content.trim()).reverse();
        const taskRunIds = new Set(task ? (await db.agentRuns.where("taskId").equals(task.id).toArray()).map((run) => run.id) : []);
        const calls = (await db.agentToolCalls.where("threadId").equals(thread.id).toArray()).filter((c) => c.status === "completed" && c.effect !== "bookkeeping" && !!c.result && taskRunIds.has(c.runId)).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
        if (args.source?.type === "generation") {
            if (!task) throw new Error("当前任务不存在");
            const item = await taskGenerationSource(task, args.source.id), contentOffset = args.contentOffset ?? 0,
                contentLimit = args.contentLimit ?? 6000;
            return {
                source: args.source,
                content: item.body.slice(contentOffset, contentOffset + contentLimit),
                totalLength: item.body.length,
                nextOffset: contentOffset + contentLimit < item.body.length ? contentOffset + contentLimit : null
            };
        }
        if (args.source) {
            const item = args.source.type === "message" ? messages.find((message) => message.id === args.source!.id) : calls.find((call) => call.id === args.source!.id);
            if (!item) throw new Error("来源不是当前任务可读取的用户消息或已完成业务工具结果");
            const content = "content" in item ? item.content : await currentTaskToolContent(item, task);
            const contentOffset = args.contentOffset ?? 0, contentLimit = args.contentLimit ?? 6000;
            return {
                source: args.source,
                content: content.slice(contentOffset, contentOffset + contentLimit),
                totalLength: content.length,
                nextOffset: contentOffset + contentLimit < content.length ? contentOffset + contentLimit : null
            };
        }
        const records = task ? await listTaskRecords(task.id) : [];
        const generations = task ? await listTaskGenerationSources(task) : [];
        const tools = [];
        for (const call of calls.slice(offset, offset + limit)) {
            const content = await Promise.resolve(currentTaskToolContent(call, task));
            tools.push({
                id: call.id,
                name: call.name,
                status: call.status,
                result: content.slice(0, 400),
                truncated: content.length > 400
            });
        }
        return {
            task: task ? taskResult(task) : null,
            records: records.slice(offset, offset + limit).map(({
                                                                    id,
                                                                    kind,
                                                                    claim,
                                                                    title,
                                                                    revision,
                                                                    author,
                                                                    todoId
                                                                }) => ({
                id,
                kind,
                claim,
                title,
                revision,
                author,
                todoId
            })),
            recordCount: records.length,
            messages: messages.slice(offset, offset + limit).map((m) => ({
                id: m.id,
                content: m.content.slice(0, 800),
                truncated: m.content.length > 800
            })),
            messageCount: messages.length,
            generations: generations.slice(offset, offset + limit).map(item => ({
                id: item.id,
                label: item.label,
                available: item.available,
                applied: item.applied,
                supportsResult: item.supportsResult, ...("batchId" in item ? {
                    batchId: item.batchId,
                    status: item.status,
                    result: item.result
                } : {}),
                sourceType: "generation"
            })),
            generationCount: generations.length,
            tools,
            toolCount: calls.length
        };
    }),
    tool("task_create", "建立创作任务", "仅在任务模式、需求和交付物足够明确后创建。先通过 task_read 获取用户消息来源。重复创建返回同一任务，不覆盖目标。", object({
        ...taskFieldsSpec,
        sources: array(source, 12, 1)
    }), async (args, _context, {run, thread, task}) => {
        if (task) return {task: taskResult(task), reused: true};
        if (!run.taskMode) throw new Error("只有任务模式可以创建任务");
        await validateTaskSources({id: "", threadId: thread.id}, args.sources, "decision", "ai");
        if (args.steps.some((step) => step.status === "completed")) throw new Error("新任务不能预先声称步骤完成");
        const at = nowIso();
        const created: AgentTask = {
            ...taskFields({...args, plan: args.steps}),
            id: createId("task"),
            projectId: run.projectId!,
            threadId: thread.id,
            agentId: GENERAL_AGENT_ID,
            revision: 1,
            lifecycle: "open",
            artifacts: [],
            createdAt: at,
            updatedAt: at
        };
        await db.agentTasks.add(created);
        await db.agentRuns.update(run.id, {taskId: created.id, plan: created.plan, updatedAt: at});
        await db.chatThreads.update(thread.id, {taskMode: true, updatedAt: at});
        await writeTaskRecord(created, {
            kind: "approach",
            claim: "decision",
            title: "任务目标与验收要求",
            body: formatTaskRequirements(created),
            sources: args.sources
        }, {author: "ai", runId: run.id, requirementSnapshot: true});
        return {task: taskResult(created), reused: false};
    }),
    tool("task_update", "更新任务要求", "修改当前任务名称、目标及验收要求，必须引用用户澄清消息并提供读取到的 revision。计划用 update_run_plan。保留变更历史。", object({
        title: text(120, 1),
        goal: text(20000, 1),
        acceptanceCriteria: array(text(500, 1), 20),
        expectedRevision: number(1, 1000000, true),
        sources: array(source, 12, 1)
    }), async (args, _context, {task, run}) => {
        const current = requiredTask(task);
        if ((current.revision ?? 1) !== args.expectedRevision) throw new Error("任务已更新，请重新读取后修改");
        await validateTaskSources(current, args.sources, "decision", "ai");
        await writeTaskRecord(current, {
            kind: "approach",
            claim: "decision",
            title: "任务要求调整",
            body: `调整前\n${formatTaskRequirements(current)}\n\n调整后\n${formatTaskRequirements(args)}`,
            sources: args.sources
        }, {author: "ai", runId: run.id, requirementSnapshot: true});
        const updated = {
            ...current, ...taskFields({...args, plan: current.plan}),
            revision: (current.revision ?? 1) + 1,
            updatedAt: nowIso()
        };
        await db.agentTasks.put(updated);
        return {task: taskResult(updated)};
    }),
    tool("task_record_write", "保存任务工作记录", "保存调研、方案、进展、验证或待解决问题。proposal 是建议；decision 必须有用户消息来源；observation 引用真实读取结果；result 必须引用完成的业务操作或当前任务真实可用的 generation 成果。声音草稿、远端完成或历史保存消息不能证明当前音频可用。来源不代表主观目标已通过验收。更新需 id 和 expectedRevision。", object({
        ...recordFields,
        id: optional(id),
        expectedRevision: optional(number(1, 1000000, true))
    }), async (args, _context, {task, run}) => {
        const {id, expectedRevision, ...input} = args;
        return {
            record: await writeTaskRecord(requiredTask(task), input, {
                id,
                expectedRevision,
                author: "ai",
                runId: run.id
            })
        };
    }),
    tool("task_record_read", "读取任务记录", "读取当前任务记录及指定历史版本，按正文 offset/limit 分页。只有当前版本会进入后续任务上下文；旧版本用于追溯。", object({
        id,
        revision: optional(number(1, 1000000, true)),
        offset: optional(number(0, 120000, true)),
        limit: optional(number(1, 6000, true))
    }), async (args, _context, {task}) => {
        const current = requiredTask(task), record = await db.agentTaskRecords.get(args.id);
        if (!record || record.taskId !== current.id) throw new Error("记录不属于当前任务");
        const versions = await listTaskRecordVersions(current.id, record.id);
        const selected = args.revision ? versions.find((v) => v.revision === args.revision) : record;
        if (!selected) throw new Error("记录版本不存在");
        const offset = args.offset ?? 0, limit = args.limit ?? 6000;
        return {
            record: {...selected, body: selected.body.slice(offset, offset + limit)},
            totalLength: selected.body.length,
            versionCount: versions.length,
            versions: versions.slice(-50).map(({revision, author, updatedAt}) => ({revision, author, updatedAt}))
        };
    }),
];

import {z} from "zod";

/** A durable, resumable tool is waiting for its external job, not a model turn. */
export class ToolPendingError extends Error {
}

export interface ToolValidationIssue {
    path: string;
    constraint: string;
    /** Numeric values or type labels only; never strings supplied by the model. */
    received?: number | string;
}

export interface ToolValidationFailure {
    code: "INVALID_TOOL_ARGUMENTS";
    executed: false;
    error: string;
    issues: ToolValidationIssue[];
    recovery: string;
}

const RECOVERY = "本次调用未执行。若任务仍需要此操作，请修正参数并使用新的工具调用标识发起调用，不要把失败当作成功或自动重放原调用。若已有其他证据足以回答，请明确说明未执行的操作及其对结论的影响。";

export class ToolValidationError extends Error {
    readonly failure: ToolValidationFailure;

    constructor(title: string, name: string, issues: ToolValidationIssue[]) {
        const detail = issues.map((issue) => `${issue.path}：${issue.constraint}${issue.received === undefined ? "" : `（收到 ${issue.received}）`}`).join("；");
        super(`工具 ${title} 的参数无效，未执行。${detail}`.slice(0, 2_048));
        this.name = "ToolValidationError";
        this.failure = {
            code: "INVALID_TOOL_ARGUMENTS", executed: false, error: this.message, issues,
            recovery: RECOVERY + (name === "business_read_text" ? " business_read_text 的 limit 必须是 1 至 12000 的整数；按返回的 nextOffset 分页读取，直到 nextOffset 为空。" : ""),
        };
    }
}

function isRecord(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function typeLabel(type: string): string {
    const labels: Record<string, string> = {
        string: "文本", number: "数字", integer: "整数", float: "小数", boolean: "布尔值",
        object: "对象", array: "数组", null: "空值", undefined: "未提供", nan: "无效数字",
        date: "日期", bigint: "大整数", symbol: "符号", function: "函数", map: "映射", set: "集合", promise: "异步结果",
    };
    return labels[type] ?? "规定的数据类型";
}

/** Only schema-owned field names may enter diagnostics; unknown keys can contain secrets. */
function safeField(path: Array<string | number>, schema: Record<string, unknown>, raw: unknown) {
    const parts: string[] = [];
    let current: unknown = schema;
    let received = raw;
    for (const segment of path.slice(0, 8)) {
        if (!isRecord(current)) return {path: parts.join(".") || "参数", received: undefined};
        if (typeof segment === "number" && current.type === "array") {
            parts.push(`[${segment}]`);
            current = current.items;
            received = Array.isArray(received) ? received[segment] : undefined;
        } else if (typeof segment === "string" && isRecord(current.properties) && Object.hasOwn(current.properties, segment)) {
            parts.push(segment.slice(0, 64));
            current = current.properties[segment];
            received = isRecord(received) && Object.hasOwn(received, segment) ? received[segment] : undefined;
        } else return {path: parts.join(".") || "参数", received: undefined};
    }
    return {path: parts.join(".") || "参数", received};
}

export function toolArgumentError(title: string, name: string, schema: Record<string, unknown>, raw: unknown, cause: unknown): ToolValidationError {
    const issues: ToolValidationIssue[] = cause instanceof z.ZodError ? cause.issues.slice(0, 6).map((issue) => {
        const field = safeField(issue.path, schema, raw);
        let constraint = "不符合工具要求，请按参数定义修正";
        if (issue.code === "too_big") constraint = `不得${issue.inclusive ? "大于" : "大于或等于"} ${issue.maximum}${issue.type === "string" ? " 个字符" : issue.type === "array" ? " 项" : ""}`;
        else if (issue.code === "too_small") constraint = `不得${issue.inclusive ? "小于" : "小于或等于"} ${issue.minimum}${issue.type === "string" ? " 个字符" : issue.type === "array" ? " 项" : ""}`;
        else if (issue.code === "invalid_type") constraint = `必须是${typeLabel(issue.expected)}`;
        else if (issue.code === "unrecognized_keys") constraint = "包含未允许的字段，请移除定义之外的参数";
        else if (issue.code === "invalid_enum_value" || issue.code === "invalid_literal") constraint = "必须使用参数定义中允许的值";
        else if (issue.code === "custom" && issue.params?.diagnosticCode === "episode_script_path") constraint = "分集剧本必须使用 story.script 字段路径，不能使用 script";
        else if (issue.code === "custom" && issue.params?.diagnosticCode === "business_field_path") constraint = "不是允许的创作字段路径，请先用 business_detail 核对字段层级，再读取文本字段";
        const received = typeof field.received === "number" && Number.isFinite(field.received) ? field.received : typeLabel(field.received === null ? "null" : Array.isArray(field.received) ? "array" : typeof field.received);
        return {path: field.path, constraint, received};
    }) : [{
        path: "参数",
        constraint: cause instanceof SyntaxError ? "必须是有效的 JSON 对象" : "不符合工具要求，请按参数定义修正"
    }];
    return new ToolValidationError(title, name, issues);
}

/** Read only the explicitly structured, bounded result; legacy generic errors need revalidation. */
export function readToolValidationFailure(result?: string): ToolValidationFailure | undefined {
    if (!result || result.length > 8_192) return;
    try {
        const value: unknown = JSON.parse(result);
        if (!isRecord(value) || value.code !== "INVALID_TOOL_ARGUMENTS" || value.executed !== false || typeof value.error !== "string" || value.error.length > 2_048 || typeof value.recovery !== "string" || value.recovery.length > 2_048 || !Array.isArray(value.issues) || value.issues.length > 6) return;
        const issues: ToolValidationIssue[] = [];
        for (const issue of value.issues) {
            if (!isRecord(issue) || typeof issue.path !== "string" || issue.path.length > 600 || typeof issue.constraint !== "string" || issue.constraint.length > 300 || issue.received !== undefined && !(typeof issue.received === "number" && Number.isFinite(issue.received)) && !(typeof issue.received === "string" && issue.received.length < 80)) return;
            issues.push({
                path: issue.path,
                constraint: issue.constraint, ...(issue.received === undefined ? {} : {received: issue.received as number | string})
            });
        }
        return {code: "INVALID_TOOL_ARGUMENTS", executed: false, error: value.error, issues, recovery: value.recovery};
    } catch {
        return;
    }
}

import {z} from "zod";
import {db} from "@/db/database";
import {executeAtomicTool} from "@/db/agentTools";
import type {AgentRun, AgentToolCall, AgentToolLoading} from "@/domain/agent";
import {toResponseInput} from "@/lib/ai/responsesStream";
import {AGENT_SKILLS, SMART_EXECUTION_INSTRUCTIONS} from "./skills";
import type {ProjectKind} from "@/domain/types";
import type {AgentToolDefinition} from "./tools";

export const DISCOVERY_TOOL_NAME = "load_tool_groups";
export const MAX_LOADED_TOOLS = 36;
const settled = (call: AgentToolCall) => ["completed", "failed", "rejected"].includes(call.status);
const foundation = (name: string) => name === "workspace_overview" || name === "update_run_plan" || name.startsWith("task_");

/** Freeze descriptions, instructions and permission-filtered names at run creation. */
export function createToolLoading(skillIds: readonly string[], allowedNames: readonly string[], projectKind?: ProjectKind): AgentToolLoading | undefined {
    const groups = AGENT_SKILLS.filter((skill) => skillIds.includes(skill.id)).map((skill) => ({
        ...skill,
        toolNames: skill.toolNames.filter((name) => allowedNames.includes(name))
    })).filter((skill) => skill.toolNames.length);
    const deferred = groups.filter((skill) => skill.toolNames.some((name) => !foundation(name)));
    if (!deferred.length) return undefined;
    const foundationToolNames = [...new Set([...allowedNames.filter(foundation), DISCOVERY_TOOL_NAME])];
    const preferred = projectKind === "audio" ? "audio-production" : projectKind === "music" ? "music-creation" : undefined;
    const initial = deferred.find((group) => group.id === preferred);
    const loadedToolNames = initial ? [...new Set(initial.toolNames)] : [];
    const preload = new Set([...foundationToolNames, ...loadedToolNames]).size <= MAX_LOADED_TOOLS;
    return {
        version: 1,
        groups: deferred,
        foundationToolNames,
        foundationInstructions: groups.filter((skill) => skill.toolNames.every(foundation)).map((skill) => skill.instructions).join("\n"),
        loadedGroupIds: initial && preload ? [initial.id] : [], loadedToolNames: preload ? loadedToolNames : [],
    };
}

export function getOfferedToolNames(run: Pick<AgentRun, "enabledToolNames" | "toolLoading" | "interactionMode">): string[] {
    if (run.interactionMode === "conversation") return [];
    if (!run.toolLoading) return run.enabledToolNames ?? [];
    const allowed = run.enabledToolNames ?? [];
    return [...new Set([...run.toolLoading.foundationToolNames, ...run.toolLoading.loadedToolNames])].filter((name) => allowed.includes(name));
}

/** A call must have been offered in its own request, not merely loaded later. */
export function toolNamesForCall(run: AgentRun, step: number): string[] {
    if (!run.toolLoading) return run.enabledToolNames ?? [];
    return (run.offeredTools?.find((offer) => offer.step === step)?.names ?? []).filter((name) => run.enabledToolNames?.includes(name));
}

export function toolLoadingInstructions(state: AgentToolLoading): string {
    return [
        SMART_EXECUTION_INSTRUCTIONS,
        state.foundationInstructions,
        "按需工具：已提供定义的业务工具可以直接调用，不必重复加载。当前未提供的工具须先调用 load_tool_groups，系统在同一次执行的下一次模型请求提供定义，收到结果后立即继续，不需要用户发送继续。groupIds 为要保留的完整分组列表（最多 2 组，替换上次加载）；空列表配合 query 只查目录，不执行业务。发现与加载不改变授权。依赖上一步结果的操作放到收到结果后的下一次模型请求。",
        "可用能力目录：\n" + state.groups.map((group) => `${group.id}｜${group.name}：${group.description}`).join("\n"),
        ...state.groups.filter((group) => state.loadedGroupIds.includes(group.id)).map((group) => group.instructions),
    ].filter(Boolean).join("\n");
}

const loadingSchema = z.object({
    groupIds: z.array(z.string().min(1).max(80)).max(2),
    query: z.string().trim().max(100).optional()
}).strict();
export const DISCOVERY_TOOLS: readonly AgentToolDefinition[] = [{
    name: DISCOVERY_TOOL_NAME,
    title: "加载创作工具",
    description: "按能力目录加载最多两组已授权工具，替换之前的业务组；同次执行的下一次模型请求获得完整定义，无需用户再次发送消息。groupIds=[] 时仅按 query 查询目录，不执行业务。",
    parameters: {
        type: "object",
        additionalProperties: false,
        required: ["groupIds"],
        properties: {
            groupIds: {type: "array", maxItems: 2, items: {type: "string", minLength: 1, maxLength: 80}},
            query: {type: "string", maxLength: 100}
        }
    },
    effect: "bookkeeping",
    atomic: true,
    highRisk: () => false,
    parseArguments: (raw) => loadingSchema.parse(raw),
    async execute(raw, context) {
        const args = loadingSchema.parse(raw);
        return executeAtomicTool(context, async () => {
            const run = await db.agentRuns.get(context.runId);
            const state = run?.toolLoading;
            const call = await db.agentToolCalls.get(context.callId);
            if (!run || !state || !call || call.name !== DISCOVERY_TOOL_NAME || !toolNamesForCall(run, call.step).includes(DISCOVERY_TOOL_NAME)) throw new Error("本轮未提供工具加载入口");
            if (args.groupIds.some((id) => !state.groups.some((group) => group.id === id))) throw new Error("请求的能力不存在或未启用，请使用可用能力目录中的分组 ID");
            const selected = state.groups.filter((group) => args.groupIds.includes(group.id));
            if (!selected.length) {
                const query = args.query?.toLocaleLowerCase();
                return {
                    groups: state.groups.filter((group) => !query || `${group.id} ${group.name} ${group.description}`.toLocaleLowerCase().includes(query)).map(({
                                                                                                                                                                    id,
                                                                                                                                                                    name,
                                                                                                                                                                    description
                                                                                                                                                                }) => ({
                        id,
                        name,
                        description
                    })),
                    loadedGroupIds: state.loadedGroupIds,
                    note: "仅查询目录；请接着选择 groupIds，系统将在同次执行的下一次模型请求加载定义；不代表业务已执行。"
                };
            }
            const pending = (await db.agentToolCalls.where("runId").equals(run.id).toArray()).filter((row) => !settled(row));
            const pinned = pending.map((row) => row.name).filter((name) => !state.foundationToolNames.includes(name));
            const loadedToolNames = [...new Set([...selected.flatMap((group) => group.toolNames), ...pinned])].filter((name) => run.enabledToolNames?.includes(name)).sort();
            if (new Set([...state.foundationToolNames, ...loadedToolNames]).size > MAX_LOADED_TOOLS) throw new Error(`同时加载的工具超过 ${MAX_LOADED_TOOLS} 个，请一次选择一个分组，待当前调用完成后再切换。`);
            const next = {
                ...state,
                loadedGroupIds: [...new Set([...selected.map((group) => group.id), ...state.loadedGroupIds.filter((id) => state.groups.find((group) => group.id === id)?.toolNames.some((name) => pinned.includes(name)))])],
                loadedToolNames
            };
            await db.agentRuns.update(run.id, {toolLoading: next});
            return {
                loadedGroupIds: next.loadedGroupIds,
                toolNames: loadedToolNames,
                effectiveFromStep: (run.modelStep ?? 0) + 1,
                note: "工具已准备好，系统会在同一次执行的下一次模型请求提供完整参数；请接着调用所需业务工具，无需用户再发送开始或继续。此操作只加载能力，没有执行任何业务。"
            };
        });
    },
}];

/** Replace only the upcoming skill layer; preserve request history and paired tool envelopes. */
export async function refreshRunToolLoading(runId: string): Promise<AgentRun> {
    return db.transaction("rw", [db.agentRuns, db.agentToolCalls], async () => {
        const run = await db.agentRuns.get(runId);
        if (!run || run.status !== "running") throw new Error("执行已停止");
        if (!run.toolLoading && !run.createdProjectBinding) return run;
        if ((await db.agentToolCalls.where("runId").equals(runId).toArray()).some((call) => !settled(call))) throw new Error("请先处理工具步骤，再切换能力");
        const bindingNotice = "当前执行已通过创建项目工具一次性绑定新项目。请以最新项目事实与创建结果中的真实 ID 在同次执行继续用户要求的创作；不需要新开对话或请用户再次发送开始。此说明取代旧技能中创建后必须新开项目对话的指引。原有付费确认、权限和停止边界继续生效。";
        let skillInstructions = run.toolLoading ? toolLoadingInstructions(run.toolLoading) : run.skillInstructions ?? "";
        if (run.createdProjectBinding?.projectId === run.projectId && !skillInstructions.includes(bindingNotice)) skillInstructions += `\n${bindingNotice}`;
        if (skillInstructions === run.skillInstructions) return run;
        const messages = run.continuationMessages ?? run.requestMessages;
        const oldBase = run.context?.baseMessages ?? [messages[0]];
        if (!oldBase[0] || oldBase[0].role !== "system" || JSON.stringify(messages.slice(0, oldBase.length)) !== JSON.stringify(oldBase)) throw new Error("技能上下文信封不匹配");
        const baseMessages = [{
            ...oldBase[0],
            content: [run.agentSnapshot.instructions, skillInstructions].filter(Boolean).join("\n")
        }, ...oldBase.slice(1)];
        const oldResponseBase = toResponseInput(oldBase);
        if (run.responseItems && JSON.stringify(run.responseItems.slice(0, oldResponseBase.length)) !== JSON.stringify(oldResponseBase)) throw new Error("Responses 技能信封不匹配");
        const next: AgentRun = {
            ...run,
            skillInstructions, ...(run.context ? {
                context: {
                    ...run.context,
                    baseMessages
                }
            } : {}),
            continuationMessages: [...baseMessages, ...messages.slice(oldBase.length)], ...(run.responseItems ? {responseItems: [...toResponseInput(baseMessages), ...run.responseItems.slice(oldResponseBase.length)]} : {})
        };
        await db.agentRuns.put(next);
        return next;
    });
}

