function parseShot(
    raw: Record<string, unknown>,
    projectId: Id,
    episodeId: Id,
    index: number,
): Shot {
    const slots = parseShotPictureSlots(raw);
    return {
        id: String(raw.id ?? createId("sht")),
        projectId,
        episodeId: String(raw.episodeId ?? episodeId),
        order: Number(raw.order ?? index + 1) || index + 1,
        shotNumber: String(raw.shotNumber ?? index + 1),
        status: normalizeShotStatus(raw.status),
        propIds: optionalIds(raw, "propIds"),
        styleId: raw.styleId === null ? null : optionalText(raw, "styleId"),
        firstFrame: slots.firstFrame,
        lastFrame: slots.lastFrame,
        clip: slots.clip,
        category: String(raw.category ?? ""),
        durationSec: Number(raw.durationSec ?? 0) || 0,
        content: String(raw.content ?? ""),
        notes: String(raw.notes ?? ""),
        sceneCloseup: String(raw.sceneCloseup ?? ""),
        sound: String(raw.sound ?? ""),
        emotion: String(raw.emotion ?? ""),
        cameraAngle: String(raw.cameraAngle ?? ""),
        cameraGear: String(raw.cameraGear ?? ""),
        focalLength: String(raw.focalLength ?? ""),
        characterIds: Array.isArray(raw.characterIds)
            ? raw.characterIds.map((id) => String(id))
            : [],
        sceneId: raw.sceneId ? String(raw.sceneId) : undefined,
        beatId: raw.beatId ? String(raw.beatId) : undefined,
        extra: pickExtra(raw, SHOT_KEYS),
    };
}

function remapId(
    map: Map<string, string>,
    oldId: string | undefined,
    prefix: string,
) {
    if (!oldId) return undefined;
    const existing = map.get(oldId);
    if (existing) return existing;
    const next = createId(prefix);
    map.set(oldId, next);
    return next;
}

type MemoryPackage = {
    memories: ProjectMemory[];
    memoryVersions: ProjectMemoryVersion[];
};

/** Validate the whole aggregate before any imported project or media is persisted. */
function parseMemoryPackage(
    rawRows: unknown,
    rawVersions: unknown,
    projectId: unknown,
): MemoryPackage {
    const rows = z
        .array(projectMemorySchema)
        .safeParse(rawRows === undefined ? [] : rawRows);
    const versions = z
        .array(projectMemoryVersionSchema)
        .safeParse(rawVersions === undefined ? [] : rawVersions);
    if (!rows.success || !versions.success)
        throw new PackageError("项目记忆或历史版本格式无效");
    const memories = rows.data;
    const memoryVersions = versions.data;
    const fail = () => {
        throw new PackageError("项目记忆的归属、替代关系或版本链无效");
    };
    const byId = new Map(memories.map((row) => [row.id, row]));
    if (
        byId.size !== memories.length ||
        new Set(memoryVersions.map((row) => row.versionId)).size !==
        memoryVersions.length
    )
        fail();
    const chains = new Map<string, ProjectMemoryVersion[]>();
    for (const version of memoryVersions) {
        if (
            !byId.has(version.memoryId) ||
            version.projectId !== projectId ||
            version.snapshot.id !== version.memoryId ||
            version.snapshot.projectId !== projectId ||
            version.snapshot.revision !== version.revision
        )
            fail();
        const chain = chains.get(version.memoryId) ?? [];
        chain.push(version);
        chains.set(version.memoryId, chain);
    }
    const validateSnapshot = (row: ProjectMemory) => {
        if (row.projectId !== projectId || row.projectId === "studio") fail();
        if (row.source.kind === "summary" && row.source.projectId !== projectId)
            fail();
        if (row.supersededBy === row.id) fail();
    };
    for (const row of memories) {
        validateSnapshot(row);
        const chain = (chains.get(row.id) ?? []).sort(
            (a, b) => a.revision - b.revision,
        );
        if (
            chain.length !== row.revision ||
            chain.some((v, index) => v.revision !== index + 1)
        )
            fail();
        if (JSON.stringify(chain.at(-1)?.snapshot) !== JSON.stringify(row)) fail();
        for (const version of chain) validateSnapshot(version.snapshot);
        const visited = new Set<string>([row.id]);
        let next = row.supersededBy;
        while (next) {
            if (visited.has(next)) fail();
            visited.add(next);
            next = byId.get(next)?.supersededBy;
        }
    }
    // Match CRUD topic identity after validating the original chain, so normalization
    // cannot conceal inconsistent source snapshots or bypass same-topic conflicts.
    for (const row of memories) row.topicKey = normalizeMemoryText(row.topicKey);
    for (const version of memoryVersions) {
        version.snapshot.topicKey = normalizeMemoryText(version.snapshot.topicKey);
    }
    return {memories, memoryVersions};
}

function detachedMemorySource(row: ProjectMemory): MemorySource {
    const source = row.source;
    if (source.kind === "imported") return {...source};
    return {
        kind: "imported",
        originProjectId: row.projectId,
        originMemoryId: row.id,
        originalKind: source.kind,
        excerpt:
            source.kind === "summary" ? source.excerpt : row.body.slice(0, 3000),
        ...(source.kind === "summary"
            ? {
                taskTitle: source.taskTitle,
                summaryId: source.summaryId,
                summaryRevision: source.summaryRevision,
                evidence: source.evidence,
            }
            : {}),
    };
}

function remapMemoryPackage(
    input: MemoryPackage,
    projectId: Id,
    at: string,
): MemoryPackage {
    const ids = new Map(input.memories.map((row) => [row.id, createId("pm")]));
    const snapshot = (row: ProjectMemory): ProjectMemory => ({
        ...row,
        id: ids.get(row.id)!,
        projectId,
        source: detachedMemorySource(row),
        supersededBy: row.supersededBy ? ids.get(row.supersededBy) : undefined,
    });
    const memoryVersions = input.memoryVersions.map((version) => ({
        ...version,
        versionId: createId("pmv"),
        memoryId: ids.get(version.memoryId)!,
        projectId,
        snapshot: snapshot(version.snapshot),
    }));
    const memories = input.memories.map((row) => {
        const current = {
            ...snapshot(row),
            status: "pending_review" as const,
            revision: row.revision + 1,
            updatedAt: at,
        };
        delete current.reviewedAt;
        const detachedReplacement = input.memoryVersions.some(
            (version) =>
                version.memoryId === row.id &&
                version.snapshot.supersededBy &&
                !ids.has(version.snapshot.supersededBy),
        );
        memoryVersions.push({
            versionId: createId("pmv"),
            memoryId: current.id,
            projectId,
            revision: current.revision,
            reason: `导入项目备份，等待重新审核${detachedReplacement ? "；原替代条目已删除，已解除关联" : ""}`,
            snapshot: current,
        });
        return current;
    });
    return {memories, memoryVersions};
}

export async function exportProjectZip(projectId: Id): Promise<Blob> {
    // Snapshot all JSON rows and referenced Blobs under one read transaction.
    // Compression happens after the transaction closes; no external awaits hold it open.
    const {
        audioPackage,
        project,
        characters,
        scenes,
        props,
        styles,
        episodes,
        shots,
        mediaRecords,
        memories,
        memoryVersions,
        references,
        referenceChunks,
    } = await db.transaction(
        "r",
        [
            ...AUDIO_TABLES,
            db.projects,
            db.characters,
            db.scenes,
            db.props,
            db.styles,
            db.episodes,
            db.shots,
            db.media,
            db.materialUses,
            db.projectMemories,
            db.projectMemoryVersions,
            db.projectReferences,
            db.referenceChunks,
        ],
        async () => {
            const project = await db.projects.get(projectId);
            if (!project) throw new PackageError("项目不存在");
            const [
                characters,
                scenes,
                props,
                styles,
                episodes,
                shots,
                memories,
                memoryVersions,
                references,
                referenceChunks,
            ] = await Promise.all([
                db.characters.where("projectId").equals(projectId).toArray(),
                db.scenes.where("projectId").equals(projectId).toArray(),
                db.props.where("projectId").equals(projectId).toArray(),
                db.styles.where("projectId").equals(projectId).toArray(),
                db.episodes.where("projectId").equals(projectId).sortBy("order"),
                db.shots.where("projectId").equals(projectId).sortBy("order"),
                db.projectMemories.where("projectId").equals(projectId).toArray(),
                db.projectMemoryVersions.where("projectId").equals(projectId).toArray(),
                db.projectReferences.where("projectId").equals(projectId).toArray(),
                db.referenceChunks.where("projectId").equals(projectId).toArray(),
            ]);
            const mediaIds = await collectMediaIds(projectId);
            const mediaRecords = (await db.media.bulkGet([...mediaIds])).filter(
                (media): media is MediaRecord =>
                    media !== undefined && media.projectId === projectId,
            );
            if (getProjectKind(project) !== "video" && mediaRecords.length !== mediaIds.size) throw new PackageError("音频项目存在缺失或归属错误的文件，请恢复文件后再备份");
            return {
                audioPackage: await snapshotAudioPackage(projectId),
                project,
                characters,
                scenes,
                props,
                styles,
                episodes,
                shots,
                mediaRecords,
                memories,
                memoryVersions,
                references,
                referenceChunks,
            };
        },
    );
    const zip = new JSZip();
    zip.file(
        "manifest.json",
        JSON.stringify(
            {
                format: PACKAGE_FORMAT,
                exportedAt: nowIso(),
                projectName: project.name,
            },
            null,
            2,
        ),
    );
    if (getProjectKind(project) !== "video") zip.file("audioProject.json", JSON.stringify(audioPackage));
    zip.file("project.json", JSON.stringify(project, null, 2));
    zip.file("characters.json", JSON.stringify(characters, null, 2));
    zip.file("scenes.json", JSON.stringify(scenes, null, 2));
    zip.file("props.json", JSON.stringify(props, null, 2));
    zip.file("styles.json", JSON.stringify(styles, null, 2));
    zip.file("episodes.json", JSON.stringify(episodes, null, 2));
    zip.file("shots.json", JSON.stringify(shots, null, 2));
    zip.file("memories.json", JSON.stringify(memories, null, 2));
    zip.file("memoryVersions.json", JSON.stringify(memoryVersions, null, 2));
    zip.file("references.json", JSON.stringify(references));
    zip.file("referenceChunks.json", JSON.stringify(referenceChunks));
    zip.file("mediaMetadata.json", JSON.stringify(mediaRecords.map((media) => ({
        id: media.id,
        projectId: media.projectId,
        filename: media.filename,
        mimeType: media.mimeType,
        libraryRetained: media.libraryRetained,
    }))));
    for (const media of mediaRecords) {
        const filename = `media/${media.id}.${extFor(media.mimeType, media.filename)}`;
        zip.file(filename, media.blob);
    }
    return zip.generateAsync({type: "blob"});
}

export async function importProjectZip(file: Blob): Promise<Project> {
    const zip = await JSZip.loadAsync(file).catch(() => {
        throw new PackageError("无法读取 zip 文件");
    });
    const manifestFile = zip.file("manifest.json");
    if (!manifestFile) throw new PackageError("缺少 manifest.json");
    const manifestJson = JSON.parse(
        await manifestFile.async("string"),
    ) as unknown;
    const manifest = manifestSchema.safeParse(manifestJson);
    if (!manifest.success) {
        throw new PackageError("不是小光点项目包（manifest.format 不匹配）");
    }

    const readJson = async (name: string, required = false) => {
        const entry = zip.file(name);
        if (!entry) {
            if (required) throw new PackageError(`缺少 ${name}`);
            return undefined;
        }
        try {
            return JSON.parse(await entry.async("string")) as unknown;
        } catch {
            throw new PackageError(`${name} 不是合法 JSON`);
        }
    };

    const projectRaw = asRecord(
        await readJson("project.json", true),
        "project.json",
    );
    const charactersRaw = asArray(
        await readJson("characters.json"),
        "characters.json",
    );
    const scenesRaw = asArray(await readJson("scenes.json"), "scenes.json");
    const propsRaw = asArray(await readJson("props.json"), "props.json");
    const stylesRaw = asArray(await readJson("styles.json"), "styles.json");
    const episodesFile = await readJson("episodes.json");
    const episodesRaw =
        episodesFile == null ? [] : asArray(episodesFile, "episodes.json");
    const shotsRaw = asArray(await readJson("shots.json"), "shots.json");
    const memoryPackage = parseMemoryPackage(
        await readJson("memories.json"),
        await readJson("memoryVersions.json"),
        projectRaw.id,
    );
    const referencePackage = parseReferencePackage(await readJson("references.json"), await readJson("referenceChunks.json"), projectRaw.id);
    const mediaMetadataRaw = await readJson("mediaMetadata.json");
    const mediaMetadata = new Map<string, { filename: string; mimeType: string; libraryRetained?: boolean }>();
    if (mediaMetadataRaw !== undefined) {
        for (const raw of asArray(mediaMetadataRaw, "mediaMetadata.json")) {
            const row = asRecord(raw, "mediaMetadata.json");
            if (typeof row.id !== "string" || !row.id || /[/\\]/.test(row.id) || mediaMetadata.has(row.id)
                || row.projectId !== projectRaw.id || typeof row.filename !== "string" || !row.filename
                || typeof row.mimeType !== "string" || !/^[a-zA-Z0-9!#$&^_.+-]+\/[a-zA-Z0-9!#$&^_.+-]+(?:;[a-zA-Z0-9=._ ,"+-]+)*$/.test(row.mimeType)) {
                throw new PackageError("媒体元数据无效、重复或不属于当前项目");
            }
            if (row.libraryRetained !== undefined && typeof row.libraryRetained !== "boolean") throw new PackageError("素材保留标记无效");
            mediaMetadata.set(row.id, {
                filename: row.filename,
                mimeType: row.mimeType,
                libraryRetained: row.libraryRetained
            });
        }
    }
    const hasEpisodes = episodesRaw.length > 0;

    const project = parseProject(projectRaw, "导入的项目");
    const audioPackage = parseAudioPackage(await readJson("audioProject.json"), projectRaw.id, getProjectKind(project));
    if (getProjectKind(project) !== "video" && (episodesRaw.length || shotsRaw.length || charactersRaw.length || scenesRaw.length || propsRaw.length || stylesRaw.length)) throw new PackageError("音频或音乐项目不能包含视频记录");
    const projectId = createId("prj");
    const at = nowIso();
    project.id = projectId;
    project.createdAt = at;
    project.updatedAt = at;
    const {memories, memoryVersions} = remapMemoryPackage(
        memoryPackage,
        projectId,
        at,
    );
    if (!hasEpisodes) {
        project.columnSettings = {visible: [...DEFAULT_VISIBLE_COLUMNS]};
    }

    const mediaMap = new Map<string, string>();
    const characterMap = new Map<string, string>();
    const sceneMap = new Map<string, string>();
    const propMap = new Map<string, string>();
    const styleMap = new Map<string, string>();
    const episodeMap = new Map<string, string>();
    const beatMaps = new Map<string, Map<string, string>>();
    const shotMap = new Map<string, string>();

    const mediaRecords: MediaRecord[] = [];
    const mediaFiles = zip.file(/^media\//);
    for (const entry of mediaFiles) {
        if (entry.dir) continue;
        const base = entry.name.split("/").pop() ?? entry.name;
        const oldId = base.replace(/\.[^.]+$/, "");
        if (mediaMap.has(oldId)) throw new PackageError("项目包中存在重复媒体 ID");
        const metadata = mediaMetadata.get(oldId);
        if (mediaMetadataRaw !== undefined && !metadata) throw new PackageError("媒体缺少元数据");
        const newId = remapId(mediaMap, oldId, "med")!;
        const blob = await entry.async("blob");
        const mimeType = metadata?.mimeType ?? (blob.type || mimeForFilename(base));
        mediaRecords.push({
            id: newId,
            projectId,
            mimeType,
            filename: metadata?.filename ?? base,
            libraryRetained: metadata?.libraryRetained,
            blob: new Blob([blob], {type: mimeType}),
        });
    }

    if ([...mediaMetadata.keys()].some((id) => !mediaMap.has(id))) throw new PackageError("媒体元数据对应的文件缺失");

    const remappedAudioPackage = remapAudioPackage(audioPackage, projectId, mediaMap);
    const {
        references,
        chunks: referenceChunks
    } = await remapReferencePackage(referencePackage, projectId, mediaMap, mediaRecords);

    const mapMedia = (id?: string) => (id ? mediaMap.get(id) : undefined);

    if (project.coverMediaId) {
        const mappedCover = mapMedia(project.coverMediaId);
        if (mappedCover) project.coverMediaId = mappedCover;
        else delete project.coverMediaId;
    }

    const characters = charactersRaw.map((raw) => {
        const character = parseCharacter(raw, projectId);
        const newId = remapId(characterMap, character.id, "chr")!;
        character.id = newId;
        character.projectId = projectId;
        const images: Character["slots"] = {};
        for (const [slot, value] of Object.entries(character.slots)) {
            if (!value) continue;
            images[slot as keyof Character["slots"]] = remapSlot(value, mapMedia);
        }
        character.slots = images;
        return character;
    });

    const scenes = scenesRaw.map((raw) => {
        const scene = parseScene(raw, projectId);
        scene.id = remapId(sceneMap, scene.id, "scn")!;
        scene.projectId = projectId;
        const images: Scene["slots"] = {};
        for (const [slot, value] of Object.entries(scene.slots)) {
            if (!value) continue;
            images[slot as keyof Scene["slots"]] = remapSlot(value, mapMedia);
        }
        scene.slots = images;
        return scene;
    });

    const props = propsRaw.map((raw) => {
        const prop = parseProp(raw, projectId);
        prop.id = remapId(propMap, prop.id, "prp")!;
        prop.slots = Object.fromEntries(
            Object.entries(prop.slots).map(([slot, value]) => [
                slot,
                value ? remapSlot(value, mapMedia) : value,
            ]),
        ) as Prop["slots"];
        return prop;
    });

    const styles = stylesRaw.map((raw) => {
        const style = parseStyle(raw, projectId);
        style.id = remapId(styleMap, style.id, "sty")!;
        style.slots = Object.fromEntries(
            Object.entries(style.slots).map(([slot, value]) => [
                slot,
                value ? remapSlot(value, mapMedia) : value,
            ]),
        ) as VisualStyle["slots"];
        return style;
    });

    if (project.defaultStyleId !== undefined)
        project.defaultStyleId = styleMap.get(project.defaultStyleId);

    const parsedEpisodes = getProjectKind(project) !== "video" ? [] : hasEpisodes
        ? episodesRaw.map((raw, index) => parseEpisode(raw, projectId, index))
        : [synthesizeFirstEpisode(project, projectRaw)];

    const episodes = parsedEpisodes.map((episode) => {
        const filters = getEpisodeShotFilters(episode, project);
        const oldEpisodeId = episode.id;
        const newId = remapId(episodeMap, oldEpisodeId, "ep")!;
        const beatMap = new Map<string, string>();
        beatMaps.set(oldEpisodeId, beatMap);
        episode.id = newId;
        episode.projectId = projectId;
        episode.story = {
            ...episode.story,
            beats: episode.story.beats.map((beat) => {
                const newBeatId = remapId(beatMap, beat.id, "beat")!;
                return {
                    ...beat,
                    id: newBeatId,
                    characterIds: beat.characterIds
                        .map((id) => characterMap.get(id))
                        .filter((id): id is string => Boolean(id)),
                    sceneId: beat.sceneId ? sceneMap.get(beat.sceneId) : undefined,
                };
            }),
        };
        episode.shotFilters = {
            ...filters,
            beatIds: filters.beatIds.flatMap((id) => {
                if (id === SHOT_UNASSIGNED_BEAT) return [id];
                const mapped = beatMap.get(id);
                return mapped ? [mapped] : [];
            }),
        };
        return episode;
    });
    // Legacy filters have been migrated per episode; never retain obsolete beat IDs.
    project.shotSettings.filters = normalizeShotFilters(undefined);

    const fallbackEpisodeId = episodes[0]?.id ?? createId("ep");

    const shots = shotsRaw.map((raw, index) => {
        const shot = parseShot(raw, projectId, fallbackEpisodeId, index);
        const oldEpisodeId = shot.episodeId;
        shot.id = remapId(shotMap, shot.id, "sht")!;
        shot.projectId = projectId;
        shot.episodeId = episodeMap.get(oldEpisodeId) ?? fallbackEpisodeId;
        shot.firstFrame = remapSlot(shot.firstFrame, mapMedia);
        shot.lastFrame = remapSlot(shot.lastFrame, mapMedia);
        shot.clip = remapSlot(shot.clip, mapMedia);
        shot.characterIds = shot.characterIds
            .map((id) => characterMap.get(id))
            .filter((id): id is string => Boolean(id));
        shot.sceneId = shot.sceneId ? sceneMap.get(shot.sceneId) : undefined;
        if (shot.propIds !== undefined)
            shot.propIds = shot.propIds.flatMap((id) => propMap.get(id) ?? []);
        // A missing explicit style must not unexpectedly inherit a different default.
        if (typeof shot.styleId === "string")
            shot.styleId = styleMap.get(shot.styleId) ?? null;
        const beatMap =
            beatMaps.get(oldEpisodeId) ?? beatMaps.values().next().value;
        shot.beatId = shot.beatId ? beatMap?.get(shot.beatId) : undefined;
        return shot;
    });

    try {
        await db.transaction(
            "rw",
            [
                ...AUDIO_TABLES,
                db.projects,
                db.characters,
                db.scenes,
                db.props,
                db.styles,
                db.episodes,
                db.shots,
                db.media,
                db.projectMemories,
                db.projectMemoryVersions,
                db.projectReferences,
                db.referenceChunks,
            ],
            async () => {
                await db.projects.add(project);
                if (characters.length) await db.characters.bulkAdd(characters);
                if (scenes.length) await db.scenes.bulkAdd(scenes);
                if (props.length) await db.props.bulkAdd(props);
                if (styles.length) await db.styles.bulkAdd(styles);
                if (episodes.length) await db.episodes.bulkAdd(episodes);
                if (shots.length) await db.shots.bulkAdd(shots);
                if (mediaRecords.length) await db.media.bulkAdd(mediaRecords);
                await insertAudioPackage(remappedAudioPackage);
                if (references.length) await db.projectReferences.bulkAdd(references);
                if (referenceChunks.length) await db.referenceChunks.bulkAdd(referenceChunks);
                if (memories.length) await db.projectMemories.bulkAdd(memories);
                if (memoryVersions.length)
                    await db.projectMemoryVersions.bulkAdd(memoryVersions);
            },
        );
    } catch (error) {
        throw new PackageError(
            error instanceof Error ? `导入失败：${error.message}` : "导入失败",
        );
    }

    return project;
}

export function downloadBlob(blob: Blob, filename: string) {
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
}

import {db} from "@/db/database";
import {generationImageDimensions} from "@/lib/agent/generationMedia";
import {
    type ParsedReference,
    type ProjectReference,
    REFERENCE_LIMITS as LIMITS,
    type ReferenceKind
} from "@/domain/references";
import {isStudioLibrary} from "@/domain/types";
import {createId, nowIso} from "@/lib/ids";
import {assertReferenceSignature, identifyReference, parseTextReference} from "./parse";

export interface ReferenceImportOptions {
    signal?: AbortSignal;
    onProgress?: (reference: ProjectReference) => void
}

async function parseDocxInWorker(buffer: ArrayBuffer, signal?: AbortSignal): Promise<ParsedReference> {
    const worker = new Worker(new URL("./docx.worker.ts", import.meta.url), {type: "module"});
    return new Promise((resolve, reject) => {
        const finish = (error?: unknown, result?: ParsedReference) => {
            clearTimeout(timer);
            signal?.removeEventListener("abort", abort);
            worker.terminate();
            if (error) reject(error); else resolve(result!);
        };
        const abort = () => finish(signal?.reason ?? new Error("解析已取消"));
        const timer = setTimeout(() => finish(new Error("DOCX 解析超时，请拆分文档后重试")), LIMITS.workerTimeoutMs);
        worker.onmessage = (event: MessageEvent<{
            result?: ParsedReference;
            error?: string
        }>) => finish(event.data.error ? new Error(event.data.error) : undefined, event.data.result);
        worker.onerror = () => finish(new Error("DOCX 解析失败，请检查文件后重试"));
        signal?.addEventListener("abort", abort, {once: true});
        if (signal?.aborted) abort(); else worker.postMessage(buffer, [buffer]);
    });
}

export async function parseReferenceFile(buffer: ArrayBuffer, kind: ReferenceKind, mimeType: string, signal?: AbortSignal): Promise<ParsedReference> {
    signal?.throwIfAborted();
    if (kind === "text") return parseTextReference(buffer);
    if (kind === "pdf") return (await import("./pdf")).parsePdfReference(buffer, signal);
    if (kind === "docx") return parseDocxInWorker(buffer, signal);
    const dimensions = await generationImageDimensions(new Blob([buffer], {type: mimeType}));
    if (dimensions.width * dimensions.height > 100_000_000) throw new Error("图片像素超过 1 亿，请缩小后重试");
    if (typeof createImageBitmap !== "undefined") {
        const image = await createImageBitmap(new Blob([buffer], {type: mimeType})).catch(() => {
            throw new Error("图片已损坏，无法解码");
        });
        try {
            if (image.width * image.height > 100_000_000) throw new Error("图片像素超过 1 亿，请缩小后重试");
        } finally {
            image.close();
        }
    }
    return {
        chunks: [],
        coverage: {totalUnits: 1, processedUnits: 1, emptyUnits: [], characters: 0, truncated: false},
        warnings: []
    };
}

async function finishImport(reference: ProjectReference, buffer: ArrayBuffer, options: ReferenceImportOptions): Promise<ProjectReference> {
    options.onProgress?.(reference);
    let parsed: ParsedReference | undefined;
    let error: string | undefined;
    try {
        parsed = await parseReferenceFile(buffer, reference.kind, reference.mimeType, options.signal);
        options.signal?.throwIfAborted();
    } catch (failure) {
        error = options.signal?.aborted ? "解析已取消，可以重试" : failure instanceof Error ? failure.message : "解析失败，请重试";
    }
    return db.transaction("rw", [db.projects, db.projectReferences, db.referenceChunks], async () => {
        const current = await db.projectReferences.get(reference.id);
        if (!current || current.operationId !== reference.operationId || current.status !== "parsing" || !(await db.projects.get(reference.projectId))) throw new Error("资料已移除或本次解析已被替代");
        const next: ProjectReference = {
            ...current,
            updatedAt: nowIso(),
            status: error ? "failed" : parsed!.coverage.truncated || parsed!.coverage.emptyUnits.length > 0 && reference.kind === "pdf" ? "partial" : "ready",
            error,
            coverage: parsed?.coverage ?? current.coverage,
            warnings: parsed?.warnings ?? [],
        };
        await db.referenceChunks.where("referenceId").equals(reference.id).delete();
        if (parsed?.chunks.length) await db.referenceChunks.bulkAdd(parsed.chunks.map((chunk) => ({
            ...chunk,
            id: createId("rfc"),
            referenceId: reference.id,
            revision: reference.revision,
            projectId: reference.projectId
        })));
        await db.projectReferences.put(next);
        return next;
    });
}

async function importSource(projectId: string, file: File, options: ReferenceImportOptions, existingMediaId?: string): Promise<ProjectReference> {
    const format = identifyReference(file);
    if (isStudioLibrary(projectId) || !(await db.projects.get(projectId))) throw new Error("请先选择一个项目，再添加参考资料");
    options.signal?.throwIfAborted();
    const buffer = await file.arrayBuffer();
    assertReferenceSignature(new Uint8Array(buffer), format.kind, format.mimeType);
    const digest = [...new Uint8Array(await crypto.subtle.digest("SHA-256", buffer))].map((byte) => byte.toString(16).padStart(2, "0")).join("");
    options.signal?.throwIfAborted();
    const operationId = createId("parse");
    const reference = await db.transaction("rw", [db.projects, db.media, db.projectReferences], async () => {
        options.signal?.throwIfAborted();
        if (!(await db.projects.get(projectId))) throw new Error("项目已删除");
        const duplicate = await db.projectReferences.where("[projectId+digest]").equals([projectId, digest]).filter((row) => row.status !== "unavailable").first();
        if (duplicate) return duplicate;
        const mediaId = existingMediaId ?? createId("med");
        if (existingMediaId) {
            const media = await db.media.get(existingMediaId);
            if (!media || media.projectId !== projectId || media.blob.size !== file.size) throw new Error("图片已不可用");
        } else await db.media.add({
            id: mediaId,
            projectId,
            filename: file.name,
            mimeType: format.mimeType,
            blob: new Blob([buffer], {type: format.mimeType})
        });
        const at = nowIso();
        const row: ProjectReference = {
            ...format,
            id: createId("ref"),
            projectId,
            mediaId,
            digest,
            filename: file.name,
            size: file.size,
            revision: 1,
            operationId,
            status: "parsing",
            coverage: {totalUnits: 0, processedUnits: 0, emptyUnits: [], characters: 0, truncated: false},
            warnings: [],
            createdAt: at,
            updatedAt: at
        };
        await db.projectReferences.add(row);
        await db.projects.update(projectId, {updatedAt: at});
        return row;
    });
    if (reference.operationId !== operationId) return reference;
    return finishImport(reference, buffer, options);
}

export function importReferenceFile(projectId: string, file: File, options: ReferenceImportOptions = {}): Promise<ProjectReference> {
    return importSource(projectId, file, options);
}

/** Import/reuse generated or business-owned pixels without duplicating its Blob. */
export async function registerProjectImage(projectId: string, mediaId: string, options: ReferenceImportOptions = {}): Promise<ProjectReference> {
    const media = await db.media.get(mediaId);
    if (!media || media.projectId !== projectId) throw new Error("图片不属于当前项目或已删除");
    const extensions: Record<string, string> = {"image/png": "png", "image/jpeg": "jpg", "image/webp": "webp"};
    const ext = extensions[media.mimeType];
    if (!ext) throw new Error("当前仅支持 PNG、JPEG 和 WebP 图片");
    const filename = /\.(png|jpe?g|webp)$/i.test(media.filename) ? media.filename : `${media.filename}.${ext}`;
    return importSource(projectId, new File([media.blob], filename, {type: media.mimeType}), options, mediaId);
}

/** Explicitly recover an interrupted local parse; no network or model request. */
export async function retryReferenceImport(projectId: string, referenceId: string, options: ReferenceImportOptions = {}): Promise<ProjectReference> {
    const source = await db.transaction("r", [db.projects, db.projectReferences, db.media], async () => {
        const row = await db.projectReferences.get(referenceId);
        if (isStudioLibrary(projectId) || !(await db.projects.get(projectId)) || !row || row.projectId !== projectId || row.status === "unavailable") throw new Error("资料已不可用");
        const media = await db.media.get(row.mediaId);
        if (!media || media.projectId !== projectId) throw new Error("原始文件已不可用");
        return {row, media};
    });
    if (source.row.status === "ready" || source.row.status === "partial") return source.row;
    const buffer = await source.media.blob.arrayBuffer();
    options.signal?.throwIfAborted();
    const reference = await db.transaction("rw", [db.projects, db.projectReferences], async () => {
        const row = await db.projectReferences.get(referenceId);
        if (!row || row.status === "unavailable" || row.operationId !== source.row.operationId || !(await db.projects.get(projectId))) throw new Error("资料状态已变化，请刷新后重试");
        const next: ProjectReference = {
            ...row,
            status: "parsing",
            error: undefined,
            operationId: createId("parse"),
            updatedAt: nowIso()
        };
        await db.projectReferences.put(next);
        return next;
    });
    return finishImport(reference, buffer, options);
}

import {z} from "zod";
import type {ProjectReference, ReferenceChunk} from "@/domain/references";
import {REFERENCE_LIMITS as LIMITS} from "@/domain/references";
import type {MediaRecord} from "@/domain/types";
import {createId} from "@/lib/ids";
import {assertReferenceSignature, identifyReference} from "./parse";

const integer = z.number().int().nonnegative();
const coverage = z.object({
    totalUnits: integer,
    processedUnits: integer,
    emptyUnits: z.array(z.number().int().positive()).max(LIMITS.pages),
    characters: integer.max(LIMITS.characters),
    truncated: z.boolean()
});
const referenceSchema = z.object({
    id: z.string().min(1),
    projectId: z.string().min(1),
    mediaId: z.string().min(1),
    digest: z.string().regex(/^[a-f0-9]{64}$/),
    filename: z.string().min(1).max(1000),
    mimeType: z.string(),
    kind: z.enum(["image", "text", "pdf", "docx"]),
    size: integer.max(LIMITS.documentBytes),
    revision: z.number().int().positive(),
    operationId: z.string(),
    status: z.enum(["parsing", "ready", "partial", "failed", "unavailable"]),
    coverage,
    warnings: z.array(z.string().max(4000)).max(100),
    error: z.string().max(4000).optional(),
    createdAt: z.string(),
    updatedAt: z.string(),
});
const chunkSchema = z.object({
    id: z.string().min(1),
    projectId: z.string().min(1),
    referenceId: z.string().min(1),
    revision: z.number().int().positive(),
    index: integer,
    text: z.string().max(LIMITS.chunkCharacters),
    locator: z.object({
        kind: z.enum(["page", "lines", "paragraph"]),
        start: z.number().int().positive(),
        end: z.number().int().positive()
    }),
});

export function parseReferencePackage(rawRows: unknown, rawChunks: unknown, projectId: unknown) {
    const references = z.array(referenceSchema).parse(rawRows ?? []);
    const chunks = z.array(chunkSchema).parse(rawChunks ?? []);
    const byId = new Map(references.map((row) => [row.id, row]));
    const fail = () => {
        throw new Error("参考资料归属、正文或版本不一致");
    };
    if (byId.size !== references.length || new Set(chunks.map((chunk) => chunk.id)).size !== chunks.length) fail();
    for (const row of references) {
        if (row.projectId !== projectId || projectId === "studio" || row.coverage.processedUnits > row.coverage.totalUnits) fail();
        if (row.coverage.emptyUnits.some((unit) => unit > row.coverage.totalUnits)) fail();
        const parts = chunks.filter((part) => part.referenceId === row.id).sort((a, b) => a.index - b.index);
        if (parts.some((part, i) => part.index !== i || part.revision !== row.revision || part.projectId !== projectId || part.locator.end < part.locator.start || part.locator.end > row.coverage.totalUnits || part.locator.kind !== (row.kind === "pdf" ? "page" : row.kind === "docx" ? "paragraph" : "lines"))) fail();
        const textCharacters = parts.reduce((sum, part) => sum + part.text.length, 0);
        if (textCharacters > LIMITS.characters) fail();
        if (row.status === "ready" || row.status === "partial") {
            if (textCharacters !== row.coverage.characters) fail();
            if (!row.coverage.truncated && row.coverage.processedUnits !== row.coverage.totalUnits) fail();
            const incomplete = row.coverage.truncated || row.kind === "pdf" && row.coverage.emptyUnits.length > 0;
            if ((row.status === "partial") !== incomplete) fail();
        }
        if (new Set(row.coverage.emptyUnits).size !== row.coverage.emptyUnits.length || row.kind !== "pdf" && row.coverage.emptyUnits.length > 0) fail();
        if ((row.status === "unavailable" || row.status === "failed" || row.status === "parsing" || row.kind === "image") && parts.length) fail();
    }
    if (chunks.some((part) => !byId.has(part.referenceId))) fail();
    return {references, chunks};
}

/** All blob verification happens before opening the import transaction. */
export async function remapReferencePackage(input: ReturnType<typeof parseReferencePackage>, projectId: string, mediaMap: Map<string, string>, media: MediaRecord[]) {
    const ids = new Map(input.references.map((row) => [row.id, createId("ref")]));
    const references: ProjectReference[] = [];
    for (const row of input.references) {
        const mediaId = mediaMap.get(row.mediaId);
        if (row.status !== "unavailable") {
            const record = media.find((entry) => entry.id === mediaId);
            if (!record || record.blob.size !== row.size) throw new Error("参考资料缺少原始文件或大小不符");
            const format = identifyReference({name: row.filename, size: row.size});
            if (format.kind !== row.kind || format.mimeType !== row.mimeType) throw new Error("参考资料文件类型不一致");
            const bytes = await record.blob.arrayBuffer();
            assertReferenceSignature(new Uint8Array(bytes), row.kind, row.mimeType);
            const digest = [...new Uint8Array(await crypto.subtle.digest("SHA-256", bytes))].map((byte) => byte.toString(16).padStart(2, "0")).join("");
            if (digest !== row.digest) throw new Error("参考资料原始文件校验失败");
            record.filename = row.filename;
            record.mimeType = row.mimeType;
            record.blob = new Blob([bytes], {type: row.mimeType});
        }
        references.push({
            ...row,
            id: ids.get(row.id)!,
            projectId,
            mediaId: mediaId ?? createId("unavailable"),
            operationId: createId("import"),
            ...(row.status === "parsing" ? {status: "failed", error: "导入前解析尚未完成，请重试解析"} : {})
        });
    }
    const chunks: ReferenceChunk[] = input.chunks.map((part) => ({
        ...part,
        id: createId("rfc"),
        projectId,
        referenceId: ids.get(part.referenceId)!
    }));
    return {references, chunks};
}

import {type ParsedReference, REFERENCE_LIMITS as LIMITS, type ReferenceKind} from "@/domain/references";

export function identifyReference(file: Pick<File, "name" | "size">): { kind: ReferenceKind; mimeType: string } {
    const ext = file.name.split(".").at(-1)?.toLowerCase();
    const formats: Record<string, [ReferenceKind, string]> = {
        png: ["image", "image/png"],
        jpg: ["image", "image/jpeg"],
        jpeg: ["image", "image/jpeg"],
        webp: ["image", "image/webp"],
        txt: ["text", "text/plain"],
        md: ["text", "text/markdown"],
        markdown: ["text", "text/markdown"],
        pdf: ["pdf", "application/pdf"],
        docx: ["docx", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"],
    };
    const format = ext && formats[ext];
    if (!format) throw new Error("支持 PNG、JPEG、WebP、TXT、Markdown、文字型 PDF 和 DOCX");
    const [kind, mimeType] = format;
    const max = kind === "image" ? LIMITS.imageBytes : kind === "text" ? LIMITS.textBytes : LIMITS.documentBytes;
    if (file.size > max) throw new Error(`文件过大：此格式最多 ${max / 1024 / 1024} MB`);
    return {kind, mimeType};
}

export function assertReferenceSignature(bytes: Uint8Array, kind: ReferenceKind, mime: string) {
    const ascii = (from: number, to: number) => String.fromCharCode(...bytes.slice(from, to));
    const valid = kind === "text" || (kind === "pdf" && ascii(0, 5) === "%PDF-") ||
        (kind === "docx" && bytes[0] === 0x50 && bytes[1] === 0x4b && bytes[2] === 3 && bytes[3] === 4) ||
        (mime === "image/png" && [137, 80, 78, 71, 13, 10, 26, 10].every((value, i) => bytes[i] === value)) ||
        (mime === "image/jpeg" && bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255) ||
        (mime === "image/webp" && ascii(0, 4) === "RIFF" && ascii(8, 12) === "WEBP");
    if (!valid) throw new Error("文件内容与扩展名不符，或文件已损坏");
}

export function decodeReferenceText(buffer: ArrayBuffer): string {
    const bytes = new Uint8Array(buffer);
    const encoding = bytes[0] === 0xff && bytes[1] === 0xfe ? "utf-16le" : bytes[0] === 0xfe && bytes[1] === 0xff ? "utf-16be" : "utf-8";
    try {
        const text = new TextDecoder(encoding, {fatal: true}).decode(bytes);
        if (text.includes("\0")) throw new Error("binary");
        return text.replace(/\r\n?/g, "\n");
    } catch {
        throw new Error("无法读取文本编码，请保存为 UTF-8 或带 BOM 的 UTF-16 后重试");
    }
}

/** Units are real source pages / lines / extracted paragraphs, never invented PDF layout. */
export function chunkReferenceUnits(units: string[], kind: "page" | "lines" | "paragraph", totalUnits = units.length): ParsedReference {
    const chunks: ParsedReference["chunks"] = [];
    const emptyUnits: number[] = [];
    let characters = 0;
    let processedUnits = 0;
    let truncated = units.length < totalUnits || units.length > LIMITS.sourceUnits;
    for (let i = 0; i < Math.min(units.length, LIMITS.sourceUnits); i++) {
        const text = units[i];
        if (!text.trim() && kind === "page") emptyUnits.push(i + 1);
        let offset = 0;
        while (offset < text.length) {
            const previous = chunks.at(-1);
            const pieceLength = Math.min(LIMITS.chunkCharacters, text.length - offset);
            const merge = kind !== "page" && previous && previous.text.length + pieceLength + 1 <= LIMITS.chunkCharacters;
            // Coverage and the extraction cap count exactly the persisted chunk text,
            // including separators inserted when real source units share a chunk.
            const separator = merge ? 1 : 0;
            const remaining = LIMITS.characters - characters - separator;
            if (remaining <= 0) break;
            const part = text.slice(offset, offset + Math.min(pieceLength, remaining));
            if (merge) {
                previous.text += "\n" + part;
                previous.locator.end = i + 1;
            } else chunks.push({index: chunks.length, text: part, locator: {kind, start: i + 1, end: i + 1}});
            characters += part.length + separator;
            offset += part.length;
        }
        if (offset === text.length) processedUnits++;
        else {
            truncated = true;
            break;
        }
        if (characters >= LIMITS.characters && i < units.length - 1) {
            truncated = true;
            break;
        }
    }
    return {
        chunks,
        coverage: {totalUnits, processedUnits, emptyUnits, characters, truncated},
        warnings: truncated ? ["文件较长，仅提取了部分正文；未覆盖内容不会自动发送"] : []
    };
}

export function parseTextReference(buffer: ArrayBuffer): ParsedReference {
    const text = decodeReferenceText(buffer);
    let totalUnits = 1;
    for (const character of text) if (character === "\n") totalUnits++;
    const result = chunkReferenceUnits(text.split("\n", LIMITS.sourceUnits), "lines", totalUnits);
    if (!result.chunks.some((chunk) => chunk.text.trim())) result.warnings.push("文件为空，没有可发送的正文");
    return result;
}

/** True when two id lists are the same length and order. */
export function sameIdOrder(left: readonly string[], right: readonly string[]): boolean {
    return left.length === right.length && left.every((id, index) => id === right[index]);
}

/** Move `activeId` to the index of `overId` within a flat id list. */
export function moveIdToPosition(
    orderedIds: string[],
    activeId: string,
    overId: string,
): string[] | null {
    if (activeId === overId) return null;
    const from = orderedIds.indexOf(activeId);
    const to = orderedIds.indexOf(overId);
    if (from < 0 || to < 0) return null;
    const next = [...orderedIds];
    next.splice(from, 1);
    next.splice(to, 0, activeId);
    return next;
}

/**
 * Reorder members of a group inside a full ordered list, keeping non-group
 * ids in place. Used so within-beat shot drags do not scramble other beats.
 */
export function reorderGroupInFullOrder(
    fullOrderedIds: string[],
    groupIds: string[],
    activeId: string,
    overId: string,
): string[] | null {
    const nextGroup = moveIdToPosition(groupIds, activeId, overId);
    if (!nextGroup) return null;
    const groupSet = new Set(groupIds);
    let index = 0;
    return fullOrderedIds.map((id) => (groupSet.has(id) ? nextGroup[index++]! : id));
}

import type {Project, Prop, Shot, VisualStyle} from "@/domain/types";

/** Resolve names at read time so inherited styles track the project default. */
export function shotRelations(
    project: Project,
    shot: Shot,
    props: Prop[],
    styles: VisualStyle[],
) {
    const propNames = new Map(props.filter((item) => item.projectId === project.id).map((item) => [item.id, item.name]));
    const styleId = shot.styleId === undefined ? project.defaultStyleId : shot.styleId;
    const style = styles.find((item) => item.projectId === project.id && item.id === styleId);
    return {
        props: (shot.propIds ?? []).map((id) => propNames.get(id) ?? `未知道具(${id})`).join("、"),
        style: styleId ? (style?.name || `未知风格(${styleId})`) : "无风格",
        styleSource: shot.styleId === undefined ? "继承项目" : shot.styleId === null ? "不使用风格" : "镜头指定",
    };
}

